// 💾 OFFLINE MANAGER CLASS
class OfflineManager {
  constructor() {
    this.db = null;
    this.isOnline = navigator.onLine;
    this.syncInProgress = false;
    this.listeners = [];
  }

  async init() {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open("CPOfflineDB", 1);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => {
        this.db = request.result;
        console.log("✅ Offline DB ready");
        resolve(this.db);
      };

      request.onupgradeneeded = (event) => {
        const db = event.target.result;

        if (!db.objectStoreNames.contains("appData")) {
          const appDataStore = db.createObjectStore("appData", {
            keyPath: "key",
          });
          appDataStore.createIndex("timestamp", "timestamp", { unique: false });
        }

        if (!db.objectStoreNames.contains("mutations")) {
          const mutationsStore = db.createObjectStore("mutations", {
            keyPath: "id",
            autoIncrement: true,
          });
          mutationsStore.createIndex("timestamp", "timestamp", {
            unique: false,
          });
          mutationsStore.createIndex("synced", "synced", { unique: false });
        }
      };
    });
  }

  async saveData(key, data) {
    if (!this.db) await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction(["appData"], "readwrite");
      const store = transaction.objectStore("appData");
      const record = { key, data, timestamp: Date.now() };
      const request = store.put(record);

      request.onsuccess = () => resolve(record);
      request.onerror = () => reject(request.error);
    });
  }

  async getData(key) {
    if (!this.db) await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction(["appData"], "readonly");
      const store = transaction.objectStore("appData");
      const request = store.get(key);

      request.onsuccess = () =>
        resolve(request.result ? request.result.data : null);
      request.onerror = () => reject(request.error);
    });
  }

  async addMutation(mutation) {
    if (!this.db) await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction(["mutations"], "readwrite");
      const store = transaction.objectStore("mutations");
      const record = {
        ...mutation,
        timestamp: Date.now(),
        synced: false,
        retries: 0,
      };
      const request = store.add(record);

      request.onsuccess = () => {
        console.log("📴 Mutation queued:", mutation.type);
        if (this.isOnline) this.syncMutations();
        resolve(request.result);
      };
      request.onerror = () => reject(request.error);
    });
  }

  async getPendingMutations() {
    if (!this.db) await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction(["mutations"], "readonly");
      const store = transaction.objectStore("mutations");
      const index = store.index("synced");
      const request = index.getAll(false);

      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }

  async deleteMutation(id) {
    if (!this.db) await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction(["mutations"], "readwrite");
      const store = transaction.objectStore("mutations");
      const request = store.delete(id);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async syncMutations() {
    if (!this.isOnline || this.syncInProgress) return;

    this.syncInProgress = true;
    console.log("🔄 Syncing offline mutations...");

    try {
      const mutations = await this.getPendingMutations();

      if (mutations.length === 0) {
        console.log("✅ No mutations to sync");
        this.syncInProgress = false;
        return;
      }

      console.log(`🔄 Syncing ${mutations.length} mutations...`);

      for (const mutation of mutations) {
        try {
          // Firebase sync gebeurt in App component via executeMutation callback
          this.notifyListeners("mutationReady", mutation);
          await this.deleteMutation(mutation.id);
          console.log(`✅ Synced mutation ${mutation.id}`);
        } catch (error) {
          console.error(`❌ Failed to sync mutation ${mutation.id}:`, error);
        }
      }

      this.notifyListeners("syncComplete");
    } catch (error) {
      console.error("❌ Sync error:", error);
    } finally {
      this.syncInProgress = false;
    }
  }

  setOnlineStatus(isOnline) {
    const wasOffline = !this.isOnline;
    this.isOnline = isOnline;

    console.log(`🌐 ${isOnline ? "ONLINE" : "OFFLINE"}`);

    if (isOnline && wasOffline) {
      console.log("🔄 Back online! Starting sync...");
      this.syncMutations();
    }

    this.notifyListeners("connectionChange", { isOnline });
  }

  addListener(callback) {
    this.listeners.push(callback);
  }

  removeListener(callback) {
    this.listeners = this.listeners.filter((l) => l !== callback);
  }

  notifyListeners(event, data) {
    this.listeners.forEach((callback) => callback(event, data));
  }
}

const offlineManager = new OfflineManager();

// 🎨 OFFLINE INDICATOR COMPONENT
const OfflineIndicator = ({ isOnline, pendingMutations, isSyncing }) => {
  if (isOnline && pendingMutations === 0 && !isSyncing) {
    return null;
  }

  return (
    <div
      className="fixed top-0 left-0 right-0 z-50 px-4 py-2 text-center text-sm font-bold shadow-lg animate-in slide-in-from-top"
      style={{
        backgroundColor: isOnline ? "#045E51" : "#700606",
        color: "white",
      }}
    >
      {!isOnline && (
        <div className="flex items-center justify-center gap-2">
          <WifiOff size={16} />
          <span>Offline - Wijzigingen worden opgeslagen</span>
        </div>
      )}

      {isOnline && isSyncing && (
        <div className="flex items-center justify-center gap-2">
          <RefreshCw size={16} className="animate-spin" />
          <span>Synchroniseren... ({pendingMutations} items)</span>
        </div>
      )}

      {isOnline && !isSyncing && pendingMutations > 0 && (
        <div className="flex items-center justify-center gap-2">
          <AlertCircle size={16} />
          <span>{pendingMutations} wijzigingen wachten op sync</span>
        </div>
      )}
    </div>
  );
};

