const appId = typeof __app_id !== "undefined" ? __app_id : "default-app-id";
const DATA_PROTECTION = {
  KEYS: {
    CURRENT: "cp_app_data",
    LAST_GOOD: "cp_last_known_good",
    EMERGENCY: "cp_emergency_backup",
    SAVE_TIME: "cp_last_save_time",
    RECOVERY_LOG: "cp_recovery_log",
    SNAPSHOT_DATE: "cp_last_snapshot_date",
  },

  // LAAG 1: Auto-save every 10 seconds
  startAutoSave: (getData) => {
    return setInterval(() => {
      try {
        const data = getData();
        if (data && Object.keys(data).length > 5) {
          localStorage.setItem(
            DATA_PROTECTION.KEYS.CURRENT,
            JSON.stringify(data)
          );
          localStorage.setItem(
            DATA_PROTECTION.KEYS.SAVE_TIME,
            new Date().toISOString()
          );
        }
      } catch (e) {
        console.error("⚠️ Auto-save failed:", e);
      }
    }, 10000);
  },

  // LAAG 2: Emergency snapshot before destructive operations
  createEmergencySnapshot: (data) => {
    try {
      const snapshot = {
        data: data,
        timestamp: Date.now(),
        reason: "pre-operation-safety",
      };
      localStorage.setItem(
        DATA_PROTECTION.KEYS.EMERGENCY,
        JSON.stringify(snapshot)
      );
    } catch (e) {
      console.error("⚠️ Failed to create emergency snapshot:", e);
    }
  },

  // LAAG 3: Save last known good state
  saveLastKnownGood: (data) => {
    try {
      localStorage.setItem(
        DATA_PROTECTION.KEYS.LAST_GOOD,
        JSON.stringify(data)
      );
      console.log("✅ Last known good state saved");
    } catch (e) {
      console.error("⚠️ Failed to save last known good:", e);
    }
  },

  // Recovery waterfall: try all sources in order
  recoverFromLocal: () => {
    const sources = [
      { key: DATA_PROTECTION.KEYS.CURRENT, name: "Current" },
      { key: DATA_PROTECTION.KEYS.LAST_GOOD, name: "Last Known Good" },
      {
        key: DATA_PROTECTION.KEYS.EMERGENCY,
        name: "Emergency",
        isSnapshot: true,
      },
    ];

    for (const source of sources) {
      try {
        const stored = localStorage.getItem(source.key);
        if (!stored) continue;

        const parsed = source.isSnapshot
          ? JSON.parse(stored).data
          : JSON.parse(stored);

        if (parsed && Object.keys(parsed).length > 5) {
          console.log(`✅ Recovered from ${source.name}`);
          DATA_PROTECTION.logRecovery(source.name, true);
          return sanitizeData(parsed);
        }
      } catch (e) {
        console.error(`⚠️ Failed to recover from ${source.name}:`, e);
      }
    }

    console.warn("⚠️ No valid local backups found");
    DATA_PROTECTION.logRecovery("local-storage", false);
    return null;
  },

  // Log recovery attempts for debugging
  logRecovery: (method, success) => {
    try {
      const log = JSON.parse(
        localStorage.getItem(DATA_PROTECTION.KEYS.RECOVERY_LOG) || "[]"
      );
      log.push({
        method,
        success,
        timestamp: new Date().toISOString(),
      });
      localStorage.setItem(
        DATA_PROTECTION.KEYS.RECOVERY_LOG,
        JSON.stringify(log.slice(-50))
      );
    } catch (e) {
      console.error("Failed to log recovery:", e);
    }
  },

  // Get info about available backups
  getBackupInfo: () => {
    try {
      return {
        current: {
          exists: !!localStorage.getItem(DATA_PROTECTION.KEYS.CURRENT),
          time: localStorage.getItem(DATA_PROTECTION.KEYS.SAVE_TIME),
        },
        lastGood: {
          exists: !!localStorage.getItem(DATA_PROTECTION.KEYS.LAST_GOOD),
        },
        emergency: {
          exists: !!localStorage.getItem(DATA_PROTECTION.KEYS.EMERGENCY),
        },
        logs: JSON.parse(
          localStorage.getItem(DATA_PROTECTION.KEYS.RECOVERY_LOG) || "[]"
        ),
      };
    } catch (e) {
      return null;
    }
  },
};

// --- FOTO UPLOAD HELPER FUNCTIES ---
/**
 * Comprimeert een foto voor het uploaden
 * @param {File} file - Het originele foto bestand
 * @param {number} maxWidth - Maximale breedte (default 1200px)
 * @param {number} quality - Compressie kwaliteit 0-1 (default 0.8)
 * @returns {Promise<Blob>} - Gecomprimeerde foto als Blob
 */
const compressImage = async (file, maxWidth = 1200, quality = 0.8) => {
  return new Promise((resolve, reject) => {
    const img = new window.Image(); // Use window.Image to avoid conflict with lucide-react Image import
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");

    img.onload = () => {
      let width = img.width;
      let height = img.height;

      if (width > maxWidth) {
        height = (height * maxWidth) / width;
        width = maxWidth;
      }

      canvas.width = width;
      canvas.height = height;
      ctx.drawImage(img, 0, 0, width, height);

      canvas.toBlob(
        (blob) => {
          if (blob) {
            console.log(
              `✅ Foto gecomprimeerd van ${(file.size / 1024 / 1024).toFixed(
                2
              )}MB naar ${(blob.size / 1024 / 1024).toFixed(2)}MB`
            );
            resolve(blob);
          } else {
            reject(new Error("Compressie gefaald"));
          }
        },
        "image/jpeg",
        quality
      );
    };

    img.onerror = () => reject(new Error("Foto kan niet geladen worden"));
    img.src = URL.createObjectURL(file);
  });
};

/**
 * Upload foto naar Firebase Storage
 * @param {Blob} photoBlob - Gecomprimeerde foto
 * @param {string} dateKey - Datum (bijv. "2026-01-14")
 * @param {string} type - Type (bijv. "ent" of "crea")
 * @param {string} photoId - Unieke foto ID
 * @returns {Promise<Object>} - Object met url en storagePath
 *
 * FIREBASE STORAGE RULES VEREIST:
 * Zorg dat de volgende rules ingesteld zijn in Firebase Console > Storage > Rules:
 *
 * rules_version = '2';
 * service firebase.storage {
 *   match /b/{bucket}/o {
 *     match /handover-photos/{allPaths=**} {
 *       allow read: if true;
 *       allow write: if request.auth != null && request.resource.size < 10 * 1024 * 1024;
 *     }
 *   }
 * }
 */
const uploadHandoverPhoto = async (photoBlob, dateKey, type, photoId) => {
  // Controleer of storage geïnitialiseerd is
  if (!storage) {
    throw new Error("Firebase Storage is niet geïnitialiseerd");
  }

  const storagePath = `handover-photos/${dateKey}/${type}/${photoId}.jpg`;
  console.log("📤 Upload start:", storagePath);

  try {
    const storageRef = ref(storage, storagePath);

    await uploadBytes(storageRef, photoBlob, {
      contentType: "image/jpeg",
      cacheControl: "public, max-age=31536000",
    });

    console.log("✅ Bytes uploaded, getting URL...");
    const downloadURL = await getDownloadURL(storageRef);
    console.log("✅ Upload compleet:", downloadURL);

    return { url: downloadURL, storagePath };
  } catch (error) {
    console.error("❌ Upload gefaald:", {
      path: storagePath,
      error: error.message,
      code: error.code,
      details: error,
    });
    throw error;
  }
};

/**
 * Verwijder foto van Firebase Storage
 * @param {string} storagePath - Pad in Firebase Storage
 */
const deleteHandoverPhoto = async (storagePath) => {
  try {
    const storageRef = ref(storage, storagePath);
    await deleteObject(storageRef);
    console.log("✅ Foto verwijderd:", storagePath);
  } catch (error) {
    console.error("⚠️ Kon foto niet verwijderen:", error);
  }
};

/**
 * Upload profielfoto naar Firebase Storage
 * @param {File} file - Afbeeldingsbestand
 * @param {string} staffName - Naam van het personeelslid
 * @returns {Promise<{url: string, storagePath: string}>}
 */
const uploadProfilePhoto = async (file, staffName) => {
  if (!storage) throw new Error("Firebase Storage is niet geïnitialiseerd");
  const safeName = staffName.replace(/[^a-zA-Z0-9_-]/g, "_");
  const storagePath = `profile-photos/${safeName}.jpg`;
  const storageRef = ref(storage, storagePath);

  // Comprimeer naar max 400x400
  const compressed = await new Promise((resolve, reject) => {
    const img = new Image();
    const url = URL.createObjectURL(file);
    img.onload = () => {
      const size = Math.min(img.width, img.height);
      const canvas = document.createElement("canvas");
      canvas.width = 400;
      canvas.height = 400;
      const ctx = canvas.getContext("2d");
      const sx = (img.width - size) / 2;
      const sy = (img.height - size) / 2;
      ctx.drawImage(img, sx, sy, size, size, 0, 0, 400, 400);
      URL.revokeObjectURL(url);
      canvas.toBlob(resolve, "image/jpeg", 0.82);
    };
    img.onerror = reject;
    img.src = url;
  });

  await uploadBytes(storageRef, compressed, {
    contentType: "image/jpeg",
    cacheControl: "public, max-age=31536000",
  });
  const downloadURL = await getDownloadURL(storageRef);
  return { url: downloadURL, storagePath };
};

// --- CSV SCHEDULE PARSER FUNCTIES ---
/**
 * Parse CSV line met quotes handling
 */
const parseCSVLine = (line) => {
  const result = [];
  let current = "";
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];

    if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === "," && !inQuotes) {
      result.push(current.trim());
      current = "";
    } else {
      current += char;
    }
  }
  result.push(current.trim());

  return result;
};

/**
 * Parse datum formaat
 */
const parseCsvDate = (dateStr) => {
  if (!dateStr || !dateStr.includes("-")) return null;
  // "1-2-2026" -> "2026-02-01"
  const parts = dateStr.split("-");
  if (parts.length !== 3) return null;

  const [day, month, year] = parts;
  return `${year}-${month.padStart(2, "0")}-${day.padStart(2, "0")}`;
};

/**
 * Bepaal type o.b.v. location
 */
const determineScheduleType = (location) => {
  if (!location) return "other";
  const loc = location.toLowerCase();

  if (loc.includes("crea")) return "crea";
  if (loc.includes("springkussen")) return "springkussen";
  if (loc.includes("fm")) return "fm";
  // O&F, DJ, Quiz, Bingo, Live, KKO allemaal entertainment
  return "entertainment";
};

/**
 * Match CSV naam naar app user
 */
const findMatchingUser = (csvName, staffList, fmLastName = null) => {
  if (!csvName || !csvName.includes(",")) return null;

  // csvName = "Billekens, L.M.J." of "Broek van den, M.P.R."
  const lastName = csvName.split(",")[0].trim();

  // Check eerst of het Maik (FM) is
  if (fmLastName && fmLastName.toLowerCase() === lastName.toLowerCase()) {
    return "Maik";
  }

  // Zoek in staffList
  const match = staffList.find(
    (s) => s.lastName && s.lastName.toLowerCase() === lastName.toLowerCase()
  );

  return match ? match.name : null;
};

/**
 * Parse volledige schedule CSV
 */
const parseScheduleCSV = (csvText, staffList, fmLastName = null) => {
  const lines = csvText.split("\n");
  const schedule = {};
  let currentEmployee = null;
  const unmatchedEmployees = new Set();
  // Sla pauzes op die vóór de werkregel staan
  const pendingBreaks = {}; // employeeName+date → [{start, end}]

  for (let i = 1; i < lines.length; i++) {
    // Skip header
    const line = lines[i];
    if (!line.trim()) continue;

    const cols = parseCSVLine(line);

    // Nieuwe medewerker?
    if (cols[0] && cols[0].includes(",")) {
      currentEmployee = cols[0].trim();
    }

    // Shift data?
    if (cols[3] && cols[5] && currentEmployee) {
      const date = parseCsvDate(cols[3]);
      if (!date) continue;

      const timeRange = cols[5]; // "09:45 - 15:45"
      const location = cols[6] || "";
      const workTimeRange = cols[8] || "";
      const description = (cols[9] || "").toLowerCase();

      // Match naar app user - geef fmLastName mee!
      const matchedUser = findMatchingUser(
        currentEmployee,
        staffList,
        fmLastName
      );
      if (!matchedUser) {
        unmatchedEmployees.add(currentEmployee);
      }

      if (!schedule[date]) schedule[date] = [];

      // Zoek bestaande shift voor deze employee
      let existingShift = schedule[date].find(
        (s) => s.employeeName === currentEmployee
      );

      const isPauze =
        description.includes("pauze") ||
        description.includes("break") ||
        description.includes("lunch");
      const isWerk =
        description.includes("werk") || description.includes("work");

      if (isPauze) {
        // Voeg pauze toe aan bestaande shift, of sla op als pending
        if (workTimeRange.includes(" - ")) {
          const [breakStart, breakEnd] = workTimeRange.split(" - ");
          const brk = { start: breakStart.trim(), end: breakEnd.trim() };
          if (existingShift) {
            if (!existingShift.breaks) existingShift.breaks = [];
            existingShift.breaks.push(brk);
          } else {
            // Pauze komt vóór werkregel — bewaar voor later
            const key = `${currentEmployee}|${date}`;
            if (!pendingBreaks[key]) pendingBreaks[key] = [];
            pendingBreaks[key].push(brk);
          }
        }
      } else if (isWerk) {
        // Dit is een werk segment
        if (!existingShift) {
          // Maak nieuwe shift
          if (timeRange.includes(" - ")) {
            const [start, end] = timeRange.split(" - ");
            const key = `${currentEmployee}|${date}`;
            schedule[date].push({
              employeeName: currentEmployee,
              matchedUser: matchedUser,
              start: start.trim(),
              end: end.trim(),
              location: location.trim(),
              type: determineScheduleType(location),
              breaks: pendingBreaks[key] || [],
            });
            delete pendingBreaks[key];
          }
        }
      }
    }
  }

  return {
    schedule,
    unmatchedEmployees: Array.from(unmatchedEmployees),
  };
};

/**
 * Bereken shift duur in uren
 */
const calculateShiftDuration = (start, end, breaks = []) => {
  const [startH, startM] = start.split(":").map(Number);
  const [endH, endM] = end.split(":").map(Number);

  let minutes = endH * 60 + endM - (startH * 60 + startM);
  if (minutes < 0) minutes += 24 * 60; // Overnight shift

  // Trek pauzes af
  if (breaks && breaks.length > 0) {
    breaks.forEach((brk) => {
      const [bStartH, bStartM] = brk.start.split(":").map(Number);
      const [bEndH, bEndM] = brk.end.split(":").map(Number);
      const breakMinutes = bEndH * 60 + bEndM - (bStartH * 60 + bStartM);
      minutes -= breakMinutes;
    });
  }

  const hours = Math.floor(minutes / 60);
  const mins = minutes % 60;

  return mins > 0 ? `${hours}:${mins.toString().padStart(2, "0")}` : `${hours}`;
};

