// --- DATA HELPERS ---
// 🔥 Remove undefined values for Firebase compatibility
// Firebase does not accept undefined values - only null or omit the field
const removeUndefined = (obj) => {
  if (obj === null || obj === undefined) {
    return null;
  }

  if (Array.isArray(obj)) {
    return obj.map(removeUndefined).filter((item) => item !== null);
  }

  if (typeof obj === "object") {
    const cleaned = {};
    for (const [key, value] of Object.entries(obj)) {
      if (value !== undefined) {
        const cleanedValue = removeUndefined(value);
        if (cleanedValue !== null || value === null) {
          cleaned[key] = cleanedValue;
        }
      }
    }
    return cleaned;
  }

  return obj;
};

// 🗜️ Strip default/empty fields from schedule items before saving
// Velden met default-waarden worden weggelaten; bij inladen vul je ze terug met || default
const SCHEDULE_FIELD_DEFAULTS = {
  refhd: "",
  paris: false,
  villageMap: false,
  linkedManuals: [],
  remarks: "",
  infoText: "",
  promoInfoNL: "",
  promoInfoEN: "",
  photo: null,
  price: "",
};

const stripScheduleDefaults = (item) => {
  const stripped = { ...item };
  for (const [field, defaultVal] of Object.entries(SCHEDULE_FIELD_DEFAULTS)) {
    const val = stripped[field];
    if (val === defaultVal) {
      delete stripped[field];
    } else if (
      Array.isArray(defaultVal) &&
      Array.isArray(val) &&
      val.length === 0
    ) {
      delete stripped[field];
    } else if (val === null && defaultVal === null) {
      delete stripped[field];
    } else if (val === "" && defaultVal === "") {
      delete stripped[field];
    }
  }
  return stripped;
};

