const getFirstName = (fullName) => {
  if (!fullName) return "";
  return fullName.split(" ")[0];
};

const calculateAge = (dob) => {
  if (!dob) return 0;
  const birthDate = new Date(dob);
  const today = new Date();
  let age = today.getFullYear() - birthDate.getFullYear();
  const m = today.getMonth() - birthDate.getMonth();
  if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) age--;
  return age;
};

// Geeft alle teamleden terug die op dateKey jarig zijn
const getBirthdaysOnDate = (dateKey, staffList = [], fmDob = null) => {
  const [year, month, day] = dateKey.split("-").map(Number);
  const result = [];
  staffList.forEach((s) => {
    if (!s.dob) return;
    const d = new Date(s.dob);
    if (d.getMonth() + 1 === month && d.getDate() === day) {
      const age = year - d.getFullYear();
      result.push({ name: s.name, age });
    }
  });
  if (fmDob) {
    const d = new Date(fmDob);
    if (d.getMonth() + 1 === month && d.getDate() === day) {
      const age = year - d.getFullYear();
      if (!result.some((r) => r.name === "Maik")) {
        result.push({ name: "Maik", age });
      }
    }
  }
  return result;
};

const getGreeting = () => {
  const h = new Date().getHours();
  return h < 6
    ? "Goedenacht"
    : h < 12
    ? "Goedemorgen"
    : h < 18
    ? "Goedemiddag"
    : "Goedenavond";
};

const getWeatherIcon = (code) => {
  if (code === 0) return { icon: Sun, desc: "Zon" };
  if (code >= 1 && code <= 3) return { icon: CloudSun, desc: "Bewolkt" };
  if (code >= 45 && code <= 48) return { icon: Cloud, desc: "Mist" };
  if (code >= 51 && code <= 67) return { icon: CloudRain, desc: "Regen" };
  if (code >= 71 && code <= 77) return { icon: CloudSnow, desc: "Sneeuw" };
  if (code >= 80 && code <= 82) return { icon: CloudRain, desc: "Buien" };
  if (code >= 95) return { icon: CloudLightning, desc: "Onweer" };
  return { icon: CloudSun, desc: "Wisselvallig" };
};

const getCharColorInfo = (role) => {
  const r = role.toLowerCase();
  if (r.includes("orry")) return { bg: C.Blossom, text: C.Sunset }; // 🔴 Roze/Rood
  if (r.includes("rep")) return { bg: C.Honey, text: C.Bark }; // 🟡 Geel
  if (r.includes("woops")) return { bg: C.Sky, text: C.Lagoon }; // 🔵 Blauw
  if (r.includes("bing")) return { bg: C.Grass, text: C.Pine }; // 🟢 Groen
  return { bg: C.Bg, text: C.Bark };
};

const safeRenderText = (item) => {
  if (typeof item === "string") return item;
  if (typeof item === "object" && item !== null) return item.text || "";
  return "";
};

const formatStaffList = (staff) => {
  if (!staff) return [];
  if (Array.isArray(staff))
    return staff.map((s) =>
      typeof s === "object" ? s.name || "Error" : String(s)
    );
  if (typeof staff === "object") return [staff.name || "Error"];
  return [String(staff)];
};

const getFridayOfWeek = (date) => {
  const d = new Date(date);
  const day = d.getDay();
  let daysToSubtract = 0;
  if (day === 5) daysToSubtract = 0;
  else if (day === 6) daysToSubtract = 1;
  else if (day === 0) daysToSubtract = 2;
  else if (day === 1) daysToSubtract = 3;
  else if (day === 2) daysToSubtract = 4;
  else if (day === 3) daysToSubtract = 5;
  else if (day === 4) daysToSubtract = 6;
  d.setDate(d.getDate() - daysToSubtract);
  return d;
};

const useWeather = (date, isLoggedIn) => {
  const [weather, setWeather] = useState({
    temp: "--",
    desc: "...",
    icon: Cloud,
  });
  useEffect(() => {
    // America (Horst aan de Maas): lat 51.4408, lon 6.0536
    // Actueel weer via current_weather + hourly feel, ververs elke 15 min
    const fetchWeather = async () => {
      try {
        const url =
          "https://api.open-meteo.com/v1/forecast?latitude=51.4408&longitude=6.0536&current=temperature_2m,weather_code&timezone=Europe%2FAmsterdam";
        const response = await fetch(url);
        const data = await response.json();
        if (data.current) {
          const code = data.current.weather_code;
          const temp = Math.round(data.current.temperature_2m);
          setWeather({ temp, ...getWeatherIcon(code) });
        } else {
          setWeather({ temp: "--", desc: "Geen data", icon: Cloud });
        }
      } catch (error) {
        setWeather({ temp: "--", desc: "Offline", icon: WifiOff });
      }
    };
    fetchWeather();
    const interval = setInterval(fetchWeather, 900000); // elke 15 min
    return () => clearInterval(interval);
  }, [isLoggedIn]);
  return weather;
};

const isActivityPast = (timeStr, date) => {
  if (!timeStr) return false;
  const todayStr = toIsoDate(new Date());
  const checkDateStr = toIsoDate(date);
  if (checkDateStr < todayStr) return true;
  if (checkDateStr > todayStr) return false;
  const now = new Date();
  const parts = timeStr.split("-");
  const timeToParse = parts.length > 1 ? parts[1] : parts[0];
  const [hours, minutes] = timeToParse.trim().split(":").map(Number);
  if (isNaN(hours) || isNaN(minutes)) return false;
  const activityTime = new Date(now);
  activityTime.setHours(hours, minutes, 0, 0);
  return now > activityTime;
};

const isActivityNow = (timeStr, date) => {
  if (!timeStr) return false;
  if (toIsoDate(date) !== toIsoDate(new Date())) return false;
  const parts = timeStr.split("-");
  const sp = parts[0].trim().split(":").map(Number);
  const ep = (parts[1] || parts[0]).trim().split(":").map(Number);
  if (isNaN(sp[0]) || isNaN(ep[0])) return false;
  const now = new Date();
  const cur = now.getHours() * 60 + now.getMinutes();
  const start = sp[0] * 60 + (sp[1] || 0);
  const end = ep[0] * 60 + (ep[1] || 0);
  return cur >= start && cur <= end;
};

const sortActivities = (a, b, currentDay) => {
  const pastA = isActivityPast(a.time, currentDay);
  const pastB = isActivityPast(b.time, currentDay);
  if (pastA && !pastB) return 1;
  if (!pastA && pastB) return -1;
  const getStartTime = (t) => {
    const parts = t.split("-")[0].trim().split(":");
    return parseInt(parts[0]) * 60 + parseInt(parts[1]);
  };
  return getStartTime(a.time) - getStartTime(b.time);
};

