const Card = ({
  children,
  className = "",
  borderColor = "transparent",
  accentColor, // 🆕 Accent kleur voor linker/top rand
  accentPosition = "left", // 🆕 "left", "top", "bottom"
  style = {},
  onClick,
  glass = false,
  hover = true,
  elevated = false, // 🆕 Voor extra shadow
  animate = false, // 🆕 Fade-in animatie
}) => {
  const accentStyles = accentColor
    ? {
        borderLeftWidth: accentPosition === "left" ? "4px" : undefined,
        borderTopWidth: accentPosition === "top" ? "4px" : undefined,
        borderBottomWidth: accentPosition === "bottom" ? "4px" : undefined,
        borderColor: accentPosition === "left" ? accentColor : undefined,
        borderTopColor: accentPosition === "top" ? accentColor : undefined,
        borderBottomColor:
          accentPosition === "bottom" ? accentColor : undefined,
        borderStyle: "solid",
      }
    : {};

  return (
    <div
      onClick={onClick}
      className={`
        ${glass ? "glass-card" : "bg-white"} 
        rounded-2xl 
        ${elevated ? "shadow-medium" : "shadow-soft"}
        border border-gray-100
        ${hover && onClick ? "smooth-hover cursor-pointer" : ""}
        ${animate ? "animate-fade-in-up" : ""}
        ${className}
      `}
      style={{
        borderColor: borderColor !== "transparent" ? borderColor : undefined,
        ...accentStyles,
        ...style,
      }}
    >
      {children}
    </div>
  );
};

const Progress = ({
  value = 0,
  max = 100,
  showLabel = false,
  color = "pine", // pine, honey, grass
  size = "md", // sm, md, lg
  className = "",
}) => {
  const percentage = Math.min(100, Math.max(0, (value / max) * 100));

  const colors = {
    pine: `linear-gradient(90deg, ${C.Pine} 0%, ${C.PineMedium} 100%)`,
    honey: `linear-gradient(90deg, ${C.Honey} 0%, #FFD97D 100%)`,
    grass: `linear-gradient(90deg, ${C.Pine} 0%, ${C.Grass} 100%)`,
  };

  const sizes = {
    sm: "h-1.5",
    md: "h-2.5",
    lg: "h-4",
  };

  return (
    <div className={className}>
      <div
        className={`bg-gray-100 rounded-full overflow-hidden ${sizes[size]}`}
      >
        <div
          className="h-full rounded-full transition-all duration-700 ease-out"
          style={{
            width: `${percentage}%`,
            background: colors[color],
          }}
        />
      </div>
      {showLabel && (
        <div className="flex justify-between text-xs text-gray-500 mt-1.5">
          <span>
            {value} / {max}
          </span>
          <span className="font-medium">{Math.round(percentage)}%</span>
        </div>
      )}
    </div>
  );
};

