const BirthdayWidget = ({ staffList, currentDay, fmDob }) => {
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const getBirthdays = () => {
    const birthdays = staffList.filter((s) => {
      if (!s.dob) return false;
      const d = new Date(s.dob);
      return (
        d.getDate() === currentDay.getDate() &&
        d.getMonth() === currentDay.getMonth()
      );
    });

    // Check ook Maik (FM)
    if (fmDob) {
      const fmDate = new Date(fmDob);
      if (
        fmDate.getDate() === currentDay.getDate() &&
        fmDate.getMonth() === currentDay.getMonth()
      ) {
        birthdays.push({ name: "Maik", dob: fmDob });
      }
    }

    return birthdays;
  };

  const birthdays = getBirthdays();
  const [showConfetti, setShowConfetti] = useState(false);

  useEffect(() => {
    // Alleen confetti op VANDAAG en alleen bij eerste keer vandaag
    const isToday = currentDay.toDateString() === today.toDateString();

    if (birthdays.length > 0 && isToday) {
      // Check localStorage of confetti al getoond is vandaag
      const confettiKey = `birthday_confetti_shown_${toIsoDate(today)}`;
      const alreadyShown = localStorage.getItem(confettiKey);

      if (!alreadyShown) {
        setShowConfetti(true);
        // Sla op dat confetti getoond is
        localStorage.setItem(confettiKey, "true");

        // Stop confetti na 5 seconden
        setTimeout(() => setShowConfetti(false), 5000);
      }
    } else {
      setShowConfetti(false);
    }
  }, [birthdays.length, currentDay]);

  if (birthdays.length === 0) return null;

  // Check of de geselecteerde dag in het verleden, heden of toekomst is
  const selectedDate = new Date(currentDay);
  selectedDate.setHours(0, 0, 0, 0);

  const isPast = selectedDate < today;
  const isToday = selectedDate.getTime() === today.getTime();
  const isFuture = selectedDate > today;

  const getMessage = (person) => {
    const age = calculateAge(person.dob);

    if (isToday) {
      return `${person.name} is vandaag ${age} jaar geworden!`;
    } else if (isPast) {
      return `${person.name} was jarig en werd ${age} jaar`;
    } else {
      // Toekomst - bereken leeftijd op die datum
      const futureAge =
        age +
        Math.ceil((selectedDate - today) / (365.25 * 24 * 60 * 60 * 1000));
      return `${person.name} wordt ${futureAge} jaar`;
    }
  };

  const getTitle = () => {
    if (isToday) return "Hieperdepiep Hoera!";
    if (isPast) return "Was Jarig";
    return "Binnenkort Jarig";
  };

  const getThemeColor = () => {
    if (isToday) return C.Forest; // Donkergroen voor vandaag
    if (isPast) return C.Pine; // Groen voor verleden
    return C.Forest; // Donkergroen voor toekomst
  };

  const themeColor = getThemeColor();

  return (
    <>
      {showConfetti && <Confetti />}
      <div
        className="bg-white rounded-2xl shadow-sm overflow-hidden animate-fade-in-up border-2"
        style={{ borderColor: themeColor }}
      >
        <div className="cp-pattern-dots">
          <div className="p-6">
            <div className="flex items-start gap-4">
              {/* Icoon */}
              <div
                className="p-3 rounded-xl shadow-sm"
                style={{
                  backgroundColor: `${themeColor}20`,
                  color: themeColor,
                }}
              >
                {isToday ? (
                  <Gift size={28} />
                ) : isPast ? (
                  <CalendarIcon size={28} />
                ) : (
                  <PartyPopper size={28} />
                )}
              </div>

              {/* Content */}
              <div className="flex-1">
                <h3
                  className="text-base font-bold mb-2"
                  style={{ color: themeColor }}
                >
                  {getTitle()}
                </h3>

                <div className="space-y-1">
                  {birthdays.map((b) => (
                    <p
                      key={b.name}
                      className="text-sm font-medium"
                      style={{ color: themeColor }}
                    >
                      {getMessage(b)}
                    </p>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  );
};

