const useDashboardLayout = (loggedInUserName, appData, saveData) => {
  const KEY = `dashLayout_${loggedInUserName}`;
  const saved = appData.userPrefs?.[KEY];
  // Nieuwe widgets uit de defaults worden achteraan een bestaande layout
  // toegevoegd, zodat ze ook verschijnen voor wie al een opgeslagen indeling heeft.
  const base = (() => {
    const defaults = DASHBOARD_WIDGET_DEFAULTS.map((w) => ({
      id: w.id,
      size: w.size,
    }));
    if (!Array.isArray(saved) || !saved.length) return defaults;
    const present = new Set(saved.map((w) => w.id));
    const missing = defaults.filter((w) => !present.has(w.id));
    return [...saved, ...missing];
  })();

  // Migratie: elke (normale) widget krijgt een expliciete kolom (0..2).
  let _ni = 0;
  const layout = base.map((w) => {
    if (typeof w.col === "number") return w;
    if (w.size === 3) return { ...w, col: 0 };
    const col = _ni % 3;
    _ni += 1;
    return { ...w, col };
  });

  const save = (newLayout) => {
    saveData({ userPrefs: { ...appData.userPrefs, [KEY]: newLayout } });
  };

  const setSize = (id, size) => {
    save(layout.map((w) => (w.id === id ? { ...w, size } : w)));
  };

  // Mobiel (1 kolom): ruil met de buur in de lijstvolgorde.
  const reorder = (fromId, toId) => {
    if (fromId === toId) return;
    const next = [...layout];
    const fromIdx = next.findIndex((w) => w.id === fromId);
    const toIdx = next.findIndex((w) => w.id === toId);
    if (fromIdx < 0 || toIdx < 0) return;
    const [moved] = next.splice(fromIdx, 1);
    next.splice(toIdx, 0, moved);
    save(next);
  };

  // Desktop: plaats fromId vóór/ná targetId en neem de kolom van het doel over.
  const placeRelative = (fromId, targetId, before) => {
    if (fromId === targetId) return;
    const next = [...layout];
    const fromIdx = next.findIndex((w) => w.id === fromId);
    const tIdx0 = next.findIndex((w) => w.id === targetId);
    if (fromIdx < 0 || tIdx0 < 0) return;
    const target = next[tIdx0];
    const moved = {
      ...next[fromIdx],
      col: target.size === 3 ? next[fromIdx].col ?? 0 : target.col ?? 0,
    };
    next.splice(fromIdx, 1);
    const tIdx = next.findIndex((w) => w.id === targetId);
    next.splice(before ? tIdx : tIdx + 1, 0, moved);
    save(next);
  };

  // Desktop: laat in een (lege) kolom vallen — zet kolom, plaats onderaan.
  const placeInColumn = (fromId, col) => {
    const next = [...layout];
    const fromIdx = next.findIndex((w) => w.id === fromId);
    if (fromIdx < 0) return;
    const [moved] = next.splice(fromIdx, 1);
    moved.col = col;
    next.push(moved);
    save(next);
  };

  return {
    layout,
    setSize,
    reorder,
    placeRelative,
    placeInColumn,
    isCustom: Array.isArray(saved) && saved.length > 0,
  };
};

// Widget-wrapper met drag handle (desktop) of verschuif-knoppen (mobiel)
const DashboardWidgetShell = ({
  id,
  size,
  label,
  editing,
  index,
  total,
  isMobile,
  onReorder,
  onMove,
  onResize,
  children,
  colSpanClass,
  colSpanStyle,
}) => {
  const [dragOver, setDragOver] = useState(false);

  return (
    <div
      className={`relative ${colSpanClass}`}
      style={{
        ...(colSpanStyle || {}),
        ...(dragOver && editing && !isMobile
          ? { boxShadow: `0 0 0 2px ${C.Lagoon}`, borderRadius: 16 }
          : {}),
      }}
      draggable={editing && !isMobile}
      onDragStart={(e) => {
        e.dataTransfer.setData("widgetId", id);
      }}
      onDragOver={(e) => {
        e.preventDefault();
        setDragOver(true);
      }}
      onDragLeave={() => setDragOver(false)}
      onDrop={(e) => {
        e.preventDefault();
        setDragOver(false);
        const from = e.dataTransfer.getData("widgetId");
        if (from && from !== id) onReorder(from, id);
      }}
    >
      {editing &&
        (isMobile ? (
          <div className="absolute top-2 right-2 z-20 flex items-center gap-1">
            {/* Mobiel: verschuiven met knoppen (touch heeft geen drag&drop) */}
            <button
              onClick={() => onMove(id, "up")}
              disabled={index === 0}
              className="flex items-center justify-center w-8 h-8 rounded-lg bg-white shadow border border-gray-200 text-gray-600 disabled:opacity-30 active:scale-95"
              title="Omhoog"
            >
              <ChevronUp size={16} />
            </button>
            <button
              onClick={() => onMove(id, "down")}
              disabled={index === total - 1}
              className="flex items-center justify-center w-8 h-8 rounded-lg bg-white shadow border border-gray-200 text-gray-600 disabled:opacity-30 active:scale-95"
              title="Omlaag"
            >
              <ChevronDown size={16} />
            </button>
          </div>
        ) : (
          <div className="absolute top-2 right-2 z-20 flex items-center gap-1">
            {/* Resize — CSS-columns ondersteunt alleen 'normaal' of 'volle breedte' */}
            <button
              onClick={() => onResize(id, size === 3 ? 1 : 3)}
              className="flex items-center gap-1 px-2 py-1 rounded-lg text-[11px] font-semibold bg-white shadow border border-gray-200 text-gray-600 hover:bg-white"
              title={size === 3 ? "Naar normale breedte" : "Naar volle breedte"}
            >
              {size === 3 ? "↔ Normaal" : "↔ Breed"}
            </button>
            {/* Drag handle */}
            <div className="cursor-grab active:cursor-grabbing px-1.5 py-1 rounded-lg bg-white shadow border border-gray-200 text-gray-400">
              <GripVertical size={14} />
            </div>
          </div>
        ))}
      {children}
    </div>
  );
};

// Dunne invoeg-zone tussen twee widgets; licht op bij slepen erboven.
const DashDropZone = ({ targetId, before, onDropAt, pos }) => {
  const [over, setOver] = useState(false);
  return (
    <div
      onDragOver={(e) => {
        e.preventDefault();
        setOver(true);
      }}
      onDragLeave={() => setOver(false)}
      onDrop={(e) => {
        e.preventDefault();
        setOver(false);
        const from = e.dataTransfer.getData("widgetId");
        if (from) onDropAt(from, targetId, before);
      }}
      className="absolute left-0 right-0 z-30"
      style={{ [pos]: -7, height: 14 }}
    >
      <div
        className="absolute left-1 right-1"
        style={{
          [pos]: 0,
          height: 3,
          borderRadius: 999,
          background: over ? C.Lagoon : "transparent",
          transition: "background .1s ease",
        }}
      />
    </div>
  );
};

const colSpanClass = (size) => {
  // In columns-layout werkt col-span niet; column-span via inline style
  return "";
};

const colSpanStyle = (size) => {
  if (size === 3) return { columnSpan: "all" };
  return {};
};

// Echte React component zodat hooks (useState, custom hooks) geldig zijn
const DashboardContent = ({
  loggedInUserName,
  appData,
  saveData,
  currentTheme,
  currentDay,
  setView,
  setCurrentDay,
  handoverUnreadCount,
  todaysSchedule,
  entTasks,
  creaTasks,
  extraTasks,
  hotspotTasks,
  programExpanded,
  setProgramExpanded,
  userRole,
  triggerAlert,
  triggerConfirm,
  AISummaryWidgetComponent,
  setAdminSubView,
}) => {
  const { layout, setSize, reorder, placeRelative, placeInColumn } =
    useDashboardLayout(loggedInUserName, appData, saveData);
  const [editing, setEditing] = React.useState(false);
  const calcCols = () =>
    window.innerWidth < 768 ? 1 : window.innerWidth < 1024 ? 2 : 3;
  const [isMobile, setIsMobile] = React.useState(() => window.innerWidth < 768);
  const [numCols, setNumCols] = React.useState(calcCols);
  React.useEffect(() => {
    const handler = () => {
      setIsMobile(window.innerWidth < 768);
      setNumCols(calcCols());
    };
    window.addEventListener("resize", handler);
    return () => window.removeEventListener("resize", handler);
  }, []);

  const primary = currentTheme.primary;

  // Lokaal weggeklikte mededelingen per gebruiker (afsluitbaar prikbord)
  const [dismissedAnns, setDismissedAnns] = React.useState(() => {
    try {
      return new Set(
        JSON.parse(
          localStorage.getItem(`cp_dismissedAnns_${loggedInUserName}`) || "[]"
        )
      );
    } catch {
      return new Set();
    }
  });
  const dismissAnn = (id) => {
    setDismissedAnns((prev) => {
      const next = new Set(prev);
      next.add(id);
      try {
        localStorage.setItem(
          `cp_dismissedAnns_${loggedInUserName}`,
          JSON.stringify([...next])
        );
      } catch {}
      return next;
    });
  };

  const visibleLayout = layout.filter((w) => {
    if (w.id === "swaps" && userRole !== "fm") return false;
    if (w.id === "checklist" && userRole !== "fm") return false;
    if (w.id === "handover" && userRole === "co") return false;
    return true;
  });

  // Eén volgorde over alle apparaten — mobiel toont dezelfde opgeslagen layout
  // als één kolom. Voorkomt een verspringende lijst bij het verschuiven.
  const activeLayout = visibleLayout;

  // Mobiel verschuiven: zoek de buur in de zichtbare volgorde en wissel om.
  const moveWidget = (id, dir) => {
    const ids = activeLayout.map((w) => w.id);
    const i = ids.indexOf(id);
    const j = dir === "up" ? i - 1 : i + 1;
    if (i < 0 || j < 0 || j >= ids.length) return;
    reorder(id, ids[j]);
  };

  const renderWidget = (id) => {
    const dayKey = toIsoDate(currentDay);
    switch (id) {
      case "ai":
        return (
          <div className="rounded-2xl shadow-sm border border-gray-100 bg-white overflow-hidden h-full flex flex-col">
            <AISummaryWidgetComponent
              currentDay={currentDay}
              loggedInUserName={loggedInUserName}
              appData={appData}
              todaysSchedule={todaysSchedule}
              entTasks={entTasks}
              creaTasks={creaTasks}
              extraTasks={extraTasks}
              currentTheme={currentTheme}
            />
            {(() => {
              const bdays = [
                ...(appData.staffList || []).filter((s) => {
                  if (!s.dob) return false;
                  const d = new Date(s.dob);
                  return (
                    d.getDate() === currentDay.getDate() &&
                    d.getMonth() === currentDay.getMonth()
                  );
                }),
                ...(appData.settings?.fmDob
                  ? (() => {
                      const d = new Date(appData.settings.fmDob);
                      return d.getDate() === currentDay.getDate() &&
                        d.getMonth() === currentDay.getMonth()
                        ? [{ name: "Maik", dob: appData.settings.fmDob }]
                        : [];
                    })()
                  : []),
              ];
              if (!bdays.length) return null;
              return (
                <div className="px-4 pb-3 space-y-2">
                  {bdays.map((b) => {
                    const age =
                      currentDay.getFullYear() - new Date(b.dob).getFullYear();
                    return (
                      <div
                        key={b.name}
                        className="p-3 rounded-xl border flex items-center gap-3"
                        style={{
                          backgroundColor: `${C.Pine}0D`,
                          borderColor: `${C.Pine}30`,
                        }}
                      >
                        <ProfileAvatar
                          name={b.name}
                          staffList={appData.staffList || []}
                          size={36}
                          color={C.Pine}
                        />
                        <div>
                          <div
                            className="text-xs font-semibold"
                            style={{ color: C.Pine }}
                          >
                            🎂 {b.name} wordt vandaag {age} jaar!
                          </div>
                          <div className="text-xs text-gray-500">
                            Vergeet niet te feliciteren
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              );
            })()}
          </div>
        );
      case "announcements": {
        const today0 = new Date().setHours(0, 0, 0, 0);
        const anns = (appData.settings?.announcements || [])
          .filter(
            (a) =>
              !a.expiryDate ||
              new Date(a.expiryDate).setHours(0, 0, 0, 0) >= today0
          )
          .filter((a) => !dismissedAnns.has(a.id));
        return (
          <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden flex flex-col h-full">
            <div className="px-4 py-3 flex items-center gap-2.5 border-b border-gray-100">
              <div
                className="w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0"
                style={{ backgroundColor: `${C.Sunset}1A` }}
              >
                <Megaphone size={18} style={{ color: C.Sunset }} />
              </div>
              <h3 className="text-sm font-bold" style={{ color: C.Lagoon }}>
                Mededelingen
              </h3>
              {anns.length > 0 && (
                <span
                  className="text-[10px] font-bold px-1.5 py-0.5 rounded-full text-white"
                  style={{ backgroundColor: C.Sunset }}
                >
                  {anns.length}
                </span>
              )}
              {userRole === "fm" && (
                <button
                  onClick={() => {
                    setView("admin");
                    setAdminSubView("settings");
                  }}
                  className="ml-auto flex items-center gap-1 text-xs font-semibold px-2.5 py-1 rounded-lg hover:opacity-80"
                  style={{ color: C.Sunset, backgroundColor: `${C.Sunset}14` }}
                >
                  Beheren
                </button>
              )}
            </div>
            <div className="px-4 pt-3 pb-4 space-y-2 flex-1">
              {anns.length === 0 ? (
                <div className="text-xs text-gray-400 py-2">
                  Geen mededelingen.
                </div>
              ) : (
                anns.map((a) => {
                  const hasRead = a.readBy?.includes(loggedInUserName);
                  let countdown = null;
                  if (a.expiryDate) {
                    const days = Math.round(
                      (new Date(a.expiryDate).setHours(0, 0, 0, 0) - today0) /
                        86400000
                    );
                    countdown =
                      days <= 0
                        ? "Verloopt vandaag"
                        : days === 1
                        ? "Nog 1 dag"
                        : `Nog ${days} dagen`;
                  }
                  return (
                    <div
                      key={a.id}
                      className="p-3 rounded-xl border relative"
                      style={{
                        backgroundColor: `${C.Sunset}0D`,
                        borderColor: `${C.Sunset}30`,
                      }}
                    >
                      <button
                        onClick={() => {
                          if (!hasRead) {
                            const updated = (
                              appData.settings?.announcements || []
                            ).map((ann) =>
                              ann.id === a.id
                                ? {
                                    ...ann,
                                    readBy: [
                                      ...(ann.readBy || []),
                                      loggedInUserName,
                                    ],
                                  }
                                : ann
                            );
                            saveData({
                              settings: {
                                ...appData.settings,
                                announcements: updated,
                              },
                            });
                          }
                          dismissAnn(a.id);
                        }}
                        className="absolute top-2 right-2 text-gray-400 hover:text-gray-600"
                        title="Sluiten"
                      >
                        <CloseIcon size={14} />
                      </button>
                      <div className="flex items-start gap-2 pr-5">
                        <AlertCircle
                          size={16}
                          style={{ color: C.Sunset }}
                          className="flex-shrink-0 mt-0.5"
                        />
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 flex-wrap">
                            <span
                              className="text-xs font-semibold"
                              style={{ color: C.Sunset }}
                            >
                              {a.title}
                            </span>
                            {!hasRead && (
                              <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-red-500 text-white font-bold">
                                NIEUW
                              </span>
                            )}
                          </div>
                          <p className="text-xs text-gray-600 mt-0.5 whitespace-pre-wrap">
                            {a.text}
                          </p>
                          {countdown && (
                            <div
                              className="inline-flex items-center gap-1 mt-1.5 text-[10px] font-semibold px-1.5 py-0.5 rounded-md"
                              style={{
                                backgroundColor: `${C.Sunset}14`,
                                color: C.Sunset,
                              }}
                            >
                              <Clock size={10} /> {countdown}
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  );
                })
              )}
            </div>
          </div>
        );
      }

      case "timeline":
        return (
          <div className="rounded-2xl shadow-sm border border-gray-100 bg-white overflow-hidden h-full flex flex-col">
            <MijnDagWidget
              embedded
              appData={appData}
              loggedInUserName={loggedInUserName}
              currentDay={currentDay}
              currentTheme={currentTheme}
              saveData={saveData}
              setView={setView}
              handoverUnreadCount={handoverUnreadCount}
              summarySlot={null}
            />
          </div>
        );
      case "swaps":
        return userRole === "fm" ? (
          <SwapRequestsWidget
            appData={appData}
            onViewSwaps={() => setView("rooster")}
            theme={currentTheme}
            userRole={userRole}
          />
        ) : null;
      case "team": {
        const todaysShiftsRaw2 = appData.workSchedule?.[dayKey] || [];
        // Wie werkt er die dag = puur workSchedule.matchedUser (de waarheid),
        // zodat élke wijziging (ziek/ruil/bewerk/verwijder) meteen zichtbaar is.
        const ts2 = todaysShiftsRaw2.filter((s) => s.matchedUser);
        const staff2 = [...new Set(ts2.map((s) => s.matchedUser))];
        const dv2 = appData.dailyDv?.[dayKey];
        const fm2 = appData.dailyFmPresent?.[dayKey];
        const respName = fm2 ? "Maik" : dv2 || null;
        const respRole = fm2 ? "Floormanager" : "Dagverantwoordelijke";
        // Starttijd -> minuten, voor chronologische sortering
        const toMin2 = (t) => {
          if (!t || typeof t !== "string") return 99999;
          const [hh, mm] = t.split(":").map(Number);
          return (hh || 0) * 60 + (mm || 0);
        };
        // Alle aanwezigen incl. verantwoordelijke (ook zonder shift)
        const allNames2 = [...staff2];
        if (respName && !allNames2.includes(respName)) allNames2.push(respName);
        const teamEntries2 = allNames2
          .map((name) => ({
            name,
            shift: ts2.find((x) => x.matchedUser === name) || null,
            isResp: name === respName,
          }))
          .sort((a, b) => {
            const am = a.shift ? toMin2(a.shift.start) : 99999;
            const bm = b.shift ? toMin2(b.shift.start) : 99999;
            return am !== bm ? am - bm : a.name.localeCompare(b.name);
          });
        return (
          <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden flex flex-col h-full">
            <div className="px-4 py-3 flex items-center gap-2.5 border-b border-gray-100">
              <div
                className="w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0"
                style={{ backgroundColor: `${primary}1A` }}
              >
                <Users size={18} style={{ color: primary }} />
              </div>
              <h3 className="text-sm font-bold" style={{ color: C.Lagoon }}>
                Team vandaag
              </h3>
              <button
                onClick={() => setView("rooster")}
                className="ml-auto flex items-center gap-1 text-xs font-semibold px-2.5 py-1 rounded-lg hover:opacity-80"
                style={{ color: primary, backgroundColor: `${primary}14` }}
              >
                Rooster <ChevronRight size={14} />
              </button>
            </div>
            <div className="px-4 pt-3 pb-4 space-y-2">
              {userRole === "fm" && (
                <div
                  className="rounded-xl border p-3 space-y-2.5"
                  style={{
                    backgroundColor: `${primary}0A`,
                    borderColor: `${primary}26`,
                  }}
                >
                  <div className="flex items-center gap-1.5">
                    <Settings size={13} style={{ color: primary }} />
                    <span
                      className="text-[11px] font-bold uppercase tracking-wide"
                      style={{ color: primary }}
                    >
                      FM Beheer
                    </span>
                  </div>
                  {/* Aanwezig — toggle-pill i.p.v. kale checkbox */}
                  <button
                    onClick={() =>
                      saveData({
                        dailyFmPresent: {
                          ...appData.dailyFmPresent,
                          [dayKey]: !fm2,
                        },
                      })
                    }
                    className="w-full flex items-center justify-between gap-2 px-3 py-2 rounded-lg border transition-all active:scale-[0.99]"
                    style={{
                      backgroundColor: fm2 ? primary : "#fff",
                      borderColor: fm2 ? primary : `${primary}26`,
                    }}
                  >
                    <span
                      className="text-xs font-semibold"
                      style={{ color: fm2 ? "#fff" : C.Lagoon }}
                    >
                      Ik ben aanwezig
                    </span>
                    <span
                      className="w-9 h-5 rounded-full flex items-center px-0.5 transition-all"
                      style={{
                        backgroundColor: fm2
                          ? "rgba(255,255,255,0.35)"
                          : `${primary}26`,
                        justifyContent: fm2 ? "flex-end" : "flex-start",
                      }}
                    >
                      <span className="w-4 h-4 rounded-full bg-white shadow-sm" />
                    </span>
                  </button>
                  {/* Dagverantwoordelijke — nette select */}
                  <div className="relative">
                    <select
                      className="w-full appearance-none border rounded-lg text-xs bg-white pl-3 pr-8 py-2 font-medium focus:outline-none cursor-pointer"
                      style={{ borderColor: `${primary}33`, color: C.Lagoon }}
                      value={dv2 || ""}
                      onChange={(e) =>
                        saveData({
                          dailyDv: {
                            ...appData.dailyDv,
                            [dayKey]: e.target.value || null,
                          },
                        })
                      }
                    >
                      <option value="">Wijs dagverantwoordelijke toe…</option>
                      {staff2
                        .filter((n) => n !== "Maik")
                        .map((n) => (
                          <option key={n} value={n}>
                            {n}
                          </option>
                        ))}
                    </select>
                    <ChevronRight
                      size={14}
                      className="absolute right-2.5 top-1/2 -translate-y-1/2 rotate-90 pointer-events-none"
                      style={{ color: primary }}
                    />
                  </div>
                </div>
              )}
              {(() => {
                const seg = ts2
                  .filter(
                    (s) =>
                      toMin2(s.start) < 99999 &&
                      toMin2(s.end) < 99999 &&
                      toMin2(s.end) > toMin2(s.start)
                  )
                  .map((s) => ({
                    name: s.matchedUser,
                    start: toMin2(s.start),
                    end: toMin2(s.end),
                  }))
                  .sort((a, b) => a.start - b.start);
                if (seg.length === 0) return null;
                const winStart =
                  Math.floor(Math.min(...seg.map((s) => s.start)) / 60) * 60;
                const winEnd =
                  Math.ceil(Math.max(...seg.map((s) => s.end)) / 60) * 60;
                const span = Math.max(winEnd - winStart, 60);
                const isToday = toIsoDate(currentDay) === toIsoDate(new Date());
                const nowM = isToday
                  ? new Date().getHours() * 60 + new Date().getMinutes()
                  : null;
                const nowPct =
                  nowM !== null && nowM >= winStart && nowM <= winEnd
                    ? ((nowM - winStart) / span) * 100
                    : null;
                const fmt = (m) =>
                  `${String(Math.floor(m / 60)).padStart(2, "0")}:${String(
                    m % 60
                  ).padStart(2, "0")}`;
                return (
                  <div className="mb-1">
                    <div className="space-y-1">
                      {seg.map((s, i) => (
                        <div key={i} className="flex items-center gap-2">
                          <span className="text-[10px] text-gray-500 w-14 truncate flex-shrink-0">
                            {s.name}
                          </span>
                          <div className="relative flex-1 h-3 rounded-full bg-gray-100 overflow-hidden">
                            <div
                              className="absolute top-0 bottom-0 rounded-full"
                              style={{
                                left: `${((s.start - winStart) / span) * 100}%`,
                                width: `${((s.end - s.start) / span) * 100}%`,
                                backgroundColor:
                                  s.name === respName ? C.Pine : primary,
                                opacity: 0.85,
                              }}
                            />
                            {nowPct !== null && (
                              <div
                                className="absolute top-0 bottom-0 w-px z-10"
                                style={{
                                  left: `${nowPct}%`,
                                  backgroundColor: C.Sunset,
                                }}
                              />
                            )}
                          </div>
                        </div>
                      ))}
                    </div>
                    <div className="flex items-center gap-2 mt-1">
                      <span className="w-14 flex-shrink-0" />
                      <div className="flex-1 flex justify-between">
                        <span className="text-[9px] text-gray-400">
                          {fmt(winStart)}
                        </span>
                        {nowPct !== null && (
                          <span
                            className="text-[9px] font-semibold"
                            style={{ color: C.Sunset }}
                          >
                            nu {fmt(nowM)}
                          </span>
                        )}
                        <span className="text-[9px] text-gray-400">
                          {fmt(winEnd)}
                        </span>
                      </div>
                    </div>
                  </div>
                );
              })()}
              <div>
                <div className="text-[11px] font-semibold uppercase tracking-wide mb-1.5 text-gray-400">
                  Aanwezig ({allNames2.length})
                </div>
                <div className="space-y-1.5">
                  {teamEntries2.map(({ name, shift, isResp }) => (
                    <div
                      key={name}
                      className="flex items-center gap-2 rounded-xl"
                      style={
                        isResp
                          ? {
                              backgroundColor: `${C.Grass}59`,
                              border: `1px solid ${C.Pine}3D`,
                              padding: "6px 8px",
                            }
                          : undefined
                      }
                    >
                      <ProfileAvatar
                        name={name}
                        staffList={appData.staffList || []}
                        size={28}
                        color={isResp ? C.Pine : primary}
                      />
                      <div className="min-w-0 flex-1">
                        <div className="flex items-center gap-1.5 flex-wrap">
                          <span
                            className="text-xs font-semibold truncate"
                            style={{ color: isResp ? C.Pine : C.Lagoon }}
                          >
                            {name}
                          </span>
                          {isResp && (
                            <span
                              className="text-[9px] font-bold uppercase tracking-wide px-1.5 py-0.5 rounded-md flex-shrink-0"
                              style={{ backgroundColor: C.Pine, color: "#fff" }}
                            >
                              Verantwoordelijke
                            </span>
                          )}
                        </div>
                        {shift ? (
                          <div
                            className="text-[11px]"
                            style={{ color: isResp ? C.Pine : "#9ca3af" }}
                          >
                            {shift.start}–{shift.end}
                            {shift.location ? ` · ${shift.location}` : ""}
                          </div>
                        ) : (
                          isResp && (
                            <div
                              className="text-[11px]"
                              style={{ color: C.Pine }}
                            >
                              {respRole}
                            </div>
                          )
                        )}
                      </div>
                    </div>
                  ))}
                  {allNames2.length === 0 && (
                    <div className="text-xs text-gray-400">
                      Nog niemand ingepland
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        );
      }
      case "occupancy": {
        const st3 = appData.dailyStats?.[dayKey] || {};
        const tot3 =
          st3.total > 0
            ? st3.total
            : (st3.adults || 0) + (st3.kids || 0) + (st3.babies || 0);
        const bt3 =
          (st3.adults || 0) + (st3.kids || 0) + (st3.babies || 0) || 1;
        const sg3 = [
          { label: "Volwassenen", count: st3.adults || 0, color: primary },
          { label: "Kinderen", count: st3.kids || 0, color: C.Honey },
          { label: "Baby's", count: st3.babies || 0, color: C.Blossom },
        ].filter((s) => s.count > 0);
        const br3 = st3.breakdown || {};
        const col3 = [
          primary,
          C.Sky,
          C.Honey,
          C.Blossom,
          C.Bark,
          C.Grass,
          C.Sunset,
        ];
        const nat3 = NATIONALITIES.filter((n) => (br3[n.k] || 0) > 0)
          .map((n) => ({
            ...n,
            count: br3[n.k] || 0,
            pct: Math.round(((br3[n.k] || 0) / (tot3 || 1)) * 100),
          }))
          .sort((a, b) => b.count - a.count);
        const circ3 = 2 * Math.PI * 30;
        return (
          <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden flex flex-col h-full">
            <div className="px-4 py-3 flex items-center gap-2.5 border-b border-gray-100">
              <div
                className="w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0"
                style={{ backgroundColor: `${primary}1A` }}
              >
                <Home size={18} style={{ color: primary }} />
              </div>
              <h3 className="text-sm font-bold" style={{ color: C.Lagoon }}>
                Bezetting
              </h3>
            </div>
            <div className="px-4 pt-3 pb-4 space-y-3">
              <div className="flex gap-4">
                <div>
                  <div
                    className="text-3xl font-bold leading-none"
                    style={{ color: C.Lagoon }}
                  >
                    {tot3}
                  </div>
                  <div className="text-[11px] text-gray-400 uppercase tracking-wide mt-0.5">
                    Totaal gasten
                  </div>
                </div>
                {(st3.villas || 0) > 0 && (
                  <div
                    className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl self-start"
                    style={{ backgroundColor: `${primary}14` }}
                  >
                    <Home size={14} style={{ color: primary }} />
                    <div>
                      <div
                        className="text-sm font-bold leading-none"
                        style={{ color: primary }}
                      >
                        {st3.villas}
                      </div>
                      <div className="text-[11px] text-gray-400 uppercase tracking-wide">
                        Cottages
                      </div>
                    </div>
                  </div>
                )}
              </div>
              {sg3.length > 0 && (
                <div>
                  <div className="flex rounded-lg overflow-hidden h-2.5 mb-1.5">
                    {sg3.map((s, i) => (
                      <div
                        key={i}
                        style={{
                          width: `${(s.count / bt3) * 100}%`,
                          backgroundColor: s.color,
                        }}
                      />
                    ))}
                  </div>
                  <div className="flex gap-3 flex-wrap">
                    {sg3.map((s, i) => (
                      <div
                        key={i}
                        className="flex items-center gap-1 text-[11px] text-gray-500"
                      >
                        <div
                          className="w-2 h-2 rounded-full flex-shrink-0"
                          style={{ backgroundColor: s.color }}
                        />
                        {s.label}{" "}
                        <span className="font-semibold text-gray-700">
                          {s.count}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
              {nat3.length > 0 && (
                <div>
                  <div
                    className="text-[11px] font-semibold mb-2 flex items-center gap-1.5 uppercase tracking-wide"
                    style={{ color: C.Lagoon }}
                  >
                    <Globe size={12} /> Nationaliteiten
                  </div>
                  <div className="flex items-center gap-3">
                    <svg
                      width={88}
                      height={88}
                      className="flex-shrink-0 -rotate-90"
                    >
                      {(() => {
                        let off = 0;
                        return nat3.map((n, i) => {
                          const dash = (n.pct / 100) * circ3;
                          const el = (
                            <circle
                              key={i}
                              cx={44}
                              cy={44}
                              r={30}
                              fill="none"
                              stroke={col3[i % col3.length]}
                              strokeWidth={16}
                              strokeDasharray={`${dash} ${circ3 - dash}`}
                              strokeDashoffset={-off}
                            />
                          );
                          off += dash;
                          return el;
                        });
                      })()}
                      <circle cx={44} cy={44} r={20} fill="white" />
                    </svg>
                    <div className="flex flex-col gap-1 flex-1 min-w-0">
                      {nat3.map((n, i) => (
                        <div
                          key={n.k}
                          className="flex items-center gap-1.5 text-[11px] text-gray-600 min-w-0"
                        >
                          <div
                            className="w-2 h-2 rounded-full flex-shrink-0"
                            style={{ backgroundColor: col3[i % col3.length] }}
                          />
                          <span className="truncate">
                            {n.i} {n.l}
                          </span>
                          <span className="ml-auto flex-shrink-0 font-semibold text-gray-700">
                            {n.count}{" "}
                            <span className="font-normal text-gray-400">
                              ({n.pct}%)
                            </span>
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              )}
              <button
                onClick={() => setView("occupancy")}
                className="w-full py-2 rounded-lg font-semibold text-sm flex items-center justify-center gap-1.5 hover:opacity-80 mt-auto"
                style={{ backgroundColor: `${primary}14`, color: primary }}
              >
                Ga naar Bezetting <ChevronRight size={16} />
              </button>
            </div>
          </div>
        );
      }
      case "handover": {
        if (userRole === "co") return null;
        // 🧩 Dagbord-widget (vervangt de losse overdracht-widget)
        const dbToday = appData.dagbord?.[toIsoDate(new Date())] || {};
        const dbBriefing =
          dbToday.briefing && !dbToday.briefing.deleted && dbToday.briefing.text
            ? dbToday.briefing
            : null;
        const dbRead =
          !dbBriefing ||
          dbBriefing.author === loggedInUserName ||
          (dbToday[`read_${dbSlug(loggedInUserName)}`]?.at || 0) >=
            (dbBriefing.updatedAt || 0);
        const dbOpen = Object.values(appData.openPunten || {}).filter(
          (p) => p && !p.deleted && p.status !== "opgelost"
        );
        const dbMine = dbOpen.filter((p) => p.assignee === loggedInUserName);
        const dbAttention = getDagbordAttention(appData, loggedInUserName);
        return (
          <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden flex flex-col h-full">
            <div className="w-full px-4 py-3 flex items-center gap-2.5 border-b border-gray-100">
              <div
                className="w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0"
                style={{ backgroundColor: `${primary}1A` }}
              >
                <CalendarCheck2 size={18} style={{ color: primary }} />
              </div>
              <div className="flex-1 min-w-0">
                <h3 className="text-sm font-bold" style={{ color: C.Lagoon }}>
                  Dagbord
                </h3>
                <p className="text-xs text-gray-500">
                  {dbOpen.length > 0
                    ? `${dbOpen.length} open ${dbOpen.length === 1 ? "punt" : "punten"}`
                    : "Geen open punten"}
                </p>
              </div>
              {dbAttention > 0 && (
                <span
                  className="px-2.5 py-0.5 rounded-full text-xs font-bold text-white flex-shrink-0"
                  style={{ backgroundColor: primary }}
                >
                  {dbAttention}
                </span>
              )}
            </div>
            <div className="px-4 pt-3 space-y-2">
              {dbBriefing ? (
                <div
                  className="rounded-xl px-3 py-2"
                  style={{ backgroundColor: dbRead ? "#F9FAFB" : C.PineLight }}
                >
                  <p className="text-[11px] font-semibold" style={{ color: C.Pine }}>
                    Briefing{!dbRead && " · nog niet gelezen"}
                  </p>
                  <p className="text-xs text-gray-700 line-clamp-3 whitespace-pre-wrap">
                    {dbBriefing.text}
                  </p>
                </div>
              ) : (
                <p className="text-xs text-gray-400 italic">
                  Nog geen briefing voor vandaag.
                </p>
              )}
              {dbMine.length > 0 && (
                <p className="text-xs font-semibold" style={{ color: "#B45309" }}>
                  {dbMine.length} open {dbMine.length === 1 ? "punt staat" : "punten staan"} op jouw naam
                </p>
              )}
            </div>
            <div className="px-4 pt-2 pb-4 mt-auto">
              <button
                onClick={() => {
                  setView("dagbord");
                  setCurrentDay(new Date());
                }}
                className="w-full py-2 rounded-lg font-semibold text-sm flex items-center justify-center gap-1.5 hover:opacity-80"
                style={{ backgroundColor: `${primary}14`, color: primary }}
              >
                Open dagbord <ChevronRight size={16} />
              </button>
            </div>
          </div>
        );
      }
      case "checklist":
        if (userRole !== "fm") return null;
        {
          const template4 = appData.checklistTemplates?.fm || [];
          const checks4 = appData.checklists?.fm?.[dayKey] || {};
          const done4 = template4.filter((t) => checks4[t.id]);
          const pct4 = template4.length
            ? Math.round((done4.length / template4.length) * 100)
            : 0;
          return (
            <div>
              <button
                onClick={() => setView("fm_checklist")}
                className="w-full flex flex-col rounded-2xl border border-gray-100 p-3.5 hover:shadow-sm text-left cp-dashboard-card bg-white"
              >
                <div className="flex items-center gap-2.5 mb-4 pb-3 border-b border-gray-100">
                  <div
                    className="w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0"
                    style={{ backgroundColor: `${primary}1A` }}
                  >
                    <ClipboardCheck size={18} style={{ color: primary }} />
                  </div>
                  <h3 className="font-bold text-sm" style={{ color: C.Lagoon }}>
                    FM Checklist
                  </h3>
                </div>
                {template4.length === 0 ? (
                  <div className="flex items-center gap-1.5 text-xs text-gray-400 mt-auto">
                    <Plus size={13} /> Nog geen checklist-items — tik om toe te
                    voegen
                  </div>
                ) : (
                  <>
                    <div className="flex justify-between text-xs text-gray-500 mb-1.5">
                      <span>
                        {done4.length}/{template4.length} klaar
                      </span>
                      <span className="font-bold" style={{ color: primary }}>
                        {pct4}%
                      </span>
                    </div>
                    <div className="w-full bg-gray-100 rounded-full h-2 overflow-hidden mt-auto">
                      <div
                        className="h-2 rounded-full transition-all"
                        style={{ backgroundColor: primary, width: `${pct4}%` }}
                      />
                    </div>
                  </>
                )}
              </button>
            </div>
          );
        }
      case "tasks":
        return (
          <div className="rounded-2xl shadow-sm border border-gray-100 bg-white h-full overflow-hidden">
            <div className="px-4 py-3 flex items-center gap-2.5 border-b border-gray-100">
              <div
                className="w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0"
                style={{ backgroundColor: `${primary}1A` }}
              >
                <ListChecks size={18} style={{ color: primary }} />
              </div>
              <h3 className="text-sm font-bold" style={{ color: C.Lagoon }}>
                Taken vandaag
              </h3>
            </div>
            <div className="px-4 pt-3 pb-4">
              <div className="grid gap-3 grid-cols-[repeat(auto-fit,minmax(190px,1fr))]">
                {(() => {
                  const tot = entTasks.length;
                  const dn = entTasks.filter((t) => t.done).length;
                  const pt = tot ? Math.round((dn / tot) * 100) : 0;
                  return (
                    <div className="p-3 rounded-xl border border-gray-100 bg-white">
                      <div className="flex items-center gap-2 mb-2">
                        <Mic size={15} style={{ color: C.Bark }} />
                        <span
                          className="text-xs font-semibold"
                          style={{ color: C.Bark }}
                        >
                          Entertainment
                        </span>
                      </div>
                      {tot === 0 ? (
                        <p className="text-xs text-gray-400">Geen taken</p>
                      ) : (
                        <>
                          <p className="text-xs text-gray-500 mb-2">
                            {dn}/{tot} ({pt}%)
                          </p>
                          <button
                            onClick={() => setView("checks")}
                            className="w-full flex items-center justify-center gap-1 py-2 rounded-lg text-xs font-semibold transition-all hover:opacity-90 active:scale-[0.99]"
                            style={{
                              backgroundColor: `${C.Bark}14`,
                              color: C.Bark,
                            }}
                          >
                            Bekijk taken <ChevronRight size={13} />
                          </button>
                        </>
                      )}
                    </div>
                  );
                })()}
                {appData.dailyCrea?.[dayKey]?.open !== false &&
                  (() => {
                    const tot = creaTasks.length;
                    const dn = creaTasks.filter((t) => t.done).length;
                    const pt = tot ? Math.round((dn / tot) * 100) : 0;
                    return (
                      <div className="p-3 rounded-xl border border-gray-100 bg-white">
                        <div className="flex items-center gap-2 mb-2">
                          <Palette size={15} style={{ color: C.Lagoon }} />
                          <span
                            className="text-xs font-semibold"
                            style={{ color: C.Lagoon }}
                          >
                            Crea Club
                          </span>
                        </div>
                        {tot === 0 ? (
                          <p className="text-xs text-gray-400">Geen taken</p>
                        ) : (
                          <>
                            <p className="text-xs text-gray-500 mb-2">
                              {dn}/{tot} ({pt}%)
                            </p>
                            <button
                              onClick={() => setView("checks")}
                              className="w-full flex items-center justify-center gap-1 py-2 rounded-lg text-xs font-semibold transition-all hover:opacity-90 active:scale-[0.99]"
                              style={{
                                backgroundColor: `${C.Lagoon}14`,
                                color: C.Lagoon,
                              }}
                            >
                              Bekijk taken <ChevronRight size={13} />
                            </button>
                          </>
                        )}
                      </div>
                    );
                  })()}
                {appData.dailyHotspot?.[dayKey]?.open !== false &&
                  (() => {
                    const tot = hotspotTasks.length;
                    const dn = hotspotTasks.filter((t) => t.done).length;
                    const pt = tot ? Math.round((dn / tot) * 100) : 0;
                    return (
                      <div className="p-3 rounded-xl border border-gray-100 bg-white">
                        <div className="flex items-center gap-2 mb-2">
                          <MapPin size={15} style={{ color: "#FF8A3D" }} />
                          <span
                            className="text-xs font-semibold"
                            style={{ color: "#FF8A3D" }}
                          >
                            Hotspot
                          </span>
                        </div>
                        {tot === 0 ? (
                          <p className="text-xs text-gray-400">Geen taken</p>
                        ) : (
                          <>
                            <p className="text-xs text-gray-500 mb-2">
                              {dn}/{tot} ({pt}%)
                            </p>
                            <button
                              onClick={() => setView("checks")}
                              className="w-full flex items-center justify-center gap-1 py-2 rounded-lg text-xs font-semibold transition-all hover:opacity-90 active:scale-[0.99]"
                              style={{
                                backgroundColor: "#FF8A3D14",
                                color: "#FF8A3D",
                              }}
                            >
                              Bekijk taken <ChevronRight size={13} />
                            </button>
                          </>
                        )}
                      </div>
                    );
                  })()}
                {(() => {
                  const tot = extraTasks.length;
                  const dn = extraTasks.filter((t) => t.done).length;
                  const pt = tot ? Math.round((dn / tot) * 100) : 0;
                  return (
                    <div className="p-3 rounded-xl border border-gray-100 bg-white">
                      <div className="flex items-center gap-2 mb-2">
                        <ClipboardList size={15} style={{ color: C.Pine }} />
                        <span
                          className="text-xs font-semibold"
                          style={{ color: C.Pine }}
                        >
                          Extra taken
                        </span>
                      </div>
                      {tot === 0 ? (
                        <p className="text-xs text-gray-400">Geen taken</p>
                      ) : (
                        <>
                          <p className="text-xs text-gray-500 mb-2">
                            {dn}/{tot} ({pt}%)
                          </p>
                          <button
                            onClick={() => setView("checks")}
                            className="w-full flex items-center justify-center gap-1 py-2 rounded-lg text-xs font-semibold transition-all hover:opacity-90 active:scale-[0.99]"
                            style={{
                              backgroundColor: `${C.Pine}14`,
                              color: C.Pine,
                            }}
                          >
                            Bekijk taken <ChevronRight size={13} />
                          </button>
                        </>
                      )}
                    </div>
                  );
                })()}
              </div>
            </div>
          </div>
        );
      case "schedule":
        return (() => {
          const sorted5 = todaysSchedule
            .slice()
            .sort((a, b) => sortActivities(a, b, currentDay));
          const displayed5 = programExpanded ? sorted5 : sorted5.slice(0, 5);
          return (
            <div className="bg-white rounded-2xl shadow-sm border border-gray-100 h-full flex flex-col overflow-hidden">
              <div className="px-4 py-3 flex items-center justify-between border-b border-gray-100 gap-2 flex-shrink-0">
                <div className="flex items-center gap-2.5 min-w-0">
                  <div
                    className="w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0"
                    style={{ backgroundColor: `${primary}1A` }}
                  >
                    <CalendarIcon size={18} style={{ color: primary }} />
                  </div>
                  <div className="min-w-0">
                    <h3
                      className="text-sm font-bold truncate"
                      style={{ color: C.Lagoon }}
                    >
                      Programma vandaag
                    </h3>
                    <p className="text-xs text-gray-500">
                      {toDutchDate(currentDay)}
                    </p>
                  </div>
                </div>
                <div className="text-right shrink-0">
                  <div
                    className="text-2xl font-bold leading-none"
                    style={{ color: C.Lagoon }}
                  >
                    {todaysSchedule.length}
                  </div>
                  <div className="text-[11px] text-gray-400 uppercase">
                    activiteiten
                  </div>
                </div>
              </div>
              <div className="px-4 pt-3 pb-4 flex flex-col flex-1">
                <div className="space-y-1 mb-3">
                  {sorted5.length > 0 ? (
                    displayed5.map((item) => {
                      const catInfo = ACTIVITY_TYPES.find(
                        (t) => t.id === item.type
                      );
                      const isPast = isActivityPast(item.time, currentDay);
                      const isNow = isActivityNow(item.time, currentDay);
                      const actStaff = item.staff || [];
                      return (
                        <div
                          key={item.id}
                          className={`flex items-center gap-2 py-1.5 px-2 rounded-lg ${
                            isPast && !isNow ? "opacity-40" : "hover:bg-gray-50"
                          }`}
                          style={
                            isNow
                              ? { backgroundColor: `${C.Pine}0D` }
                              : undefined
                          }
                        >
                          <div
                            className="w-2 h-2 rounded-full flex-shrink-0 mt-0.5"
                            style={{
                              backgroundColor: isNow
                                ? C.Pine
                                : catInfo?.bg || C.Grass,
                            }}
                          />
                          <div className="text-xs text-gray-400 flex-shrink-0 w-[76px]">
                            {item.time}
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-1.5">
                              <div className="text-sm font-medium text-gray-800 truncate">
                                {item.title}
                              </div>
                              {isNow && (
                                <span
                                  className="flex items-center gap-1 text-[9px] font-bold uppercase tracking-wide px-1.5 py-0.5 rounded-md flex-shrink-0"
                                  style={{
                                    backgroundColor: C.Pine,
                                    color: "#fff",
                                  }}
                                >
                                  <span className="w-1.5 h-1.5 rounded-full bg-white animate-pulse" />
                                  Nu bezig
                                </span>
                              )}
                            </div>
                            {item.location && (
                              <div className="flex items-center gap-0.5 text-[11px] text-gray-400 mt-0.5">
                                <MapPin size={10} className="flex-shrink-0" />
                                {item.location}
                              </div>
                            )}
                          </div>
                          {actStaff.length > 0 ? (
                            <div className="flex items-center -space-x-1.5 flex-shrink-0">
                              {actStaff.slice(0, 3).map((nm) => (
                                <div
                                  key={nm}
                                  className="rounded-full ring-2 ring-white"
                                >
                                  <ProfileAvatar
                                    name={nm}
                                    staffList={appData.staffList || []}
                                    size={20}
                                    color={primary}
                                  />
                                </div>
                              ))}
                              {actStaff.length > 3 && (
                                <span className="text-[10px] text-gray-400 pl-2.5">
                                  +{actStaff.length - 3}
                                </span>
                              )}
                            </div>
                          ) : (
                            <span
                              className="flex items-center gap-1 text-[10px] font-medium px-1.5 py-0.5 rounded-md flex-shrink-0"
                              style={{
                                backgroundColor: `${C.Honey}26`,
                                color: C.Bark,
                              }}
                              title="Geen personeel gekoppeld"
                            >
                              <AlertCircle size={10} /> Niet ingedeeld
                            </span>
                          )}
                        </div>
                      );
                    })
                  ) : (
                    <EmptyState
                      compact
                      icon={CalendarIcon}
                      message="Geen activiteiten"
                    />
                  )}
                </div>
                {sorted5.length > 5 && (
                  <button
                    onClick={() => setProgramExpanded(!programExpanded)}
                    className="w-full py-1.5 text-xs font-semibold rounded-lg mb-2 hover:opacity-80"
                    style={{ backgroundColor: `${primary}14`, color: primary }}
                  >
                    {programExpanded ? "Minder tonen" : "Meer tonen"}
                  </button>
                )}
                <button
                  onClick={() => setView("schedule")}
                  className="w-full py-2 rounded-lg font-semibold text-sm flex items-center justify-center gap-1.5 hover:opacity-80 mt-auto"
                  style={{ backgroundColor: `${primary}14`, color: primary }}
                >
                  Naar volledige programma <ChevronRight size={16} />
                </button>
              </div>
            </div>
          );
        })();
      case "quicklinks":
        return (
          <QuickLinksBar
            loggedInUserName={loggedInUserName}
            currentTheme={currentTheme}
            setView={setView}
            saveData={saveData}
            appData={appData}
            userRole={userRole}
            setAdminSubView={setAdminSubView}
            handoverUnreadCount={handoverUnreadCount}
          />
        );
      default:
        return null;
    }
  };

  return (
    <>
      <div className="flex justify-end">
        <button
          onClick={() => setEditing(!editing)}
          className="flex items-center gap-1.5 text-xs font-semibold px-3 py-1.5 rounded-xl hover:opacity-80"
          style={{
            backgroundColor: editing ? primary : `${primary}14`,
            color: editing ? "white" : primary,
          }}
        >
          <GripVertical size={14} /> {editing ? "Klaar" : "Indeling aanpassen"}
        </button>
      </div>
      {(() => {
        const cols = numCols;
        const total = activeLayout.length;
        const idxOf = {};
        activeLayout.forEach((w, i) => (idxOf[w.id] = i));
        const renderShell = (w) => {
          const content = renderWidget(w.id);
          if (!content) return null;
          return (
            <DashboardWidgetShell
              key={w.id}
              id={w.id}
              size={w.size}
              index={idxOf[w.id]}
              total={total}
              isMobile={isMobile}
              editing={editing}
              onReorder={(from, id) => placeRelative(from, id, true)}
              onMove={moveWidget}
              onResize={setSize}
              colSpanClass=""
              colSpanStyle={{}}
            >
              {content}
            </DashboardWidgetShell>
          );
        };
        // Volle-breedte widgets breken de masonry op in segmenten.
        const segments = [];
        let run = [];
        activeLayout.forEach((w) => {
          if (w.size === 3) {
            if (run.length) {
              segments.push({ type: "grid", items: run });
              run = [];
            }
            segments.push({ type: "full", item: w });
          } else {
            run.push(w);
          }
        });
        if (run.length) segments.push({ type: "grid", items: run });

        return (
          <div className="space-y-3">
            {segments.map((seg, si) => {
              const zones = editing && !isMobile;
              if (seg.type === "full") {
                const fw = seg.item;
                return (
                  <div key={`f${si}`} className="relative">
                    {renderShell(fw)}
                    {zones && (
                      <>
                        <DashDropZone
                          targetId={fw.id}
                          before={true}
                          pos="top"
                          onDropAt={placeRelative}
                        />
                        <DashDropZone
                          targetId={fw.id}
                          before={false}
                          pos="bottom"
                          onDropAt={placeRelative}
                        />
                      </>
                    )}
                  </div>
                );
              }
              // Deterministische kolom-toewijzing (kolom-voor-kolom): stabiel,
              // onafhankelijk van content-hoogte. Content groeit alleen
              // de eigen kolom — widgets springen niet meer rond.
              const buckets = Array.from({ length: cols }, () => []);
              seg.items.forEach((w) => {
                const ci = Math.min(
                  typeof w.col === "number" ? w.col : 0,
                  cols - 1
                );
                buckets[ci].push(w);
              });
              return (
                <div
                  key={`g${si}`}
                  className="grid gap-3"
                  style={{
                    gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))`,
                    alignItems: "start",
                  }}
                >
                  {buckets.map((bucket, bi) => (
                    <div key={bi} className="flex flex-col gap-3 min-w-0">
                      {zones && bucket.length === 0 && (
                        <div
                          onDragOver={(e) => e.preventDefault()}
                          onDrop={(e) => {
                            e.preventDefault();
                            const from = e.dataTransfer.getData("widgetId");
                            if (from) placeInColumn(from, bi);
                          }}
                          className="rounded-2xl border-2 border-dashed"
                          style={{
                            minHeight: 64,
                            borderColor: `${C.Lagoon}55`,
                          }}
                        />
                      )}
                      {bucket.map((w) => (
                        <div key={w.id} className="relative">
                          {renderShell(w)}
                          {zones && (
                            <>
                              <DashDropZone
                                targetId={w.id}
                                before={true}
                                pos="top"
                                onDropAt={placeRelative}
                              />
                              <DashDropZone
                                targetId={w.id}
                                before={false}
                                pos="bottom"
                                onDropAt={placeRelative}
                              />
                            </>
                          )}
                        </div>
                      ))}
                    </div>
                  ))}
                </div>
              );
            })}
          </div>
        );
      })()}
    </>
  );
};

const QuickLinksBar = ({
  loggedInUserName,
  currentTheme,
  setView,
  saveData,
  appData,
  userRole,
  setAdminSubView,
  handoverUnreadCount = 0,
}) => {
  const [editing, setEditing] = useState(false);
  const primary = currentTheme?.primary || C.Pine;
  const logoColor = CP_LOGO_COLORS[currentTheme?.id] || "#b4d6a1";

  // Persoonlijke snelkoppelingen uit appData
  const KEY = `quickLinks_${loggedInUserName}`;
  const saved = appData.userPrefs?.[KEY];
  const chosen =
    Array.isArray(saved) && saved.length
      ? saved.slice(0, 4)
      : ["schedule", "handover", "rooster", "occupancy"];

  const links = chosen
    .map((id) => ALL_QUICK_LINKS.find((l) => l.id === id))
    .filter(Boolean);

  const save = (ids) => {
    saveData({
      userPrefs: { ...appData.userPrefs, [KEY]: ids },
    });
    setEditing(false);
  };

  const fmLinksData =
    userRole === "fm"
      ? (() => {
          const openHours = (appData.hourCorrections || []).filter(
            (c) => !c.processed
          ).length;
          const openOrders = (appData.orders || []).filter(
            (o) => o.status === "open"
          ).length;
          return [
            {
              label: "Uren",
              icon: Clock,
              badge: openHours,
              action: () => {
                setView("admin");
                setAdminSubView("edit_hours");
              },
            },
            {
              label: "Bestellingen",
              icon: Layers,
              badge: openOrders,
              action: () => {
                setView("orders");
              },
            },
            {
              label: "Prog. aanpassen",
              icon: CalendarDays,
              badge: 0,
              action: () => {
                setView("admin");
                setAdminSubView("edit_schedule");
              },
            },
            {
              label: "Bez. aanpassen",
              icon: Home,
              badge: 0,
              action: () => {
                setView("admin");
                setAdminSubView("edit_stats");
              },
            },
          ];
        })()
      : null;

  const FmButton = ({ link, idx }) => {
    const Icon = link.icon;
    return (
      <button
        key={idx}
        onClick={link.action}
        className="flex-1 flex flex-col items-center gap-1 py-2.5 px-1 rounded-xl transition-colors hover:opacity-80 active:scale-95 relative"
        style={{ backgroundColor: `${primary}28` }}
      >
        {link.badge > 0 && (
          <span
            className="absolute top-1 right-1 min-w-[16px] h-4 px-1 rounded-full text-[9px] font-bold text-white flex items-center justify-center"
            style={{ backgroundColor: C.Sunset }}
          >
            {link.badge}
          </span>
        )}
        <Icon size={18} style={{ color: primary }} />
        <span
          className="text-[11px] font-semibold leading-none text-center"
          style={{ color: primary }}
        >
          {link.label}
        </span>
      </button>
    );
  };

  return (
    <>
      {/* Op desktop: alles in één rij */}
      <div className="hidden md:flex items-stretch gap-2">
        {links.map((link) => {
          const Icon = link.icon;
          const badge =
            link.id === "handover" && handoverUnreadCount > 0
              ? handoverUnreadCount
              : 0;
          return (
            <button
              key={link.id}
              onClick={() => setView(link.id)}
              className="flex-1 flex flex-col items-center gap-1 py-2.5 px-1 rounded-xl transition-colors hover:opacity-80 active:scale-95 relative"
              style={{ backgroundColor: `${primary}14` }}
            >
              {badge > 0 && (
                <span
                  className="absolute top-1 right-1 min-w-[16px] h-4 px-1 rounded-full text-[9px] font-bold text-white flex items-center justify-center"
                  style={{ backgroundColor: C.Sunset }}
                >
                  {badge}
                </span>
              )}
              <Icon size={18} style={{ color: primary }} />
              <span
                className="text-[11px] font-semibold leading-none text-center"
                style={{ color: primary }}
              >
                {link.label}
              </span>
            </button>
          );
        })}
        {fmLinksData &&
          fmLinksData.map((link, idx) => (
            <FmButton key={idx} link={link} idx={idx} />
          ))}
        <button
          onClick={() => setEditing(true)}
          className="w-8 flex flex-col items-center justify-center rounded-xl transition-opacity opacity-40 hover:opacity-90"
          title="Snelkoppelingen aanpassen"
        >
          <Edit2 size={13} style={{ color: primary }} />
        </button>
      </div>

      {/* Op mobiel: persoonlijke links + bewerkknop op rij 1, FM op rij 2 */}
      <div className="flex md:hidden flex-col gap-2">
        <div className="flex items-stretch gap-2">
          {links.map((link) => {
            const Icon = link.icon;
            const badge =
              link.id === "handover" && handoverUnreadCount > 0
                ? handoverUnreadCount
                : 0;
            return (
              <button
                key={link.id}
                onClick={() => setView(link.id)}
                className="flex-1 flex flex-col items-center gap-1 py-2.5 px-1 rounded-xl transition-colors hover:opacity-80 active:scale-95 relative"
                style={{ backgroundColor: `${primary}14` }}
              >
                {badge > 0 && (
                  <span
                    className="absolute top-1 right-1 min-w-[16px] h-4 px-1 rounded-full text-[9px] font-bold text-white flex items-center justify-center"
                    style={{ backgroundColor: C.Sunset }}
                  >
                    {badge}
                  </span>
                )}
                <Icon size={18} style={{ color: primary }} />
                <span
                  className="text-[11px] font-semibold leading-none text-center"
                  style={{ color: primary }}
                >
                  {link.label}
                </span>
              </button>
            );
          })}
        </div>
        {fmLinksData && (
          <div className="flex items-stretch gap-2">
            {fmLinksData.map((link, idx) => (
              <FmButton key={idx} link={link} idx={idx} />
            ))}
          </div>
        )}
      </div>

      {/* Kies-modal */}
      {editing && (
        <QuickLinksModal
          chosen={chosen}
          primary={primary}
          logoColor={logoColor}
          onSave={save}
          onClose={() => setEditing(false)}
        />
      )}
    </>
  );
};

const QuickLinksModal = ({ chosen, primary, logoColor, onSave, onClose }) => {
  const [selected, setSelected] = useState([...chosen]);

  const toggle = (id) => {
    if (selected.includes(id)) {
      setSelected(selected.filter((s) => s !== id));
    } else if (selected.length < 4) {
      setSelected([...selected, id]);
    }
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4"
      style={{ backgroundColor: "rgba(0,0,0,0.5)" }}
    >
      <div className="bg-white rounded-2xl shadow-sm w-full max-w-sm overflow-hidden">
        {/* Header */}
        <div
          className="px-4 py-3 flex items-center justify-between"
          style={{ backgroundColor: primary }}
        >
          <div>
            <div className="font-bold text-sm" style={{ color: logoColor }}>
              Snelkoppelingen
            </div>
            <div className="text-[11px]" style={{ color: `${logoColor}99` }}>
              Kies 4 pagina's
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded-lg"
            style={{ backgroundColor: "rgba(0,0,0,0.2)" }}
          >
            <X size={16} style={{ color: logoColor }} />
          </button>
        </div>
        {/* Grid */}
        <div className="p-4 grid grid-cols-3 gap-2 max-h-72 overflow-y-auto">
          {ALL_QUICK_LINKS.map((link) => {
            const Icon = link.icon;
            const active = selected.includes(link.id);
            const disabled = !active && selected.length >= 4;
            return (
              <button
                key={link.id}
                onClick={() => toggle(link.id)}
                disabled={disabled}
                className="flex flex-col items-center gap-1.5 py-3 px-2 rounded-xl border-2 transition-all"
                style={{
                  borderColor: active ? primary : "transparent",
                  backgroundColor: active ? `${primary}14` : "#F9FAFB",
                  opacity: disabled ? 0.35 : 1,
                }}
              >
                <Icon
                  size={20}
                  style={{ color: active ? primary : "#6B7280" }}
                />
                <span
                  className="text-[11px] font-semibold text-center leading-tight"
                  style={{ color: active ? primary : "#6B7280" }}
                >
                  {link.label}
                </span>
                {active && (
                  <span
                    className="text-[9px] font-bold px-1.5 py-0.5 rounded-full text-white"
                    style={{ backgroundColor: primary }}
                  >
                    {selected.indexOf(link.id) + 1}
                  </span>
                )}
              </button>
            );
          })}
        </div>
        {/* Footer */}
        <div className="px-4 pb-4 flex gap-2">
          <button
            onClick={onClose}
            className="flex-1 py-2 rounded-lg text-sm font-semibold text-gray-500 bg-gray-100 hover:bg-gray-200"
          >
            Annuleren
          </button>
          <button
            onClick={() => onSave(selected)}
            disabled={selected.length === 0}
            className="flex-1 py-2 rounded-lg text-sm font-semibold text-white transition-colors hover:opacity-90"
            style={{ backgroundColor: primary }}
          >
            Opslaan ({selected.length}/4)
          </button>
        </div>
      </div>
    </div>
  );
};

const MijnDagWidget = ({
  appData,
  loggedInUserName,
  currentDay,
  currentTheme,
  saveData,
  setView,
  handoverUnreadCount = 0,
  summarySlot = null,
  embedded = false,
}) => {
  // Live tikker zodat gewerkte tijd & "nu"-markering meelopen
  const [, tick] = useState(0);
  useEffect(() => {
    const id = setInterval(() => tick((n) => n + 1), 30000);
    return () => clearInterval(id);
  }, []);

  const primary = currentTheme?.primary || C.Pine;
  const dateKey = toIsoDate(currentDay);
  const todayKey = toIsoDate(new Date());
  const isToday = dateKey === todayKey;

  const shift = (appData.workSchedule?.[dateKey] || []).find(
    (s) => s.matchedUser === loggedInUserName || s.name === loggedInUserName
  );

  const myActs = (appData.schedule || [])
    .filter(
      (a) => a.date === dateKey && (a.staff || []).includes(loggedInUserName)
    )
    .sort((a, b) => sortActivities(a, b, currentDay));

  const clock = appData.timeClock?.[dateKey]?.[loggedInUserName] || {};
  const clockedIn = !!clock.in;
  const clockedOut = !!clock.out;

  const fmt = (iso) =>
    new Date(iso).toLocaleTimeString("nl-NL", {
      hour: "2-digit",
      minute: "2-digit",
    });
  const durLabel = (ms) => {
    const m = Math.max(0, Math.floor(ms / 60000));
    return `${Math.floor(m / 60)}u ${String(m % 60).padStart(2, "0")}m`;
  };
  const workedMs = clock.in
    ? (clock.out ? new Date(clock.out) : new Date()) - new Date(clock.in)
    : 0;

  const setClock = (patch) => {
    const cur = appData.timeClock?.[dateKey]?.[loggedInUserName] || {};
    saveData({
      timeClock: { [dateKey]: { [loggedInUserName]: { ...cur, ...patch } } },
    });
  };

  const nowMin = (() => {
    const n = new Date();
    return n.getHours() * 60 + n.getMinutes();
  })();
  const parseRange = (t) => {
    if (!t) return { start: null, end: null };
    const [s, e] = t.split("-").map((x) => x.trim());
    const toMin = (x) => {
      const [h, m] = (x || "").split(":").map(Number);
      return isNaN(h) ? null : h * 60 + (m || 0);
    };
    return { start: toMin(s), end: e ? toMin(e) : null };
  };
  const typeColor = (type) => {
    const t = (type || "").toLowerCase();
    if (t.includes("crea")) return C.Sky;
    if (t.includes("orry")) return C.Blossom;
    if (t.includes("spring")) return C.Blossom;
    if (t.includes("ent")) return C.Honey;
    return primary;
  };

  const items = myActs.map((a) => {
    const { start, end } = parseRange(a.time);
    const past = isActivityPast(a.time, currentDay);
    const current =
      isToday &&
      start != null &&
      nowMin >= start &&
      (end != null ? nowMin <= end : nowMin <= start + 30);
    return { a, past, current };
  });
  const nextIdx = isToday
    ? items.findIndex((it) => !it.past && !it.current)
    : -1;

  const empty = !shift && items.length === 0;

  const Wrap = embedded ? React.Fragment : "div";
  const wrapProps = embedded
    ? {}
    : {
        className:
          "rounded-2xl shadow-sm border border-gray-100 bg-white overflow-hidden cp-dashboard-card",
      };

  return (
    <Wrap {...wrapProps}>
      {!embedded && (
        <div className="px-4 py-3 flex items-center gap-2.5 border-b border-gray-100">
          <div
            className="w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0"
            style={{ backgroundColor: `${primary}1A` }}
          >
            <Clock size={18} style={{ color: primary }} />
          </div>
          <div className="min-w-0">
            <h3 className="text-sm font-bold" style={{ color: C.Lagoon }}>
              Mijn dag
            </h3>
            <p className="text-xs text-gray-500 truncate">
              {shift
                ? `Dienst ${shift.start}–${shift.end}${
                    shift.location ? " · " + shift.location : ""
                  }`
                : isToday
                ? "Geen dienst ingepland"
                : "Andere dag"}
            </p>
          </div>
        </div>
      )}

      {embedded && (
        <div className="px-4 py-3 flex items-center gap-2.5 border-b border-gray-100">
          <div
            className="w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0"
            style={{ backgroundColor: `${primary}1A` }}
          >
            <Clock size={18} style={{ color: primary }} />
          </div>
          <div className="min-w-0">
            <h3 className="text-sm font-bold" style={{ color: C.Lagoon }}>
              Mijn dag
            </h3>
            {shift && (
              <p className="text-xs text-gray-500 truncate">
                {shift.start}–{shift.end}
                {shift.location ? " · " + shift.location : ""}
              </p>
            )}
          </div>
        </div>
      )}

      {/* ⏱️ Inklokken/uitklokken tijdelijk verborgen */}

      {/* Tijdlijn */}
      <div className="px-4 py-3">
        {empty ? (
          <EmptyState
            compact
            icon={Coffee}
            message="Geen activiteiten op deze dag"
            sub="Fijne dag! 🌿"
          />
        ) : items.length === 0 ? (
          <div className="flex items-center gap-2 text-xs text-gray-400 py-1">
            <CalendarIcon size={14} />
            {shift
              ? "Geen vaste activiteiten — fijne dienst! 🌿"
              : "Geen activiteiten ingepland"}
          </div>
        ) : (
          <div>
            {items.map((it, i) => {
              const dot = it.current
                ? primary
                : it.past
                ? "#D1D5DB"
                : `${typeColor(it.a.type)}`;
              return (
                <div key={it.a.id || i} className="flex gap-3">
                  {/* Rail */}
                  <div className="flex flex-col items-center pt-1">
                    <div
                      className="w-2.5 h-2.5 rounded-full flex-shrink-0"
                      style={{
                        backgroundColor: it.past ? "#D1D5DB" : dot,
                        boxShadow: it.current
                          ? `0 0 0 3px ${primary}33`
                          : "none",
                      }}
                    />
                    {i < items.length - 1 && (
                      <div
                        className="w-px flex-1 my-1"
                        style={{ backgroundColor: "#EAECEF" }}
                      />
                    )}
                  </div>
                  {/* Inhoud */}
                  <div className={`flex-1 pb-2 ${it.past ? "opacity-55" : ""}`}>
                    <div className="flex items-center gap-2 flex-wrap">
                      <span
                        className="text-xs font-semibold"
                        style={{
                          color: it.current ? primary : C.TextSecondary,
                        }}
                      >
                        {it.a.time}
                      </span>
                      {it.current && (
                        <span
                          className="text-[11px] font-bold px-1.5 py-0.5 rounded-full text-white"
                          style={{ backgroundColor: primary }}
                        >
                          NU
                        </span>
                      )}
                      {i === nextIdx && (
                        <span
                          className="text-[11px] font-semibold px-1.5 py-0.5 rounded-full"
                          style={{
                            backgroundColor: `${primary}14`,
                            color: primary,
                          }}
                        >
                          Straks
                        </span>
                      )}
                    </div>
                    <div
                      className="text-sm font-medium"
                      style={{ color: C.Lagoon }}
                    >
                      {it.a.title}
                    </div>
                    {it.a.loc && (
                      <div className="flex items-center gap-1 text-xs text-gray-500 mt-0.5">
                        <MapPin size={11} /> {it.a.loc}
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {/* Extra: ongelezen overdrachten vóór de dienst */}
        {isToday && handoverUnreadCount > 0 && (
          <button
            onClick={() => setView("handover")}
            className="w-full mt-1 flex items-center gap-2 text-sm font-semibold px-3 py-2 rounded-lg transition-colors hover:opacity-80"
            style={{ backgroundColor: `${primary}14`, color: primary }}
          >
            <BookOpen size={16} />
            Lees {handoverUnreadCount} overdracht
            {handoverUnreadCount === 1 ? "" : "en"} voor je dienst
            <ChevronRight size={16} className="ml-auto" />
          </button>
        )}
      </div>
    </Wrap>
  );
};

// --- SCHEDULE UPLOAD VIEW ---
const ScheduleUploadView = ({
  appData,
  updateData,
  showAlert,
  theme,
  setAdminSubView,
}) => {
  const [uploading, setUploading] = useState(false);
  const [preview, setPreview] = useState(null);
  const fileInputRef = useRef(null);

  const handleFileSelect = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    if (!file.name.endsWith(".csv")) {
      showAlert("❌ Upload alleen CSV bestanden!");
      return;
    }

    setUploading(true);

    try {
      const text = await file.text();
      const { schedule, unmatchedEmployees } = parseScheduleCSV(
        text,
        appData.staffList || [],
        appData.settings.fmLastName || null
      );

      // Tel statistieken
      const totalDays = Object.keys(schedule).length;
      const allShifts = Object.values(schedule).flat();
      const totalShifts = allShifts.length;
      const matched = allShifts.filter((s) => s.matchedUser).length;
      const unmatched = allShifts.filter((s) => !s.matchedUser).length;

      // Toon preview
      setPreview({
        schedule,
        totalDays,
        totalShifts,
        matched,
        unmatched,
        unmatchedEmployees,
      });
    } catch (error) {
      console.error("Parse error:", error);
      showAlert("❌ CSV parsing mislukt! Check het bestand.");
    }

    setUploading(false);
  };

  const confirmImport = () => {
    if (!preview) return;

    // MERGE nieuwe roosters met bestaande roosters (behoud oude data!)
    updateData({
      workSchedule: { ...appData.workSchedule, ...preview.schedule },
    });

    showAlert(`✅ ${preview.totalShifts} shifts geïmporteerd!`);
    setPreview(null);
    setAdminSubView("menu");
  };

  const clearSchedule = async () => {
    const scheduleStats = getScheduleStats();
    if (!scheduleStats) return;

    const totalDays = scheduleStats.totalDays;
    const totalShifts = scheduleStats.totalShifts;

    if (
      await cpConfirm(
        `⚠️ WAARSCHUWING: Je gaat ${totalDays} dagen met ${totalShifts} shifts PERMANENT wissen!\n\nDit kan NIET ongedaan gemaakt worden!\n\nWeet je het ZEKER?`
      )
    ) {
      if (
        await cpConfirm(
          `⚠️ LAATSTE BEVESTIGING!\n\nAlle ${totalDays} dagen met roosters worden nu verwijderd.\n\nKlik OK om te bevestigen.`
        )
      ) {
        updateData({
          workSchedule: {},
        });
        showAlert("🗑️ Alle roosters gewist!");
      }
    }
  };

  // Bereken rooster statistieken
  const getScheduleStats = () => {
    if (
      !appData.workSchedule ||
      Object.keys(appData.workSchedule).length === 0
    ) {
      return null;
    }

    const dates = Object.keys(appData.workSchedule).sort();
    const allShifts = Object.values(appData.workSchedule).flat();

    return {
      dateRange:
        dates.length > 0
          ? {
              start: dates[0],
              end: dates[dates.length - 1],
            }
          : null,
      totalDays: dates.length,
      totalShifts: allShifts.length,
      uniqueEmployees: [
        ...new Set(allShifts.map((s) => s.matchedUser).filter(Boolean)),
      ].length,
    };
  };

  const scheduleStats = getScheduleStats();

  return (
    <div className="p-6 max-w-4xl mx-auto">
      {/* Header */}
      <div className="flex items-center gap-3 mb-6">
        <button
          onClick={() => setAdminSubView("menu")}
          className="p-2 rounded-lg hover:bg-gray-100"
        >
          <ArrowLeft size={24} style={{ color: theme.primary }} />
        </button>
        <div className="flex items-center gap-2">
          <CalendarDays size={28} style={{ color: theme.primary }} />
          <h2 className="text-xl font-bold" style={{ color: theme.primary }}>
            Werkrooster Beheren
          </h2>
        </div>
      </div>

      {/* Huidige rooster overzicht */}
      {scheduleStats && (
        <div
          className="bg-white rounded-2xl border-2 p-6 shadow-sm mb-6"
          style={{ borderColor: theme.primary }}
        >
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-2">
              <BarChart3 size={20} style={{ color: theme.primary }} />
              <h3
                className="font-bold text-lg"
                style={{ color: theme.primary }}
              >
                Huidig Rooster
              </h3>
            </div>
            <button
              onClick={clearSchedule}
              className="flex items-center gap-2 px-4 py-2 rounded-lg bg-red-50 text-red-600 font-bold hover:bg-red-100 transition-colors border-2 border-red-200"
            >
              <Trash2 size={16} />
              Wis Alles
            </button>
          </div>

          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="bg-gray-50 p-4 rounded-lg">
              <div className="text-xs text-gray-600 mb-1">Periode</div>
              <div
                className="font-bold text-sm"
                style={{ color: theme.primary }}
              >
                {scheduleStats.dateRange ? (
                  <>
                    {new Date(scheduleStats.dateRange.start).toLocaleDateString(
                      "nl-NL",
                      { day: "numeric", month: "short" }
                    )}
                    {" - "}
                    {new Date(scheduleStats.dateRange.end).toLocaleDateString(
                      "nl-NL",
                      { day: "numeric", month: "short", year: "numeric" }
                    )}
                  </>
                ) : (
                  "N/A"
                )}
              </div>
            </div>

            <div className="bg-gray-50 p-4 rounded-lg">
              <div className="text-xs text-gray-600 mb-1">Dagen</div>
              <div
                className="text-2xl font-bold"
                style={{ color: theme.primary }}
              >
                {scheduleStats.totalDays}
              </div>
            </div>

            <div className="bg-gray-50 p-4 rounded-lg">
              <div className="text-xs text-gray-600 mb-1">Shifts</div>
              <div
                className="text-2xl font-bold"
                style={{ color: theme.primary }}
              >
                {scheduleStats.totalShifts}
              </div>
            </div>

            <div className="bg-gray-50 p-4 rounded-lg">
              <div className="text-xs text-gray-600 mb-1">Medewerkers</div>
              <div
                className="text-2xl font-bold"
                style={{ color: theme.primary }}
              >
                {scheduleStats.uniqueEmployees}
              </div>
            </div>
          </div>
        </div>
      )}

      {!preview ? (
        <>
          {/* Instructies */}
          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 mb-6">
            <div className="flex items-start gap-3">
              <Info size={20} className="text-blue-600 mt-0.5 flex-shrink-0" />
              <div className="text-sm text-blue-800">
                <p className="font-bold mb-2">Let op:</p>
                <ul className="list-disc ml-4 space-y-1">
                  <li>
                    Zorg dat alle medewerkers in het systeem staan met correcte
                    achternamen
                  </li>
                  <li>Upload het CSV bestand van het rooster systeem</li>
                  <li>De app matcht automatisch op achternaam</li>
                </ul>
              </div>
            </div>
          </div>

          {/* Upload button */}
          <input
            ref={fileInputRef}
            type="file"
            accept=".csv"
            onChange={handleFileSelect}
            className="hidden"
          />

          <button
            onClick={() => fileInputRef.current?.click()}
            disabled={uploading}
            className="w-full py-6 border-2 border-dashed rounded-2xl flex flex-col items-center justify-center gap-3 hover:border-opacity-100 hover:bg-opacity-5 transition-all disabled:opacity-50"
            style={{
              borderColor: theme.primary,
              backgroundColor: uploading ? `${theme.primary}10` : "transparent",
            }}
          >
            {uploading ? (
              <>
                <RefreshCw
                  size={32}
                  style={{ color: theme.primary }}
                  className="animate-spin"
                />
                <span
                  className="font-bold text-lg"
                  style={{ color: theme.primary }}
                >
                  Bezig met uploaden...
                </span>
              </>
            ) : (
              <>
                <Upload size={32} style={{ color: theme.primary }} />
                <span
                  className="font-bold text-lg"
                  style={{ color: theme.primary }}
                >
                  Selecteer CSV Bestand
                </span>
                <span className="text-sm text-gray-500">
                  Klik of sleep het bestand hierheen
                </span>
              </>
            )}
          </button>
        </>
      ) : (
        /* Preview scherm */
        <div className="space-y-4">
          {/* Statistieken */}
          <div
            className="bg-white rounded-2xl border-2 p-6 shadow-sm"
            style={{ borderColor: theme.primary }}
          >
            <div className="flex items-center gap-2 mb-4">
              <BarChart3 size={20} style={{ color: theme.primary }} />
              <h3
                className="font-bold text-lg"
                style={{ color: theme.primary }}
              >
                Import Preview
              </h3>
            </div>

            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
              <div className="bg-gray-50 p-4 rounded-lg text-center">
                <div
                  className="text-3xl font-bold"
                  style={{ color: theme.primary }}
                >
                  {preview.totalDays}
                </div>
                <div className="text-sm text-gray-600 mt-1">Dagen</div>
              </div>

              <div className="bg-gray-50 p-4 rounded-lg text-center">
                <div
                  className="text-3xl font-bold"
                  style={{ color: theme.primary }}
                >
                  {preview.totalShifts}
                </div>
                <div className="text-sm text-gray-600 mt-1">Shifts</div>
              </div>

              <div className="bg-green-50 p-4 rounded-lg text-center">
                <div className="text-3xl font-bold text-green-600">
                  {preview.matched}
                </div>
                <div className="text-sm text-gray-600 mt-1">✅ Gekoppeld</div>
              </div>

              <div className="bg-orange-50 p-4 rounded-lg text-center">
                <div className="text-3xl font-bold text-orange-600">
                  {preview.unmatched}
                </div>
                <div className="text-sm text-gray-600 mt-1">
                  ⚠️ Niet gekoppeld
                </div>
              </div>
            </div>

            {/* Waarschuwing bij unmatched */}
            {preview.unmatched > 0 && (
              <div className="bg-orange-50 border border-orange-200 rounded-lg p-4 mb-4">
                <div className="flex items-start gap-3">
                  <AlertTriangle
                    size={20}
                    className="text-orange-600 mt-0.5 flex-shrink-0"
                  />
                  <div className="text-sm text-orange-800">
                    <p className="font-bold mb-2">
                      Let op: {preview.unmatched} shifts kunnen niet gekoppeld
                      worden
                    </p>
                    <p className="mb-2">
                      De volgende medewerkers zijn niet gevonden in het systeem:
                    </p>
                    <ul className="list-disc ml-4 space-y-1">
                      {preview.unmatchedEmployees.slice(0, 5).map((emp) => (
                        <li key={emp}>{emp}</li>
                      ))}
                      {preview.unmatchedEmployees.length > 5 && (
                        <li className="text-gray-600">
                          ... en {preview.unmatchedEmployees.length - 5} meer
                        </li>
                      )}
                    </ul>
                    <p className="mt-2">
                      Controleer of alle achternamen correct zijn ingevuld in
                      Team Beheer.
                    </p>
                  </div>
                </div>
              </div>
            )}

            {/* Actie knoppen */}
            <div className="flex gap-3">
              <button
                onClick={() => setPreview(null)}
                className="flex-1 py-3 rounded-xl border-2 font-bold hover:bg-white transition-colors"
                style={{ borderColor: theme.primary, color: theme.primary }}
              >
                Annuleren
              </button>

              <button
                onClick={confirmImport}
                className="flex-1 py-3 rounded-xl font-bold text-white hover:opacity-90 transition-opacity"
                style={{ backgroundColor: theme.primary }}
              >
                ✅ Importeren ({preview.matched} shifts)
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// --- MY SCHEDULE VIEW ---
const MyScheduleView = ({
  appData,
  currentDay,
  loggedInUserName,
  theme,
  onPrev,
  onNext,
  onCalendar,
  setCurrentDay,
  updateData,
  showAlert,
  onExport,
}) => {
  const [swapModalOpen, setSwapModalOpen] = useState(false);
  const [selectedShiftForSwap, setSelectedShiftForSwap] = useState(null);
  const [expandedDays, setExpandedDays] = useState({});
  const [viewMode, setViewMode] = useState("week"); // "week" | "month"

  // Month state (for month view)
  const nowForMonth = new Date();
  const [viewYear, setViewYear] = useState(nowForMonth.getFullYear());
  const [viewMonthNum, setViewMonthNum] = useState(nowForMonth.getMonth() + 1);

  const changeMyMonth = (dir) => {
    let y = viewYear,
      m = viewMonthNum + dir;
    if (m > 12) {
      m = 1;
      y++;
    }
    if (m < 1) {
      m = 12;
      y--;
    }
    setViewYear(y);
    setViewMonthNum(m);
  };
  const isCurrentMonthView =
    viewYear === nowForMonth.getFullYear() &&
    viewMonthNum === nowForMonth.getMonth() + 1;

  // Month view: all days with my shifts
  const getMonthDays = () => {
    const days = [];
    const daysInMo = new Date(viewYear, viewMonthNum, 0).getDate();
    for (let d = 1; d <= daysInMo; d++) {
      const date = new Date(viewYear, viewMonthNum - 1, d);
      const key = toIsoDate(date);
      const shifts = (appData.workSchedule?.[key] || [])
        .filter((s) => s.matchedUser === loggedInUserName)
        .sort((a, b) => a.start.localeCompare(b.start));
      days.push({ date, dateKey: key, shifts });
    }
    return days;
  };

  // Week view data
  const getWeekDays = () => {
    const days = [];
    const start = new Date(currentDay);
    start.setDate(start.getDate() - start.getDay() + 1); // Maandag
    for (let i = 0; i < 7; i++) {
      const date = new Date(start);
      date.setDate(start.getDate() + i);
      const key = toIsoDate(date);
      const shifts = appData.workSchedule?.[key] || [];
      const myDayShifts = shifts
        .filter((s) => s.matchedUser === loggedInUserName)
        .sort((a, b) => a.start.localeCompare(b.start));
      days.push({ date, dateKey: key, shifts: myDayShifts });
    }
    return days;
  };

  const weekDays = getWeekDays();
  const todayKey = toIsoDate(new Date());

  const goToPrevWeek = () => {
    const d = new Date(currentDay);
    d.setDate(d.getDate() - 7);
    setCurrentDay(d);
  };
  const goToNextWeek = () => {
    const d = new Date(currentDay);
    d.setDate(d.getDate() + 7);
    setCurrentDay(d);
  };
  const goToThisWeek = () => setCurrentDay(new Date());

  // Bereken weekstart/eind voor display
  const weekStart = new Date(currentDay);
  weekStart.setDate(weekStart.getDate() - weekStart.getDay() + 1);
  const weekEnd = new Date(weekStart);
  weekEnd.setDate(weekStart.getDate() + 6);
  const isCurrentWeek = (() => {
    const now = new Date();
    const nowStart = new Date(now);
    nowStart.setDate(now.getDate() - now.getDay() + 1);
    return toIsoDate(nowStart) === toIsoDate(weekStart);
  })();

  const weekLabel = (() => {
    const fmtDay = (d) =>
      d.toLocaleDateString("nl-NL", { day: "numeric", month: "short" });
    return `${fmtDay(weekStart)} – ${fmtDay(weekEnd)}`;
  })();

  const activeDays = viewMode === "month" ? getMonthDays() : weekDays;
  const totalShifts = activeDays.reduce((n, d) => n + d.shifts.length, 0);
  const totalHours = activeDays.reduce((total, day) => {
    return (
      total +
      day.shifts.reduce((h, s) => {
        const dur = dienstHours(s);
        return h + dur;
      }, 0)
    );
  }, 0);

  const toggleDay = (key) =>
    setExpandedDays((prev) => ({ ...prev, [key]: !prev[key] }));

  const dayNames = ["Ma", "Di", "Wo", "Do", "Vr", "Za", "Zo"];

  return (
    <div
      className="flex flex-col"
      style={{ height: "100%", overflow: "hidden" }}
    >
      {/* ── NAV BALK ── */}
      <div
        className="flex-shrink-0 mx-3 mb-3 px-3 pt-2.5 pb-2.5 rounded-2xl"
        style={{
          backgroundColor: C.White,
          border: `1px solid ${C.BorderLight}`,
          boxShadow: "0 2px 10px rgba(0,0,0,0.05)",
        }}
      >
        {/* Week/Maand toggle + badges */}
        <div className="flex items-center justify-between mb-2">
          <div
            className="flex rounded-xl p-0.5 gap-0.5"
            style={{ backgroundColor: `${theme.primary}0D` }}
          >
            {[
              ["week", "Week"],
              ["month", "Maand"],
            ].map(([mode, label]) => (
              <button
                key={mode}
                onClick={() => setViewMode(mode)}
                className="px-3 py-1 rounded-lg text-xs font-semibold transition-all"
                style={{
                  backgroundColor:
                    viewMode === mode ? theme.primary : "transparent",
                  color: viewMode === mode ? C.White : C.TextMuted,
                  opacity: 1,
                }}
              >
                {label}
              </button>
            ))}
          </div>
          <div className="flex items-center gap-1.5 text-xs font-semibold">
            {totalShifts > 0 && (
              <>
                <span
                  className="px-2 py-0.5 rounded-full font-bold"
                  style={{
                    backgroundColor: theme.primary,
                    color: C.White,
                  }}
                >
                  {totalShifts}×
                </span>
                <span
                  className="px-2 py-0.5 rounded-full font-bold"
                  style={{
                    backgroundColor: theme.primary,
                    color: C.White,
                  }}
                >
                  {formatHours(totalHours)}
                </span>
              </>
            )}
            <button
              onClick={onExport}
              title="Exporteer naar agenda"
              className="p-1.5 rounded-xl transition-all"
              style={{
                backgroundColor: `${theme.primary}10`,
                color: theme.primary,
              }}
            >
              <Download size={14} />
            </button>
          </div>
        </div>

        {/* Navigatie per modus */}
        {viewMode === "week" ? (
          <>
            <div className="flex items-center gap-1.5">
              <button
                onClick={goToPrevWeek}
                className="p-2 rounded-xl transition-colors"
                style={{
                  backgroundColor: `${theme.primary}10`,
                  color: theme.primary,
                }}
              >
                <ChevronLeft size={16} />
              </button>
              <div className="flex-1 flex items-center justify-center gap-1">
                {weekDays.map((day, i) => {
                  const isToday = day.dateKey === todayKey;
                  const hasShift = day.shifts.length > 0;
                  const isWeekend = i >= 5;
                  return (
                    <button
                      key={day.dateKey}
                      onClick={() => setCurrentDay(day.date)}
                      className="flex flex-col items-center gap-0.5 px-1.5 py-1.5 rounded-xl transition-all"
                      style={{
                        backgroundColor: isToday
                          ? theme.primary
                          : "transparent",
                        minWidth: 34,
                      }}
                    >
                      <span
                        className="text-[9px] font-bold uppercase"
                        style={{
                          color: isToday
                            ? C.White
                            : isWeekend
                            ? C.TextMuted
                            : C.TextSecondary,
                        }}
                      >
                        {dayNames[i]}
                      </span>
                      <span
                        className="text-sm font-bold"
                        style={{
                          color: isToday ? C.White : C.TextPrimary,
                        }}
                      >
                        {day.date.getDate()}
                      </span>
                      <div
                        className="w-1.5 h-1.5 rounded-full"
                        style={{
                          backgroundColor: hasShift
                            ? isToday
                              ? C.White
                              : theme.primary
                            : "transparent",
                          opacity: hasShift && !isToday ? 0.6 : 1,
                        }}
                      />
                    </button>
                  );
                })}
              </div>
              <button
                onClick={goToNextWeek}
                className="p-2 rounded-xl transition-colors"
                style={{
                  backgroundColor: `${theme.primary}10`,
                  color: theme.primary,
                }}
              >
                <ChevronRight size={16} />
              </button>
            </div>
            {!isCurrentWeek && (
              <button
                onClick={goToThisWeek}
                className="mt-2 w-full py-1.5 rounded-xl text-xs font-semibold transition-colors"
                style={{
                  backgroundColor: `${theme.primary}10`,
                  color: theme.primary,
                }}
              >
                ↩ Terug naar deze week
              </button>
            )}
          </>
        ) : (
          <>
            <div className="flex items-center gap-1.5">
              <button
                onClick={() => changeMyMonth(-1)}
                className="p-2 rounded-xl transition-colors"
                style={{
                  backgroundColor: `${theme.primary}10`,
                  color: theme.primary,
                }}
              >
                <ChevronLeft size={16} />
              </button>
              <div className="flex-1 text-center">
                <span
                  className="font-bold text-sm capitalize"
                  style={{ color: C.TextPrimary }}
                >
                  {new Date(viewYear, viewMonthNum - 1).toLocaleDateString(
                    "nl-NL",
                    { month: "long", year: "numeric" }
                  )}
                </span>
              </div>
              <button
                onClick={() => changeMyMonth(1)}
                className="p-2 rounded-xl transition-colors"
                style={{
                  backgroundColor: `${theme.primary}10`,
                  color: theme.primary,
                }}
              >
                <ChevronRight size={16} />
              </button>
            </div>
            {!isCurrentMonthView && (
              <button
                onClick={() => {
                  setViewYear(nowForMonth.getFullYear());
                  setViewMonthNum(nowForMonth.getMonth() + 1);
                }}
                className="mt-2 w-full py-1.5 rounded-xl text-xs font-semibold transition-colors"
                style={{
                  backgroundColor: `${theme.primary}10`,
                  color: theme.primary,
                }}
              >
                ↩ Terug naar deze maand
              </button>
            )}
          </>
        )}
      </div>

      {/* ── SCROLLBARE DAGLIJST ── */}
      <div className="flex-1 overflow-y-auto px-4 py-3 pb-24">
        {viewMode === "month" ? (
          // ── MAAND WEERGAVE ──
          <>
            {/* Desktop: kalender-grid (zoals team-maand) */}
            <div
              className="hidden md:block bg-white rounded-2xl border p-4 mb-2"
              style={{ borderColor: `${theme.primary}25` }}
            >
              <div className="grid grid-cols-7 gap-2">
                {["Ma", "Di", "Wo", "Do", "Vr", "Za", "Zo"].map((d) => (
                  <div
                    key={d}
                    className="text-center font-bold p-2 text-sm"
                    style={{ color: theme.primary }}
                  >
                    {d}
                  </div>
                ))}
                {(() => {
                  const md = getMonthDays();
                  const first = md[0]?.date;
                  const offset = first
                    ? first.getDay() === 0
                      ? 6
                      : first.getDay() - 1
                    : 0;
                  return Array(offset)
                    .fill(null)
                    .map((_, idx) => <div key={"e" + idx} className="p-2" />);
                })()}
                {getMonthDays().map((day) => {
                  const isToday = day.dateKey === toIsoDate(new Date());
                  const hasShifts = day.shifts.length > 0;
                  const dow = day.date.getDay();
                  const isWeekend = dow === 0 || dow === 6;
                  return (
                    <div
                      key={day.dateKey}
                      className="p-2 rounded-lg border min-h-[120px] transition-all"
                      style={{
                        borderColor: isToday
                          ? theme.primary
                          : hasShifts
                          ? C.Border
                          : "transparent",
                        backgroundColor: isToday
                          ? `${theme.primary}08`
                          : hasShifts
                          ? "white"
                          : isWeekend
                          ? C.Bg
                          : C.BorderLight + "40",
                      }}
                    >
                      <div className="text-sm font-bold mb-1.5">
                        <span
                          style={
                            isToday
                              ? {
                                  backgroundColor: theme.primary,
                                  color: "white",
                                  padding: "1px 8px",
                                  borderRadius: "9999px",
                                }
                              : { color: C.TextPrimary }
                          }
                        >
                          {day.date.getDate()}
                        </span>
                      </div>
                      {hasShifts && (
                        <div className="space-y-1">
                          {day.shifts
                            .slice()
                            .sort((a, b) =>
                              (a.start || "").localeCompare(b.start || "")
                            )
                            .map((shift, si) => {
                              const tc =
                                RM_TYPES[shift.type] || RM_TYPES.overig;
                              const TIcon = tc.icon;
                              return (
                                <div
                                  key={si}
                                  className="rounded-lg px-1.5 py-1 text-[11px] font-semibold flex items-center gap-1"
                                  style={{
                                    backgroundColor: tc.bg,
                                    color: tc.color,
                                  }}
                                >
                                  {TIcon && (
                                    <TIcon
                                      size={11}
                                      style={{ flexShrink: 0 }}
                                    />
                                  )}
                                  <span className="truncate">
                                    {shift.start}–{shift.end}
                                  </span>
                                </div>
                              );
                            })}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
            {/* Mobiel: bestaande lijst */}
            <div className="space-y-2 md:hidden">
              {getMonthDays().map((day) => {
                const isToday = day.dateKey === toIsoDate(new Date());
                const hasShifts = day.shifts.length > 0;
                const dow = day.date.getDay();
                const isWeekend = dow === 0 || dow === 6;
                const dayNL = day.date.toLocaleDateString("nl-NL", {
                  weekday: "short",
                });
                if (!hasShifts && !isToday)
                  return (
                    <div
                      key={day.dateKey}
                      className="flex items-center gap-3 px-3 py-1.5 rounded-xl opacity-40"
                      style={{
                        backgroundColor: isWeekend
                          ? C.BorderLight + "80"
                          : "transparent",
                      }}
                    >
                      <div
                        className="w-8 h-8 rounded-full flex flex-col items-center justify-center flex-shrink-0"
                        style={{ backgroundColor: C.BorderLight }}
                      >
                        <span
                          className="text-[8px] uppercase font-bold"
                          style={{ color: C.TextMuted }}
                        >
                          {dayNL}
                        </span>
                        <span
                          className="text-xs font-black"
                          style={{ color: C.TextMuted }}
                        >
                          {day.date.getDate()}
                        </span>
                      </div>
                      <span className="text-xs" style={{ color: C.TextMuted }}>
                        Vrij
                      </span>
                    </div>
                  );
                const monthShouldShow =
                  expandedDays[day.dateKey] === true ||
                  (expandedDays[day.dateKey] === undefined &&
                    (hasShifts || isToday));
                return (
                  <div
                    key={day.dateKey}
                    className="rounded-2xl overflow-hidden transition-all"
                    style={{
                      border: isToday
                        ? `2px solid ${theme.primary}`
                        : `1.5px solid ${theme.primary}25`,
                      backgroundColor: isToday ? `${theme.primary}07` : "white",
                    }}
                  >
                    {/* Klikbare header */}
                    <button
                      onClick={() => toggleDay(day.dateKey)}
                      className="w-full flex items-center gap-3 px-3 py-2.5 text-left"
                      style={{ cursor: "pointer" }}
                    >
                      <div
                        className="w-11 h-11 rounded-full flex flex-col items-center justify-center font-bold flex-shrink-0"
                        style={{
                          backgroundColor: isToday
                            ? theme.primary
                            : `${theme.primary}12`,
                          color: isToday ? "white" : theme.primary,
                        }}
                      >
                        <span className="text-[8px] uppercase font-bold leading-none tracking-wide opacity-80">
                          {dayNL}
                        </span>
                        <span className="text-base font-black leading-tight">
                          {day.date.getDate()}
                        </span>
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-1.5 flex-wrap">
                          <span
                            className="font-bold text-sm capitalize"
                            style={{
                              color: isToday ? theme.primary : C.TextPrimary,
                            }}
                          >
                            {day.date.toLocaleDateString("nl-NL", {
                              weekday: "long",
                            })}
                          </span>
                          {isToday && (
                            <span
                              className="text-[9px] px-1.5 py-0.5 rounded-full font-black"
                              style={{
                                backgroundColor: theme.primary,
                                color: "white",
                              }}
                            >
                              NU
                            </span>
                          )}
                          {(() => {
                            const bdays = getBirthdaysOnDate(
                              day.dateKey,
                              appData.staffList || [],
                              appData.settings?.fmDob
                            );
                            if (bdays.length === 0) return null;
                            return bdays.map((b, bi) => (
                              <span
                                key={bi}
                                className="text-[9px] px-1.5 py-0.5 rounded-full font-bold flex items-center gap-0.5 flex-shrink-0"
                                style={{
                                  backgroundColor: "#FFF3CD",
                                  color: "#92400e",
                                  border: "1px solid #F59E0B",
                                }}
                              >
                                🎂 {b.name.split(" ")[0]} {b.age}
                              </span>
                            ));
                          })()}
                        </div>
                        <div className="space-y-0.5 mt-1">
                          {day.shifts.map((s, si) => (
                            <div
                              key={si}
                              className="flex items-center gap-1.5 flex-wrap"
                            >
                              <span
                                className="text-[11px] font-bold px-2 py-0.5 rounded-full"
                                style={{
                                  backgroundColor: `${theme.primary}12`,
                                  color: theme.primary,
                                }}
                              >
                                {s.start}–{s.end}
                              </span>
                              {(s.title || s.location) && (
                                <span
                                  className="text-[11px]"
                                  style={{ color: C.TextSecondary }}
                                >
                                  {s.title || s.location}
                                </span>
                              )}
                            </div>
                          ))}
                        </div>
                      </div>
                      <div className="flex items-center gap-1.5 flex-shrink-0">
                        <span
                          className="text-xs font-bold px-2 py-1 rounded-full"
                          style={{
                            backgroundColor: `${theme.primary}12`,
                            color: theme.primary,
                          }}
                        >
                          {formatHours(
                            day.shifts.reduce((h, s) => h + dienstHours(s), 0)
                          )}
                        </span>
                        <ChevronDown
                          size={14}
                          style={{
                            color: theme.primary,
                            opacity: 0.5,
                            transform: monthShouldShow
                              ? "rotate(180deg)"
                              : "rotate(0deg)",
                            transition: "transform 0.2s",
                          }}
                        />
                      </div>
                    </button>
                    {/* Uitklapbare detail — zelfde als weekview */}
                    {monthShouldShow && (
                      <div
                        className="px-4 pb-4 pt-1 space-y-3"
                        style={{
                          borderTop: `1px solid ${
                            isToday ? theme.primary + "30" : C.BorderLight
                          }`,
                        }}
                      >
                        {day.shifts.map((shift, idx) => {
                          const myActivities = (appData.schedule || [])
                            .filter(
                              (a) =>
                                a.date === day.dateKey &&
                                a.staff?.includes(loggedInUserName)
                            )
                            .map((a) => ({
                              ...a,
                              type: "activity",
                              sortTime: (a.time || "").split(" ")[0],
                            }));
                          const myBreaks = (shift.breaks || []).map((brk) => ({
                            ...brk,
                            type: "break",
                            sortTime: brk.start,
                          }));
                          const allItems = [...myActivities, ...myBreaks].sort(
                            (a, b) => a.sortTime.localeCompare(b.sortTime)
                          );
                          const dur = dienstHours(shift);
                          return (
                            <div key={idx} className="space-y-2">
                              <div className="flex items-center gap-2">
                                <div
                                  className="flex-1 h-1.5 rounded-full"
                                  style={{
                                    backgroundColor: `${theme.primary}20`,
                                  }}
                                >
                                  <div
                                    className="h-full rounded-full"
                                    style={{
                                      backgroundColor: theme.primary,
                                      width: "100%",
                                    }}
                                  />
                                </div>
                                <span
                                  className="text-xs font-semibold"
                                  style={{ color: theme.primary }}
                                >
                                  {shift.start}–{shift.end} · {formatHours(dur)}
                                </span>
                              </div>
                              {allItems.length > 0 && (
                                <div className="space-y-1">
                                  {allItems.map((item, aidx) => (
                                    <div
                                      key={aidx}
                                      className="bg-white rounded px-2 py-1.5 flex items-center gap-2 text-xs border"
                                      style={{ borderColor: C.BorderLight }}
                                    >
                                      {item.type === "break" ? (
                                        <Utensils
                                          size={11}
                                          style={{ color: C.Honey }}
                                          className="flex-shrink-0"
                                        />
                                      ) : item.category === "crea" ? (
                                        <Palette
                                          size={11}
                                          style={{ color: C.Lagoon }}
                                          className="flex-shrink-0"
                                        />
                                      ) : (
                                        <Music
                                          size={11}
                                          style={{ color: C.Honey }}
                                          className="flex-shrink-0"
                                        />
                                      )}
                                      <span className="font-bold text-gray-600 flex-shrink-0">
                                        {item.type === "break"
                                          ? `${item.start}–${item.end}`
                                          : item.time}
                                      </span>
                                      <span className="text-gray-700 truncate">
                                        {item.type === "break"
                                          ? "Pauze"
                                          : item.title}
                                      </span>
                                      {item.location &&
                                        item.type === "activity" && (
                                          <span className="text-gray-400 flex-shrink-0">
                                            · {item.location}
                                          </span>
                                        )}
                                    </div>
                                  ))}
                                </div>
                              )}
                              <button
                                onClick={() => {
                                  setSelectedShiftForSwap({
                                    ...shift,
                                    dateKey: day.dateKey,
                                  });
                                  setSwapModalOpen(true);
                                }}
                                className="w-full py-2 rounded-lg font-semibold text-xs flex items-center justify-center gap-1.5 border"
                                style={{
                                  backgroundColor: "white",
                                  color: theme.primary,
                                  borderColor: `${theme.primary}40`,
                                }}
                              >
                                <Repeat size={12} /> Ruil aanvragen
                              </button>
                            </div>
                          );
                        })}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </>
        ) : (
          <div className="space-y-2">
            {weekDays.map((day, i) => {
              const isToday = day.dateKey === todayKey;
              const hasShifts = day.shifts.length > 0;
              const isWeekend = i >= 5;
              const isExpanded =
                expandedDays[day.dateKey] !== false
                  ? hasShifts || isToday // standaard open als er shifts zijn of vandaag
                  : expandedDays[day.dateKey];

              // Echte expanded logica: open als heeft shifts (tenzij handmatig dichtgeklapt)
              const shouldShow =
                expandedDays[day.dateKey] === true ||
                (expandedDays[day.dateKey] === undefined && hasShifts);

              return (
                <div
                  key={day.dateKey}
                  className="rounded-2xl overflow-hidden"
                  style={{
                    border: isToday
                      ? `2px solid ${theme.primary}`
                      : `1.5px solid ${
                          hasShifts ? theme.primary + "25" : C.BorderLight
                        }`,
                    backgroundColor: isToday ? `${theme.primary}07` : "white",
                    opacity: isWeekend && !hasShifts ? 0.55 : 1,
                  }}
                >
                  {/* Dag-header — altijd zichtbaar, klikbaar */}
                  <button
                    onClick={() => hasShifts && toggleDay(day.dateKey)}
                    className="w-full flex items-center gap-3 px-3 py-2.5 text-left"
                    style={{ cursor: hasShifts ? "pointer" : "default" }}
                  >
                    {/* Datum cirkel */}
                    <div
                      className="flex-shrink-0 w-11 h-11 rounded-full flex flex-col items-center justify-center font-bold"
                      style={{
                        backgroundColor: isToday
                          ? theme.primary
                          : hasShifts
                          ? `${theme.primary}12`
                          : `${C.BorderLight}`,
                        color: isToday
                          ? "white"
                          : hasShifts
                          ? theme.primary
                          : C.TextMuted,
                      }}
                    >
                      <span className="text-[8px] uppercase font-bold leading-none tracking-wide opacity-80">
                        {dayNames[i]}
                      </span>
                      <span className="text-base font-black leading-tight">
                        {day.date.getDate()}
                      </span>
                    </div>

                    {/* Naam + samenvatting */}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-1.5 flex-wrap">
                        <span
                          className="font-bold text-sm capitalize"
                          style={{
                            color: isToday
                              ? theme.primary
                              : hasShifts
                              ? C.TextPrimary
                              : C.TextMuted,
                          }}
                        >
                          {day.date.toLocaleDateString("nl-NL", {
                            weekday: "long",
                          })}
                        </span>
                        {isToday && (
                          <span
                            className="text-[9px] px-1.5 py-0.5 rounded-full font-black tracking-wide"
                            style={{
                              backgroundColor: theme.primary,
                              color: "white",
                            }}
                          >
                            NU
                          </span>
                        )}
                        {(() => {
                          const bdays = getBirthdaysOnDate(
                            day.dateKey,
                            appData.staffList || [],
                            appData.settings?.fmDob
                          );
                          if (bdays.length === 0) return null;
                          return bdays.map((b, bi) => (
                            <span
                              key={bi}
                              className="text-[9px] px-1.5 py-0.5 rounded-full font-bold flex items-center gap-0.5 flex-shrink-0"
                              style={{
                                backgroundColor: "#FFF3CD",
                                color: "#92400e",
                                border: "1px solid #F59E0B",
                              }}
                            >
                              🎂 {b.name.split(" ")[0]} {b.age}
                            </span>
                          ));
                        })()}
                      </div>
                      {hasShifts ? (
                        <div className="space-y-0.5 mt-1">
                          {day.shifts.map((s, si) => (
                            <div
                              key={si}
                              className="flex items-center gap-1.5 flex-wrap"
                            >
                              <span
                                className="text-[11px] font-bold px-2 py-0.5 rounded-full"
                                style={{
                                  backgroundColor: `${theme.primary}12`,
                                  color: theme.primary,
                                }}
                              >
                                {s.start}–{s.end}
                              </span>
                              {(s.title || s.location) && (
                                <span
                                  className="text-[11px]"
                                  style={{ color: C.TextSecondary }}
                                >
                                  {s.title || s.location}
                                </span>
                              )}
                            </div>
                          ))}
                        </div>
                      ) : (
                        <div
                          className="text-xs mt-0.5"
                          style={{ color: C.TextMuted }}
                        >
                          Vrij
                        </div>
                      )}
                    </div>

                    {/* Uren + chevron */}
                    {hasShifts && (
                      <div className="flex items-center gap-1.5 flex-shrink-0">
                        <span
                          className="text-xs font-bold px-2 py-1 rounded-full"
                          style={{
                            backgroundColor: `${theme.primary}12`,
                            color: theme.primary,
                          }}
                        >
                          {formatHours(
                            day.shifts.reduce((h, s) => h + dienstHours(s), 0)
                          )}
                        </span>
                        <ChevronDown
                          size={15}
                          style={{
                            color: theme.primary,
                            opacity: 0.5,
                            transform: shouldShow
                              ? "rotate(180deg)"
                              : "rotate(0deg)",
                            transition: "transform 0.2s",
                          }}
                        />
                      </div>
                    )}
                  </button>

                  {/* Shift detail — inklapbaar */}
                  {shouldShow && hasShifts && (
                    <div
                      className="px-4 pb-4 pt-1 space-y-3"
                      style={{
                        borderTop: `1px solid ${
                          isToday ? theme.primary + "30" : C.BorderLight
                        }`,
                      }}
                    >
                      {day.shifts.map((shift, idx) => {
                        const myActivities = (appData.schedule || [])
                          .filter(
                            (s) =>
                              s.date === day.dateKey &&
                              s.staff?.includes(loggedInUserName)
                          )
                          .map((a) => ({
                            ...a,
                            type: "activity",
                            sortTime: (a.time || "").split(" ")[0],
                          }));

                        const myBreaks = (shift.breaks || []).map((brk) => ({
                          ...brk,
                          type: "break",
                          sortTime: brk.start,
                        }));

                        const allItems = [...myActivities, ...myBreaks].sort(
                          (a, b) =>
                            (a.sortTime || "").localeCompare(b.sortTime || "")
                        );

                        return (
                          <div key={idx}>
                            {/* Shift tijdbalk */}
                            <div
                              className="flex items-center justify-between rounded-lg px-3 py-2 mb-2"
                              style={{
                                backgroundColor: `${theme.primary}10`,
                                border: `1px solid ${theme.primary}25`,
                              }}
                            >
                              <div className="flex items-center gap-2">
                                <Clock
                                  size={14}
                                  style={{ color: theme.primary }}
                                />
                                <span
                                  className="font-bold text-sm"
                                  style={{ color: theme.primary }}
                                >
                                  {shift.start} – {shift.end}
                                </span>
                              </div>
                              <div className="flex items-center gap-3">
                                <span className="text-xs text-gray-600 flex items-center gap-1">
                                  <MapPin size={11} className="text-gray-400" />
                                  {shift.title || shift.location}
                                </span>
                                <span
                                  className="text-xs font-bold px-2 py-0.5 rounded-full"
                                  style={{
                                    backgroundColor: `${C.Grass}20`,
                                    color: C.Pine,
                                  }}
                                >
                                  {formatHours(dienstHours(shift))}
                                </span>
                              </div>
                            </div>

                            {/* Karakters */}
                            {(() => {
                              const myChars = (appData.characters || []).filter(
                                (c) =>
                                  c.date === day.dateKey &&
                                  c.actor === loggedInUserName
                              );
                              if (!myChars.length) return null;
                              return (
                                <div className="flex flex-wrap gap-1 mb-2">
                                  {myChars.map((char, cidx) => {
                                    const col = getCharColorInfo(char.role);
                                    return (
                                      <span
                                        key={cidx}
                                        className="text-xs px-2 py-1 rounded-full font-bold"
                                        style={{
                                          backgroundColor: col.bg,
                                          color: col.text,
                                        }}
                                      >
                                        {char.role}
                                      </span>
                                    );
                                  })}
                                </div>
                              );
                            })()}

                            {/* Activiteiten + pauzes */}
                            {allItems.length > 0 && (
                              <div
                                className="rounded-xl border p-2 space-y-1"
                                style={{
                                  backgroundColor: `${C.Sky}10`,
                                  borderColor: `${C.Sky}50`,
                                }}
                              >
                                <div className="flex items-center gap-1 mb-1.5">
                                  <CalendarDays
                                    size={12}
                                    style={{ color: C.Lagoon }}
                                  />
                                  <span
                                    className="text-[11px] font-semibold"
                                    style={{ color: C.Lagoon }}
                                  >
                                    Planning ({allItems.length})
                                  </span>
                                </div>
                                {allItems.map((item, aidx) => (
                                  <div
                                    key={aidx}
                                    className="bg-white rounded px-2 py-1.5 flex items-center gap-2 text-xs border"
                                    style={{ borderColor: C.BorderLight }}
                                  >
                                    {item.type === "break" ? (
                                      <Utensils
                                        size={11}
                                        style={{ color: C.Honey }}
                                        className="flex-shrink-0"
                                      />
                                    ) : item.type === "activity" &&
                                      item.category === "crea" ? (
                                      <Palette
                                        size={11}
                                        style={{ color: C.Lagoon }}
                                        className="flex-shrink-0"
                                      />
                                    ) : (
                                      <Music
                                        size={11}
                                        style={{ color: C.Honey }}
                                        className="flex-shrink-0"
                                      />
                                    )}
                                    <span className="font-bold text-gray-600 flex-shrink-0">
                                      {item.type === "break"
                                        ? `${item.start}–${item.end}`
                                        : item.time}
                                    </span>
                                    <span className="text-gray-700 truncate">
                                      {item.type === "break"
                                        ? "Pauze"
                                        : item.title}
                                    </span>
                                    {item.location &&
                                      item.type === "activity" && (
                                        <span className="text-gray-400 flex-shrink-0">
                                          · {item.location}
                                        </span>
                                      )}
                                  </div>
                                ))}
                              </div>
                            )}

                            {/* Ruil knop */}
                            <button
                              onClick={() => {
                                setSelectedShiftForSwap({
                                  ...shift,
                                  dateKey: day.dateKey,
                                });
                                setSwapModalOpen(true);
                              }}
                              className="mt-2 w-full py-2 rounded-lg font-semibold text-xs flex items-center justify-center gap-1.5 transition-opacity hover:opacity-80 border"
                              style={{
                                backgroundColor: "white",
                                color: theme.primary,
                                borderColor: `${theme.primary}40`,
                              }}
                            >
                              <Repeat size={12} />
                              Ruil aanvragen
                            </button>
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Swap Request Modal */}
      {swapModalOpen && selectedShiftForSwap && (
        <div
          className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50"
          onClick={() => setSwapModalOpen(false)}
        >
          <div
            className="bg-white rounded-2xl max-w-md w-full p-6"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center justify-between mb-6">
              <h3
                className="text-base font-bold"
                style={{ color: theme.primary }}
              >
                Ruiling Aanvragen
              </h3>
              <button
                onClick={() => setSwapModalOpen(false)}
                className="p-2 hover:bg-gray-100 rounded-lg"
              >
                <CloseIcon size={24} />
              </button>
            </div>

            <div className="bg-gray-50 rounded-xl p-4 mb-6">
              <p className="text-sm font-bold text-gray-600 mb-2">
                Jouw shift:
              </p>
              <div
                className="font-bold text-lg"
                style={{ color: theme.primary }}
              >
                {parseDateKey(selectedShiftForSwap.dateKey).toLocaleDateString(
                  "nl-NL",
                  {
                    weekday: "long",
                    day: "numeric",
                    month: "long",
                  }
                )}
              </div>
              <div className="text-gray-700 mt-1">
                {selectedShiftForSwap.start} - {selectedShiftForSwap.end}
              </div>
              <div className="text-gray-600 text-sm mt-1">
                {selectedShiftForSwap.location}
              </div>
            </div>

            <div className="mb-6">
              <label className="block text-sm font-bold text-gray-700 mb-2">
                Ruil met wie?
              </label>
              <StyledSelect
                id="swap-colleague"
                className="w-full border rounded-xl p-3"
                style={{ borderColor: theme.primary }}
                defaultValue=""
              >
                <option value="" disabled>
                  Kies een collega...
                </option>
                {appData.staffList
                  .filter((s) => s.name !== loggedInUserName && !s.inactive)
                  .sort((a, b) => a.name.localeCompare(b.name))
                  .map((s) => (
                    <option key={s.name} value={s.name}>
                      {getFirstName(s.name)}
                    </option>
                  ))}
              </StyledSelect>
            </div>

            <div className="mb-6">
              <label className="block text-sm font-bold text-gray-700 mb-2">
                Reden (optioneel)
              </label>
              <textarea
                id="swap-reason"
                className="w-full border rounded-xl p-3 resize-none"
                style={{ borderColor: theme.primary }}
                rows="3"
                placeholder="bijv. Doktersafspraak, vrij nodig..."
              />
            </div>

            <div className="flex gap-3">
              <button
                onClick={() => setSwapModalOpen(false)}
                className="flex-1 py-3 rounded-xl font-bold text-gray-600 bg-gray-100 hover:bg-gray-200"
              >
                Annuleren
              </button>
              <button
                onClick={() => {
                  const colleague =
                    document.getElementById("swap-colleague").value;
                  const reason = document.getElementById("swap-reason").value;
                  if (!colleague) {
                    showAlert("⚠️ Kies een collega om mee te ruilen!");
                    return;
                  }
                  const swapRequest = {
                    id: Date.now(),
                    requestedBy: loggedInUserName,
                    swapWith: colleague,
                    shift: selectedShiftForSwap,
                    reason,
                    status: "pending",
                    requestedAt: new Date().toISOString(),
                  };
                  updateData({
                    shiftSwapRequests: [
                      ...(appData.shiftSwapRequests || []),
                      swapRequest,
                    ],
                  });
                  showAlert(
                    "✅ Ruiling aangevraagd! FM ontvangt een notificatie."
                  );
                  setSwapModalOpen(false);
                  setSelectedShiftForSwap(null);
                }}
                className="flex-1 py-3 rounded-xl font-bold text-white hover:opacity-90"
                style={{ backgroundColor: theme.primary }}
              >
                Versturen
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// ============================================================
// 📅 BESCHIKBAARHEIDSSYSTEEM
// Medewerkers geven per dag een tijdvak + opmerking op.
// FM ziet maandoverzicht + genereert automatisch rooster.
//
// Data: staffAvailability[naam]["2026-03"][15] =
//   { start: "09:00", end: "17:00", note: "..." } | null (= niet beschikbaar)
// ============================================================

// ─── Utility helpers ───────────────────────────────────────

const getDaysInMonth = (year, month) => new Date(year, month, 0).getDate();
const getFirstWeekday = (year, month) => {
  const d = new Date(year, month - 1, 1).getDay();
  return d === 0 ? 6 : d - 1; // 0=Ma
};
const dutchMonths = [
  "januari",
  "februari",
  "maart",
  "april",
  "mei",
  "juni",
  "juli",
  "augustus",
  "september",
  "oktober",
  "november",
  "december",
];
const dutchDaysShort = ["Ma", "Di", "Wo", "Do", "Vr", "Za", "Zo"];

// Parse "HH:MM" naar minuten
const timeToMins = (t) => {
  if (!t) return 0;
  const [h, m] = t.split(":").map(Number);
  return h * 60 + (m || 0);
};
const minsToHours = (m) => (m / 60).toFixed(1).replace(".0", "");

// ─── HELPER: maandsleutel "YYYY-MM" ───────────────────────
const toMonthKey = (y, m) => `${y}-${String(m).padStart(2, "0")}`;
const parseMonthKey = (mk) => ({
  year: parseInt(mk.slice(0, 4)),
  month: parseInt(mk.slice(5, 7)),
});
const nextMonthKey = (mk) => {
  const { year, month } = parseMonthKey(mk);
  return month === 12 ? toMonthKey(year + 1, 1) : toMonthKey(year, month + 1);
};
const currentMonthKey = () => {
  const n = new Date();
  return toMonthKey(n.getFullYear(), n.getMonth() + 1);
};
const formatMonthLabel = (mk) => {
  const { year, month } = parseMonthKey(mk);
  return `${dutchMonths[month - 1]} ${year}`;
};
const formatDeadline = (iso) => {
  if (!iso) return null;
  const d = new Date(iso);
  return d.toLocaleDateString("nl-NL", { day: "numeric", month: "long" });
};
const isDeadlinePassed = (deadline) => {
  if (!deadline) return false;
  return new Date(deadline) < new Date();
};

// ============================================================
// 🎯 GEDEELDE BESCHIKBAARHEID-HELPERS
// Eén bron van waarheid voor alle FM/RoosterMaker-weergaven die
// staffAvailability samenvatten of labelen — zodat elke view (matrix,
// kalendercellen, exportrij, dienstruil-check, ...) exact dezelfde
// tellingen, tekst en kleuren gebruikt i.p.v. het zelf opnieuw te
// berekenen.
// ============================================================

// Status van 1 opgave: "approved" | "pending" | "rejected" | null.
// Oude entries zonder status-veld gelden vanaf APPROVAL_CUTOFF_DATE
// alsnog als "pending" — zie de FM-goedkeuringsflow hieronder.
const getAvailStatus = (a, date) => {
  if (!a) return null;
  if (a.status) return a.status;
  if (date && date >= APPROVAL_CUTOFF_DATE) return "pending";
  return "approved";
};

// Eén-regel label + categorie ("full" | "partial" | "off" | "none")
// voor 1 persoon op 1 dag.
const getPersonAvailLabel = (allAvail, naam, date) => {
  const a = allAvail?.[naam]?.[date];
  if (!a) return { tekst: "Nog niet ingevuld", kind: "none", status: null };
  const status = getAvailStatus(a, date);
  if (a.available === false) {
    return { tekst: "Niet beschikbaar", kind: "off", status, note: a.note };
  }
  if (a.start) {
    return {
      tekst: `${a.start}–${a.end}`,
      kind: "partial",
      status,
      note: a.note,
    };
  }
  return {
    tekst: "Hele dag beschikbaar",
    kind: "full",
    status,
    note: a.note,
  };
};

// Samenvatting van 1 dag over alle medewerkers — telling per categorie.
// Gebruikt door kalendercellen, exportrij en het maandoverzicht.
const getDayAvailSummary = (allAvail, allStaff, date) => {
  let beschikbaar = 0,
    deels = 0,
    nietBeschikbaar = 0,
    geenOpgave = 0,
    pending = 0;
  (allStaff || []).forEach((s) => {
    const a = allAvail?.[s.name]?.[date];
    if (!a) {
      geenOpgave++;
      return;
    }
    if (getAvailStatus(a, date) === "pending") pending++;
    if (a.available === false) nietBeschikbaar++;
    else if (a.start) deels++;
    else beschikbaar++;
  });
  return {
    beschikbaar,
    deels,
    nietBeschikbaar,
    geenOpgave,
    pending,
    totaal: (allStaff || []).length,
    beschikbaarTotaal: beschikbaar + deels,
  };
};

// Eén kleurenschema voor heel de app: Grass = beschikbaar,
// Honey = deels/pending, Sunset = niet beschikbaar/afgekeurd, grijs = geen opgave.
const AVAIL_COLORS = {
  full: { bg: C.Grass + "35", border: C.Pine, text: C.Pine, symbol: "✓" },
  partial: { bg: C.Honey + "35", border: C.Bark, text: C.Bark, symbol: "~" },
  off: { bg: C.Sunset + "25", border: C.Sunset, text: C.Sunset, symbol: "✗" },
  none: { bg: "#f9fafb", border: C.BorderLight, text: C.TextMuted, symbol: "" },
};

// Klein symbool voor krappe cellen (kalender/grid).
const AvailDot = ({ kind, size = 10 }) => {
  const c = AVAIL_COLORS[kind] || AVAIL_COLORS.none;
  if (!c.symbol) return null;
  return (
    <span className="font-black leading-none" style={{ color: c.text, fontSize: size }}>
      {c.symbol}
    </span>
  );
};

// Chip met tekst voor lijsten/kaarten, optioneel met goedkeuringsstatus.
const AvailBadge = ({ kind, label, status }) => {
  const c = AVAIL_COLORS[kind] || AVAIL_COLORS.none;
  return (
    <span
      className="inline-flex items-center gap-1 text-[11px] font-semibold px-1.5 py-0.5 rounded-full"
      style={{ backgroundColor: c.bg, color: c.text }}
    >
      {label}
      {status === "pending" && " · wacht op goedkeuring"}
      {status === "rejected" && " · afgekeurd"}
    </span>
  );
};

// ============================================================
// 📋 INSCHRIJVEN — één pagina voor iedereen
// FM: diensten aanmaken, maanden openen, zelf inschrijven,
//     toewijzen, uren bewaken
// Staff: inschrijven op open diensten, eigen uren zien
// ============================================================

// ============================================================
// 📅 BESCHIKBAARHEID — per dag invullen
// Staff: kalender → dag aanklikken → beschikbaar ja/nee + tijden
// FM: overzicht per dag wie beschikbaar is en wanneer
// ============================================================

const BeschikbaarheidView = ({
  appData,
  updateData,
  theme,
  userRole,
  loggedInUserName,
  showAlert,
}) => {
  const t = theme || THEMES.general;
  const isFM = userRole === "fm";
  const today = new Date();

  const nextMonth = new Date(today.getFullYear(), today.getMonth() + 1, 1);
  const [viewYear, setViewYear] = useState(nextMonth.getFullYear());
  const [viewMonth, setViewMonth] = useState(nextMonth.getMonth() + 1);
  const [selectedDate, setSelectedDate] = useState(null);
  const [rangeStart, setRangeStart] = useState(null); // multi-day select start
  const [rangeMode, setRangeMode] = useState(false);
  const [editForm, setEditForm] = useState(null);
  const [showDeadlineSettings, setShowDeadlineSettings] = useState(false);
  const [viewingName, setViewingName] = useState(loggedInUserName); // FM can switch

  // Sync viewingName als loggedInUserName verandert (bijv. na herlaad of re-auth)
  React.useEffect(() => {
    if (!isFM) setViewingName(loggedInUserName);
  }, [loggedInUserName]);

  // Wie we bewerken: FM kan wisselen, staff altijd zichzelf
  const activeUser = isFM ? viewingName : loggedInUserName;

  const allAvail = appData.staffAvailability || {};
  const allAvailRef = React.useRef(allAvail);
  allAvailRef.current = allAvail; // altijd up-to-date, ook tussen re-renders
  const maandInst = appData.maandInstellingen || {};
  const contractInfo = appData.staffContractInfo || {};

  // Voor het pushen van een "nieuwe verlofaanvraag"-melding naar de FM
  const notificationsRef = React.useRef(appData.notifications || []);
  notificationsRef.current = appData.notifications || [];

  // ── Dagen dichtgezet door FM (per medewerker) ─────────
  const allLocks = appData.staffAvailabilityLocks || {};
  const allLocksRef = React.useRef(allLocks);
  allLocksRef.current = allLocks;
  const [lockMode, setLockMode] = useState(false); // FM: snel-vergrendel-modus in maandoverzicht
  const [showVerlofHistory, setShowVerlofHistory] = useState(false); // FM: geschiedenis van afgehandelde verlofaanvragen tonen
  const [lockRangeAnchor, setLockRangeAnchor] = useState(null); // { name, date, locked } — 1e klik van een periode-selectie

  // isDayLocked checkt expliciet .locked === true (i.p.v. key-existence), zodat
  // ontgrendelen via een expliciete { locked: false } werkt — de 2-niveau
  // concurrency-merge (persoon → datums) kan namelijk alleen overschrijven,
  // nooit een key verwijderen. Verwijderen zou dus door de merge weer worden
  // "teruggezet" naar de server-versie.
  const isDayLocked = (name, date) => allLocks[name]?.[date]?.locked === true;

  // Vergrendel of ontgrendel 1 of meerdere dagen voor 1 medewerker.
  // Zelfde 2-niveau delta-patroon als saveAvail: alleen de gewijzigde
  // persoon wordt meegestuurd, zodat gelijktijdige saves elkaar niet
  // overschrijven.
  const setDaysLocked = (name, dates, locked) => {
    const base = allLocksRef.current;
    const personLocks = { ...(base[name] || {}) };
    dates.forEach((d) => {
      personLocks[d] = {
        locked,
        lockedAt: new Date().toISOString(),
        lockedBy: loggedInUserName,
      };
    });
    allLocksRef.current = { ...base, [name]: personLocks };
    updateData({ staffAvailabilityLocks: { [name]: personLocks } });
  };
  const _baseStaff = (appData.staffList || []).filter(
    (s) => !s.inactive && s.name !== "Jarno"
  );
  const allStaff = isFM
    ? _baseStaff.some((s) => s.name === "Maik")
      ? _baseStaff
      : [..._baseStaff, { name: "Maik", role: "fm" }]
    : _baseStaff;

  const monthKey = toMonthKey(viewYear, viewMonth);
  const inst = maandInst[monthKey] || {};
  const deadlinePassed = isDeadlinePassed(inst.deadline);
  const isOpen = inst.open !== false; // default open unless explicitly closed
  const daysInMonth = new Date(viewYear, viewMonth, 0).getDate();
  const firstDayOfWeek = (() => {
    const wd = new Date(viewYear, viewMonth - 1, 1).getDay();
    return wd === 0 ? 6 : wd - 1;
  })();

  const changeMonth = (n) => {
    const d = new Date(viewYear, viewMonth - 1 + n, 1);
    setViewYear(d.getFullYear());
    setViewMonth(d.getMonth() + 1);
    setSelectedDate(null);
    setRangeStart(null);
    setRangeMode(false);
    setEditForm(null);
    setLockRangeAnchor(null);
  };

  const dk = (day) =>
    `${viewYear}-${String(viewMonth).padStart(2, "0")}-${String(day).padStart(
      2,
      "0"
    )}`;

  // ── Maand open/sluiten (FM) ───────────────────────────
  const setMaandOpen = (val) =>
    updateData({
      maandInstellingen: { ...maandInst, [monthKey]: { ...inst, open: val } },
    });
  const setDeadline = (val) =>
    updateData({
      maandInstellingen: {
        ...maandInst,
        [monthKey]: { ...inst, deadline: val },
      },
    });

  // ── Eigen beschikbaarheid ophalen ─────────────────────
  const getMyAvail = (date) => allAvail[activeUser]?.[date] || null;

  // ── Dag selecteren ───────────────────────────────────
  const getDatesInRange = (a, b) => {
    const dates = [];
    const start = new Date(Math.min(new Date(a), new Date(b)));
    const end = new Date(Math.max(new Date(a), new Date(b)));
    for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
      dates.push(d.toISOString().slice(0, 10));
    }
    return dates;
  };

  const rangeDates =
    rangeStart && selectedDate ? getDatesInRange(rangeStart, selectedDate) : [];

  const selectDay = (day) => {
    const date = dk(day);
    if (!isFM && (!isOpen || deadlinePassed)) return;
    if (!isFM && isDayLocked(activeUser, date)) {
      showAlert(
        "Deze dag is dichtgezet door de FM en kan niet worden aangepast."
      );
      return;
    }

    // Als rangeMode actief is: dit is de einddatum
    if (rangeMode && rangeStart) {
      setSelectedDate(date);
      setRangeMode(false);
      setEditForm({
        mode: "hele_dag",
        start: "09:00",
        end: "17:30",
        note: "",
        step: "form",
      });
      return;
    }

    // Toggle: zelfde dag opnieuw klikken sluit panel
    if (selectedDate === date && !rangeMode) {
      setSelectedDate(null);
      setEditForm(null);
      setRangeStart(null);
      return;
    }

    setSelectedDate(date);
    setRangeStart(null);
    setRangeMode(false);
    const existing = getMyAvail(date);
    if (existing) {
      const mode = !existing.available
        ? "niet"
        : existing.start
        ? "tijd"
        : "hele_dag";
      setEditForm({
        mode,
        start: existing.start || "09:00",
        end: existing.end || "17:30",
        note: existing.note || "",
        step: "form",
      });
    } else {
      setEditForm({
        mode: "hele_dag",
        start: "09:00",
        end: "17:30",
        note: "",
        step: "scope",
      });
    }
  };

  // ── Goedkeuring van beschikbaarheid ───────────────────
  // Nieuwe/gewijzigde beschikbaarheid van medewerkers gaat eerst als
  // "pending" de lucht in; de FM moet 'm goedkeuren voor 'ie telt.
  // Oude entries zonder status-veld (van vóór deze functie) gelden vanaf
  // APPROVAL_CUTOFF_DATE (september) ALSNOG als "pending" — die moeten dus
  // ook nog goedgekeurd worden, ook al stonden ze er al. Voor dagen vóór de
  // cutoff blijven ze impliciet goedgekeurd, puur om oude/voorbije data niet
  // onnodig als "wachtend" te laten opstapelen. Entries die de FM zelf
  // invult (voor zichzelf of namens iemand anders) zijn direct goedgekeurd.
  const availStatus = getAvailStatus;

  const setAvailStatus = (name, date, status) => {
    const base = allAvailRef.current;
    const existing = base[name]?.[date];
    if (!existing) return;
    const updatedEntry = {
      ...existing,
      status,
      ...(status === "approved"
        ? { approvedBy: loggedInUserName, approvedAt: new Date().toISOString() }
        : {}),
      ...(status === "rejected"
        ? { rejectedBy: loggedInUserName, rejectedAt: new Date().toISOString() }
        : {}),
    };
    // Alleen de gewijzigde datum meesturen (niet de volledige personData-
    // snapshot). Zo kan een (mogelijk) verouderde lokale ref nooit per
    // ongeluk andere, net-ingevulde dagen van dezelfde persoon overschrijven
    // — de bestaande 2-niveau merge (persoon → datums) vult de rest aan
    // vanuit de server-versie.
    allAvailRef.current = {
      ...base,
      [name]: { ...(base[name] || {}), [date]: updatedEntry },
    };
    updateData({ staffAvailability: { [name]: { [date]: updatedEntry } } });
  };

  // Keur in 1 klik alle openstaande aanvragen voor 1 specifieke dag goed.
  const bulkApproveDate = (date) => {
    const base = allAvailRef.current;
    allStaff.forEach((s) => {
      const entry = base[s.name]?.[date];
      if (entry && availStatus(entry, date) === "pending") {
        setAvailStatus(s.name, date, "approved");
      }
    });
  };

  // ── Opslaan beschikbaarheid ───────────────────────────
  // We sturen alleen de delta van de bewerkte persoon, NIET het volledige
  // staffAvailability object. Zo overschrijft een gelijktijdige save van
  // een andere gebruiker nooit elkaars data (deep merge op persoonsniveau).
  const saveAvail = (date, data) => {
    const base = allAvailRef.current;
    const personData = { ...(base[activeUser] || {}), [date]: data };
    allAvailRef.current = { ...base, [activeUser]: personData };
    updateData({ staffAvailability: { [activeUser]: personData } });
  };

  const clearAvail = (date) => {
    const base = allAvailRef.current;
    const personData = { ...(base[activeUser] || {}) };
    delete personData[date];
    allAvailRef.current = { ...base, [activeUser]: personData };
    updateData({ staffAvailability: { [activeUser]: personData } });
    setSelectedDate(null);
    setEditForm(null);
  };

  const saveCurrent = () => {
    if (!selectedDate || !editForm) return;
    const { mode, start, end, note } = editForm;
    if (mode === "tijd") {
      let mins = timeToMins(end) - timeToMins(start);
      if (mins <= 0) mins += 24 * 60;
      if (mins > 23 * 60) {
        showAlert("Eindtijd moet na starttijd liggen");
        return;
      }
    }
    const basePayload =
      mode === "niet"
        ? { available: false, note }
        : mode === "hele_dag"
        ? { available: true, note }
        : { available: true, start, end, note };
    // Medewerkers dienen nieuwe/gewijzigde beschikbaarheid in ter goedkeuring;
    // de FM (voor zichzelf of namens iemand anders) keurt direct goed.
    const payload = isFM
      ? {
          ...basePayload,
          status: "approved",
          approvedBy: loggedInUserName,
          approvedAt: new Date().toISOString(),
        }
      : {
          ...basePayload,
          status: "pending",
          submittedAt: new Date().toISOString(),
        };
    const dates =
      rangeStart && rangeStart !== selectedDate
        ? getDatesInRange(rangeStart, selectedDate)
        : [selectedDate];
    const base = allAvailRef.current;
    const personData = { ...(base[activeUser] || {}) };
    dates.forEach((d) => {
      personData[d] = payload;
    });
    allAvailRef.current = { ...base, [activeUser]: personData };
    const updates = { staffAvailability: { [activeUser]: personData } };

    // 🔔 Nieuwe verlofaanvraag (niet beschikbaar) van een medewerker → popup-
    // melding voor de FM, met meteen het aantal reeds-beschikbaar/vrij.
    if (!isFM && mode === "niet") {
      const notif = {
        id: `verlof_${Date.now()}_${Math.random().toString(36).slice(2)}`,
        type: "verlof_aanvraag",
        employeeName: activeUser,
        dates,
        note,
        createdAt: new Date().toISOString(),
        readBy: [],
      };
      const updatedNotifs = [...notificationsRef.current, notif];
      notificationsRef.current = updatedNotifs;
      updates.notifications = updatedNotifs;
    }

    updateData(updates);
    setSelectedDate(null);
    setRangeStart(null);
    setRangeMode(false);
    setEditForm(null);
  };

  // ── Helpers ───────────────────────────────────────────
  const formatDayLabel = (date) => {
    const d = new Date(date);
    return `${
      dutchDaysShort[d.getDay() === 0 ? 6 : d.getDay() - 1]
    } ${d.getDate()} ${dutchMonths[d.getMonth()]}`;
  };

  const hoursFromAvail = (a) => {
    if (!a?.available || !a.start || !a.end) return 0;
    return (timeToMins(a.end) - timeToMins(a.start)) / 60;
  };

  // Beschikbare uren deze maand voor een persoon
  const monthHours = (name) => {
    const userAvail = allAvail[name] || {};
    return Object.entries(userAvail)
      .filter(([date]) => date.startsWith(monthKey))
      .reduce((sum, [, a]) => sum + hoursFromAvail(a), 0);
  };

  // Kleur voor dag-indicator
  const dayAvailColor = (name, date) => {
    const a = allAvail[name]?.[date];
    if (!a) return null;
    return a.available ? t.primary : "#9ca3af";
  };

  // ── RENDER ────────────────────────────────────────────
  const currentMonthRef = (() => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(
      2,
      "0"
    )}`;
  })();
  const isCurrentMonthView =
    `${viewYear}-${String(viewMonth).padStart(2, "0")}` === currentMonthRef;

  return (
    <div className="flex flex-col h-full overflow-hidden">
      {/* ── NAV BALK ── */}
      <div
        className="flex-shrink-0 mx-3 mb-3 px-3 pt-2.5 pb-2.5 rounded-2xl"
        style={{
          backgroundColor: C.White,
          border: `1px solid ${C.BorderLight}`,
          boxShadow: "0 2px 10px rgba(0,0,0,0.05)",
        }}
      >
        <div className="flex items-center gap-1.5">
          <button
            onClick={() => changeMonth(-1)}
            className="p-2 rounded-xl transition-colors"
            style={{ backgroundColor: `${t.primary}10`, color: t.primary }}
          >
            <ChevronLeft size={16} />
          </button>
          <div className="flex-1 text-center">
            <span
              className="font-bold text-sm capitalize"
              style={{ color: C.TextPrimary }}
            >
              {dutchMonths[viewMonth - 1]} {viewYear}
            </span>
          </div>
          <button
            onClick={() => changeMonth(1)}
            className="p-2 rounded-xl transition-colors"
            style={{ backgroundColor: `${t.primary}10`, color: t.primary }}
          >
            <ChevronRight size={16} />
          </button>
        </div>
        {!isCurrentMonthView && (
          <button
            onClick={() => {
              const now = new Date();
              setViewYear(now.getFullYear());
              setViewMonth(now.getMonth() + 1);
              setSelectedDate(null);
              setEditForm(null);
            }}
            className="mt-2 w-full py-1.5 rounded-xl text-xs font-semibold transition-colors"
            style={{ backgroundColor: `${t.primary}10`, color: t.primary }}
          >
            ↩ Terug naar huidige maand
          </button>
        )}
      </div>

      {/* ── SCROLLBARE CONTENT ── */}
      <div className="flex-1 overflow-y-auto px-4 pb-6 pt-3 space-y-4">
        {/* FM: medewerker selector */}
        {isFM && (
          <div
            className="flex items-center gap-2 p-1 rounded-2xl border"
            style={{
              borderColor: t.primary + "20",
              backgroundColor: t.primary + "06",
            }}
          >
            <div className="flex items-center gap-1.5 px-2 flex-shrink-0">
              <Users size={13} style={{ color: t.primary }} />
              <span
                className="text-[11px] font-semibold"
                style={{ color: t.primary }}
              >
                Medewerker:
              </span>
            </div>
            <div className="flex-1 flex flex-wrap gap-1 py-1">
              {allStaff.map((s) => {
                const isActive = viewingName === s.name;
                const myAvail = allAvail[s.name] || {};
                const filled = Object.keys(myAvail).filter((d) =>
                  d.startsWith(monthKey)
                ).length;
                const daysInMo = new Date(viewYear, viewMonth, 0).getDate();
                const complete = filled >= daysInMo;
                return (
                  <button
                    key={s.name}
                    onClick={() => {
                      setViewingName(s.name);
                      setSelectedDate(null);
                      setEditForm(null);
                      setRangeStart(null);
                      setRangeMode(false);
                    }}
                    className="flex items-center gap-1.5 px-2.5 py-1.5 rounded-xl text-xs font-semibold transition-all"
                    style={{
                      backgroundColor: isActive
                        ? t.primary
                        : complete
                        ? C.Pine
                        : "white",
                      color: isActive || complete ? "white" : C.TextPrimary,
                      border: `1.5px solid ${
                        isActive ? t.primary : complete ? C.Pine : C.BorderLight
                      }`,
                    }}
                  >
                    <ProfileAvatar
                      name={s.name}
                      staffList={appData.staffList || []}
                      size={16}
                      color={isActive || complete ? "white" : t.primary}
                    />
                    {s.name.split(" ")[0]}
                    {complete && !isActive && (
                      <Check size={10} style={{ color: "white" }} />
                    )}
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {true && (
          <>
            {/* Gesloten / deadline banner — alleen voor staff */}
            {!isFM &&
              (!isOpen || deadlinePassed ? (
                <div
                  className="flex items-center gap-3 px-4 py-3 rounded-xl"
                  style={{
                    backgroundColor: C.Sunset + "18",
                    border: `1px solid ${C.Sunset}60`,
                  }}
                >
                  <Lock size={16} style={{ color: C.Sunset }} />
                  <p
                    className="text-sm font-medium"
                    style={{ color: C.Sunset }}
                  >
                    {!isOpen
                      ? "Inschrijvingen zijn gesloten door de FM"
                      : "De deadline is verstreken — inschrijvingen gesloten"}
                  </p>
                </div>
              ) : inst.deadline ? (
                (() => {
                  const today = new Date();
                  const dl = new Date(inst.deadline + "T23:59:59");
                  const daysLeft = Math.ceil((dl - today) / 86400000);
                  const urgent = daysLeft <= 3;
                  const bg = urgent ? C.Sunset + "15" : C.HoneyLight;
                  const border = urgent ? C.Sunset + "60" : C.Honey;
                  const color = urgent ? C.Sunset : C.Bark;
                  const icon = urgent ? (
                    <AlertTriangle size={16} style={{ color, flexShrink: 0 }} />
                  ) : (
                    <Clock size={16} style={{ color, flexShrink: 0 }} />
                  );
                  return (
                    <div
                      className="flex items-center gap-3 px-4 py-3 rounded-xl"
                      style={{
                        backgroundColor: bg,
                        border: `1.5px solid ${border}`,
                      }}
                    >
                      {icon}
                      <div>
                        <p className="text-sm font-bold" style={{ color }}>
                          {urgent
                            ? daysLeft === 0
                              ? "Vandaag is de deadline voor je beschikbaarheid!"
                              : daysLeft === 1
                              ? "Morgen sluit de beschikbaarheid — vul nog in!"
                              : `Nog ${daysLeft} dagen om je beschikbaarheid door te geven`
                            : `Geef je beschikbaarheid door voor ${
                                dutchMonths[viewMonth - 1]
                              }`}
                        </p>
                        {daysLeft > 3 && (
                          <p
                            className="text-xs mt-0.5"
                            style={{ color: C.TextMuted }}
                          >
                            Je hebt nog {daysLeft} dagen
                          </p>
                        )}
                      </div>
                    </div>
                  );
                })()
              ) : null)}
            {/* Legenda */}
            <div
              className="flex flex-wrap items-center gap-3 text-xs"
              style={{ color: C.TextMuted }}
            >
              <div className="flex items-center gap-1.5">
                <div
                  className="w-3 h-3 rounded-sm"
                  style={{
                    backgroundColor: C.Grass + "60",
                    border: `1.5px solid ${C.Grass}`,
                  }}
                />
                Hele dag
              </div>
              <div className="flex items-center gap-1.5">
                <div
                  className="w-3 h-3 rounded-sm"
                  style={{
                    backgroundColor: C.Honey + "50",
                    border: `1.5px solid ${C.Honey}`,
                  }}
                />
                Bepaalde tijd
              </div>
              <div className="flex items-center gap-1.5">
                <div
                  className="w-3 h-3 rounded-sm"
                  style={{
                    backgroundColor: C.Sunset + "20",
                    border: `1.5px solid ${C.Sunset + "60"}`,
                  }}
                />
                Niet beschikbaar
              </div>
              <div className="flex items-center gap-1.5">
                <div
                  className="w-3 h-3 rounded-sm"
                  style={{
                    backgroundColor: "white",
                    border: `1.5px solid ${C.BorderLight}`,
                  }}
                />
                Niet ingevuld
              </div>
              <div className="flex items-center gap-1.5">
                <div
                  className="w-3 h-3 rounded-sm flex items-center justify-center"
                  style={{
                    backgroundColor: "#e5e7eb",
                    border: `1.5px solid ${C.TextMuted}`,
                  }}
                >
                  <Lock size={7} style={{ color: C.TextMuted }} />
                </div>
                Dichtgezet door FM
              </div>
              <div className="flex items-center gap-1.5">
                <div
                  className="w-3 h-3 rounded-full flex items-center justify-center"
                  style={{ backgroundColor: C.Honey }}
                >
                  <Clock3 size={7} style={{ color: "white" }} />
                </div>
                Wacht op goedkeuring
              </div>
              <div className="flex items-center gap-1.5">
                <div
                  className="w-3 h-3 rounded-full flex items-center justify-center"
                  style={{ backgroundColor: C.Sunset }}
                >
                  <AlertTriangle size={7} style={{ color: "white" }} />
                </div>
                Afgekeurd
              </div>
            </div>

            {/* Range-modus instructiebanner */}
            {rangeMode && rangeStart && (
              <div
                className="flex items-center gap-3 px-4 py-3 rounded-xl"
                style={{
                  backgroundColor: t.primary + "12",
                  border: `1.5px solid ${t.primary}`,
                }}
              >
                <CalendarRange
                  size={16}
                  style={{ color: t.primary, flexShrink: 0 }}
                />
                <div className="flex-1">
                  <p className="text-sm font-bold" style={{ color: t.primary }}>
                    Kies de einddatum
                  </p>
                  <p className="text-xs mt-0.5" style={{ color: C.TextMuted }}>
                    Begindatum: {formatDayLabel(rangeStart)}
                  </p>
                </div>
                <button
                  onClick={() => {
                    setRangeMode(false);
                    setRangeStart(null);
                  }}
                  className="text-xs font-semibold px-2.5 py-1 rounded-lg"
                  style={{ backgroundColor: C.BorderLight, color: C.TextMuted }}
                >
                  Annuleren
                </button>
              </div>
            )}

            {/* Kalender */}
            <div
              className="bg-white rounded-2xl border overflow-hidden"
              style={{ borderColor: C.BorderLight }}
            >
              <div
                className="grid grid-cols-7 border-b"
                style={{ borderColor: C.BorderLight }}
              >
                {["Ma", "Di", "Wo", "Do", "Vr", "Za", "Zo"].map((d) => (
                  <div
                    key={d}
                    className="text-center py-2 text-xs font-semibold"
                    style={{ color: C.TextMuted }}
                  >
                    {d}
                  </div>
                ))}
              </div>
              <div className="grid grid-cols-7">
                {Array.from({ length: firstDayOfWeek }, (_, i) => (
                  <div
                    key={"e" + i}
                    className="border-b border-r min-h-[56px]"
                    style={{ borderColor: C.BorderLight }}
                  />
                ))}
                {Array.from({ length: daysInMonth }, (_, i) => {
                  const day = i + 1;
                  const date = dk(day);
                  const avail = getMyAvail(date);
                  const locked = isDayLocked(activeUser, date);
                  const status = availStatus(avail, date);
                  const isSelected = selectedDate === date;
                  const isToday = date === toIsoDate(today);
                  const isPast = new Date(date) < new Date(toIsoDate(today));
                  const col = (firstDayOfWeek + i) % 7;
                  const isWeekend = col >= 5;
                  const isRangeStart = rangeStart === date;
                  const isInRange =
                    rangeStart && selectedDate && rangeDates.includes(date);

                  return (
                    <button
                      key={day}
                      onClick={() => selectDay(day)}
                      className="border-b border-r min-h-[56px] p-1.5 flex flex-col items-center gap-1 transition-colors relative"
                      style={{
                        borderColor: C.BorderLight,
                        backgroundColor:
                          isSelected && !rangeMode
                            ? t.primary
                            : isRangeStart || (isInRange && isSelected)
                            ? t.primary
                            : isInRange
                            ? t.primary + "30"
                            : isToday
                            ? t.primary + "12"
                            : !avail
                            ? "white"
                            : !avail.available
                            ? C.Sunset + "22"
                            : avail.start
                            ? C.Honey + "40"
                            : C.Grass + "35",
                        opacity: isPast ? 0.5 : locked && !isFM ? 0.75 : 1,
                        outline: isRangeStart
                          ? `2px solid ${t.primary}`
                          : locked
                          ? `1.5px dashed ${C.TextMuted}80`
                          : "none",
                        outlineOffset: -1,
                      }}
                    >
                      {locked && (
                        <div
                          className="absolute top-0.5 right-0.5 rounded-full flex items-center justify-center"
                          style={{
                            width: 13,
                            height: 13,
                            backgroundColor: isSelected
                              ? "rgba(255,255,255,0.35)"
                              : "#4b5563",
                          }}
                          title="Dichtgezet door FM"
                        >
                          <Lock
                            size={8}
                            style={{
                              color: isSelected ? "white" : "white",
                              flexShrink: 0,
                            }}
                          />
                        </div>
                      )}
                      {status === "pending" && (
                        <div
                          className="absolute top-0.5 left-0.5 rounded-full flex items-center justify-center"
                          style={{
                            width: 13,
                            height: 13,
                            backgroundColor: isSelected
                              ? "rgba(255,255,255,0.35)"
                              : C.Honey,
                          }}
                          title="Wacht op goedkeuring van de FM"
                        >
                          <Clock3
                            size={8}
                            style={{ color: "white", flexShrink: 0 }}
                          />
                        </div>
                      )}
                      {status === "rejected" && (
                        <div
                          className="absolute top-0.5 left-0.5 rounded-full flex items-center justify-center"
                          style={{
                            width: 13,
                            height: 13,
                            backgroundColor: isSelected
                              ? "rgba(255,255,255,0.35)"
                              : C.Sunset,
                          }}
                          title="Afgekeurd door de FM — opnieuw invullen"
                        >
                          <AlertTriangle
                            size={8}
                            style={{ color: "white", flexShrink: 0 }}
                          />
                        </div>
                      )}
                      <span
                        className="text-xs font-bold w-5 h-5 flex items-center justify-center rounded-full"
                        style={{
                          backgroundColor:
                            isToday && !isSelected && !isInRange
                              ? t.primary
                              : "transparent",
                          color:
                            (isSelected && !rangeMode) ||
                            isRangeStart ||
                            (isInRange && isSelected)
                              ? "white"
                              : isInRange
                              ? t.primary
                              : isToday
                              ? "white"
                              : C.TextPrimary,
                        }}
                      >
                        {day}
                      </span>
                      {avail ? (
                        <div
                          className="w-full rounded-lg flex items-center justify-center gap-0.5 py-0.5 px-1"
                          style={{
                            backgroundColor: isSelected
                              ? "rgba(255,255,255,0.2)"
                              : !avail.available
                              ? C.Sunset + "40"
                              : avail.start
                              ? C.Honey + "60"
                              : C.Grass + "60",
                          }}
                        >
                          {!avail.available ? (
                            <BanIcon
                              size={9}
                              style={{
                                color: isSelected
                                  ? "rgba(255,255,255,0.8)"
                                  : C.Sunset,
                                flexShrink: 0,
                              }}
                            />
                          ) : avail.start ? (
                            <Clock
                              size={9}
                              style={{
                                color: isSelected
                                  ? "rgba(255,255,255,0.8)"
                                  : C.Bark,
                                flexShrink: 0,
                              }}
                            />
                          ) : (
                            <Check
                              size={9}
                              style={{
                                color: isSelected
                                  ? "rgba(255,255,255,0.8)"
                                  : C.Pine,
                                flexShrink: 0,
                              }}
                            />
                          )}
                          {avail?.available && avail.start && (
                            <span
                              className="text-[8px] font-medium leading-none truncate"
                              style={{
                                color: isSelected
                                  ? "rgba(255,255,255,0.8)"
                                  : C.Bark,
                              }}
                            >
                              {avail.start}
                            </span>
                          )}
                        </div>
                      ) : (
                        <div
                          className="w-full h-3 rounded-sm"
                          style={{
                            backgroundColor: isSelected
                              ? "rgba(255,255,255,0.1)"
                              : "transparent",
                          }}
                        />
                      )}
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Dag invoerpanel — popup stijl */}
            {(() => {
              const panelTargetDates =
                rangeStart && selectedDate && rangeStart !== selectedDate
                  ? rangeDates
                  : selectedDate
                  ? [selectedDate]
                  : [];
              const panelAllLocked =
                panelTargetDates.length > 0 &&
                panelTargetDates.every((d) => isDayLocked(activeUser, d));
              return (
                selectedDate &&
                editForm && (
                  <div
                    className="bg-white rounded-2xl border overflow-hidden shadow-sm"
                    style={{ borderColor: t.primary }}
                  >
                    {/* Header */}
                    <div
                      className="flex items-center justify-between px-4 py-3"
                      style={{ backgroundColor: t.primary }}
                    >
                      <div>
                        {isFM && viewingName !== loggedInUserName && (
                          <p className="text-[11px] text-white opacity-75 font-medium mb-0.5 flex items-center gap-1">
                            <Users size={10} /> {viewingName}
                          </p>
                        )}
                        <p className="font-bold text-sm text-white">
                          {rangeStart && rangeStart !== selectedDate
                            ? `${formatDayLabel(
                                rangeStart
                              )} t/m ${formatDayLabel(selectedDate)}`
                            : formatDayLabel(selectedDate)}
                        </p>
                        {rangeStart && rangeStart !== selectedDate && (
                          <p className="text-[11px] text-white opacity-75 mt-0.5">
                            {rangeDates.length} dagen
                          </p>
                        )}
                      </div>
                      <div className="flex items-center gap-1.5">
                        {isFM &&
                          !(rangeStart && rangeStart !== selectedDate) && (
                            <button
                              onClick={() => {
                                setRangeStart(selectedDate);
                                setRangeMode(true);
                                setSelectedDate(null);
                                setEditForm(null);
                              }}
                              className="p-1.5 rounded-lg"
                              style={{
                                backgroundColor: "rgba(255,255,255,0.2)",
                                color: "white",
                              }}
                              title="Kies een periode (meerdere dagen) om te vergrendelen"
                            >
                              <CalendarRange size={15} />
                            </button>
                          )}
                        {isFM && (
                          <button
                            onClick={() =>
                              setDaysLocked(
                                activeUser,
                                panelTargetDates,
                                !panelAllLocked
                              )
                            }
                            className="p-1.5 rounded-lg"
                            style={{
                              backgroundColor: "rgba(255,255,255,0.2)",
                              color: "white",
                            }}
                            title={
                              panelAllLocked
                                ? "Ontgrendel deze dag(en)"
                                : "Zet deze dag(en) dicht voor de medewerker"
                            }
                          >
                            {panelAllLocked ? (
                              <Unlock size={15} />
                            ) : (
                              <Lock size={15} />
                            )}
                          </button>
                        )}
                        <button
                          onClick={() => {
                            setSelectedDate(null);
                            setEditForm(null);
                            setRangeStart(null);
                            setRangeMode(false);
                          }}
                          className="p-1.5 rounded-lg"
                          style={{
                            backgroundColor: "rgba(255,255,255,0.2)",
                            color: "white",
                          }}
                        >
                          <X size={15} />
                        </button>
                      </div>
                    </div>

                    {/* Dichtgezet-banner (FM) — vervangt de invulstappen */}
                    {panelAllLocked ? (
                      <div className="px-4 py-5 space-y-3">
                        <div
                          className="flex items-center gap-3 px-3 py-3 rounded-xl"
                          style={{
                            backgroundColor: "#e5e7eb",
                            border: `1px solid ${C.TextMuted}60`,
                          }}
                        >
                          <Lock
                            size={16}
                            style={{ color: C.TextMuted, flexShrink: 0 }}
                          />
                          <p
                            className="text-sm font-medium"
                            style={{ color: C.TextSecondary }}
                          >
                            {panelTargetDates.length > 1
                              ? "Deze dagen zijn dichtgezet."
                              : "Deze dag is dichtgezet."}{" "}
                            {viewingName} kan hier geen beschikbaarheid meer
                            voor invullen.
                          </p>
                        </div>
                        {panelTargetDates.length === 1 &&
                          (() => {
                            const a = getMyAvail(selectedDate);
                            const label = !a
                              ? "Nog niet ingevuld"
                              : !a.available
                              ? "Niet beschikbaar"
                              : a.start
                              ? `${a.start}–${a.end} beschikbaar`
                              : "Hele dag beschikbaar";
                            const dotColor = !a
                              ? C.BorderLight
                              : !a.available
                              ? C.Sunset
                              : a.start
                              ? C.Honey
                              : C.Grass;
                            return (
                              <div className="flex items-center gap-2 px-1 text-xs">
                                <span
                                  className="w-2 h-2 rounded-full flex-shrink-0"
                                  style={{ backgroundColor: dotColor }}
                                />
                                <span style={{ color: C.TextMuted }}>
                                  Ingevulde beschikbaarheid: {label}
                                  {a?.note && (
                                    <span className="italic opacity-70">
                                      {" "}
                                      · {a.note}
                                    </span>
                                  )}
                                </span>
                              </div>
                            );
                          })()}
                        <button
                          onClick={() =>
                            setDaysLocked(activeUser, panelTargetDates, false)
                          }
                          className="w-full py-2.5 rounded-xl font-bold text-sm flex items-center justify-center gap-2"
                          style={{
                            backgroundColor: t.primary + "12",
                            color: t.primary,
                          }}
                        >
                          <Unlock size={14} />
                          Ontgrendelen
                        </button>
                      </div>
                    ) : (
                      <>
                        {/* Stap 1: scope — 1 dag of meerdere */}
                        {editForm.step === "scope" && (
                          <div className="px-4 py-5 space-y-3">
                            <p
                              className="text-xs font-semibold uppercase tracking-wide"
                              style={{ color: C.TextMuted }}
                            >
                              Geldt voor
                            </p>
                            <div className="grid grid-cols-2 gap-3">
                              <button
                                onClick={() =>
                                  setEditForm((f) => ({ ...f, step: "form" }))
                                }
                                className="flex flex-col items-center gap-2 py-4 rounded-xl border text-sm font-bold transition-all"
                                style={{
                                  borderColor: t.secondary,
                                  backgroundColor: "white",
                                  color: C.TextPrimary,
                                }}
                              >
                                <CalendarDays
                                  size={22}
                                  style={{ color: t.primary }}
                                />
                                1 dag
                                <span
                                  className="text-[11px] font-normal"
                                  style={{ color: C.TextMuted }}
                                >
                                  Alleen{" "}
                                  {formatDayLabel(selectedDate)
                                    .split(" ")
                                    .slice(0, 2)
                                    .join(" ")}
                                </span>
                              </button>
                              <button
                                onClick={() => {
                                  // Enable range mode: user picks end date from calendar
                                  setRangeStart(selectedDate);
                                  setRangeMode(true);
                                  setSelectedDate(null);
                                  setEditForm(null);
                                }}
                                className="flex flex-col items-center gap-2 py-4 rounded-xl border text-sm font-bold transition-all"
                                style={{
                                  borderColor: t.secondary,
                                  backgroundColor: "white",
                                  color: C.TextPrimary,
                                }}
                              >
                                <CalendarRange
                                  size={22}
                                  style={{ color: t.primary }}
                                />
                                Meerdere dagen
                                <span
                                  className="text-[11px] font-normal"
                                  style={{ color: C.TextMuted }}
                                >
                                  Kies einddatum
                                </span>
                              </button>
                            </div>
                          </div>
                        )}

                        {/* Stap 2: beschikbaarheid invullen */}
                        {editForm.step === "form" && (
                          <div className="px-4 py-4 space-y-4">
                            {/* Scope label als meerdere dagen */}
                            {rangeStart && rangeStart !== selectedDate && (
                              <div
                                className="flex items-center gap-2 px-3 py-2 rounded-xl text-xs font-medium"
                                style={{
                                  backgroundColor: t.primary + "10",
                                  color: t.primary,
                                }}
                              >
                                <CalendarRange size={13} />
                                Geldt voor {rangeDates.length} dagen (
                                {formatDayLabel(rangeStart)} t/m{" "}
                                {formatDayLabel(selectedDate)})
                              </div>
                            )}

                            {/* FM: snel-goedkeuren als deze dag al is ingevuld en wacht op goedkeuring */}
                            {isFM &&
                              !(rangeStart && rangeStart !== selectedDate) &&
                              (() => {
                                const existing = getMyAvail(selectedDate);
                                const status = availStatus(
                                  existing,
                                  selectedDate
                                );
                                if (
                                  status !== "pending" &&
                                  status !== "rejected"
                                )
                                  return null;
                                return (
                                  <div
                                    className="flex items-center gap-2 px-3 py-2 rounded-xl text-xs font-medium"
                                    style={{
                                      backgroundColor:
                                        status === "pending"
                                          ? C.HoneyLight
                                          : C.BlossomLight,
                                      color:
                                        status === "pending"
                                          ? C.Bark
                                          : C.Sunset,
                                    }}
                                  >
                                    {status === "pending" ? (
                                      <Clock3 size={13} />
                                    ) : (
                                      <AlertTriangle size={13} />
                                    )}
                                    <span className="flex-1">
                                      {status === "pending"
                                        ? "Wacht op jouw goedkeuring"
                                        : "Afgekeurd — moet opnieuw ingevuld worden"}
                                    </span>
                                    {status === "pending" && (
                                      <>
                                        <button
                                          onClick={() =>
                                            setAvailStatus(
                                              activeUser,
                                              selectedDate,
                                              "rejected"
                                            )
                                          }
                                          className="p-1 rounded-lg"
                                          style={{
                                            backgroundColor: "white",
                                            color: C.Sunset,
                                          }}
                                          title="Afwijzen"
                                        >
                                          <X size={12} />
                                        </button>
                                        <button
                                          onClick={() =>
                                            setAvailStatus(
                                              activeUser,
                                              selectedDate,
                                              "approved"
                                            )
                                          }
                                          className="p-1 rounded-lg"
                                          style={{
                                            backgroundColor: "white",
                                            color: C.Pine,
                                          }}
                                          title="Goedkeuren"
                                        >
                                          <Check size={12} />
                                        </button>
                                      </>
                                    )}
                                  </div>
                                );
                              })()}

                            {/* 3 keuzes */}
                            <div className="grid grid-cols-3 gap-2">
                              {[
                                {
                                  id: "hele_dag",
                                  label: "Hele dag",
                                  Icon: Sun,
                                  color: C.Pine,
                                  bg: C.Grass + "40",
                                  border: C.Grass,
                                },
                                {
                                  id: "niet",
                                  label: "Niet beschikbaar",
                                  Icon: BanIcon,
                                  color: C.Sunset,
                                  bg: C.Sunset + "15",
                                  border: C.Sunset + "60",
                                },
                                {
                                  id: "tijd",
                                  label: "Bepaalde tijd",
                                  Icon: Clock,
                                  color: C.Bark,
                                  bg: C.Honey + "40",
                                  border: C.Honey,
                                },
                              ].map((opt) => {
                                const Icon = opt.Icon;
                                const isActive = editForm.mode === opt.id;
                                return (
                                  <button
                                    key={opt.id}
                                    onClick={() =>
                                      setEditForm((f) => ({
                                        ...f,
                                        mode: opt.id,
                                      }))
                                    }
                                    className="flex flex-col items-center gap-1.5 py-3 rounded-xl border text-xs font-semibold transition-all"
                                    style={{
                                      borderColor: isActive
                                        ? opt.border
                                        : C.BorderLight,
                                      backgroundColor: isActive
                                        ? opt.bg
                                        : C.White,
                                      color: isActive ? opt.color : C.TextMuted,
                                    }}
                                  >
                                    <Icon size={18} />
                                    {opt.label}
                                  </button>
                                );
                              })}
                            </div>

                            {/* Tijden (alleen bij "tijd") */}
                            {editForm.mode === "tijd" && (
                              <div className="flex gap-3 items-end">
                                <div className="flex-1">
                                  <label className="text-xs font-semibold text-gray-500 block mb-1.5">
                                    Van
                                  </label>
                                  <input
                                    type="time"
                                    value={editForm.start}
                                    onChange={(e) =>
                                      setEditForm((f) => ({
                                        ...f,
                                        start: e.target.value,
                                      }))
                                    }
                                    className="w-full border rounded-xl px-3 py-2.5 text-sm focus:outline-none"
                                    style={{ borderColor: t.secondary }}
                                    onFocus={(e) =>
                                      (e.target.style.borderColor = t.primary)
                                    }
                                    onBlur={(e) =>
                                      (e.target.style.borderColor = t.secondary)
                                    }
                                  />
                                </div>
                                <span className="text-gray-400 pb-3 text-lg">
                                  –
                                </span>
                                <div className="flex-1">
                                  <label className="text-xs font-semibold text-gray-500 block mb-1.5">
                                    Tot
                                  </label>
                                  <input
                                    type="time"
                                    value={editForm.end}
                                    onChange={(e) =>
                                      setEditForm((f) => ({
                                        ...f,
                                        end: e.target.value,
                                      }))
                                    }
                                    className="w-full border rounded-xl px-3 py-2.5 text-sm focus:outline-none"
                                    style={{ borderColor: t.secondary }}
                                    onFocus={(e) =>
                                      (e.target.style.borderColor = t.primary)
                                    }
                                    onBlur={(e) =>
                                      (e.target.style.borderColor = t.secondary)
                                    }
                                  />
                                </div>
                              </div>
                            )}

                            {/* Opmerking */}
                            <input
                              type="text"
                              value={editForm.note}
                              onChange={(e) =>
                                setEditForm((f) => ({
                                  ...f,
                                  note: e.target.value,
                                }))
                              }
                              placeholder={
                                editForm.mode === "niet"
                                  ? "Reden (optioneel)"
                                  : "Opmerking (optioneel)"
                              }
                              className="w-full border rounded-xl px-3 py-2.5 text-sm focus:outline-none"
                              style={{ borderColor: t.secondary }}
                              onFocus={(e) =>
                                (e.target.style.borderColor = t.primary)
                              }
                              onBlur={(e) =>
                                (e.target.style.borderColor = t.secondary)
                              }
                              onKeyDown={(e) =>
                                e.key === "Enter" && saveCurrent()
                              }
                            />

                            {/* Opslaan */}
                            <div className="flex gap-2">
                              <button
                                onClick={saveCurrent}
                                className="flex-1 py-2.5 rounded-xl font-bold text-white text-sm flex items-center justify-center gap-2"
                                style={{ backgroundColor: t.primary }}
                              >
                                <CheckCircle size={14} />
                                {rangeStart && rangeStart !== selectedDate
                                  ? `Opslaan voor ${rangeDates.length} dagen`
                                  : "Opslaan"}
                              </button>
                              {!rangeStart && getMyAvail(selectedDate) && (
                                <button
                                  onClick={() => clearAvail(selectedDate)}
                                  className="py-2.5 px-3 rounded-xl"
                                  style={{
                                    backgroundColor: C.BlossomLight,
                                    color: C.Sunset,
                                  }}
                                >
                                  <Trash2 size={16} />
                                </button>
                              )}
                            </div>
                          </div>
                        )}
                      </>
                    )}
                  </div>
                )
              );
            })()}

            {/* Maand samenvatting + nog in te vullen */}
            {(() => {
              const today = new Date();
              const todayIso = toIsoDate(today);
              const myData = allAvail[loggedInUserName] || {};

              // Alle dagen van de maand (ook weekenden — altijd open)
              // Dichtgezette dagen tellen niet mee: die hoeft de medewerker
              // niet meer in te vullen. Afgekeurde dagen tellen als nog te
              // doen (moet opnieuw worden ingevuld).
              const workdaysLeft = [];
              const workdaysDone = [];
              let pendingCount = 0;
              for (let d = 1; d <= daysInMonth; d++) {
                const date = dk(d);
                if (isDayLocked(loggedInUserName, date)) continue;
                const entry = myData[date];
                const status = availStatus(entry, date);
                if (status === "pending") pendingCount++;
                if (entry && status !== "rejected") {
                  workdaysDone.push(date);
                } else {
                  workdaysLeft.push(date);
                }
              }

              const totalWorkdays = workdaysDone.length + workdaysLeft.length;
              const filled = workdaysDone.length;
              const remaining = workdaysLeft.length;
              const pct =
                totalWorkdays > 0
                  ? Math.round((filled / totalWorkdays) * 100)
                  : 0;

              const myAvailDays = Object.entries(myData).filter(
                ([date, a]) => date.startsWith(monthKey) && a.available
              );
              const totalHours = myAvailDays.reduce(
                (s, [, a]) => s + hoursFromAvail(a),
                0
              );

              const barColor =
                pct === 100 ? C.Grass : pct >= 60 ? C.Honey : C.Sunset;

              return (
                <div
                  className="rounded-2xl overflow-hidden border"
                  style={{
                    borderColor: pct === 100 ? C.Pine : barColor + "50",
                    backgroundColor: pct === 100 ? C.Grass : barColor + "0A",
                  }}
                >
                  <div className="px-4 pt-3 pb-2">
                    <div className="flex items-center justify-between mb-2">
                      <div className="flex items-center gap-2">
                        <CalendarCheck2
                          size={16}
                          style={{ color: pct === 100 ? C.Pine : barColor }}
                        />
                        <p
                          className="font-bold text-sm"
                          style={{ color: pct === 100 ? C.Pine : barColor }}
                        >
                          {pct === 100
                            ? "Alle dagen ingevuld!"
                            : remaining === 0
                            ? "Ingevuld"
                            : `Nog ${remaining} dag${
                                remaining !== 1 ? "en" : ""
                              } in te vullen`}
                        </p>
                      </div>
                      <span
                        className="text-xs font-semibold"
                        style={{ color: pct === 100 ? "white" : barColor }}
                      >
                        {filled}/{totalWorkdays}
                      </span>
                    </div>
                    {/* Voortgangsbalk */}
                    {pct < 100 && (
                      <div
                        className="w-full h-2 rounded-full overflow-hidden mb-2"
                        style={{ backgroundColor: barColor + "20" }}
                      >
                        <div
                          className="h-full rounded-full transition-all"
                          style={{
                            width: `${pct}%`,
                            backgroundColor: barColor,
                          }}
                        />
                      </div>
                    )}
                    {totalHours > 0 && (
                      <p
                        className="text-xs"
                        style={{ color: pct === 100 ? C.Pine : C.TextMuted }}
                      >
                        {totalHours.toFixed(1).replace(".0", "")}u beschikbaar ·{" "}
                        {dutchMonths[viewMonth - 1]} {viewYear}
                      </p>
                    )}
                    {pendingCount > 0 && (
                      <p
                        className="text-xs mt-1 flex items-center gap-1.5"
                        style={{ color: C.Bark }}
                      >
                        <Clock3 size={12} style={{ flexShrink: 0 }} />
                        {pendingCount} dag{pendingCount !== 1 ? "en" : ""} wacht
                        {pendingCount === 1 ? "" : "en"} nog op goedkeuring van
                        de FM
                      </p>
                    )}
                  </div>
                </div>
              );
            })()}
          </>
        )}

        {/* ── FM VIEW ── */}
        {isFM && (
          <>
            {/* Open/sluiten toggle */}
            <div
              className="rounded-2xl border overflow-hidden"
              style={{ borderColor: isOpen ? t.secondary : C.Border }}
            >
              <div
                className="flex items-center gap-3 px-4 py-3"
                style={{
                  backgroundColor: isOpen ? t.primary + "08" : C.BorderLight,
                }}
              >
                <div className="flex-1">
                  <p
                    className="font-bold text-sm"
                    style={{ color: isOpen ? t.primary : C.TextMuted }}
                  >
                    {isOpen
                      ? "Open voor inschrijvingen"
                      : "Gesloten voor medewerkers"}
                  </p>
                  {inst.deadline && (
                    <p
                      className="text-xs mt-0.5"
                      style={{ color: deadlinePassed ? C.Sunset : C.TextMuted }}
                    >
                      {deadlinePassed ? "Deadline verstreken: " : "Deadline: "}
                      {formatDeadline(inst.deadline)}
                    </p>
                  )}
                </div>
                <button
                  onClick={() => setMaandOpen(!isOpen)}
                  className="relative w-11 h-6 rounded-full transition-colors flex-shrink-0"
                  style={{ backgroundColor: isOpen ? t.primary : C.Border }}
                >
                  <span
                    className="absolute top-0.5 w-5 h-5 bg-white rounded-full shadow transition-all"
                    style={{
                      left: isOpen ? "calc(100% - 1.375rem)" : "0.125rem",
                    }}
                  />
                </button>
                <button
                  onClick={() => setShowDeadlineSettings((s) => !s)}
                  className="p-1.5 rounded-lg"
                  style={{ color: C.TextMuted }}
                >
                  <ChevronDown
                    size={15}
                    style={{
                      transform: showDeadlineSettings
                        ? "rotate(180deg)"
                        : "none",
                      transition: "transform 0.2s",
                    }}
                  />
                </button>
              </div>
              {showDeadlineSettings && (
                <div
                  className="px-4 pb-3 pt-2 space-y-2 border-t"
                  style={{ borderColor: C.BorderLight }}
                >
                  <label
                    className="text-xs font-semibold uppercase tracking-wide block"
                    style={{ color: C.TextMuted }}
                  >
                    Sluitingsdatum
                  </label>
                  <div className="flex gap-2">
                    <input
                      type="date"
                      value={inst.deadline || ""}
                      onChange={(e) => setDeadline(e.target.value)}
                      className="flex-1 border rounded-xl px-3 py-2 text-sm focus:outline-none"
                      style={{ borderColor: t.secondary }}
                      onFocus={(e) => (e.target.style.borderColor = t.primary)}
                      onBlur={(e) => (e.target.style.borderColor = t.secondary)}
                    />
                    {inst.deadline && (
                      <button
                        onClick={() => setDeadline("")}
                        className="p-2 rounded-xl"
                        style={{
                          backgroundColor: C.BlossomLight,
                          color: C.Sunset,
                        }}
                      >
                        <X size={14} />
                      </button>
                    )}
                  </div>
                  <p className="text-[11px] text-gray-400">
                    Na deze datum kunnen medewerkers geen beschikbaarheid meer
                    invullen
                  </p>
                </div>
              )}
            </div>

            {/* Ter goedkeuring — nieuwe/gewijzigde beschikbaarheid van medewerkers */}
            {(() => {
              const pendingEntries = [];
              allStaff.forEach((s) => {
                const userAvail = allAvail[s.name] || {};
                Object.entries(userAvail).forEach(([date, a]) => {
                  if (
                    date.startsWith(monthKey) &&
                    availStatus(a, date) === "pending"
                  ) {
                    pendingEntries.push({ name: s.name, date, a });
                  }
                });
              });
              if (pendingEntries.length === 0) return null;

              // Groepeer per dag, zodat de FM per dag in 1 oogopslag ziet
              // hoeveel mensen er al (goedgekeurd of nog wachtend) vrij
              // hebben gevraagd, vóór hij/zij een aanvraag beoordeelt.
              const byDate = {};
              pendingEntries.forEach((e) => {
                if (!byDate[e.date]) byDate[e.date] = [];
                byDate[e.date].push(e);
              });
              const dateKeys = Object.keys(byDate).sort();

              const dateStats = (date) => {
                let offApproved = 0,
                  offPending = 0,
                  availApproved = 0,
                  availPending = 0;
                allStaff.forEach((s) => {
                  const entry = allAvail[s.name]?.[date];
                  if (!entry) return;
                  const st = availStatus(entry, date);
                  if (entry.available === false) {
                    if (st === "approved") offApproved++;
                    else if (st === "pending") offPending++;
                  } else if (entry.available === true) {
                    if (st === "approved") availApproved++;
                    else if (st === "pending") availPending++;
                  }
                });
                return {
                  offApproved,
                  offPending,
                  offTotal: offApproved + offPending,
                  availApproved,
                  availPending,
                  total: allStaff.length,
                };
              };

              return (
                <div
                  className="rounded-2xl border overflow-hidden"
                  style={{ borderColor: C.Honey }}
                >
                  <div
                    className="px-4 py-2.5 border-b flex items-center gap-2"
                    style={{
                      borderColor: C.BorderLight,
                      backgroundColor: C.HoneyLight,
                    }}
                  >
                    <Clock3 size={15} style={{ color: C.Bark }} />
                    <p
                      className="text-xs font-semibold uppercase tracking-wide flex-1"
                      style={{ color: C.Bark }}
                    >
                      Wacht op goedkeuring ({pendingEntries.length})
                    </p>
                  </div>
                  <div
                    className="divide-y"
                    style={{ borderColor: C.BorderLight }}
                  >
                    {dateKeys.map((date) => {
                      const stats = dateStats(date);
                      return (
                        <div key={date}>
                          {/* Dagkop met overzicht: hoeveel is er al vrij gevraagd */}
                          <div
                            className="px-4 py-2 flex items-center flex-wrap gap-x-3 gap-y-1"
                            style={{ backgroundColor: C.Bg }}
                          >
                            <p
                              className="text-xs font-bold flex-shrink-0"
                              style={{ color: C.TextPrimary }}
                            >
                              {formatDayLabel(date)}
                            </p>
                            <span
                              className="text-[11px] font-semibold px-1.5 py-0.5 rounded-full"
                              style={{
                                backgroundColor: C.Sunset + "20",
                                color: C.Sunset,
                              }}
                              title="Aantal medewerkers dat vrij heeft gevraagd (goedgekeurd + nog wachtend)"
                            >
                              {stats.offTotal}/{stats.total} vrij gevraagd
                              {stats.offPending > 0 &&
                                ` (${stats.offApproved} goedgekeurd, ${stats.offPending} wacht)`}
                            </span>
                            {stats.availApproved + stats.availPending > 0 && (
                              <span
                                className="text-[11px] font-semibold px-1.5 py-0.5 rounded-full"
                                style={{
                                  backgroundColor: C.Grass + "25",
                                  color: C.Pine,
                                }}
                              >
                                {stats.availApproved + stats.availPending}/
                                {stats.total} beschikbaar
                              </span>
                            )}
                            <button
                              onClick={() => bulkApproveDate(date)}
                              className="ml-auto flex items-center gap-1 text-[11px] font-bold px-2 py-1 rounded-lg flex-shrink-0"
                              style={{
                                backgroundColor: C.Grass + "20",
                                color: C.Pine,
                              }}
                              title="Alle openstaande aanvragen voor deze dag goedkeuren"
                            >
                              <CheckCheck size={12} />
                              Hele dag goedkeuren
                            </button>
                          </div>
                          {byDate[date].map(({ name, date, a }) => {
                            const label = !a.available
                              ? "Niet beschikbaar"
                              : a.start
                              ? `${a.start}–${a.end}`
                              : "Hele dag";
                            return (
                              <div
                                key={name + date}
                                className="flex items-center gap-3 px-4 py-2.5 border-t"
                                style={{ borderColor: C.BorderLight }}
                              >
                                <ProfileAvatar
                                  name={name}
                                  staffList={appData.staffList || []}
                                  size={28}
                                  color={t.primary}
                                />
                                <div className="flex-1 min-w-0">
                                  <p className="text-sm font-semibold">
                                    {name}
                                  </p>
                                  <p
                                    className="text-xs"
                                    style={{ color: C.TextMuted }}
                                  >
                                    {label}
                                    {a.note && (
                                      <span className="italic opacity-70">
                                        {" "}
                                        · {a.note}
                                      </span>
                                    )}
                                  </p>
                                  {a.submittedAt && (
                                    <p
                                      className="text-[11px] flex items-center gap-1 mt-0.5"
                                      style={{
                                        color: C.TextMuted,
                                        opacity: 0.75,
                                      }}
                                    >
                                      <Clock3 size={10} />
                                      Aangevraagd op{" "}
                                      {new Date(
                                        a.submittedAt
                                      ).toLocaleDateString("nl-NL", {
                                        day: "numeric",
                                        month: "short",
                                      })}{" "}
                                      om{" "}
                                      {new Date(
                                        a.submittedAt
                                      ).toLocaleTimeString("nl-NL", {
                                        hour: "2-digit",
                                        minute: "2-digit",
                                      })}
                                    </p>
                                  )}
                                </div>
                                <button
                                  onClick={() =>
                                    setAvailStatus(name, date, "rejected")
                                  }
                                  className="p-2 rounded-lg flex-shrink-0"
                                  style={{
                                    backgroundColor: C.BlossomLight,
                                    color: C.Sunset,
                                  }}
                                  title="Afwijzen"
                                >
                                  <X size={14} />
                                </button>
                                <button
                                  onClick={() =>
                                    setAvailStatus(name, date, "approved")
                                  }
                                  className="p-2 rounded-lg flex-shrink-0"
                                  style={{
                                    backgroundColor: C.Grass + "25",
                                    color: C.Pine,
                                  }}
                                  title="Goedkeuren"
                                >
                                  <Check size={14} />
                                </button>
                              </div>
                            );
                          })}
                        </div>
                      );
                    })}
                  </div>
                </div>
              );
            })()}

            {/* Geschiedenis — al afgehandelde (goedgekeurde/afgekeurde) aanvragen
                van deze maand, zodat je kunt terugkomen op eerdere vragen
                (wie vroeg wat aan, wanneer, en wanneer/door wie beslist). */}
            {(() => {
              const decidedEntries = [];
              allStaff.forEach((s) => {
                const userAvail = allAvail[s.name] || {};
                Object.entries(userAvail).forEach(([date, a]) => {
                  const status = availStatus(a, date);
                  if (
                    date.startsWith(monthKey) &&
                    (status === "approved" || status === "rejected")
                  ) {
                    decidedEntries.push({ name: s.name, date, a, status });
                  }
                });
              });
              if (decidedEntries.length === 0) return null;

              decidedEntries.sort((x, y) => {
                const dx = x.a.approvedAt || x.a.rejectedAt || x.date;
                const dy = y.a.approvedAt || y.a.rejectedAt || y.date;
                return dy.localeCompare(dx);
              });

              const fmtDateTime = (iso) =>
                `${new Date(iso).toLocaleDateString("nl-NL", {
                  day: "numeric",
                  month: "short",
                })} om ${new Date(iso).toLocaleTimeString("nl-NL", {
                  hour: "2-digit",
                  minute: "2-digit",
                })}`;

              return (
                <div
                  className="rounded-2xl border overflow-hidden"
                  style={{ borderColor: C.BorderLight }}
                >
                  <button
                    onClick={() => setShowVerlofHistory((v) => !v)}
                    className="w-full flex items-center gap-2 px-4 py-3"
                    style={{ backgroundColor: C.White }}
                  >
                    <p
                      className="font-bold text-sm flex-1 text-left"
                      style={{ color: C.TextPrimary }}
                    >
                      Geschiedenis vrijaanvragen
                    </p>
                    <span
                      className="text-[11px] font-semibold px-1.5 py-0.5 rounded-full"
                      style={{
                        backgroundColor: C.TextMuted + "15",
                        color: C.TextSecondary,
                      }}
                    >
                      {decidedEntries.length}
                    </span>
                    {showVerlofHistory ? (
                      <ChevronUp size={16} style={{ color: C.TextMuted }} />
                    ) : (
                      <ChevronDown size={16} style={{ color: C.TextMuted }} />
                    )}
                  </button>
                  {showVerlofHistory && (
                    <div>
                      {decidedEntries.map(({ name, date, a, status }) => {
                        const label = !a.available
                          ? "Niet beschikbaar"
                          : a.start
                          ? `${a.start}–${a.end}`
                          : "Hele dag";
                        return (
                          <div
                            key={name + date}
                            className="flex items-center gap-3 px-4 py-2.5 border-t"
                            style={{ borderColor: C.BorderLight }}
                          >
                            <ProfileAvatar
                              name={name}
                              staffList={appData.staffList || []}
                              size={28}
                              color={t.primary}
                            />
                            <div className="flex-1 min-w-0">
                              <p className="text-sm font-semibold">
                                {name}{" "}
                                <span
                                  className="font-normal"
                                  style={{ color: C.TextMuted }}
                                >
                                  · {formatDayLabel(date)}
                                </span>
                              </p>
                              <p
                                className="text-xs"
                                style={{ color: C.TextMuted }}
                              >
                                {label}
                                {a.note && (
                                  <span className="italic opacity-70">
                                    {" "}
                                    · {a.note}
                                  </span>
                                )}
                              </p>
                              {a.submittedAt && (
                                <p
                                  className="text-[11px] mt-0.5"
                                  style={{ color: C.TextMuted, opacity: 0.75 }}
                                >
                                  Aangevraagd op {fmtDateTime(a.submittedAt)}
                                </p>
                              )}
                              {status === "approved" && a.approvedAt && (
                                <p
                                  className="text-[11px] mt-0.5"
                                  style={{ color: C.Pine, opacity: 0.85 }}
                                >
                                  Goedgekeurd op {fmtDateTime(a.approvedAt)}
                                  {a.approvedBy ? ` door ${a.approvedBy}` : ""}
                                </p>
                              )}
                              {status === "rejected" && a.rejectedAt && (
                                <p
                                  className="text-[11px] mt-0.5"
                                  style={{ color: C.Sunset, opacity: 0.85 }}
                                >
                                  Afgekeurd op {fmtDateTime(a.rejectedAt)}
                                  {a.rejectedBy ? ` door ${a.rejectedBy}` : ""}
                                </p>
                              )}
                            </div>
                            <span
                              className="text-[11px] font-bold px-2 py-1 rounded-lg flex-shrink-0"
                              style={{
                                backgroundColor:
                                  status === "approved"
                                    ? C.Grass + "25"
                                    : C.BlossomLight,
                                color:
                                  status === "approved" ? C.Pine : C.Sunset,
                              }}
                            >
                              {status === "approved"
                                ? "Goedgekeurd"
                                : "Afgekeurd"}
                            </span>
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              );
            })()}

            {/* Vergrendel-modus: dagen per medewerker dichtzetten */}
            <div
              className="rounded-2xl border overflow-hidden"
              style={{ borderColor: lockMode ? C.TextMuted : C.BorderLight }}
            >
              <div
                className="flex items-center gap-3 px-4 py-3"
                style={{
                  backgroundColor: lockMode ? "#e5e7eb" : C.White,
                }}
              >
                <div
                  className="p-2 rounded-xl flex-shrink-0"
                  style={{
                    backgroundColor: lockMode ? "#d1d5db" : C.TextMuted + "15",
                  }}
                >
                  <Lock
                    size={15}
                    style={{ color: lockMode ? C.TextSecondary : C.TextMuted }}
                  />
                </div>
                <div className="flex-1">
                  <p
                    className="font-bold text-sm"
                    style={{
                      color: lockMode ? C.TextSecondary : C.TextPrimary,
                    }}
                  >
                    Dagen dichtzetten per medewerker
                  </p>
                  <p className="text-xs mt-0.5" style={{ color: C.TextMuted }}>
                    {lockMode
                      ? lockRangeAnchor
                        ? `Klik nu op de laatste dag voor ${
                            lockRangeAnchor.name.split(" ")[0]
                          } — of dezelfde dag nogmaals voor 1 dag`
                        : "Klik op een dag, en op de laatste dag voor een periode"
                      : "Zet aan om dagen te vergrendelen in het overzicht"}
                  </p>
                </div>
                <button
                  onClick={() => {
                    setLockMode((v) => !v);
                    setLockRangeAnchor(null);
                  }}
                  className="relative w-11 h-6 rounded-full transition-colors flex-shrink-0"
                  style={{ backgroundColor: lockMode ? C.TextMuted : C.Border }}
                >
                  <span
                    className="absolute top-0.5 w-5 h-5 bg-white rounded-full shadow transition-all"
                    style={{
                      left: lockMode ? "calc(100% - 1.375rem)" : "0.125rem",
                    }}
                  />
                </button>
              </div>
            </div>

            {/* ── MAANDGRID OVERZICHT ── */}
            {(() => {
              const staffNames = allStaff.map((s) => s.name);
              const colTemplate = `100px repeat(${daysInMonth}, minmax(0,1fr))`;
              const dayLabels = ["Ma", "Di", "Wo", "Do", "Vr", "Za", "Zo"];
              return (
                <div
                  className="bg-white rounded-2xl border overflow-hidden"
                  style={{ borderColor: C.BorderLight }}
                >
                  <div
                    className="px-4 py-2.5 border-b flex items-center gap-2"
                    style={{
                      borderColor: C.BorderLight,
                      backgroundColor: C.Bg,
                    }}
                  >
                    <p
                      className="text-xs font-semibold uppercase tracking-wide flex-1"
                      style={{ color: C.TextMuted }}
                    >
                      Maandoverzicht — {dutchMonths[viewMonth - 1]} {viewYear}
                    </p>
                    <div className="flex items-center gap-2 text-[11px] font-semibold">
                      <span
                        className="px-2 py-0.5 rounded-full"
                        style={{
                          backgroundColor: C.Grass + "30",
                          color: C.Pine,
                        }}
                      >
                        ✓ Beschikbaar
                      </span>
                      <span
                        className="px-2 py-0.5 rounded-full"
                        style={{
                          backgroundColor: C.Honey + "30",
                          color: C.Bark,
                        }}
                      >
                        ~ Deels
                      </span>
                      <span
                        className="px-2 py-0.5 rounded-full"
                        style={{
                          backgroundColor: C.Sunset + "20",
                          color: C.Sunset,
                        }}
                      >
                        ✗ Niet
                      </span>
                      <span
                        className="px-2 py-0.5 rounded-full"
                        style={{
                          backgroundColor: "#d1d5db",
                          color: C.TextSecondary,
                        }}
                      >
                        🔒 Dicht
                      </span>
                    </div>
                  </div>
                  <div className="overflow-x-auto">
                    <div
                      style={{
                        minWidth: `calc(100px + ${daysInMonth * 28}px)`,
                      }}
                    >
                      {/* Dag koprij */}
                      <div
                        className="grid border-b"
                        style={{
                          gridTemplateColumns: colTemplate,
                          borderColor: C.BorderLight,
                        }}
                      >
                        <div className="px-3 py-1.5 text-[11px] font-semibold text-gray-400 uppercase">
                          Naam
                        </div>
                        {Array.from({ length: daysInMonth }, (_, i) => {
                          const day = i + 1;
                          const date = dk(day);
                          const d = new Date(date);
                          const wd = d.getDay() === 0 ? 6 : d.getDay() - 1;
                          const isWeekend = wd >= 5;
                          const isToday =
                            date === new Date().toISOString().slice(0, 10);
                          return (
                            <div
                              key={day}
                              className="flex flex-col items-center py-1 text-center"
                              style={{
                                backgroundColor: isWeekend
                                  ? "#f9fafb"
                                  : "transparent",
                              }}
                            >
                              <span
                                className="text-[9px] font-bold"
                                style={{
                                  color: isWeekend
                                    ? C.TextMuted
                                    : C.TextSecondary,
                                }}
                              >
                                {dayLabels[wd]}
                              </span>
                              <span
                                className="text-[11px] font-black w-5 h-5 flex items-center justify-center rounded-full"
                                style={{
                                  backgroundColor: isToday
                                    ? t.primary
                                    : "transparent",
                                  color: isToday
                                    ? "white"
                                    : isWeekend
                                    ? C.TextMuted
                                    : C.TextPrimary,
                                }}
                              >
                                {day}
                              </span>
                            </div>
                          );
                        })}
                      </div>

                      {/* Medewerker rijen */}
                      {staffNames.map((name, rowIdx) => (
                        <div
                          key={name}
                          className="grid border-b last:border-0"
                          style={{
                            gridTemplateColumns: colTemplate,
                            borderColor: C.BorderLight,
                            backgroundColor: rowIdx % 2 === 0 ? "white" : C.Bg,
                          }}
                        >
                          {/* Naam */}
                          <div className="px-3 py-1.5 flex items-center gap-1.5">
                            <ProfileAvatar
                              name={name}
                              staffList={appData.staffList || []}
                              size={20}
                              color={t.primary}
                            />
                            <span
                              className="text-xs font-semibold truncate"
                              style={{ color: C.TextPrimary }}
                            >
                              {name}
                            </span>
                          </div>

                          {/* Dag cellen */}
                          {Array.from({ length: daysInMonth }, (_, i) => {
                            const day = i + 1;
                            const date = dk(day);
                            const d = new Date(date);
                            const wd = d.getDay() === 0 ? 6 : d.getDay() - 1;
                            const isWeekend = wd >= 5;
                            const avail = allAvail[name]?.[date];
                            const isAvail = avail?.available === true;
                            const isNotAvail = avail?.available === false;
                            const isDeels = isAvail && avail?.start;
                            const locked = isDayLocked(name, date);
                            const avStatus = availStatus(avail, date);

                            let bg = "transparent";
                            let symbol = "";
                            let color = "transparent";

                            if (isNotAvail) {
                              bg = C.Sunset + "25";
                              color = C.Sunset;
                              symbol = "✗";
                            } else if (isDeels) {
                              bg = C.Honey + "35";
                              color = C.Bark;
                              symbol = "~";
                            } else if (isAvail) {
                              bg = C.Grass + "35";
                              color = C.Pine;
                              symbol = "✓";
                            }

                            // Bij een dichtgezette dag blijft de kleur van de
                            // onderliggende beschikbaarheid zichtbaar (bg/color),
                            // met een slotje erbovenop — zo zie je in 1 oogopslag
                            // zowel "dichtgezet" als "wel/niet beschikbaar".
                            const lockColor =
                              color !== "transparent" ? color : C.TextMuted;

                            const isPendingAnchor =
                              lockRangeAnchor &&
                              lockRangeAnchor.name === name &&
                              lockRangeAnchor.date === date;

                            const handleLockClick = () => {
                              if (
                                !lockRangeAnchor ||
                                lockRangeAnchor.name !== name
                              ) {
                                // 1e klik: begin van periode (of nieuwe rij → reset)
                                setLockRangeAnchor({ name, date, locked });
                                return;
                              }
                              if (lockRangeAnchor.date === date) {
                                // Zelfde dag nogmaals: gewoon 1 dag (ont)grendelen
                                setDaysLocked(name, [date], !locked);
                                setLockRangeAnchor(null);
                                return;
                              }
                              // 2e klik: hele periode (ont)grendelen
                              const rangeForRow = getDatesInRange(
                                lockRangeAnchor.date,
                                date
                              ).filter((dd) => dd.startsWith(monthKey));
                              setDaysLocked(
                                name,
                                rangeForRow,
                                !lockRangeAnchor.locked
                              );
                              setLockRangeAnchor(null);
                            };

                            return (
                              <div
                                key={day}
                                onClick={lockMode ? handleLockClick : undefined}
                                className="flex items-center justify-center relative"
                                style={{
                                  backgroundColor:
                                    isWeekend && !symbol
                                      ? "#f9fafb"
                                      : bg ||
                                        (isWeekend ? "#f9fafb" : "transparent"),
                                  height: 28,
                                  cursor: lockMode ? "pointer" : "default",
                                  outline: isPendingAnchor
                                    ? `2px solid ${t.primary}`
                                    : locked
                                    ? `1.5px solid ${C.TextMuted}90`
                                    : lockMode
                                    ? `1px dashed ${C.TextMuted}50`
                                    : "none",
                                  outlineOffset: -1,
                                }}
                                title={
                                  isPendingAnchor
                                    ? "Startdag van periode — klik de laatste dag"
                                    : locked
                                    ? `Dichtgezet${
                                        isNotAvail
                                          ? " · niet beschikbaar"
                                          : isDeels
                                          ? ` · ${avail.start}–${avail.end}`
                                          : isAvail
                                          ? " · hele dag beschikbaar"
                                          : " · nog niet ingevuld"
                                      }`
                                    : lockMode
                                    ? "Klik om te vergrendelen (of een 2e dag voor een periode)"
                                    : avStatus === "pending"
                                    ? "Wacht op goedkeuring van de FM"
                                    : avStatus === "rejected"
                                    ? "Afgekeurd — medewerker moet opnieuw invullen"
                                    : avail?.note ||
                                      (isDeels
                                        ? `${avail.start}–${avail.end}`
                                        : "")
                                }
                              >
                                {!lockMode && avStatus === "pending" && (
                                  <span
                                    className="absolute top-0 right-0 rounded-full"
                                    style={{
                                      width: 6,
                                      height: 6,
                                      backgroundColor: C.Honey,
                                    }}
                                  />
                                )}
                                {!lockMode && avStatus === "rejected" && (
                                  <span
                                    className="absolute top-0 right-0 rounded-full"
                                    style={{
                                      width: 6,
                                      height: 6,
                                      backgroundColor: C.Sunset,
                                    }}
                                  />
                                )}
                                {locked ? (
                                  <Lock
                                    size={10}
                                    style={{ color: lockColor }}
                                  />
                                ) : (
                                  symbol && (
                                    <span
                                      className="text-[11px] font-black"
                                      style={{ color }}
                                    >
                                      {symbol}
                                    </span>
                                  )
                                )}
                              </div>
                            );
                          })}
                        </div>
                      ))}

                      {/* Totaalrij */}
                      <div
                        className="grid border-t"
                        style={{
                          gridTemplateColumns: colTemplate,
                          borderColor: C.BorderLight,
                          backgroundColor: t.primary + "08",
                        }}
                      >
                        <div
                          className="px-3 py-1.5 text-[11px] font-semibold uppercase"
                          style={{ color: t.primary }}
                        >
                          Totaal
                        </div>
                        {Array.from({ length: daysInMonth }, (_, i) => {
                          const day = i + 1;
                          const date = dk(day);
                          const count = allStaff.filter(
                            (s) => allAvail[s.name]?.[date]?.available
                          ).length;
                          const total = allStaff.length;
                          const pct = count / Math.max(total, 1);
                          const bg =
                            pct >= 0.75
                              ? C.Grass + "40"
                              : pct >= 0.5
                              ? C.Honey + "40"
                              : pct > 0
                              ? C.Sunset + "30"
                              : "transparent";
                          const col =
                            pct >= 0.75
                              ? C.Pine
                              : pct >= 0.5
                              ? C.Bark
                              : C.Sunset;
                          return (
                            <div
                              key={day}
                              className="flex items-center justify-center"
                              style={{ height: 28, backgroundColor: bg }}
                            >
                              {count > 0 && (
                                <span
                                  className="text-[11px] font-black"
                                  style={{ color: col }}
                                >
                                  {count}
                                </span>
                              )}
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  </div>
                </div>
              );
            })()}

            <div
              className="bg-white rounded-2xl border overflow-hidden"
              style={{ borderColor: C.BorderLight }}
            >
              <div
                className="px-4 py-2.5 border-b"
                style={{ borderColor: C.BorderLight, backgroundColor: C.Bg }}
              >
                <p
                  className="text-xs font-semibold uppercase tracking-wide"
                  style={{ color: C.TextMuted }}
                >
                  Beschikbare uren — {dutchMonths[viewMonth - 1]} {viewYear}
                </p>
              </div>
              <div className="divide-y" style={{ borderColor: C.BorderLight }}>
                {allStaff.map((s) => {
                  const hours = monthHours(s.name);
                  const filled = Object.values(allAvail[s.name] || {}).filter(
                    (a) => {
                      const date = Object.keys(allAvail[s.name] || {}).find(
                        (k) => allAvail[s.name][k] === a
                      );
                      return date?.startsWith(monthKey);
                    }
                  ).length;
                  const filledCount = Object.entries(
                    allAvail[s.name] || {}
                  ).filter(([date, a]) => date.startsWith(monthKey)).length;
                  const availCount = Object.entries(
                    allAvail[s.name] || {}
                  ).filter(
                    ([date, a]) => date.startsWith(monthKey) && a.available
                  ).length;
                  return (
                    <div
                      key={s.name}
                      className="flex items-center gap-3 px-4 py-2.5"
                    >
                      <ProfileAvatar
                        name={s.name}
                        staffList={appData.staffList || []}
                        size={28}
                        color={t.primary}
                      />
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium">{s.name}</p>
                        <p className="text-xs" style={{ color: C.TextMuted }}>
                          {filledCount} dag{filledCount !== 1 ? "en" : ""}{" "}
                          ingevuld · {availCount} beschikbaar
                        </p>
                      </div>
                      <span
                        className="text-base font-bold"
                        style={{ color: hours > 0 ? t.primary : C.TextMuted }}
                      >
                        {hours > 0
                          ? `${hours.toFixed(1).replace(".0", "")}u`
                          : "–"}
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>

          </>
        )}
      </div>
    </div>
  );
};

