// ════════════════════════════════════════════════════════════════
// GEDEELDE ROOSTER-MUTATIELAAG (single source of truth)
// ----------------------------------------------------------------
// Dit is de ENIGE plek die shiftdata muteert. Elke functie krijgt
// appData + params en geeft een patch terug voor updateData(...).
// `workSchedule` is de waarheid (wat iedereen leest: dashboard,
// Mijn Rooster, Teamrooster, programma). `roosterDiensten` is de
// planlaag van de maker en wordt hier consistent meegehouden.
//
// Migratieplan: bestaande losse writes (publishMonth/publishDay,
// ShiftManagementModal, AddShiftModal, swap-goedkeuring) worden
// één voor één op deze functies aangesloten, zodat er nog maar
// één gedragsdefinitie is.
// ════════════════════════════════════════════════════════════════
const ROOSTER_SOURCE = "from-roostermaker";

// Projecteer een dienst-array (roosterDiensten[date]) naar
// workSchedule-shifts. Spiegelt exact de publish-logica.
const dienstenToShifts = (diensten) =>
  (diensten || []).flatMap((d) =>
    (d.assigned || []).map((name) => ({
      matchedUser: name,
      employeeName: name,
      type: d.type,
      start: d.start,
      end: d.end,
      location: d.title || RM_TYPES[d.type]?.label || d.type,
      source: ROOSTER_SOURCE,
      breaks: d.breaks || [],
      title: d.title || RM_TYPES[d.type]?.label || d.type,
    }))
  );

// Publiceer de diensten van opgegeven datums naar workSchedule.
// Behoudt niet-maker shifts; vervangt enkel de from-roostermaker
// entries. Retourneert { workSchedule }.
const publishDienstenPatch = (appData, dates) => {
  const ws = { ...(appData.workSchedule || {}) };
  (dates || []).forEach((date) => {
    const diensten = appData.roosterDiensten?.[date] || [];
    const kept = (ws[date] || []).filter((s) => s.source !== ROOSTER_SOURCE);
    ws[date] = [...kept, ...dienstenToShifts(diensten)];
  });
  return { workSchedule: ws };
};

// Herverdeel een shift op `date` van `fromName` naar `toName`
// (ruil/herschikking). Houdt workSchedule (matchedUser + status)
// én roosterDiensten (assigned) consistent. `shiftMatch` is een
// optionele predikaat om de juiste shift te vinden; standaard op
// matchedUser === fromName. Retourneert { workSchedule, roosterDiensten }.
const reassignShiftPatch = (
  appData,
  { date, fromName, toName, shiftMatch }
) => {
  const ws = { ...(appData.workSchedule || {}) };
  ws[date] = (ws[date] || []).map((shift) => {
    const isMatch = shiftMatch
      ? shiftMatch(shift)
      : shift.matchedUser === fromName;
    return isMatch
      ? { ...shift, matchedUser: toName, status: "swapped" }
      : shift;
  });
  const rd = { ...(appData.roosterDiensten || {}) };
  if (Array.isArray(rd[date])) {
    rd[date] = rd[date].map((d) => ({
      ...d,
      assigned: (d.assigned || []).map((n) => (n === fromName ? toName : n)),
    }));
  }
  return { workSchedule: ws, roosterDiensten: rd };
};

// Signaleer programma-items (activiteiten) die na een mutatie naar
// iemand verwijzen die niet meer op die dag is ingeroosterd. Geeft
// een lijst terug zodat de aanroeper de FM kan waarschuwen.
const orphanedActivities = (appData, date, name) => {
  const stillScheduled = (appData.workSchedule?.[date] || []).some(
    (s) => s.matchedUser === name
  );
  if (stillScheduled) return [];
  return (appData.schedule || []).filter(
    (a) => a.date === date && (a.staff || []).includes(name)
  );
};

const dienstHours = (d) => {
  if (!d) return 0;
  // Verloftypes met vaste uren
  const tc = RM_TYPES[d.type];
  if (tc?.fixedHours !== undefined && !tc.noCount) {
    // Als de gebruiker een custom uren-waarde heeft meegegeven, gebruik die
    return d.fixedHours != null ? Number(d.fixedHours) : tc.fixedHours;
  }
  if (!d.start || !d.end) return 0;
  let mins = timeToMins(d.end) - timeToMins(d.start);
  if (mins <= 0) mins += 24 * 60; // overnight shift
  // Trek pauze af
  if (d.breaks && d.breaks.length > 0) {
    d.breaks.forEach((brk) => {
      if (brk.start && brk.end) {
        let bMins = timeToMins(brk.end) - timeToMins(brk.start);
        if (bMins < 0) bMins += 24 * 60;
        mins -= bMins;
      }
    });
  }
  return +(Math.max(0, mins) / 60).toFixed(2);
};
// Format decimal hours as h:mm (e.g. 6.25 → "6:15")
const formatHours = (h) => {
  const totalMins = Math.round(h * 60);
  const hrs = Math.floor(totalMins / 60);
  const mins = totalMins % 60;
  return mins === 0 ? `${hrs}u` : `${hrs}:${String(mins).padStart(2, "0")}u`;
};

const sortDiensten = (diensten) => {
  if (!diensten) return [];
  return [...diensten].sort((a, b) => {
    const ma = timeToMins(a.start || "00:00");
    const mb = timeToMins(b.start || "00:00");
    // Treat times < 06:00 as next-day (after midnight)
    const ra = ma < 360 ? ma + 1440 : ma;
    const rb = mb < 360 ? mb + 1440 : mb;
    return ra - rb;
  });
};

const EMPTY_DIENST_FORM = {
  type: "entertainment",
  title: "",
  start: "09:00",
  end: "17:30",
  slots: 1,
  pauzeStart: "",
  pauzeEnd: "",
  urencode: "",
};
const EMPTY_TPL_FORM = {
  type: "entertainment",
  title: "",
  start: "09:00",
  end: "17:30",
  slots: 1,
  pauzeStart: "",
  pauzeEnd: "",
  urencode: "",
};

const DienstFormFields = function DienstFormFields({
  initialForm,
  onSubmit,
  onCancel,
  submitLabel,
  theme,
  urencodes,
}) {
  const t = theme || THEMES.general;
  const [form, setForm] = React.useState(initialForm || EMPTY_DIENST_FORM);

  // Auto-fill urencode when type changes (only if user hasn't manually set one)
  const LEAVE_TYPES = ["snipper", "verlof", "at", "comp", "ziek"];
  const isLeave = LEAVE_TYPES.includes(form.type);

  const setType = (key) =>
    setForm((f) => {
      const leaveNow = LEAVE_TYPES.includes(key);
      const tc = RM_TYPES[key];
      return {
        ...f,
        type: key,
        // Auto-fill title with type label for leave types
        title: leaveNow
          ? tc?.label || key
          : LEAVE_TYPES.includes(f.type)
          ? ""
          : f.title,
        // Clear times for leave types
        start: leaveNow ? "" : f.start,
        end: leaveNow ? "" : f.end,
        fixedHours: leaveNow ? tc?.fixedHours ?? 8 : undefined,
        urencode:
          f.urencode !== "" && f.urencode !== String(urencodes?.[f.type] || "")
            ? f.urencode
            : String(urencodes?.[key] || ""),
      };
    });

  // Live netto-uren berekening
  const calcNetto = () => {
    if (!form.start || !form.end) return null;
    let mins = timeToMins(form.end) - timeToMins(form.start);
    if (mins <= 0) mins += 24 * 60;
    if (form.pauzeStart && form.pauzeEnd) {
      let p = timeToMins(form.pauzeEnd) - timeToMins(form.pauzeStart);
      if (p < 0) p += 24 * 60;
      mins -= p;
    }
    mins = Math.max(0, mins);
    const h = Math.floor(mins / 60);
    const m = mins % 60;
    return m > 0 ? `${h}u ${m}m` : `${h}u`;
  };
  const netto = calcNetto();

  return (
    <div className="space-y-3">
      <div className="grid grid-cols-3 gap-1.5">
        {Object.entries(RM_TYPES).map(([key, tc]) => {
          const Icon = tc.icon;
          return (
            <button
              key={key}
              onClick={() => setType(key)}
              className="flex flex-col items-center gap-1 py-2 px-1 rounded-xl border text-[11px] font-semibold text-center transition-all"
              style={{
                borderColor: form.type === key ? tc.border : C.BorderLight,
                backgroundColor: form.type === key ? tc.bg : "white",
                color: form.type === key ? tc.color : C.TextMuted,
              }}
            >
              {Icon && <Icon size={14} />}
              {tc.label}
            </button>
          );
        })}
      </div>
      <input
        type="text"
        value={form.title}
        onChange={(e) => setForm((f) => ({ ...f, title: e.target.value }))}
        placeholder="Naam (bijv. Ochtenddienst)"
        className="w-full border rounded-xl px-3 py-2 text-sm focus:outline-none"
        style={{ borderColor: t.secondary }}
        onFocus={(e) => (e.target.style.borderColor = t.primary)}
        onBlur={(e) => (e.target.style.borderColor = t.secondary)}
      />
      {/* Tijden of vaste uren */}
      {isLeave ? (
        <div className="flex gap-2 items-end">
          <div className="flex-1">
            <label className="text-xs font-semibold text-gray-500 block mb-1">
              Aantal uren
            </label>
            <input
              type="number"
              min="0"
              max="24"
              step="0.5"
              value={form.fixedHours ?? RM_TYPES[form.type]?.fixedHours ?? 8}
              onChange={(e) =>
                setForm((f) => ({
                  ...f,
                  fixedHours: parseFloat(e.target.value) || 0,
                }))
              }
              className="w-full border rounded-xl px-3 py-2 text-sm focus:outline-none font-bold"
              style={{ borderColor: t.secondary }}
              onFocus={(e) => (e.target.style.borderColor = t.primary)}
              onBlur={(e) => (e.target.style.borderColor = t.secondary)}
            />
          </div>
          <div className="w-16 pb-1 flex flex-col items-center justify-end">
            <label className="text-xs font-semibold text-gray-500 block mb-1">
              Telt mee
            </label>
            <div
              className="w-full text-center rounded-xl py-2 text-sm font-bold"
              style={{ backgroundColor: t.primary + "15", color: t.primary }}
            >
              {RM_TYPES[form.type]?.noCount ? "Nee" : "Ja"}
            </div>
          </div>
        </div>
      ) : (
        <div className="flex gap-2 items-end">
          <div className="flex-1">
            <label className="text-xs font-semibold text-gray-500 block mb-1">
              Van
            </label>
            <input
              type="time"
              value={form.start}
              onChange={(e) =>
                setForm((f) => ({ ...f, start: e.target.value }))
              }
              className="w-full border rounded-xl px-3 py-2 text-sm focus:outline-none"
              style={{ borderColor: t.secondary }}
              onFocus={(e) => (e.target.style.borderColor = t.primary)}
              onBlur={(e) => (e.target.style.borderColor = t.secondary)}
            />
          </div>
          <span className="pb-2 text-gray-400">–</span>
          <div className="flex-1">
            <label className="text-xs font-semibold text-gray-500 block mb-1">
              Tot
            </label>
            <input
              type="time"
              value={form.end}
              onChange={(e) => setForm((f) => ({ ...f, end: e.target.value }))}
              className="w-full border rounded-xl px-3 py-2 text-sm focus:outline-none"
              style={{ borderColor: t.secondary }}
              onFocus={(e) => (e.target.style.borderColor = t.primary)}
              onBlur={(e) => (e.target.style.borderColor = t.secondary)}
            />
          </div>
          {/* Netto uren badge — inclusief pauze-aftrek */}
          <div className="w-16 pb-1 flex flex-col items-center justify-end">
            <label className="text-xs font-semibold text-gray-500 block mb-1">
              Netto
            </label>
            <div
              className="w-full text-center rounded-xl py-2 text-sm font-bold"
              style={{ backgroundColor: t.primary + "15", color: t.primary }}
            >
              {netto || "–"}
            </div>
          </div>
        </div>
      )}
      {/* Aantal diensten */}
      <div>
        <label className="text-xs font-semibold text-gray-500 block mb-1.5">
          Hoeveel medewerkers nodig?
        </label>
        <div className="flex gap-2 items-center">
          {[1, 2, 3, 4].map((n) => {
            const isCustom = n === 4;
            const slots = Number(form.slots) || 1;
            const active = isCustom ? slots >= 4 : slots === n;
            return (
              <button
                key={n}
                type="button"
                onClick={() =>
                  setForm((f) => ({
                    ...f,
                    slots: isCustom ? (slots >= 4 ? slots : 4) : n,
                  }))
                }
                className="flex-1 py-2 rounded-xl border text-sm font-bold transition-all"
                style={{
                  borderColor: active ? t.primary : C.BorderLight,
                  backgroundColor: active ? t.primary + "15" : "white",
                  color: active ? t.primary : C.TextMuted,
                }}
              >
                {isCustom ? "4+" : n}
              </button>
            );
          })}
          {Number(form.slots) >= 4 && (
            <input
              type="number"
              min="4"
              max="20"
              value={form.slots}
              onChange={(e) =>
                setForm((f) => ({ ...f, slots: e.target.value }))
              }
              className="w-14 border rounded-xl px-2 py-2 text-sm text-center font-bold focus:outline-none"
              style={{ borderColor: t.primary }}
              onFocus={(e) => (e.target.style.borderColor = t.primary)}
              onBlur={(e) => (e.target.style.borderColor = t.secondary)}
            />
          )}
        </div>
      </div>

      {/* Pauze */}
      {!isLeave && (
        <div className="flex gap-2 items-end">
          <div className="flex-1">
            <label className="text-xs font-semibold text-gray-500 block mb-1">
              Pauze van
            </label>
            <input
              type="time"
              value={form.pauzeStart || ""}
              onChange={(e) =>
                setForm((f) => ({ ...f, pauzeStart: e.target.value }))
              }
              className="w-full border rounded-xl px-3 py-2 text-sm focus:outline-none"
              style={{ borderColor: t.secondary }}
              onFocus={(e) => (e.target.style.borderColor = t.primary)}
              onBlur={(e) => (e.target.style.borderColor = t.secondary)}
            />
          </div>
          <span className="pb-2 text-gray-400">–</span>
          <div className="flex-1">
            <label className="text-xs font-semibold text-gray-500 block mb-1">
              Tot
            </label>
            <input
              type="time"
              value={form.pauzeEnd || ""}
              onChange={(e) =>
                setForm((f) => ({ ...f, pauzeEnd: e.target.value }))
              }
              className="w-full border rounded-xl px-3 py-2 text-sm focus:outline-none"
              style={{ borderColor: t.secondary }}
              onFocus={(e) => (e.target.style.borderColor = t.primary)}
              onBlur={(e) => (e.target.style.borderColor = t.secondary)}
            />
          </div>
          {/* lege spacer zodat pauzerij even breed blijft als tijdrij */}
          <div className="w-16" />
        </div>
      )}
      {/* Urencode */}
      <div
        className="flex items-center gap-2 rounded-xl px-3 py-2 border"
        style={{ borderColor: C.BorderLight, backgroundColor: C.Bg }}
      >
        <Hash size={13} style={{ color: C.TextMuted, flexShrink: 0 }} />
        <label
          className="text-xs font-semibold whitespace-nowrap"
          style={{ color: C.TextMuted }}
        >
          Urencode
        </label>
        <input
          type="text"
          value={form.urencode || ""}
          onChange={(e) => setForm((f) => ({ ...f, urencode: e.target.value }))}
          placeholder={String(urencodes?.[form.type] || "–")}
          className="flex-1 bg-transparent text-sm font-bold text-right focus:outline-none"
          style={{ color: form.urencode ? C.TextPrimary : C.TextMuted }}
        />
      </div>
      <div className="flex gap-2">
        <button
          onClick={() => onSubmit(form)}
          className="flex-1 py-2.5 rounded-xl font-bold text-white text-sm"
          style={{ backgroundColor: t.primary }}
        >
          {submitLabel || "Opslaan"}
        </button>
        <button
          onClick={onCancel}
          className="py-2.5 px-4 rounded-xl text-sm font-medium"
          style={{ backgroundColor: C.BorderLight, color: C.TextMuted }}
        >
          Annuleren
        </button>
      </div>
    </div>
  );
};

const DagPanel = React.memo(function DagPanel({
  inModal,
  t,
  selDate,
  selDiensten,
  selActivities,
  fmtDay,
  publishDay,
  modalTab,
  setModalTab,
  panel,
  setPanel,
  expandedId,
  setExpandedId,
  editId,
  setEditId,
  editForm,
  setEditForm,
  allAvail,
  allStaffIncFM,
  appData,
  toggleAssign,
  startEdit,
  removeDienst,
  addDienst,
  templates,
  saveTpl,
  removeTpl,
  updateTpl,
  addFromTpl,
  saveEdit,
  dienstHours,
  availLabel,
  setSelDate,
  updateData,
  setDraggedTpl,
  showAllStaffAvail,
  setShowAllStaffAvail,
}) {
  // State for activity-link popup
  // State for template slots picker: { tpl, slots }
  const [pendingTpl, setPendingTpl] = React.useState(null);
  // State for template editing
  const [editingTpl, setEditingTpl] = React.useState(null); // tpl.id

  const dayActivities = selDate
    ? (appData.schedule || []).filter((a) => a.date === selDate)
    : [];

  const panelStats = selDate ? appData.dailyStats?.[selDate] || {} : {};
  const panelGuests =
    panelStats.total ||
    (panelStats.adults || 0) +
      (panelStats.kids || 0) +
      (panelStats.babies || 0);
  const panelPrognose = selDate ? appData.roosterPrognose?.[selDate] || {} : {};
  const panelPrognoseTotal = panelPrognose.total || 0;
  const getDrukLabel = (n) => (n < 1150 ? "L" : n <= 1850 ? "M" : "H");

  return (
    <div className={inModal ? "flex flex-col h-full" : "flex flex-col h-full"}>
      {/* Panel header */}
      <div
        className="flex items-center justify-between px-5 py-4 flex-shrink-0"
        style={{ backgroundColor: t.primary }}
      >
        <div>
          <p className="font-bold text-base text-white capitalize">
            {fmtDay(selDate)}
          </p>
          <p className="text-xs text-white opacity-70 mt-0.5">
            {selDiensten.length} dienst{selDiensten.length !== 1 ? "en" : ""}
            {selActivities.length > 0 &&
              ` · ${selActivities.length} activiteit${
                selActivities.length !== 1 ? "en" : ""
              }`}
            {panelGuests > 0 && (
              <span
                className="inline-flex items-center gap-1 ml-2 px-1.5 py-0.5 rounded-full font-semibold"
                style={{
                  backgroundColor: "rgba(255,255,255,0.2)",
                  fontSize: "10px",
                }}
              >
                <Users size={9} />
                {panelGuests.toLocaleString("nl-NL")} gasten
              </span>
            )}
            {panelPrognoseTotal > 0 && (
              <span
                className="inline-flex items-center gap-1 ml-1 px-1.5 py-0.5 rounded-full font-semibold"
                style={{
                  backgroundColor: "rgba(255,255,255,0.15)",
                  fontSize: "10px",
                }}
              >
                ~{panelPrognoseTotal.toLocaleString("nl-NL")} ·{" "}
                {getDrukLabel(panelPrognoseTotal)}
              </span>
            )}
          </p>
        </div>
        <div className="flex items-center gap-2">
          {(() => {
            const dayPublished = (appData.workSchedule?.[selDate] || []).some(
              (s) => s.source === "from-roostermaker"
            );
            const hasAssigned = selDiensten.some(
              (d) => (d.assigned || []).length > 0
            );
            // ── Pending changes-detectie ──────────────────────
            // Vergelijk de huidige planlaag (geprojecteerd via dezelfde
            // publish-logica) met de daadwerkelijk gepubliceerde
            // from-roostermaker shifts. Negeer swap/status-velden.
            const _sigRM = (s) =>
              JSON.stringify({
                u: s.matchedUser ?? s.employeeName ?? "",
                t: s.type ?? "",
                s: s.start ?? "",
                e: s.end ?? "",
                l: s.location ?? s.title ?? "",
                b: (s.breaks || []).map(
                  (b) => `${b.start || ""}-${b.end || ""}`
                ),
              });
            const _projRM = dienstenToShifts(selDiensten).map(_sigRM).sort();
            const _pubRM = (appData.workSchedule?.[selDate] || [])
              .filter((s) => s.source === "from-roostermaker")
              .map(_sigRM)
              .sort();
            const dirty =
              dayPublished &&
              JSON.stringify(_projRM) !== JSON.stringify(_pubRM);
            if (dirty)
              return (
                <button
                  onClick={() =>
                    updateData(publishDienstenPatch(appData, [selDate]))
                  }
                  className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold"
                  style={{
                    backgroundColor: C.Honey,
                    color: C.Bark,
                    border: `1px solid ${C.Honey}`,
                  }}
                  title="Wijzigingen zijn nog niet zichtbaar op het rooster — klik om opnieuw te publiceren"
                >
                  <RefreshCw size={12} /> Opnieuw publiceren
                </button>
              );
            if (dayPublished)
              return (
                <button
                  onClick={() => {
                    const ws = { ...(appData.workSchedule || {}) };
                    ws[selDate] = (ws[selDate] || []).filter(
                      (s) => s.source !== "from-roostermaker"
                    );
                    updateData({ workSchedule: ws });
                  }}
                  className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold"
                  style={{
                    backgroundColor: "rgba(255,255,255,0.9)",
                    color: t.primary,
                    border: "1px solid rgba(255,255,255,0.9)",
                  }}
                  title="Klik om publicatie ongedaan te maken"
                >
                  <CheckCircle size={12} /> Gepubliceerd
                </button>
              );
            if (hasAssigned)
              return (
                <button
                  onClick={() => publishDay(selDate)}
                  className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold"
                  style={{
                    backgroundColor: "rgba(255,255,255,0.2)",
                    color: "white",
                    border: "1px solid rgba(255,255,255,0.35)",
                  }}
                >
                  <CheckCircle size={12} /> Publiceer dag
                </button>
              );
            return null;
          })()}
          <button
            onClick={() => {
              setSelDate(null);
              setPanel("overview");
              setExpandedId(null);
              setEditId(null);
            }}
            className="p-2 rounded-xl"
            style={{ backgroundColor: "rgba(255,255,255,0.15)" }}
          >
            <X size={16} style={{ color: "white" }} />
          </button>
        </div>
      </div>

      {/* Panel tabs */}
      <div
        className="flex border-b flex-shrink-0"
        style={{ borderColor: C.BorderLight }}
      >
        {[
          { id: "diensten", label: "Diensten", Icon: ClipboardList },
          { id: "karakters", label: "Karakters", Icon: Baby },
          { id: "activiteiten", label: "Activiteiten", Icon: Mic },
          { id: "templates", label: "Templates", Icon: Settings },
        ].map(({ id, label, Icon }) => {
          const active = (modalTab || "diensten") === id;
          return (
            <button
              key={id}
              onClick={() => setModalTab(id)}
              className="flex-1 flex items-center justify-center gap-1 py-2.5 text-[11px] font-semibold border-b-2 transition-all"
              style={{
                borderColor: active ? t.primary : "transparent",
                color: active ? t.primary : C.TextMuted,
              }}
            >
              <Icon size={11} /> {label}
            </button>
          );
        })}
      </div>

      {/* Panel body */}
      <div className="overflow-y-auto flex-1 min-h-0">
        {/* ── TAB: DIENSTEN ── */}
        {(modalTab || "diensten") === "diensten" && (
          <div className="p-4 space-y-2">
            {/* Toggle: ook wie niet beschikbaar/nog niet ingevuld is tonen
                bij het toewijzen — vervangt de losse tab "Beschikbaarheid". */}
            <button
              type="button"
              onClick={() => setShowAllStaffAvail((v) => !v)}
              className="flex items-center gap-1.5 text-[11px] font-semibold px-2.5 py-1.5 rounded-lg border self-start"
              style={{
                borderColor: showAllStaffAvail ? t.primary : C.BorderLight,
                backgroundColor: showAllStaffAvail
                  ? t.primary + "12"
                  : "white",
                color: showAllStaffAvail ? t.primary : C.TextMuted,
              }}
            >
              {showAllStaffAvail ? <Eye size={12} /> : <EyeOff size={12} />}
              {showAllStaffAvail
                ? "Iedereen zichtbaar"
                : "Toon iedereen (incl. niet beschikbaar)"}
            </button>
            {/* ── GASTEN PROGNOSE BLOK ── */}
            {(() => {
              const prog = appData.roosterPrognose?.[selDate] || {};
              const actual = appData.dailyStats?.[selDate] || {};
              const actualTotal =
                actual.total ||
                (actual.adults || 0) +
                  (actual.kids || 0) +
                  (actual.babies || 0);
              const progTotal = prog.total || 0;
              const getDrukLabel = (n) =>
                n === 0 ? null : n < 1150 ? "L" : n <= 1850 ? "M" : "H";
              const getDrukColor = (l) =>
                ({ L: C.Pine, M: C.Bark, H: "#ef4444" }[l] || C.TextMuted);
              const label = getDrukLabel(progTotal);
              const savePrognose = (val) => {
                const n = val === "" ? 0 : parseInt(val) || 0;
                updateData({
                  roosterPrognose: {
                    ...(appData.roosterPrognose || {}),
                    [selDate]: { total: n },
                  },
                });
              };
              return (
                <div
                  className="rounded-xl p-3"
                  style={{
                    backgroundColor: t.primary + "08",
                    border: `1px solid ${t.primary}20`,
                  }}
                >
                  <p
                    className="text-[11px] font-semibold uppercase tracking-wide mb-2"
                    style={{ color: t.primary }}
                  >
                    Gasten prognose
                  </p>
                  <div className="flex items-center gap-2">
                    <input
                      type="number"
                      min="0"
                      placeholder="Aantal gasten…"
                      value={progTotal || ""}
                      onChange={(e) => savePrognose(e.target.value)}
                      className="flex-1 rounded-lg px-3 py-2 text-sm font-semibold border focus:outline-none"
                      style={{
                        borderColor: t.primary + "40",
                        color: C.TextPrimary,
                        backgroundColor: "white",
                      }}
                    />
                    {label && (
                      <div
                        className="w-10 h-10 rounded-xl flex items-center justify-center text-lg font-black flex-shrink-0"
                        style={{
                          backgroundColor: getDrukColor(label) + "18",
                          color: getDrukColor(label),
                        }}
                      >
                        {label}
                      </div>
                    )}
                  </div>
                  {actualTotal > 0 && (
                    <div
                      className="mt-2 flex items-center gap-1.5 text-[11px]"
                      style={{ color: C.TextMuted }}
                    >
                      <Users size={9} />
                      <span>
                        Geboekt:{" "}
                        <strong>{actualTotal.toLocaleString("nl-NL")}</strong>
                      </span>
                      {progTotal > 0 &&
                        (() => {
                          const diff = actualTotal - progTotal;
                          const pct = Math.round(
                            (Math.abs(diff) / progTotal) * 100
                          );
                          return (
                            <span
                              style={{
                                color:
                                  diff > 0
                                    ? C.Pine
                                    : diff < 0
                                    ? "#ef4444"
                                    : C.TextMuted,
                              }}
                            >
                              · {diff > 0 ? "+" : ""}
                              {diff.toLocaleString("nl-NL")} ({pct}%)
                            </span>
                          );
                        })()}
                    </div>
                  )}
                </div>
              );
            })()}

            {selActivities.length > 0 && (
              <div
                className="rounded-xl px-3 py-2 mb-1"
                style={{
                  backgroundColor: t.primary + "08",
                  border: `1px solid ${t.primary}20`,
                }}
              >
                <p
                  className="text-[11px] font-semibold uppercase tracking-wide mb-1.5"
                  style={{ color: t.primary }}
                >
                  Activiteiten vandaag
                </p>
                <div className="flex flex-wrap gap-1">
                  {selActivities.map((a) => (
                    <div
                      key={a.id}
                      className="flex items-center gap-1 px-2 py-1 rounded-lg text-xs"
                      style={{
                        backgroundColor: t.primary + "15",
                        color: t.primary,
                      }}
                    >
                      <span className="opacity-60">{a.time}</span> {a.title}
                    </div>
                  ))}
                </div>
              </div>
            )}

            {selDiensten.length === 0 && panel !== "nieuw" && (
              <div className="text-center py-8" style={{ color: C.TextMuted }}>
                <CalendarDays size={32} className="mx-auto mb-2 opacity-20" />
                <p className="text-sm">Geen diensten voor deze dag</p>
                <p className="text-xs mt-1 opacity-60">
                  Voeg hieronder een dienst toe
                </p>
              </div>
            )}

            {selDiensten.map((dienst) => {
              const tc = RM_TYPES[dienst.type] || RM_TYPES.overig;
              const Icon = tc.icon;
              const assigned = dienst.assigned || [];
              const isFull = assigned.length >= dienst.slots;
              const isExp = expandedId === dienst.id;
              const isEdit = editId === dienst.id;
              const hours = dienstHours(dienst);
              return (
                <div
                  key={dienst.id}
                  className="rounded-2xl border overflow-hidden"
                  style={{ borderColor: isFull ? C.Grass : tc.border }}
                >
                  <button
                    onClick={() => setExpandedId(isExp ? null : dienst.id)}
                    className="w-full flex items-center gap-3 px-4 py-3 text-left"
                    style={{ backgroundColor: isFull ? C.Grass + "15" : tc.bg }}
                  >
                    <div
                      className="w-8 h-8 rounded-xl flex items-center justify-center flex-shrink-0"
                      style={{
                        backgroundColor: isFull
                          ? C.Grass + "30"
                          : tc.color + "20",
                      }}
                    >
                      {Icon && (
                        <Icon
                          size={15}
                          style={{ color: isFull ? C.Pine : tc.color }}
                        />
                      )}
                    </div>
                    <div className="flex-1 min-w-0">
                      <p
                        className="font-bold text-sm"
                        style={{ color: isFull ? C.Pine : tc.color }}
                      >
                        {dienst.title || tc.label}
                      </p>
                      <p
                        className="text-xs mt-0.5"
                        style={{ color: C.TextMuted }}
                      >
                        {dienst.start}–{dienst.end} · {hours}u ·{" "}
                        <span
                          style={{
                            color: isFull
                              ? C.Pine
                              : assigned.length > 0
                              ? C.Bark
                              : C.TextMuted,
                            fontWeight: 600,
                          }}
                        >
                          {assigned.length}/{dienst.slots}{" "}
                          {isFull ? "✓ vol" : "nodig"}
                        </span>
                        {(dienst.urencode ||
                          appData.urencodes?.[dienst.type]) && (
                          <span
                            className="ml-1.5 inline-flex items-center gap-0.5 font-bold"
                            style={{ color: tc.color }}
                          >
                            · #
                            {dienst.urencode ||
                              appData.urencodes?.[dienst.type]}
                          </span>
                        )}
                      </p>
                    </div>
                    {assigned.length > 0 && (
                      <div className="flex -space-x-1.5 flex-shrink-0">
                        {assigned.slice(0, 3).map((name) => (
                          <div
                            key={name}
                            className="w-6 h-6 rounded-full border border-white flex items-center justify-center text-[9px] font-bold text-white"
                            style={{ backgroundColor: tc.color }}
                          >
                            {name[0]}
                          </div>
                        ))}
                        {assigned.length > 3 && (
                          <div
                            className="w-6 h-6 rounded-full border border-white flex items-center justify-center text-[9px] font-bold"
                            style={{
                              backgroundColor: C.BorderLight,
                              color: C.TextMuted,
                            }}
                          >
                            +{assigned.length - 3}
                          </div>
                        )}
                      </div>
                    )}
                    <ChevronDown
                      size={15}
                      style={{
                        color: C.TextMuted,
                        flexShrink: 0,
                        transform: isExp ? "rotate(180deg)" : "none",
                        transition: "transform 0.2s",
                      }}
                    />
                  </button>

                  {isExp && (
                    <div
                      className="border-t px-4 pb-4 pt-3 space-y-3"
                      style={{ borderColor: tc.border + "60" }}
                    >
                      {isEdit && editForm ? (
                        <DienstFormFields
                          initialForm={editForm}
                          onSubmit={saveEdit}
                          onCancel={() => {
                            setEditId(null);
                            setEditForm(null);
                          }}
                          submitLabel="Opslaan"
                          theme={t}
                          urencodes={appData.urencodes}
                        />
                      ) : (
                        <>
                          <p
                            className="text-[11px] font-semibold uppercase tracking-wide"
                            style={{ color: C.TextMuted }}
                          >
                            Medewerkers toewijzen
                          </p>
                          {/* Inline: hoeveel medewerkers nodig? */}
                          <div className="flex items-center gap-2">
                            <span
                              className="text-xs font-semibold flex-shrink-0"
                              style={{ color: C.TextMuted }}
                            >
                              Hoeveel nodig?
                            </span>
                            <div className="flex gap-1 flex-1">
                              {[1, 2, 3, 4].map((n) => {
                                const isPlus = n === 4;
                                const cur = dienst.slots || 1;
                                const active = isPlus ? cur >= 4 : cur === n;
                                return (
                                  <button
                                    key={n}
                                    type="button"
                                    onClick={() => {
                                      const newSlots = isPlus
                                        ? Math.max(4, cur)
                                        : n;
                                      if (newSlots === cur) return;
                                      const updated = sortDiensten(
                                        allDiensten[selDate] || []
                                      ).map((d) =>
                                        d.id === dienst.id
                                          ? { ...d, slots: newSlots }
                                          : d
                                      );
                                      updateData({
                                        roosterDiensten: {
                                          ...allDiensten,
                                          [selDate]: updated,
                                        },
                                      });
                                    }}
                                    className="flex-1 py-1 rounded-lg border text-xs font-semibold transition-all"
                                    style={{
                                      borderColor: active
                                        ? t.primary
                                        : C.BorderLight,
                                      backgroundColor: active
                                        ? t.primary + "15"
                                        : "white",
                                      color: active ? t.primary : C.TextMuted,
                                    }}
                                  >
                                    {isPlus ? "4+" : n}
                                  </button>
                                );
                              })}
                              {(dienst.slots || 1) >= 4 && (
                                <input
                                  type="number"
                                  min="4"
                                  max="20"
                                  value={dienst.slots}
                                  onChange={(e) => {
                                    const newSlots = Math.max(
                                      4,
                                      Number(e.target.value) || 4
                                    );
                                    const updated = sortDiensten(
                                      allDiensten[selDate] || []
                                    ).map((d) =>
                                      d.id === dienst.id
                                        ? { ...d, slots: newSlots }
                                        : d
                                    );
                                    updateData({
                                      roosterDiensten: {
                                        ...allDiensten,
                                        [selDate]: updated,
                                      },
                                    });
                                  }}
                                  className="w-12 border rounded-lg px-1 py-1 text-xs text-center font-semibold focus:outline-none"
                                  style={{ borderColor: t.primary }}
                                />
                              )}
                            </div>
                          </div>
                          <div className="space-y-1.5">
                            {(() => {
                              const available = allStaffIncFM.filter((s) => {
                                const a = allAvail[s.name]?.[selDate];
                                const isAssigned = assigned.includes(s.name);
                                if (isAssigned) return true; // always show if already assigned
                                if (showAllStaffAvail) return true; // toggle: toon iedereen
                                if (!a) return false; // no opgave → niet tonen
                                return a.available !== false; // alleen beschikbaar
                              });
                              // Niet-beschikbaar/geen-opgave (indien getoond via toggle)
                              // onderaan, beschikbaar/toegewezen bovenaan.
                              const sorted = showAllStaffAvail
                                ? [...available].sort((a, b) => {
                                    const rank = (s) => {
                                      if (assigned.includes(s.name)) return 0;
                                      const av = allAvail[s.name]?.[selDate];
                                      if (!av) return 2;
                                      return av.available === false ? 3 : 1;
                                    };
                                    return rank(a) - rank(b);
                                  })
                                : available;
                              if (sorted.length === 0)
                                return (
                                  <p
                                    className="text-xs text-center py-3"
                                    style={{ color: C.TextMuted }}
                                  >
                                    Niemand heeft beschikbaarheid opgegeven voor
                                    deze dag
                                  </p>
                                );
                              return sorted.map((s) => {
                                const isAssigned = assigned.includes(s.name);
                                const inOther = selDiensten
                                  .filter((d) => d.id !== dienst.id)
                                  .some((d) =>
                                    (d.assigned || []).includes(s.name)
                                  );
                                const avInfo = getPersonAvailLabel(
                                  allAvail,
                                  s.name,
                                  selDate
                                );
                                // Activiteiten op die dag al gekoppeld aan deze persoon
                                const linkedActs = dayActivities.filter((ac) =>
                                  (ac.staff || []).includes(s.name)
                                );
                                // Karakters die deze medewerker op deze dag speelt (uit appData.characters)
                                const myChars = (
                                  appData.characters || []
                                ).filter(
                                  (c) =>
                                    c.date === selDate && c.actor === s.name
                                );

                                return (
                                  <div key={s.name} className="space-y-1">
                                    <div
                                      className="flex items-center gap-2.5 px-3 py-2 rounded-xl transition-all"
                                      style={{
                                        backgroundColor: isAssigned
                                          ? C.Grass + "20"
                                          : "white",
                                        border: `1.5px solid ${
                                          isAssigned ? C.Grass : C.BorderLight
                                        }`,
                                        opacity:
                                          !isAssigned && avInfo.kind === "none"
                                            ? 0.65
                                            : 1,
                                      }}
                                    >
                                      <ProfileAvatar
                                        name={s.name}
                                        staffList={appData.staffList || []}
                                        size={26}
                                        color={isAssigned ? C.Pine : t.primary}
                                      />
                                      <div className="flex-1 min-w-0">
                                        <div className="flex items-center gap-1.5">
                                          <p className="text-sm font-semibold leading-tight">
                                            {s.name}
                                          </p>
                                          {myChars.map((ch) => {
                                            const cc = getCharColorInfo(
                                              ch.role
                                            );
                                            return (
                                              <span
                                                key={ch.role}
                                                className="text-[11px] px-1.5 py-0.5 rounded-full font-bold"
                                                style={{
                                                  backgroundColor: cc.bg,
                                                  color: cc.text,
                                                }}
                                              >
                                                {ch.role}
                                              </span>
                                            );
                                          })}
                                        </div>
                                        <div className="flex items-center gap-1 flex-wrap">
                                          <AvailBadge
                                            kind={avInfo.kind}
                                            label={avInfo.tekst}
                                            status={avInfo.status}
                                          />
                                          {inOther && (
                                            <span
                                              className="text-[11px]"
                                              style={{
                                                color: C.Honey,
                                                fontWeight: 600,
                                              }}
                                            >
                                              · andere dienst
                                            </span>
                                          )}
                                        </div>
                                      </div>
                                      <div className="flex items-center gap-1 flex-shrink-0">
                                        <button
                                          onClick={() =>
                                            toggleAssign(
                                              selDate,
                                              dienst.id,
                                              s.name
                                            )
                                          }
                                          className="text-xs font-semibold px-3 py-1.5 rounded-xl"
                                          style={{
                                            backgroundColor: isAssigned
                                              ? C.Grass + "30"
                                              : t.primary,
                                            color: isAssigned
                                              ? C.Pine
                                              : "white",
                                            border: `2px solid ${
                                              isAssigned
                                                ? C.Grass
                                                : "transparent"
                                            }`,
                                          }}
                                        >
                                          {isAssigned ? "✓" : "Inplannen"}
                                        </button>
                                      </div>
                                    </div>
                                  </div>
                                );
                              });
                            })()}
                          </div>
                          <div
                            className="flex gap-2 pt-1 border-t"
                            style={{ borderColor: C.BorderLight }}
                          >
                            <button
                              onClick={() => startEdit(dienst)}
                              className="flex items-center gap-1 px-3 py-1.5 rounded-xl text-xs font-semibold"
                              style={{
                                backgroundColor: C.SkyLight,
                                color: C.Lagoon,
                              }}
                            >
                              <Edit2 size={11} /> Aanpassen
                            </button>
                            <button
                              onClick={() => removeDienst(selDate, dienst.id)}
                              className="flex items-center gap-1 px-3 py-1.5 rounded-xl text-xs font-semibold"
                              style={{
                                backgroundColor: C.BlossomLight,
                                color: C.Sunset,
                              }}
                            >
                              <Trash2 size={11} /> Verwijderen
                            </button>
                          </div>
                        </>
                      )}
                    </div>
                  )}
                </div>
              );
            })}

            {/* Nieuwe dienst */}
            {panel === "nieuw" ? (
              <div
                className="rounded-2xl border p-4 space-y-3"
                style={{
                  borderColor: t.secondary,
                  backgroundColor: t.primary + "04",
                }}
              >
                <p className="font-bold text-sm" style={{ color: t.primary }}>
                  Nieuwe dienst
                </p>
                <DienstFormFields
                  initialForm={{
                    ...EMPTY_DIENST_FORM,
                    urencode: String(
                      appData.urencodes?.[EMPTY_DIENST_FORM.type] || ""
                    ),
                  }}
                  onSubmit={addDienst}
                  onCancel={() => setPanel("overview")}
                  submitLabel="Toevoegen"
                  theme={t}
                  urencodes={appData.urencodes}
                />
              </div>
            ) : (
              <button
                onClick={() => setPanel("nieuw")}
                className="w-full flex items-center justify-center gap-2 py-3 rounded-2xl border border-dashed text-sm font-bold transition-all"
                style={{
                  borderColor: t.secondary,
                  color: t.primary,
                  backgroundColor: t.primary + "05",
                }}
              >
                <Plus size={16} /> Aangepaste dienst toevoegen
              </button>
            )}
          </div>
        )}

        {/* ── TAB: KARAKTERS ── */}
        {(modalTab || "diensten") === "karakters" && (
          <div className="p-4 space-y-3">
            <p className="text-xs" style={{ color: C.TextMuted }}>
              Wijs karakters toe voor {fmtDay(selDate)}
            </p>
            {BASE_ROLES.map((role) => {
              const cc = getCharColorInfo(role);
              const existing = (appData.characters || []).find(
                (c) => c.date === selDate && c.role === role
              );
              const staffOptions = allStaffIncFM.filter((s) => !s.inactive);
              return (
                <div
                  key={role}
                  className="rounded-xl border p-3"
                  style={{
                    borderColor: existing ? cc.bg : C.BorderLight,
                    backgroundColor: existing ? cc.bg + "20" : "white",
                  }}
                >
                  <div className="flex items-center gap-2.5 mb-2">
                    <div
                      className="w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold"
                      style={{ backgroundColor: cc.bg, color: cc.text }}
                    >
                      {role[0]}
                    </div>
                    <span className="font-bold text-sm">{role}</span>
                    {existing && (
                      <span
                        className="text-xs font-medium ml-auto"
                        style={{ color: cc.text }}
                      >
                        {existing.actor}
                      </span>
                    )}
                  </div>
                  <div className="flex flex-wrap gap-1.5">
                    <button
                      onClick={() => {
                        const newChars = (appData.characters || []).filter(
                          (c) => !(c.date === selDate && c.role === role)
                        );
                        updateData({ characters: newChars });
                      }}
                      className="px-3 py-1.5 rounded-xl text-xs font-semibold border transition-all"
                      style={{
                        borderColor: !existing ? cc.bg : C.BorderLight,
                        backgroundColor: !existing ? cc.bg + "30" : "white",
                        color: !existing ? cc.text : C.TextMuted,
                      }}
                    >
                      Niemand
                    </button>
                    {staffOptions.map((s) => {
                      const isSelected = existing?.actor === s.name;
                      return (
                        <button
                          key={s.name}
                          onClick={() => {
                            const newChars = (appData.characters || []).filter(
                              (c) => !(c.date === selDate && c.role === role)
                            );
                            newChars.push({
                              id: existing?.id || Date.now(),
                              date: selDate,
                              role,
                              actor: s.name,
                            });
                            updateData({ characters: newChars });
                          }}
                          className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold border transition-all"
                          style={{
                            borderColor: isSelected ? cc.bg : C.BorderLight,
                            backgroundColor: isSelected
                              ? cc.bg + "30"
                              : "white",
                            color: isSelected ? cc.text : C.TextPrimary,
                          }}
                        >
                          <ProfileAvatar
                            name={s.name}
                            staffList={appData.staffList || []}
                            size={18}
                            color={cc.text}
                          />
                          {s.name}
                        </button>
                      );
                    })}
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {/* ── TAB: ACTIVITEITEN ── */}
        {(modalTab || "diensten") === "activiteiten" && (
          <div className="p-4 space-y-3">
            <p className="text-xs" style={{ color: C.TextMuted }}>
              Koppel medewerkers aan activiteiten op {fmtDay(selDate)}
            </p>
            {(() => {
              const skData = appData.dailySpringkussen?.[selDate];
              const skAct = skData?.open
                ? [
                    {
                      id: `sk-${selDate}`,
                      title: "Springkussen",
                      type: "springkussen",
                      date: selDate,
                      time: `${skData.start || "10:00"} - ${
                        skData.end || "17:00"
                      }`,
                      staff: skData.staff || [],
                      _isSk: true,
                    },
                  ]
                : [];
              const allActs = [...selActivities, ...skAct];
              if (allActs.length === 0)
                return (
                  <div className="text-center py-8">
                    <Mic
                      size={28}
                      style={{ color: C.BorderLight, margin: "0 auto 8px" }}
                    />
                    <p
                      className="text-sm font-medium"
                      style={{ color: C.TextMuted }}
                    >
                      Geen activiteiten gepland
                    </p>
                    <p className="text-xs mt-1" style={{ color: C.TextMuted }}>
                      Voeg activiteiten toe via het programma
                    </p>
                  </div>
                );
              return allActs.map((act) => {
                const ATYPES = {
                  crea: { bg: "#9DB4F6", text: "#00192F" },
                  orry: { bg: "#FF699B", text: "#700606" },
                  entertainment: { bg: "#FFCA55", text: "#7A5226" },
                  sport: { bg: "#B1EDA6", text: "#045E51" },
                  springkussen: { bg: "#FF699B", text: "#700606" },
                };
                const ac = ATYPES[(act.type || "").toLowerCase()] || {
                  bg: "#f1f5f9",
                  text: "#475569",
                };
                const linked = act.staff || [];
                return (
                  <div
                    key={act.id || act.title}
                    className="rounded-xl border p-3"
                    style={{
                      borderColor: linked.length > 0 ? ac.bg : C.BorderLight,
                      backgroundColor:
                        linked.length > 0 ? ac.bg + "18" : "white",
                    }}
                  >
                    <div className="flex items-center gap-2 mb-2.5">
                      <div
                        className="w-2 h-2 rounded-full flex-shrink-0"
                        style={{ backgroundColor: ac.bg }}
                      />
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-bold truncate">
                          {act.title}
                        </p>
                        {act.time && (
                          <p
                            className="text-[11px]"
                            style={{ color: C.TextMuted }}
                          >
                            {act.time}
                          </p>
                        )}
                      </div>
                      {linked.length > 0 && (
                        <span
                          className="text-[11px] font-bold px-2 py-0.5 rounded-full"
                          style={{ backgroundColor: ac.bg, color: ac.text }}
                        >
                          {linked.length} gekoppeld
                        </span>
                      )}
                    </div>
                    <div className="flex flex-wrap gap-1.5">
                      {allStaffIncFM
                        .filter(
                          (s) =>
                            selDiensten.some((d) =>
                              (d.assigned || []).includes(s.name)
                            ) || linked.includes(s.name)
                        )
                        .map((s) => {
                          const isLinked = linked.includes(s.name);
                          return (
                            <button
                              key={s.name}
                              onClick={() => {
                                if (act._isSk) {
                                  const skD =
                                    appData.dailySpringkussen?.[selDate] || {};
                                  const cur = skD.staff || [];
                                  updateData({
                                    dailySpringkussen: {
                                      ...appData.dailySpringkussen,
                                      [selDate]: {
                                        ...skD,
                                        staff: isLinked
                                          ? cur.filter((n) => n !== s.name)
                                          : [...cur, s.name],
                                      },
                                    },
                                  });
                                } else {
                                  updateData({
                                    schedule: (appData.schedule || []).map(
                                      (a) =>
                                        a.id === act.id ||
                                        (a.date === act.date &&
                                          a.title === act.title &&
                                          a.time === act.time)
                                          ? {
                                              ...a,
                                              staff: isLinked
                                                ? (a.staff || []).filter(
                                                    (n) => n !== s.name
                                                  )
                                                : [...(a.staff || []), s.name],
                                            }
                                          : a
                                    ),
                                  });
                                }
                              }}
                              className="flex items-center gap-1 px-2.5 py-1 rounded-xl text-xs font-semibold border transition-all"
                              style={{
                                borderColor: isLinked ? ac.bg : C.BorderLight,
                                backgroundColor: isLinked
                                  ? ac.bg + "30"
                                  : "white",
                                color: isLinked ? ac.text : C.TextPrimary,
                              }}
                            >
                              <ProfileAvatar
                                name={s.name}
                                staffList={appData.staffList || []}
                                size={16}
                                color={isLinked ? ac.text : t.primary}
                              />
                              {s.name.split(" ")[0]}
                              {isLinked && <span> ✓</span>}
                            </button>
                          );
                        })}
                      {allStaffIncFM.filter(
                        (s) =>
                          selDiensten.some((d) =>
                            (d.assigned || []).includes(s.name)
                          ) || linked.includes(s.name)
                      ).length === 0 && (
                        <p className="text-xs" style={{ color: C.TextMuted }}>
                          Niemand ingepland op deze dag
                        </p>
                      )}
                    </div>
                  </div>
                );
              });
            })()}
          </div>
        )}

        {/* ── TAB: TEMPLATES ── */}
        {(modalTab || "diensten") === "templates" && (
          <div className="p-4 space-y-3">
            {templates.length > 0 && (
              <div
                className="bg-white rounded-2xl border overflow-hidden"
                style={{ borderColor: C.BorderLight }}
              >
                <div
                  className="divide-y"
                  style={{ borderColor: C.BorderLight }}
                >
                  {templates.map((tpl) => {
                    const tc = RM_TYPES[tpl.type] || RM_TYPES.overig;
                    const Icon = tc.icon;
                    const hours = dienstHours(tpl);
                    const isPending = pendingTpl?.tpl?.id === tpl.id;
                    const isEditing = editingTpl === tpl.id;
                    return (
                      <div key={tpl.id}>
                        <div
                          className="flex items-center gap-3 px-4 py-3 cursor-grab active:cursor-grabbing select-none"
                          draggable
                          onDragStart={(e) => {
                            e.dataTransfer.effectAllowed = "copy";
                            e.dataTransfer.setData("tplId", String(tpl.id));
                            setDraggedTpl(tpl);
                          }}
                          onDragEnd={() => setDraggedTpl(null)}
                          style={{ opacity: 1 }}
                        >
                          <div
                            className="flex-shrink-0 flex items-center"
                            style={{ cursor: "grab" }}
                          >
                            <GripVertical
                              size={13}
                              style={{ color: C.TextMuted, marginRight: 4 }}
                            />
                            <div
                              className="w-8 h-8 rounded-xl flex items-center justify-center"
                              style={{
                                backgroundColor: tc.bg,
                                color: tc.color,
                              }}
                            >
                              {Icon && <Icon size={14} />}
                            </div>
                          </div>
                          <div className="flex-1 min-w-0">
                            <p className="font-semibold text-sm">
                              {tpl.title || tc.label}
                            </p>
                            <p
                              className="text-[11px]"
                              style={{ color: C.TextMuted }}
                            >
                              {tpl.start}–{tpl.end} · {hours}u · {tpl.slots}{" "}
                              medewerker{tpl.slots !== 1 ? "s" : ""}
                            </p>
                          </div>
                          {selDate && !isEditing && (
                            <button
                              onClick={() =>
                                setPendingTpl(
                                  isPending
                                    ? null
                                    : { tpl, slots: tpl.slots || 1 }
                                )
                              }
                              className="px-2.5 py-1.5 rounded-xl text-xs font-semibold flex-shrink-0 transition-all"
                              style={{
                                backgroundColor: isPending
                                  ? t.primary
                                  : t.primary + "15",
                                color: t.primary,
                              }}
                            >
                              {isPending ? "Annuleren" : "+ Toevoegen"}
                            </button>
                          )}
                          <button
                            onClick={() => {
                              setEditingTpl(isEditing ? null : tpl.id);
                              setPendingTpl(null);
                            }}
                            className="p-1.5 rounded-lg flex-shrink-0"
                            style={{
                              color: isEditing ? t.primary : C.TextMuted,
                              backgroundColor: isEditing
                                ? t.primary + "15"
                                : C.Bg,
                            }}
                          >
                            <Edit2 size={12} />
                          </button>
                          <button
                            onClick={() => removeTpl(tpl.id)}
                            className="p-1.5 rounded-lg flex-shrink-0"
                            style={{
                              color: C.Sunset,
                              backgroundColor: C.BlossomLight,
                            }}
                          >
                            <Trash2 size={12} />
                          </button>
                        </div>
                        {/* Inline edit form */}
                        {isEditing && (
                          <div
                            className="mx-4 mb-3 rounded-2xl border p-4 space-y-3"
                            style={{
                              borderColor: t.primary + "40",
                              backgroundColor: t.primary + "05",
                            }}
                          >
                            <p
                              className="text-xs font-semibold"
                              style={{ color: t.primary }}
                            >
                              Template wijzigen
                            </p>
                            <DienstFormFields
                              initialForm={{
                                type: tpl.type,
                                title: tpl.title || "",
                                start: tpl.start,
                                end: tpl.end,
                                slots: tpl.slots || 1,
                                pauzeStart: tpl.breaks?.[0]?.start || "",
                                pauzeEnd: tpl.breaks?.[0]?.end || "",
                                urencode: tpl.urencode || "",
                              }}
                              onSubmit={(formData) => {
                                updateTpl(tpl.id, formData);
                                setEditingTpl(null);
                              }}
                              onCancel={() => setEditingTpl(null)}
                              submitLabel="Opslaan"
                              theme={t}
                              urencodes={appData.urencodes}
                            />
                          </div>
                        )}
                        {/* Inline slots picker */}
                        {isPending && (
                          <div
                            className="mx-4 mb-3 rounded-2xl border p-3 space-y-2"
                            style={{
                              borderColor: t.primary + "40",
                              backgroundColor: t.primary + "06",
                            }}
                          >
                            <p
                              className="text-xs font-semibold"
                              style={{ color: t.primary }}
                            >
                              Hoeveel medewerkers nodig?
                            </p>
                            <div className="flex gap-1.5 items-center">
                              {[1, 2, 3, 4].map((n) => {
                                const isPlus = n === 4;
                                const cur = pendingTpl.slots;
                                const active = isPlus ? cur >= 4 : cur === n;
                                return (
                                  <button
                                    key={n}
                                    type="button"
                                    onClick={() =>
                                      setPendingTpl((p) => ({
                                        ...p,
                                        slots: isPlus ? Math.max(4, cur) : n,
                                      }))
                                    }
                                    className="flex-1 py-1.5 rounded-xl border text-sm font-bold transition-all"
                                    style={{
                                      borderColor: active
                                        ? t.primary
                                        : C.BorderLight,
                                      backgroundColor: active
                                        ? t.primary + "15"
                                        : "white",
                                      color: active ? t.primary : C.TextMuted,
                                    }}
                                  >
                                    {isPlus ? "4+" : n}
                                  </button>
                                );
                              })}
                              {pendingTpl.slots >= 4 && (
                                <input
                                  type="number"
                                  min="4"
                                  max="20"
                                  value={pendingTpl.slots}
                                  onChange={(e) =>
                                    setPendingTpl((p) => ({
                                      ...p,
                                      slots: Math.max(
                                        4,
                                        Number(e.target.value) || 4
                                      ),
                                    }))
                                  }
                                  className="w-12 border rounded-xl px-1 py-1.5 text-sm text-center font-bold focus:outline-none"
                                  style={{ borderColor: t.primary }}
                                />
                              )}
                            </div>
                            <button
                              onClick={() => {
                                addFromTpl({
                                  ...pendingTpl.tpl,
                                  slots: pendingTpl.slots,
                                });
                                setPendingTpl(null);
                              }}
                              className="w-full py-2 rounded-xl text-sm font-bold text-white"
                              style={{ backgroundColor: t.primary }}
                            >
                              Toevoegen aan {selDate ? fmtDay(selDate) : "dag"}
                            </button>
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>
            )}
            <div
              className="rounded-2xl border p-4 space-y-3"
              style={{
                borderColor: t.secondary,
                backgroundColor: t.primary + "04",
              }}
            >
              <p className="font-bold text-sm" style={{ color: t.primary }}>
                Nieuwe template
              </p>
              <DienstFormFields
                initialForm={{
                  ...EMPTY_TPL_FORM,
                  urencode: String(
                    appData.urencodes?.[EMPTY_TPL_FORM.type] || ""
                  ),
                }}
                onSubmit={saveTpl}
                onCancel={() => setTplForm(EMPTY_TPL_FORM)}
                submitLabel="Template opslaan"
                theme={t}
                urencodes={appData.urencodes}
              />
            </div>
          </div>
        )}
      </div>
    </div>
  );
});

const RoosterMakerView = ({
  appData,
  updateData,
  theme,
  showAlert,
  showConfirm,
  onBack,
}) => {
  const t = theme || THEMES.general;
  const today = new Date();
  const nextMo = new Date(today.getFullYear(), today.getMonth() + 1, 1);

  // ── State ─────────────────────────────────────────────
  const [viewYear, setViewYear] = useState(nextMo.getFullYear());
  const [viewMonth, setViewMonth] = useState(nextMo.getMonth() + 1);
  const [selDate, setSelDate] = useState(null);
  const [panel, setPanel] = useState("overview"); // "overview"|"nieuw"|"templates"
  const [expandedId, setExpandedId] = useState(null);
  const [editId, setEditId] = useState(null);
  const [editForm, setEditForm] = useState(null);
  const [sidebarTab, setSidebarTab] = useState(null); // null|"templates"
  const [modalTab, setModalTab] = useState("diensten"); // "diensten"|"karakters"|"activiteiten"|"templates"
  // Toont in tab "Diensten" ook wie niet beschikbaar is / nog niets heeft
  // ingevuld — vervangt de losse tab "Beschikbaarheid" van vroeger.
  const [showAllStaffAvail, setShowAllStaffAvail] = useState(false);
  const [calView, setCalView] = useState("maand"); // "maand"|"week"|"rooster"
  const [viewWeek, setViewWeek] = useState(0); // index into weeksOfMonth
  const [draggedTpl, setDraggedTpl] = useState(null);
  const [charEdit, setCharEdit] = useState(null); // { dateKey, personName }
  const [showPrognoseModal, setShowPrognoseModal] = useState(false);
  const [prognoseDraft, setPrognoseDraft] = useState({});
  const [printingMonth, setPrintingMonth] = useState(false);

  // ── Data (memoized) ──────────────────────────────────
  const allAvail = useMemo(
    () => appData.staffAvailability || {},
    [appData.staffAvailability]
  );
  const allDiensten = useMemo(
    () => appData.roosterDiensten || {},
    [appData.roosterDiensten]
  );
  const templates = useMemo(
    () => appData.dienstTemplates || [],
    [appData.dienstTemplates]
  );
  const contractInfo = useMemo(
    () => appData.staffContractInfo || {},
    [appData.staffContractInfo]
  );
  const allStaffIncFM = useMemo(() => {
    const base = (appData.staffList || []).filter(
      (s) => !s.inactive && s.name !== "Jarno"
    );
    return base.some((s) => s.name === "Maik")
      ? base
      : [...base, { name: "Maik", role: "fm" }];
  }, [appData.staffList]);
  const activities = useMemo(() => appData.schedule || [], [appData.schedule]);

  const monthKey = useMemo(
    () => toMonthKey(viewYear, viewMonth),
    [viewYear, viewMonth]
  );
  const daysInMonth = useMemo(
    () => new Date(viewYear, viewMonth, 0).getDate(),
    [viewYear, viewMonth]
  );
  const firstDOW = useMemo(() => {
    const w = new Date(viewYear, viewMonth - 1, 1).getDay();
    return w === 0 ? 6 : w - 1;
  }, [viewYear, viewMonth]);
  const weeksInMonth = useMemo(
    () => Math.ceil((firstDOW + daysInMonth) / 7),
    [firstDOW, daysInMonth]
  );

  const dk = useCallback(
    (day) =>
      `${viewYear}-${String(viewMonth).padStart(2, "0")}-${String(day).padStart(
        2,
        "0"
      )}`,
    [viewYear, viewMonth]
  );

  const changeMonth = useCallback(
    (n) => {
      const d = new Date(viewYear, viewMonth - 1 + n, 1);
      setViewYear(d.getFullYear());
      setViewMonth(d.getMonth() + 1);
      setSelDate(null);
      setPanel("overview");
      setModalTab("diensten");
      setViewWeek(0);
    },
    [viewYear, viewMonth]
  );

  // 🖨️ PRINT HELE MAAND OP A3 (liggend)
  const printMonthA3 = useCallback(() => {
    setPrintingMonth(true);
    const dienstenMap = appData.roosterDiensten || {};
    const esc = (s) =>
      String(s == null ? "" : s)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;");

    const sortDsForPrint = (arr) =>
      [...arr].sort((a, b) => {
        const af = RM_TYPES[a.type]?.fixedHours !== undefined;
        const bf = RM_TYPES[b.type]?.fixedHours !== undefined;
        if (af !== bf) return af ? 1 : -1;
        return String(a.start || "").localeCompare(String(b.start || ""));
      });

    const dayNames = ["Ma", "Di", "Wo", "Do", "Vr", "Za", "Zo"];

    // Bouw cellen (lege opvulling vóór dag 1 + dagen)
    const totalCells = weeksInMonth * 7;
    const cells = [];
    for (let i = 0; i < totalCells; i++) {
      const dayNum = i - firstDOW + 1;
      if (dayNum < 1 || dayNum > daysInMonth) {
        cells.push('<div class="cell empty"></div>');
        continue;
      }
      const key = dk(dayNum);
      const ds = sortDsForPrint(dienstenMap[key] || []);
      const dow = (firstDOW + dayNum - 1) % 7;
      const isWeekend = dow >= 5;
      const chips = ds
        .map((d) => {
          const tc = RM_TYPES[d.type] || RM_TYPES.overig;
          const fixed = RM_TYPES[d.type]?.fixedHours !== undefined;
          const timeLabel = fixed
            ? tc.label || d.type
            : `${esc(d.start || "")}${d.end ? "–" + esc(d.end) : ""}`;
          const titleLabel = !fixed && d.title ? ` ${esc(d.title)}` : "";
          const assigned = (d.assigned || []).filter(Boolean);
          const who = assigned.length
            ? `<div class="who">${esc(assigned.join(", "))}</div>`
            : `<div class="who open">— open —</div>`;
          return `<div class="chip" style="background:${tc.bg};border-left:1mm solid ${tc.border};color:${tc.color}">
            <div class="chip-t">${timeLabel}${titleLabel}</div>${who}
          </div>`;
        })
        .join("");
      cells.push(
        `<div class="cell${isWeekend ? " weekend" : ""}">
          <div class="daynum">${dayNum}</div>
          <div class="chips">${chips || '<div class="none">·</div>'}</div>
        </div>`
      );
    }

    const head = dayNames
      .map((n, i) => `<div class="dh${i >= 5 ? " weekend" : ""}">${n}</div>`)
      .join("");

    const html = `<!doctype html><html><head><meta charset="utf-8"><title>Rooster ${esc(
      dutchMonths[viewMonth - 1]
    )} ${viewYear}</title><style>
      @page{size:A3 landscape;margin:6mm}
      *{box-sizing:border-box;margin:0;padding:0;-webkit-print-color-adjust:exact;print-color-adjust:exact}
      body{font-family:Arial,Helvetica,sans-serif;color:#1e293b}
      .title{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:3mm}
      .title h1{font-size:16pt;color:${C.Pine || "#045E51"}}
      .title .sub{font-size:8pt;color:#94a3b8}
      .head{display:grid;grid-template-columns:repeat(7,1fr);gap:1mm;margin-bottom:1mm}
      .dh{font-size:8pt;font-weight:700;text-align:center;padding:1mm;background:#f1f5f9;border-radius:1mm;color:#475569}
      .dh.weekend{background:#fef2f2;color:#b91c1c}
      .grid{display:grid;grid-template-columns:repeat(7,1fr);grid-auto-rows:1fr;gap:1mm}
      .cell{border:.3mm solid #e2e8f0;border-radius:1mm;min-height:34mm;padding:1mm;position:relative;background:#fff;overflow:hidden}
      .cell.weekend{background:#fffafa}
      .cell.empty{border:none;background:transparent}
      .daynum{font-size:8pt;font-weight:700;color:#64748b;text-align:right;line-height:1}
      .chips{margin-top:.5mm}
      .chip{border-radius:1mm;padding:.6mm 1mm;margin-bottom:.6mm}
      .chip-t{font-size:6pt;font-weight:700;line-height:1.15}
      .who{font-size:5.5pt;line-height:1.1;opacity:.85}
      .who.open{font-style:italic;opacity:.6}
      .none{color:#cbd5e1;font-size:7pt;text-align:center;margin-top:2mm}
      .ft{margin-top:2mm;font-size:6pt;color:#94a3b8;text-align:right}
    </style></head><body>
      <div class="title">
        <h1>Rooster — ${esc(dutchMonths[viewMonth - 1])} ${viewYear}</h1>
        <span class="sub">Afgedrukt ${new Date().toLocaleDateString(
          "nl-NL"
        )}</span>
      </div>
      <div class="head">${head}</div>
      <div class="grid">${cells.join("")}</div>
      <div class="ft">Center Parcs — Roostermaker</div>
    </body></html>`;

    const iframe = document.createElement("iframe");
    iframe.style.cssText =
      "position:fixed;left:-1800px;top:0;width:1587px;height:1123px;border:none;visibility:hidden;";
    document.body.appendChild(iframe);
    const doc = iframe.contentDocument || iframe.contentWindow.document;
    doc.open();
    doc.write(html);
    doc.close();
    setTimeout(() => {
      try {
        iframe.contentWindow.focus();
        iframe.contentWindow.print();
      } catch (e) {}
      setTimeout(() => {
        document.body.removeChild(iframe);
        setPrintingMonth(false);
      }, 3000);
    }, 900);
  }, [
    appData.roosterDiensten,
    viewYear,
    viewMonth,
    daysInMonth,
    firstDOW,
    weeksInMonth,
    dk,
  ]);

  // ── Diensten helpers ──────────────────────────────────
  const getDayD = useCallback(
    (date) => sortDiensten(allDiensten[date] || []),
    [allDiensten]
  );
  const saveDay = useCallback(
    (date, diensten) =>
      updateData({ roosterDiensten: { ...allDiensten, [date]: diensten } }),
    [allDiensten, updateData]
  );

  const addDienst = useCallback(
    (formData) => {
      if (!selDate) return;
      const defaultCode = String(appData.urencodes?.[formData.type] || "");
      saveDay(selDate, [
        ...sortDiensten(allDiensten[selDate] || []),
        {
          id: Date.now(),
          type: formData.type,
          title: formData.title,
          start: formData.start,
          end: formData.end,
          slots: Math.max(1, Number(formData.slots) || 1),
          breaks:
            formData.pauzeStart && formData.pauzeEnd
              ? [{ start: formData.pauzeStart, end: formData.pauzeEnd }]
              : [],
          urencode: formData.urencode || defaultCode,
          assigned: [],
        },
      ]);
      setPanel("overview");
    },
    [selDate, allDiensten, saveDay, appData.urencodes]
  );

  const addFromTpl = useCallback(
    (tpl) => {
      if (!selDate) return;
      const defaultCode = String(appData.urencodes?.[tpl.type] || "");
      saveDay(selDate, [
        ...sortDiensten(allDiensten[selDate] || []),
        {
          id: Date.now(),
          type: tpl.type,
          title: tpl.title,
          start: tpl.start,
          end: tpl.end,
          slots: Math.max(1, Number(tpl.slots) || 1),
          breaks: tpl.breaks || [],
          urencode: tpl.urencode || defaultCode,
          assigned: [],
        },
      ]);
    },
    [selDate, allDiensten, saveDay, appData.urencodes]
  );

  const removeDienst = useCallback(
    (date, id) => {
      showConfirm("Dienst verwijderen?", () => {
        saveDay(
          date,
          sortDiensten(allDiensten[date] || []).filter((d) => d.id !== id)
        );
        setExpandedId((prev) => (prev === id ? null : prev));
      });
    },
    [showConfirm, saveDay, allDiensten]
  );

  const startEdit = useCallback((dienst) => {
    const brk = dienst.breaks?.[0];
    setEditId(dienst.id);
    setEditForm({
      type: dienst.type,
      title: dienst.title || "",
      start: dienst.start,
      end: dienst.end,
      slots: dienst.slots || 1,
      pauzeStart: brk?.start || "",
      pauzeEnd: brk?.end || "",
      urencode: dienst.urencode || "",
    });
  }, []);

  const saveEdit = useCallback(
    (formData) => {
      if (!selDate) return;
      const defaultCode = String(appData.urencodes?.[formData.type] || "");
      saveDay(
        selDate,
        sortDiensten(allDiensten[selDate] || []).map((d) =>
          d.id === editId
            ? {
                ...d,
                ...formData,
                slots: Math.max(1, Number(formData.slots) || 1),
                breaks:
                  formData.pauzeStart && formData.pauzeEnd
                    ? [{ start: formData.pauzeStart, end: formData.pauzeEnd }]
                    : [],
                urencode: formData.urencode || defaultCode,
              }
            : d
        )
      );
      setEditId(null);
      setEditForm(null);
    },
    [selDate, allDiensten, editId, saveDay, appData.urencodes]
  );

  const toggleAssign = useCallback(
    (date, dienstId, name) => {
      const diensten = sortDiensten(allDiensten[date] || []);
      const d = diensten.find((x) => x.id === dienstId);
      if (!d) return;
      const isIn = (d.assigned || []).includes(name);
      if (!isIn && (d.assigned || []).length >= d.slots) {
        showAlert(
          `Max ${d.slots} medewerker${
            d.slots !== 1 ? "s" : ""
          } voor deze dienst`
        );
        return;
      }
      saveDay(
        date,
        diensten.map((x) =>
          x.id === dienstId
            ? {
                ...x,
                assigned: isIn
                  ? x.assigned.filter((n) => n !== name)
                  : [...(x.assigned || []), name],
              }
            : x
        )
      );
    },
    [allDiensten, saveDay, showAlert]
  );

  // ── Template beheer ───────────────────────────────────
  const saveTpl = useCallback(
    (formData) => {
      const defaultCode = String(appData.urencodes?.[formData.type] || "");
      updateData({
        dienstTemplates: [
          ...templates,
          {
            id: Date.now(),
            ...formData,
            slots: Math.max(1, Number(formData.slots) || 1),
            breaks:
              formData.pauzeStart && formData.pauzeEnd
                ? [{ start: formData.pauzeStart, end: formData.pauzeEnd }]
                : [],
            urencode: formData.urencode || defaultCode,
          },
        ],
      });
      showAlert("Template opgeslagen");
    },
    [templates, updateData, showAlert, appData.urencodes]
  );

  const removeTpl = useCallback(
    (id) => {
      showConfirm("Template verwijderen?", () =>
        updateData({ dienstTemplates: templates.filter((t) => t.id !== id) })
      );
    },
    [templates, updateData, showConfirm]
  );

  // ── Publiceren ────────────────────────────────────────
  const publishDay = useCallback(
    (date) => {
      const diensten = sortDiensten(allDiensten[date] || []);
      const hasAssigned = diensten.some((d) => (d.assigned || []).length > 0);
      if (!hasAssigned) {
        showAlert("Wijs eerst medewerkers toe aan een dienst");
        return;
      }

      showConfirm(`Rooster publiceren voor ${date}?`, () => {
        updateData(publishDienstenPatch(appData, [date]));
        showAlert(`✅ Gepubliceerd: ${date}`);
      });
    },
    [allDiensten, appData.workSchedule, updateData, showAlert, showConfirm]
  );

  const publishMonth = useCallback(() => {
    const days = Object.keys(allDiensten).filter(
      (d) =>
        d.startsWith(monthKey) &&
        allDiensten[d].some((x) => (x.assigned || []).length > 0)
    );
    if (!days.length) {
      showAlert("Geen toegewezen diensten om te publiceren");
      return;
    }
    showConfirm(
      `Volledige maand publiceren? (${days.length} dag${
        days.length !== 1 ? "en" : ""
      })`,
      () => {
        updateData(publishDienstenPatch(appData, days));
        showAlert(`✅ Maand ${dutchMonths[viewMonth - 1]} gepubliceerd!`);
      }
    );
  }, [
    allDiensten,
    monthKey,
    appData.workSchedule,
    updateData,
    showAlert,
    showConfirm,
    viewMonth,
  ]);

  // ── Berekeningen (memoized) ────────────────────────────
  const personMonthHours = useCallback(
    (name) => {
      const dienstH = Object.entries(allDiensten)
        .filter(([d]) => d.startsWith(monthKey))
        .reduce(
          (s, [, ds]) =>
            s +
            ds
              .filter((d) => (d.assigned || []).includes(name))
              .reduce((x, d) => x + dienstHours(d), 0),
          0
        );
      const extraH = Object.entries(appData.extraUren?.[name] || {})
        .filter(([d]) => d.startsWith(monthKey))
        .reduce(
          (s, [, items]) =>
            s + items.reduce((x, i) => x + (Number(i.hours) || 0), 0),
          0
        );
      return dienstH + extraH;
    },
    [allDiensten, monthKey, appData.extraUren]
  );

  const contractTarget = useCallback(
    (name) => {
      const ch = contractInfo[name]?.contractHours;
      return ch ? +ch : null;
    },
    [contractInfo]
  );

  const dayStatus = useCallback(
    (date) => {
      const ds = sortDiensten(allDiensten[date] || []);
      if (!ds.length) return "empty";
      const totalSlots = ds.reduce((s, d) => s + (d.slots || 1), 0);
      const assigned = ds.reduce((s, d) => s + (d.assigned || []).length, 0);
      if (assigned === 0) return "planned";
      if (assigned >= totalSlots) return "full";
      return "partial";
    },
    [allDiensten]
  );

  const prog = useMemo(() => {
    let totalSlots = 0,
      totalAssigned = 0;
    Object.keys(allDiensten)
      .filter((d) => d.startsWith(monthKey))
      .forEach((date) => {
        allDiensten[date].forEach((d) => {
          totalSlots += d.slots || 1;
          totalAssigned += (d.assigned || []).length;
        });
      });
    return { totalSlots, totalAssigned };
  }, [allDiensten, monthKey]);

  // ── Label helpers ─────────────────────────────────────
  const fmtDay = useCallback((date) => {
    if (!date) return "";
    const d = new Date(date + "T00:00:00");
    const wd = d.getDay() === 0 ? 6 : d.getDay() - 1;
    return `${dutchDaysShort[wd]} ${d.getDate()} ${dutchMonths[d.getMonth()]}`;
  }, []);

  const availLabel = useCallback(
    (name, date) => {
      const a = allAvail[name]?.[date];
      if (!a) return null;
      if (!a.available) return "niet";
      if (a.start) return `${a.start}–${a.end}`;
      return "hele dag";
    },
    [allAvail]
  );

  const STATUS = useMemo(
    () => ({
      empty: { dot: C.BorderLight, calBg: "white" },
      planned: { dot: C.Honey, calBg: C.HoneyLight },
      partial: { dot: C.Bark, calBg: C.BarkLight },
      full: { dot: C.PineMedium, calBg: C.Bg },
    }),
    []
  );

  const selDiensten = useMemo(
    () => (selDate ? sortDiensten(allDiensten[selDate] || []) : []),
    [selDate, allDiensten]
  );
  const selActivities = useMemo(
    () => (selDate ? activities.filter((a) => a.date === selDate) : []),
    [selDate, activities]
  );

  // Compute weeks of the month: array of 7-day arrays (null = outside month)
  const weeksOfMonth = useMemo(() => {
    const weeks = [];
    let week = Array(firstDOW).fill(null);
    for (let d = 1; d <= daysInMonth; d++) {
      week.push(d);
      if (week.length === 7) {
        weeks.push(week);
        week = [];
      }
    }
    if (week.length > 0) {
      while (week.length < 7) week.push(null);
      weeks.push(week);
    }
    return weeks;
  }, [firstDOW, daysInMonth]);

  // ── FORM SHARED FIELDS ────────────────────────────────
  // ─────────────────────────────────────────────────────
  // ── Dag detail panel (shared between desktop inline & mobile modal) ──

  // ── DagPanel props ───────────────────────────────────
  const dagPanelProps = useMemo(
    () => ({
      t,
      selDate,
      selDiensten,
      selActivities,
      fmtDay,
      publishDay,
      modalTab,
      setModalTab,
      panel,
      setPanel,
      expandedId,
      setExpandedId,
      editId,
      setEditId,
      editForm,
      setEditForm,
      allAvail,
      allStaffIncFM,
      appData,
      toggleAssign,
      startEdit,
      removeDienst,
      addDienst,
      templates,
      saveTpl,
      removeTpl,
      addFromTpl,
      saveEdit,
      dienstHours,
      availLabel,
      setSelDate,
      updateData,
      setDraggedTpl,
      showAllStaffAvail,
      setShowAllStaffAvail,
    }),
    [
      t,
      selDate,
      selDiensten,
      selActivities,
      fmtDay,
      publishDay,
      modalTab,
      panel,
      expandedId,
      editId,
      editForm,
      allAvail,
      allStaffIncFM,
      appData,
      toggleAssign,
      startEdit,
      removeDienst,
      addDienst,
      templates,
      saveTpl,
      removeTpl,
      addFromTpl,
      saveEdit,
      availLabel,
      updateData,
      showAllStaffAvail,
    ]
  );

  return (
    <div className="pb-8">
      {/* ── PROGNOSE MAAND MODAL ── */}
      {showPrognoseModal &&
        (() => {
          const DRUK = (n) =>
            !n ? null : n < 1150 ? "L" : n <= 1850 ? "M" : "H";
          const DRUK_COLOR = { L: C.Pine, M: C.Bark, H: "#ef4444" };
          const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);
          const DOW_NL = ["Zo", "Ma", "Di", "Wo", "Do", "Vr", "Za"];

          const saveAll = () => {
            const newProg = { ...(appData.roosterPrognose || {}) };
            days.forEach((d) => {
              const dateKey = dk(d);
              const val = parseInt(prognoseDraft[dateKey]) || 0;
              if (val > 0) newProg[dateKey] = { total: val };
              else delete newProg[dateKey];
            });
            updateData({ roosterPrognose: newProg });
            setShowPrognoseModal(false);
            showAlert(
              `✅ Prognose opgeslagen voor ${dutchMonths[viewMonth - 1]}`
            );
          };

          return (
            <div
              className="fixed inset-0 z-50 flex items-center justify-center p-4"
              style={{ backgroundColor: "rgba(0,0,0,0.5)" }}
              onClick={() => setShowPrognoseModal(false)}
            >
              <div
                className="bg-white rounded-2xl shadow-2xl w-full max-w-md flex flex-col"
                style={{ maxHeight: "85vh" }}
                onClick={(e) => e.stopPropagation()}
              >
                {/* Modal header */}
                <div
                  className="flex items-center justify-between px-5 py-4 rounded-t-2xl flex-shrink-0"
                  style={{ backgroundColor: t.primary }}
                >
                  <div>
                    <p className="font-bold text-white text-base capitalize">
                      Prognose — {dutchMonths[viewMonth - 1]} {viewYear}
                    </p>
                    <p className="text-xs text-white opacity-70 mt-0.5">
                      L &lt;1.150 · M 1.150–1.850 · H &gt;1.850
                    </p>
                  </div>
                  <button
                    onClick={() => setShowPrognoseModal(false)}
                    className="p-2 rounded-xl"
                    style={{ backgroundColor: "rgba(255,255,255,0.15)" }}
                  >
                    <X size={16} className="text-white" />
                  </button>
                </div>

                {/* Snelle vul-rij */}
                <div
                  className="px-4 py-3 flex flex-col gap-2 flex-shrink-0 border-b"
                  style={{
                    borderColor: C.BorderLight,
                    backgroundColor: t.primary + "06",
                  }}
                >
                  {/* Alles invullen */}
                  <div className="flex items-center gap-2">
                    <TrendingUp
                      size={13}
                      style={{ color: t.primary, flexShrink: 0 }}
                    />
                    <span
                      className="text-xs font-semibold flex-shrink-0"
                      style={{ color: C.TextMuted }}
                    >
                      Alles invullen met:
                    </span>
                    <input
                      type="number"
                      min="0"
                      placeholder="getal…"
                      className="flex-1 rounded-lg px-2 py-1 text-sm border focus:outline-none"
                      style={{ borderColor: t.primary + "40" }}
                      onKeyDown={(e) => {
                        if (e.key === "Enter" && e.target.value) {
                          const val = e.target.value;
                          const draft = {};
                          days.forEach((d) => {
                            draft[dk(d)] = val;
                          });
                          setPrognoseDraft(draft);
                          e.target.value = "";
                        }
                      }}
                    />
                    <span
                      className="text-[11px]"
                      style={{ color: C.TextMuted }}
                    >
                      ↵ Enter
                    </span>
                  </div>

                  {/* Excel plakken */}
                  <div className="flex items-start gap-2">
                    <ClipboardList
                      size={13}
                      style={{ color: t.primary, flexShrink: 0, marginTop: 6 }}
                    />
                    <div className="flex-1">
                      <textarea
                        rows={2}
                        placeholder={
                          "Kolom uit Excel plakken (Ctrl+V)…\n1 waarde per rij, begint bij dag 1"
                        }
                        className="w-full rounded-lg px-2 py-1.5 text-xs border focus:outline-none resize-none"
                        style={{
                          borderColor: t.primary + "40",
                          fontFamily: "monospace",
                        }}
                        onPaste={(e) => {
                          e.preventDefault();
                          const raw = e.clipboardData.getData("text");
                          const vals = raw
                            .split(/\r?\n/)
                            .map((v) => v.trim().replace(/[^\d]/g, ""))
                            .filter((v) => v !== "");
                          if (vals.length === 0) return;
                          const draft = { ...prognoseDraft };
                          vals.forEach((val, idx) => {
                            const day = idx + 1;
                            if (day <= daysInMonth) draft[dk(day)] = val;
                          });
                          setPrognoseDraft(draft);
                          e.target.value = `✅ ${vals.length} waarden ingeladen`;
                          setTimeout(() => {
                            e.target.value = "";
                          }, 1800);
                        }}
                      />
                    </div>
                  </div>
                </div>

                {/* Dag-tabel */}
                <div className="overflow-y-auto flex-1 px-4 py-2">
                  <div className="space-y-1">
                    {days.map((d) => {
                      const dateKey = dk(d);
                      const dow = new Date(viewYear, viewMonth - 1, d).getDay();
                      const isWeekend = dow === 0 || dow === 6;
                      const val = parseInt(prognoseDraft[dateKey]) || 0;
                      const label = DRUK(val);
                      const actual = appData.dailyStats?.[dateKey] || {};
                      const actualTotal =
                        actual.total ||
                        (actual.adults || 0) +
                          (actual.kids || 0) +
                          (actual.babies || 0);
                      return (
                        <div
                          key={d}
                          className="flex items-center gap-2 rounded-xl px-2 py-1.5"
                          style={{
                            backgroundColor: isWeekend
                              ? "#fff7ed"
                              : "transparent",
                          }}
                        >
                          {/* Dag label */}
                          <div className="w-14 flex items-center gap-1.5 flex-shrink-0">
                            <span
                              className="text-[11px] font-semibold w-5 text-center"
                              style={{
                                color: isWeekend ? C.Sunset : C.TextMuted,
                              }}
                            >
                              {DOW_NL[dow]}
                            </span>
                            <span
                              className="text-sm font-black w-6 text-center"
                              style={{
                                color: isWeekend ? C.Sunset : C.TextPrimary,
                              }}
                            >
                              {d}
                            </span>
                          </div>

                          {/* Input */}
                          <input
                            type="number"
                            min="0"
                            placeholder="—"
                            value={prognoseDraft[dateKey] || ""}
                            onChange={(e) =>
                              setPrognoseDraft((prev) => ({
                                ...prev,
                                [dateKey]: e.target.value,
                              }))
                            }
                            className="flex-1 rounded-lg px-2 py-1 text-sm font-semibold text-center border focus:outline-none"
                            style={{
                              borderColor:
                                val > 0 ? t.primary + "50" : C.BorderLight,
                              color: C.TextPrimary,
                              backgroundColor:
                                val > 0 ? t.primary + "06" : "white",
                            }}
                          />

                          {/* L/M/H badge */}
                          <div
                            className="w-7 h-7 rounded-lg flex items-center justify-center text-xs font-black flex-shrink-0"
                            style={{
                              backgroundColor: label
                                ? DRUK_COLOR[label] + "18"
                                : C.BorderLight + "60",
                              color: label ? DRUK_COLOR[label] : C.TextMuted,
                            }}
                          >
                            {label || "·"}
                          </div>

                          {/* Actueel geboekt */}
                          {actualTotal > 0 && (
                            <div
                              className="flex items-center gap-0.5 flex-shrink-0 w-14 justify-end"
                              style={{ color: C.TextMuted }}
                              title="Geboekt"
                            >
                              <Users size={9} />
                              <span className="text-[11px] font-medium">
                                {actualTotal >= 1000
                                  ? (actualTotal / 1000)
                                      .toFixed(1)
                                      .replace(".0", "") + "k"
                                  : actualTotal}
                              </span>
                            </div>
                          )}
                          {!actualTotal && <div className="w-14" />}
                        </div>
                      );
                    })}
                  </div>
                </div>

                {/* Footer */}
                <div
                  className="px-4 py-3 flex items-center justify-between gap-2 flex-shrink-0 border-t"
                  style={{ borderColor: C.BorderLight }}
                >
                  <button
                    onClick={() => {
                      setPrognoseDraft({});
                    }}
                    className="px-3 py-2 rounded-xl text-xs font-semibold"
                    style={{
                      color: C.TextMuted,
                      backgroundColor: C.BorderLight + "80",
                    }}
                  >
                    Leegmaken
                  </button>
                  <div className="flex gap-2">
                    <button
                      onClick={() => setShowPrognoseModal(false)}
                      className="px-3 py-2 rounded-xl text-xs font-semibold"
                      style={{ color: C.TextMuted }}
                    >
                      Annuleren
                    </button>
                    <button
                      onClick={saveAll}
                      className="flex items-center gap-1.5 px-4 py-2 rounded-xl text-xs font-semibold text-white"
                      style={{ backgroundColor: t.primary }}
                    >
                      <CheckCircle size={13} /> Opslaan
                    </button>
                  </div>
                </div>
              </div>
            </div>
          );
        })()}
      {/* ── HEADER ── */}
      <div className="px-4 pt-2 pb-3 flex items-center justify-between gap-2">
        <div className="flex items-center gap-2">
          {onBack && (
            <button
              onClick={onBack}
              className="p-2 rounded-xl flex-shrink-0"
              style={{ backgroundColor: t.primary + "15", color: t.primary }}
              title="Terug"
            >
              <ArrowLeft size={15} />
            </button>
          )}
          <button
            onClick={() => changeMonth(-1)}
            className="p-2 rounded-xl"
            style={{ backgroundColor: t.primary + "15", color: t.primary }}
          >
            <ChevronLeft size={16} />
          </button>
          <div className="text-center min-w-[120px]">
            <p
              className="font-bold text-base capitalize"
              style={{ color: t.primary }}
            >
              {dutchMonths[viewMonth - 1]} {viewYear}
            </p>
            <p className="text-[11px]" style={{ color: C.TextMuted }}>
              {prog.totalAssigned}/{prog.totalSlots} slots bezet
            </p>
          </div>
          <button
            onClick={() => changeMonth(1)}
            className="p-2 rounded-xl"
            style={{ backgroundColor: t.primary + "15", color: t.primary }}
          >
            <ChevronRight size={16} />
          </button>
        </div>
        <div className="flex items-center gap-2">
          {/* View toggle */}
          <div
            className="flex rounded-xl overflow-hidden border"
            style={{ borderColor: C.BorderLight }}
          >
            {[
              { id: "maand", label: "Maand" },
              { id: "week", label: "Week" },
              { id: "rooster", label: "Rooster" },
            ].map((v) => (
              <button
                key={v.id}
                onClick={() => {
                  setCalView(v.id);
                  if (v.id === "week" && selDate) {
                    const w = weeksOfMonth.findIndex((wk) =>
                      wk.includes(new Date(selDate + "T00:00:00").getDate())
                    );
                    if (w >= 0) setViewWeek(w);
                  }
                }}
                className="px-3 py-1.5 text-xs font-semibold transition-all"
                style={{
                  backgroundColor: calView === v.id ? t.primary : "white",
                  color: calView === v.id ? "white" : C.TextMuted,
                }}
              >
                {v.label}
              </button>
            ))}
          </div>
          <button
            onClick={printMonthA3}
            disabled={printingMonth}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold border"
            style={{
              borderColor: t.primary + "40",
              color: t.primary,
              backgroundColor: t.primary + "08",
              opacity: printingMonth ? 0.6 : 1,
            }}
            title="Hele maand printen op A3 (liggend)"
          >
            <Printer size={13} /> {printingMonth ? "Bezig…" : "Print A3"}
          </button>
          <button
            onClick={() => {
              const draft = {};
              for (let d = 1; d <= daysInMonth; d++) {
                const dateKey = dk(d);
                const p = appData.roosterPrognose?.[dateKey];
                if (p?.total) draft[dateKey] = String(p.total);
              }
              setPrognoseDraft(draft);
              setShowPrognoseModal(true);
            }}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold border"
            style={{
              borderColor: t.primary + "40",
              color: t.primary,
              backgroundColor: t.primary + "08",
            }}
            title="Prognose maand invullen"
          >
            <TrendingUp size={13} /> Prognose
          </button>
          {(() => {
            const publishedMonthDays = Object.keys(
              appData.workSchedule || {}
            ).filter(
              (d) =>
                d.startsWith(monthKey) &&
                (appData.workSchedule[d] || []).some(
                  (s) => s.source === "from-roostermaker"
                )
            );
            const isMonthPublished = publishedMonthDays.length > 0;
            if (isMonthPublished)
              return (
                <button
                  onClick={() => {
                    const ws = { ...(appData.workSchedule || {}) };
                    publishedMonthDays.forEach((d) => {
                      ws[d] = (ws[d] || []).filter(
                        (s) => s.source !== "from-roostermaker"
                      );
                    });
                    updateData({ workSchedule: ws });
                    showAlert(
                      `🗑️ Rooster van ${
                        dutchMonths[viewMonth - 1]
                      } ongedaan gemaakt.`
                    );
                  }}
                  className="flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-semibold shadow-sm"
                  style={{
                    backgroundColor: C.Pine + "15",
                    color: C.Pine,
                    border: `1px solid ${C.Pine}40`,
                  }}
                >
                  <CheckCircle size={13} /> Gepubliceerd
                </button>
              );
            return (
              <button
                onClick={publishMonth}
                className="flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-semibold text-white shadow-sm"
                style={{
                  backgroundColor:
                    prog.totalAssigned > 0 ? C.Pine : C.TextMuted,
                }}
              >
                <CheckCircle size={13} /> Publiceer
              </button>
            );
          })()}
        </div>
      </div>

      {/* ── DESKTOP: 2-kolom; MOBILE: kalender + modal ── */}
      <div className="sm:flex sm:gap-0 sm:items-start">
        {/* ── LINKER KOLOM: kalender + uren ── */}
        <div className="sm:flex-1 sm:min-w-0">
          {/* ── MAAND VIEW ── */}
          {calView === "maand" && (
            <div
              className="mx-4 bg-white rounded-2xl border overflow-hidden"
              style={{ borderColor: C.BorderLight }}
            >
              <div
                className="grid grid-cols-7 border-b"
                style={{ borderColor: C.BorderLight }}
              >
                {["Ma", "Di", "Wo", "Do", "Vr", "Za", "Zo"].map((d) => (
                  <div
                    key={d}
                    className="text-center py-2 text-[11px] font-semibold"
                    style={{ color: C.TextMuted }}
                  >
                    {d}
                  </div>
                ))}
              </div>
              <div className="grid grid-cols-7">
                {Array.from({ length: firstDOW }, (_, i) => (
                  <div
                    key={"e" + i}
                    className="border-b border-r min-h-[56px]"
                    style={{ borderColor: C.BorderLight }}
                  />
                ))}
                {Array.from({ length: daysInMonth }, (_, i) => {
                  const day = i + 1;
                  const date = dk(day);
                  const status = dayStatus(date);
                  const st = STATUS[status];
                  const isSelected = selDate === date;
                  const isToday = date === toIsoDate(today);
                  const col = (firstDOW + i) % 7;
                  const isWeekend = col >= 5;
                  const ds = sortDiensten(allDiensten[date] || []);
                  const availCount = getDayAvailSummary(
                    allAvail,
                    allStaffIncFM,
                    date
                  ).beschikbaarTotaal;
                  const dayStats = appData.dailyStats?.[date] || {};
                  const guestTotal =
                    dayStats.total ||
                    (dayStats.adults || 0) +
                      (dayStats.kids || 0) +
                      (dayStats.babies || 0);
                  const dayProg = appData.roosterPrognose?.[date] || {};
                  const progTotal = dayProg.total || 0;
                  const getDrukLabel = (n) =>
                    n < 1150 ? "L" : n <= 1850 ? "M" : "H";
                  const getDrukColor = (l) =>
                    ({ L: C.Pine, M: C.Bark, H: "#ef4444" }[l]);
                  const showGuest = guestTotal > 0;
                  const showProg = !showGuest && progTotal > 0;

                  return (
                    <button
                      key={day}
                      onClick={() => {
                        setSelDate((prev) => (prev === date ? null : date));
                        setPanel("overview");
                        setExpandedId(null);
                        setEditId(null);
                        setModalTab("diensten");
                      }}
                      className="rm-daycell border-b border-r min-h-[56px] p-1 flex flex-col items-start gap-0.5 transition-all text-left relative"
                      style={{
                        borderColor: C.BorderLight,
                        backgroundColor: isSelected
                          ? t.primary
                          : isToday
                          ? t.primary + "15"
                          : st.calBg,
                      }}
                    >
                      {status !== "empty" && (
                        <div
                          className="absolute left-0 top-0 bottom-0 w-0.5 rounded-r-full"
                          style={{
                            backgroundColor: isSelected
                              ? "rgba(255,255,255,0.5)"
                              : st.dot,
                          }}
                        />
                      )}
                      {(() => {
                        const isPublished = (
                          appData.workSchedule?.[date] || []
                        ).some((s) => s.source === "from-roostermaker");
                        return (
                          <div className="flex items-center justify-between w-full">
                            <span
                              className="text-[11px] font-bold w-5 h-5 flex items-center justify-center rounded-full flex-shrink-0"
                              style={{
                                backgroundColor:
                                  isToday && !isSelected
                                    ? t.primary
                                    : "transparent",
                                color: isSelected
                                  ? "white"
                                  : isToday
                                  ? "white"
                                  : isWeekend
                                  ? C.TextMuted
                                  : C.TextPrimary,
                              }}
                            >
                              {day}
                            </span>
                            <div className="flex items-center gap-0.5">
                              {isPublished && !isSelected && (
                                <CheckCircle
                                  size={9}
                                  style={{ color: C.Pine, flexShrink: 0 }}
                                />
                              )}
                              {availCount > 0 && !isSelected && (
                                <span
                                  className="text-[8px] font-medium leading-none"
                                  style={{ color: C.TextMuted }}
                                >
                                  {availCount}
                                </span>
                              )}
                            </div>
                          </div>
                        );
                      })()}
                      {ds.map((d, idx) => {
                        const tc = RM_TYPES[d.type] || RM_TYPES.overig;
                        const Icon = tc.icon;
                        const filled = (d.assigned || []).length >= d.slots;
                        const label = d.title || tc.label;
                        return (
                          <div
                            key={idx}
                            className="w-full rounded text-[8px] font-semibold px-1 py-px flex items-center gap-0.5 truncate"
                            style={{
                              backgroundColor: isSelected
                                ? "rgba(255,255,255,0.2)"
                                : filled
                                ? C.GrassLight
                                : tc.bg,
                              color: isSelected
                                ? "white"
                                : filled
                                ? C.Pine
                                : tc.color,
                            }}
                          >
                            {Icon && (
                              <Icon size={7} style={{ flexShrink: 0 }} />
                            )}
                            <span className="truncate">
                              {label.slice(0, 10)}{" "}
                              {filled
                                ? "✓"
                                : `${(d.assigned || []).length}/${d.slots}`}
                            </span>
                          </div>
                        );
                      })}
                      {showGuest && (
                        <div
                          className="w-full flex items-center gap-0.5 mt-auto"
                          style={{
                            color: isSelected
                              ? "rgba(255,255,255,0.75)"
                              : C.TextMuted,
                          }}
                        >
                          <Users size={7} style={{ flexShrink: 0 }} />
                          <span className="text-[8px] font-medium leading-none">
                            {guestTotal.toLocaleString("nl-NL")}
                          </span>
                        </div>
                      )}
                      {showProg && (
                        <div
                          className="w-full flex items-center gap-0.5 mt-auto"
                          style={{
                            color: isSelected
                              ? "rgba(255,255,255,0.6)"
                              : getDrukColor(getDrukLabel(progTotal)),
                          }}
                        >
                          <span className="text-[8px] font-black leading-none">
                            {getDrukLabel(progTotal)}
                          </span>
                          <span className="text-[7px] font-medium leading-none opacity-75">
                            ~
                            {progTotal >= 1000
                              ? (progTotal / 1000)
                                  .toFixed(1)
                                  .replace(".0", "") + "k"
                              : progTotal}
                          </span>
                        </div>
                      )}
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {/* ── WEEK VIEW ── */}
          {calView === "week" &&
            (() => {
              const week = weeksOfMonth[viewWeek] || [];
              const hasNext = viewWeek < weeksOfMonth.length - 1;
              const hasPrev = viewWeek > 0;
              return (
                <div className="mx-4 space-y-2">
                  {/* Week navigator */}
                  <div className="flex items-center justify-between px-1">
                    <button
                      onClick={() => hasPrev && setViewWeek((v) => v - 1)}
                      className="p-1.5 rounded-xl transition-all"
                      style={{
                        backgroundColor: hasPrev
                          ? t.primary + "15"
                          : "transparent",
                        color: hasPrev ? t.primary : C.BorderLight,
                      }}
                    >
                      <ChevronLeft size={14} />
                    </button>
                    <span
                      className="text-xs font-semibold"
                      style={{ color: C.TextMuted }}
                    >
                      Week {viewWeek + 1} van {weeksOfMonth.length}
                    </span>
                    <button
                      onClick={() => hasNext && setViewWeek((v) => v + 1)}
                      className="p-1.5 rounded-xl transition-all"
                      style={{
                        backgroundColor: hasNext
                          ? t.primary + "15"
                          : "transparent",
                        color: hasNext ? t.primary : C.BorderLight,
                      }}
                    >
                      <ChevronRight size={14} />
                    </button>
                  </div>

                  {/* 7-koloms header */}
                  <div
                    className="bg-white rounded-2xl border overflow-hidden"
                    style={{ borderColor: C.BorderLight }}
                  >
                    <div
                      className="grid grid-cols-7 border-b"
                      style={{ borderColor: C.BorderLight }}
                    >
                      {["Ma", "Di", "Wo", "Do", "Vr", "Za", "Zo"].map(
                        (d, ci) => {
                          const day = week[ci];
                          const date = day ? dk(day) : null;
                          const isToday = date === toIsoDate(today);
                          const isSelected = selDate === date;
                          return (
                            <div
                              key={d}
                              className="text-center py-2 border-r last:border-r-0"
                              style={{
                                borderColor: C.BorderLight,
                                backgroundColor: isSelected
                                  ? t.primary + "15"
                                  : "transparent",
                              }}
                            >
                              <div
                                className="text-[9px] font-bold"
                                style={{ color: C.TextMuted }}
                              >
                                {d}
                              </div>
                              {day && (
                                <div
                                  className="text-sm font-bold w-7 h-7 mx-auto flex items-center justify-center rounded-full"
                                  style={{
                                    backgroundColor: isSelected
                                      ? t.primary
                                      : isToday
                                      ? t.primary + "20"
                                      : "transparent",
                                    color: isSelected
                                      ? "white"
                                      : isToday
                                      ? t.primary
                                      : C.TextPrimary,
                                  }}
                                >
                                  {day}
                                </div>
                              )}
                            </div>
                          );
                        }
                      )}
                    </div>

                    {/* Diensten per dag */}
                    <div className="grid grid-cols-7 min-h-[160px]">
                      {week.map((day, ci) => {
                        if (!day)
                          return (
                            <div
                              key={ci}
                              className="border-r last:border-r-0 p-1"
                              style={{
                                borderColor: C.BorderLight,
                                backgroundColor: "#f9fafb",
                              }}
                            />
                          );
                        const date = dk(day);
                        const status = dayStatus(date);
                        const st = STATUS[status];
                        const isSelected = selDate === date;
                        const isWeekend = ci >= 5;
                        const ds = sortDiensten(allDiensten[date] || []);
                        const availCount = getDayAvailSummary(
                          allAvail,
                          allStaffIncFM,
                          date
                        ).beschikbaarTotaal;
                        const weekDayStats = appData.dailyStats?.[date] || {};
                        const weekGuestTotal =
                          weekDayStats.total ||
                          (weekDayStats.adults || 0) +
                            (weekDayStats.kids || 0) +
                            (weekDayStats.babies || 0);
                        const weekProg = appData.roosterPrognose?.[date] || {};
                        const weekProgTotal = weekProg.total || 0;
                        const getWDrukLabel = (n) =>
                          n < 1150 ? "L" : n <= 1850 ? "M" : "H";
                        const getWDrukColor = (l) =>
                          ({ L: C.Pine, M: C.Bark, H: "#ef4444" }[l]);
                        const weekShowGuest = weekGuestTotal > 0;
                        const weekShowProg =
                          !weekShowGuest && weekProgTotal > 0;

                        return (
                          <button
                            key={day}
                            onClick={() => {
                              setSelDate((prev) =>
                                prev === date ? null : date
                              );
                              setPanel("overview");
                              setExpandedId(null);
                              setEditId(null);
                              setModalTab("diensten");
                            }}
                            className="border-r last:border-r-0 p-1.5 flex flex-col gap-1 text-left transition-all relative"
                            style={{
                              borderColor: C.BorderLight,
                              backgroundColor: isSelected
                                ? t.primary + "08"
                                : isWeekend
                                ? "#f9fafb"
                                : "white",
                              borderLeft: isSelected
                                ? `3px solid ${t.primary}`
                                : undefined,
                            }}
                          >
                            {availCount > 0 && (
                              <div
                                className="text-[8px] font-medium"
                                style={{ color: C.TextMuted }}
                              >
                                {availCount} beschikbaar
                              </div>
                            )}
                            {weekShowGuest && (
                              <div
                                className="flex items-center gap-0.5"
                                style={{ color: C.TextMuted }}
                              >
                                <Users size={8} style={{ flexShrink: 0 }} />
                                <span className="text-[8px] font-semibold">
                                  {weekGuestTotal.toLocaleString("nl-NL")}
                                </span>
                              </div>
                            )}
                            {weekShowProg && (
                              <div
                                className="flex items-center gap-1"
                                style={{
                                  color: getWDrukColor(
                                    getWDrukLabel(weekProgTotal)
                                  ),
                                }}
                              >
                                <span className="text-[9px] font-black leading-none">
                                  {getWDrukLabel(weekProgTotal)}
                                </span>
                                <span className="text-[8px] font-medium opacity-75">
                                  ~
                                  {weekProgTotal >= 1000
                                    ? (weekProgTotal / 1000)
                                        .toFixed(1)
                                        .replace(".0", "") + "k"
                                    : weekProgTotal}
                                </span>
                              </div>
                            )}
                            {ds.length === 0 && (
                              <div className="flex-1 flex items-center justify-center">
                                <div
                                  className="w-4 h-4 rounded-full border-dashed border-2 opacity-30"
                                  style={{ borderColor: C.BorderLight }}
                                />
                              </div>
                            )}
                            {ds.map((d, idx) => {
                              const tc = RM_TYPES[d.type] || RM_TYPES.overig;
                              const Icon = tc.icon;
                              const filled =
                                (d.assigned || []).length >= d.slots;
                              const label = d.title || tc.label;
                              return (
                                <div
                                  key={idx}
                                  className="rounded-lg p-1.5 w-full"
                                  style={{
                                    backgroundColor: filled
                                      ? C.GrassLight
                                      : tc.bg,
                                    border: `1px solid ${
                                      filled ? "#86efac" : tc.border
                                    }`,
                                  }}
                                >
                                  <div className="flex items-center gap-1 mb-0.5">
                                    {Icon && (
                                      <Icon
                                        size={9}
                                        style={{
                                          color: filled ? C.Pine : tc.color,
                                          flexShrink: 0,
                                        }}
                                      />
                                    )}
                                    <span
                                      className="text-[9px] font-bold leading-tight truncate"
                                      style={{
                                        color: filled ? C.Pine : tc.color,
                                      }}
                                    >
                                      {label}
                                    </span>
                                  </div>
                                  <div
                                    className="text-[8px] leading-tight"
                                    style={{ color: C.TextMuted }}
                                  >
                                    {d.start}–{d.end}
                                  </div>
                                  {(d.assigned || []).length > 0 && (
                                    <div className="flex flex-wrap gap-px mt-1">
                                      {(d.assigned || []).map((name) => (
                                        <span
                                          key={name}
                                          className="text-[8px] px-1 py-px rounded font-medium leading-tight truncate max-w-full"
                                          style={{
                                            backgroundColor: "white",
                                            color: C.TextPrimary,
                                            border: `1px solid ${C.BorderLight}`,
                                          }}
                                        >
                                          {name.split(" ")[0]}
                                        </span>
                                      ))}
                                      {(d.assigned || []).length < d.slots && (
                                        <span
                                          className="text-[8px] px-1 py-px rounded font-medium leading-tight"
                                          style={{
                                            backgroundColor: C.BlossomLight,
                                            color: C.Sunset,
                                          }}
                                        >
                                          +{d.slots - (d.assigned || []).length}
                                        </span>
                                      )}
                                    </div>
                                  )}
                                </div>
                              );
                            })}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                </div>
              );
            })()}

          {/* ── ROOSTER VIEW: namen links, dagen rechts ── */}
          {calView === "rooster" &&
            (() => {
              const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);
              const DOW = ["Zo", "Ma", "Di", "Wo", "Do", "Vr", "Za"];
              const ROLES = ["Orry", "Bing", "Woops", "Rep"];
              const typeColors = {
                entertainment: {
                  bg: "#FFCA5540",
                  border: "#FFCA55",
                  text: "#7A5226",
                },
                crea: { bg: "#9DB4F640", border: "#9DB4F6", text: "#00192F" },
                springkussen: {
                  bg: "#FF699B30",
                  border: "#FF699B",
                  text: "#700606",
                },
                fm: { bg: "#045E5118", border: "#045E51", text: "#045E51" },
                snipper: {
                  bg: "#9DB4F640",
                  border: "#9DB4F6",
                  text: "#00192F",
                },
                verlof: { bg: "#f0fdf4", border: "#86efac", text: "#15803d" },
                at: { bg: "#FFCA5540", border: "#FFCA55", text: "#7A5226" },
                comp: { bg: "#f5f3ff", border: "#c4b5fd", text: "#7c3aed" },
                ziek: { bg: "#FF699B18", border: "#FF699B", text: "#700606" },
                overig: { bg: "#f1f5f9", border: "#cbd5e1", text: "#475569" },
              };

              const charBg = (r) =>
                ({
                  orry: "#FF699B",
                  bing: "#B1EDA6",
                  woops: "#9DB4F6",
                  rep: "#FFCA55",
                }[r.toLowerCase()] || "#e2e8f0");
              const charTx = (r) =>
                ({
                  orry: "#700606",
                  bing: "#045E51",
                  woops: "#00192F",
                  rep: "#7A5226",
                }[r.toLowerCase()] || "#475569");
              const allChars = appData.characters || [];
              const allActs = appData.schedule || [];

              const assignChar = (dateKey, personName, role) => {
                let chars = (appData.characters || []).filter(
                  (c) => !(c.date === dateKey && c.actor === personName)
                );
                if (role)
                  chars = [
                    ...chars,
                    { date: dateKey, role, actor: personName },
                  ];
                updateData({ characters: chars });
                setCharEdit(null);
              };

              let _drag = null;
              const doMove = (targetDateKey, targetPersonName) => {
                if (!_drag) return;

                // ── Type 1: Toewijzen vanuit open-diensten balk ──
                if (_drag.dragType === "assign") {
                  const { dateKey: fromDateKey, dienstIdx } = _drag;
                  const newD = JSON.parse(
                    JSON.stringify(appData.roosterDiensten || {})
                  );
                  const dienst = (newD[fromDateKey] || [])[dienstIdx];
                  if (!dienst) {
                    _drag = null;
                    return;
                  }
                  if ((dienst.assigned || []).includes(targetPersonName)) {
                    _drag = null;
                    return;
                  }
                  if ((dienst.assigned || []).length >= dienst.slots) {
                    _drag = null;
                    return;
                  }
                  dienst.assigned = [
                    ...(dienst.assigned || []),
                    targetPersonName,
                  ];
                  updateData({ roosterDiensten: newD });
                  _drag = null;
                  return;
                }

                // ── Type 2: Verplaatsen binnen het rooster ──
                const {
                  fromDateKey,
                  dienstIdx,
                  personName: fromPerson,
                } = _drag;
                if (
                  fromDateKey === targetDateKey &&
                  fromPerson === targetPersonName
                )
                  return;
                const newD = JSON.parse(
                  JSON.stringify(appData.roosterDiensten || {})
                );
                const srcDienst = (newD[fromDateKey] || [])[dienstIdx];
                if (!srcDienst) return;
                srcDienst.assigned = (srcDienst.assigned || []).filter(
                  (n) => n !== fromPerson
                );
                if (!newD[targetDateKey]) newD[targetDateKey] = [];
                const tgt = newD[targetDateKey];
                let match = tgt.find(
                  (d2) =>
                    d2.type === srcDienst.type &&
                    d2.start === srcDienst.start &&
                    d2.end === srcDienst.end
                );
                if (!match) {
                  match = {
                    ...srcDienst,
                    assigned: [],
                    id: Date.now() + Math.random(),
                  };
                  tgt.push(match);
                }
                if (!(match.assigned || []).includes(targetPersonName))
                  match.assigned = [
                    ...(match.assigned || []),
                    targetPersonName,
                  ];
                updateData({ roosterDiensten: newD });
                _drag = null;
              };

              return (
                <div
                  className="mx-4 bg-white rounded-2xl border overflow-hidden"
                  style={{ borderColor: C.BorderLight }}
                >
                  <div
                    className="overflow-auto"
                    style={{ maxHeight: "calc(100vh - 180px)" }}
                  >
                    <table
                      style={{
                        borderCollapse: "collapse",
                        width: "100%",
                        tableLayout: "fixed",
                      }}
                    >
                      <colgroup>
                        <col style={{ width: "110px", minWidth: "110px" }} />
                        {days.map((d) => (
                          <col
                            key={d}
                            style={{ width: "50px", minWidth: "44px" }}
                          />
                        ))}
                        <col style={{ width: "60px", minWidth: "60px" }} />
                      </colgroup>
                      <thead style={{ position: "sticky", top: 0, zIndex: 2 }}>
                        <tr>
                          <th
                            style={{
                              padding: "6px 10px",
                              textAlign: "left",
                              fontSize: "10px",
                              fontWeight: 700,
                              color: C.TextMuted,
                              backgroundColor: C.Bg,
                              borderBottom: `1px solid ${C.BorderLight}`,
                              borderRight: `1px solid ${C.BorderLight}`,
                              position: "sticky",
                              left: 0,
                              zIndex: 3,
                            }}
                          >
                            Naam
                          </th>
                          {days.map((d) => {
                            const date = new Date(viewYear, viewMonth - 1, d);
                            const dow = date.getDay();
                            const isWeekend = dow === 0 || dow === 6;
                            const dateKey = dk(d);
                            const isToday =
                              dateKey === new Date().toISOString().slice(0, 10);
                            const rStats = appData.dailyStats?.[dateKey] || {};
                            const rGuests =
                              rStats.total ||
                              (rStats.adults || 0) +
                                (rStats.kids || 0) +
                                (rStats.babies || 0);
                            const rProg =
                              appData.roosterPrognose?.[dateKey] || {};
                            const rProgTotal = rProg.total || 0;
                            const getRDrukLabel = (n) =>
                              n < 1150 ? "L" : n <= 1850 ? "M" : "H";
                            const getRDrukColor = (l) =>
                              ({ L: C.Pine, M: C.Bark, H: "#ef4444" }[l]);
                            const progLabel =
                              rProgTotal > 0 ? getRDrukLabel(rProgTotal) : null;
                            const progColor = progLabel
                              ? getRDrukColor(progLabel)
                              : null;
                            return (
                              <th
                                key={d}
                                onClick={() => setSelDate(dateKey)}
                                style={{
                                  padding: "4px 2px 3px",
                                  textAlign: "center",
                                  fontSize: "9px",
                                  fontWeight: 700,
                                  color: isToday
                                    ? t.primary
                                    : isWeekend
                                    ? C.Sunset
                                    : C.TextMuted,
                                  backgroundColor: isToday
                                    ? t.primary + "15"
                                    : isWeekend
                                    ? "#fff7ed"
                                    : C.Bg,
                                  borderBottom: `1px solid ${C.BorderLight}`,
                                  borderLeft: `1px solid ${C.BorderLight}`,
                                  cursor: "pointer",
                                  verticalAlign: "top",
                                }}
                              >
                                <div>{DOW[dow]}</div>
                                <div
                                  style={{
                                    fontSize: "11px",
                                    fontWeight: 900,
                                    color: isToday ? t.primary : "inherit",
                                    marginBottom: "3px",
                                  }}
                                >
                                  {d}
                                </div>
                                {/* Actueel geboekt — solid chip */}
                                {rGuests > 0 && (
                                  <div
                                    title={`Geboekt: ${rGuests.toLocaleString(
                                      "nl-NL"
                                    )} gasten`}
                                    style={{
                                      margin: "1px 3px",
                                      padding: "1px 0",
                                      borderRadius: "4px",
                                      fontSize: "8px",
                                      fontWeight: 700,
                                      lineHeight: "13px",
                                      backgroundColor: t.primary + "22",
                                      color: t.primary,
                                    }}
                                  >
                                    {rGuests >= 1000
                                      ? (rGuests / 1000)
                                          .toFixed(1)
                                          .replace(".0", "") + "k"
                                      : rGuests}
                                  </div>
                                )}
                                {/* Prognose — outlined dashed chip met L/M/H */}
                                {rProgTotal > 0 && (
                                  <div
                                    title={`Prognose: ~${rProgTotal.toLocaleString(
                                      "nl-NL"
                                    )} (${progLabel})`}
                                    style={{
                                      margin: "1px 3px",
                                      padding: "1px 0",
                                      borderRadius: "4px",
                                      fontSize: "8px",
                                      fontWeight: 700,
                                      lineHeight: "13px",
                                      border: `1px dashed ${progColor}`,
                                      color: progColor,
                                      backgroundColor: progColor + "10",
                                    }}
                                  >
                                    ~{progLabel}
                                  </div>
                                )}
                              </th>
                            );
                          })}
                          <th
                            style={{
                              padding: "4px 6px",
                              textAlign: "center",
                              fontSize: "9px",
                              fontWeight: 700,
                              color: C.TextMuted,
                              backgroundColor: C.Bg,
                              borderBottom: `1px solid ${C.BorderLight}`,
                              borderLeft: `2px solid ${C.BorderLight}`,
                              position: "sticky",
                              right: 0,
                              zIndex: 2,
                            }}
                          >
                            Uren
                          </th>
                        </tr>
                      </thead>
                      <tbody>
                        {/* ── OPEN DIENSTEN RIJ ── */}
                        <tr
                          style={{ position: "sticky", top: "57px", zIndex: 2 }}
                        >
                          <td
                            style={{
                              padding: "4px 8px",
                              fontSize: "9px",
                              fontWeight: 700,
                              color: C.TextMuted,
                              backgroundColor: "#fffbeb",
                              borderBottom: `2px solid ${C.Sunset}40`,
                              borderRight: `1px solid ${C.BorderLight}`,
                              borderTop: `1px solid ${C.Sunset}30`,
                              position: "sticky",
                              left: 0,
                              zIndex: 3,
                              whiteSpace: "nowrap",
                            }}
                          >
                            <div className="flex items-center gap-1">
                              <AlertCircle
                                size={10}
                                style={{ color: C.Sunset }}
                              />
                              <span>Open</span>
                            </div>
                          </td>
                          {days.map((d) => {
                            const dateKey = dk(d);
                            const dow = new Date(
                              viewYear,
                              viewMonth - 1,
                              d
                            ).getDay();
                            const isWeekend = dow === 0 || dow === 6;
                            const isToday =
                              dateKey === new Date().toISOString().slice(0, 10);
                            const openHere = [];
                            (allDiensten[dateKey] || []).forEach((dv, idx) => {
                              const open =
                                dv.slots - (dv.assigned || []).length;
                              for (let s = 0; s < open; s++) {
                                openHere.push({ dv, idx, slotNr: s + 1, open });
                              }
                            });
                            return (
                              <td
                                key={d}
                                onDragOver={(e) => {
                                  if (_drag?.dragType === "move") {
                                    e.preventDefault();
                                    e.currentTarget.style.outline = `2px dashed ${C.Sunset}`;
                                    e.currentTarget.style.outlineOffset =
                                      "-2px";
                                  }
                                }}
                                onDragLeave={(e) => {
                                  e.currentTarget.style.outline = "";
                                }}
                                onDrop={(e) => {
                                  e.preventDefault();
                                  e.currentTarget.style.outline = "";
                                  if (!_drag || _drag.dragType !== "move")
                                    return;
                                  const { fromDateKey, dienstIdx, personName } =
                                    _drag;
                                  const newD = JSON.parse(
                                    JSON.stringify(
                                      appData.roosterDiensten || {}
                                    )
                                  );
                                  const dienst = (newD[fromDateKey] || [])[
                                    dienstIdx
                                  ];
                                  if (!dienst) {
                                    _drag = null;
                                    return;
                                  }
                                  dienst.assigned = (
                                    dienst.assigned || []
                                  ).filter((n) => n !== personName);
                                  updateData({ roosterDiensten: newD });
                                  _drag = null;
                                }}
                                style={{
                                  padding: "2px",
                                  verticalAlign: "top",
                                  borderBottom: `2px solid ${C.Sunset}40`,
                                  borderTop: `1px solid ${C.Sunset}30`,
                                  borderLeft: `1px solid ${C.BorderLight}`,
                                  backgroundColor: isToday
                                    ? "#fef9c3"
                                    : isWeekend
                                    ? "#fff7ed"
                                    : "#fffbeb",
                                  minHeight: "20px",
                                }}
                              >
                                {openHere.map(({ dv, idx }) => {
                                  const tc =
                                    typeColors[dv.type] || typeColors.overig;
                                  const open =
                                    dv.slots - (dv.assigned || []).length;
                                  const label =
                                    RM_TYPES[dv.type]?.fixedHours !== undefined
                                      ? (
                                          RM_TYPES[dv.type]?.label || dv.type
                                        ).slice(0, 4)
                                      : `${dv.start || ""}${
                                          dv.end ? `–${dv.end}` : ""
                                        }`;
                                  return (
                                    <div
                                      key={idx}
                                      draggable
                                      onDragStart={(e) => {
                                        _drag = {
                                          dragType: "assign",
                                          dateKey,
                                          dienstIdx: idx,
                                        };
                                        window._rmDragActive = true;
                                        e.dataTransfer.effectAllowed = "copy";
                                        e.stopPropagation();
                                      }}
                                      onDragEnd={() => {
                                        window._rmDragActive = false;
                                      }}
                                      title={`${label}${
                                        dv.title ? ` – ${dv.title}` : ""
                                      } · ${open} plek${
                                        open !== 1 ? "ken" : ""
                                      } open`}
                                      style={{
                                        fontSize: "8px",
                                        fontWeight: 700,
                                        padding: "1px 3px",
                                        marginBottom: "1px",
                                        borderRadius: "3px",
                                        backgroundColor: tc.bg,
                                        borderLeft: `2px solid ${tc.border}`,
                                        color: tc.text,
                                        cursor: "grab",
                                        userSelect: "none",
                                        whiteSpace: "nowrap",
                                        overflow: "hidden",
                                        display: "flex",
                                        alignItems: "center",
                                        gap: "2px",
                                      }}
                                    >
                                      <span style={{ flexShrink: 0 }}>
                                        {label}
                                      </span>
                                      <span
                                        style={{
                                          marginLeft: "auto",
                                          backgroundColor: tc.border + "60",
                                          borderRadius: "2px",
                                          padding: "0 2px",
                                          fontSize: "7px",
                                          flexShrink: 0,
                                        }}
                                      >
                                        {(dv.assigned || []).length}/{dv.slots}
                                      </span>
                                    </div>
                                  );
                                })}
                              </td>
                            );
                          })}
                          <td
                            style={{
                              borderBottom: `2px solid ${C.Sunset}40`,
                              borderTop: `1px solid ${C.Sunset}30`,
                              borderLeft: `2px solid ${C.BorderLight}`,
                              backgroundColor: "#fffbeb",
                              position: "sticky",
                              right: 0,
                              zIndex: 1,
                            }}
                          />
                        </tr>

                        {/* ── MEDEWERKERS ── */}
                        {allStaffIncFM.map((s, si) => {
                          const rowBg = si % 2 === 0 ? "white" : "#f8fafc";
                          const h = personMonthHours(s.name);
                          const tgt2 = contractTarget(s.name);
                          const over = tgt2 && h > tgt2 * 1.05;
                          const under = tgt2 && h > 0 && h < tgt2 * 0.8;
                          const hoursColor = over
                            ? C.Sunset
                            : under
                            ? "#f59e0b"
                            : t.primary;
                          return (
                            <tr key={s.name} style={{ backgroundColor: rowBg }}>
                              <td
                                style={{
                                  padding: "4px 8px",
                                  fontSize: "11px",
                                  fontWeight: 600,
                                  color: C.TextPrimary,
                                  borderBottom: `1px solid ${C.BorderLight}`,
                                  borderRight: `1px solid ${C.BorderLight}`,
                                  position: "sticky",
                                  left: 0,
                                  zIndex: 1,
                                  backgroundColor: rowBg,
                                  whiteSpace: "nowrap",
                                  overflow: "hidden",
                                  textOverflow: "ellipsis",
                                }}
                              >
                                {s.name.split(" ")[0]}
                              </td>
                              {days.map((d) => {
                                const dateKey = dk(d);
                                const date = new Date(
                                  viewYear,
                                  viewMonth - 1,
                                  d
                                );
                                const dow = date.getDay();
                                const isWeekend = dow === 0 || dow === 6;
                                const isToday =
                                  dateKey ===
                                  new Date().toISOString().slice(0, 10);
                                const dayDiensten = allDiensten[dateKey] || [];
                                const myDiensten = dayDiensten
                                  .map((dv, idx) => ({ ...dv, _idx: idx }))
                                  .filter((dv) =>
                                    (dv.assigned || []).includes(s.name)
                                  );
                                const myChar = allChars.find(
                                  (c) =>
                                    c.date === dateKey && c.actor === s.name
                                );
                                const isEditingChar =
                                  charEdit &&
                                  charEdit.dateKey === dateKey &&
                                  charEdit.personName === s.name;
                                const avail = allAvail[s.name]?.[dateKey];
                                const cellBg = isToday
                                  ? t.primary + "08"
                                  : avail
                                  ? avail.available
                                    ? "#f0fdf4"
                                    : "#fef2f2"
                                  : isWeekend
                                  ? "#fffbf5"
                                  : "transparent";
                                // Activiteiten op deze dag
                                const dayActs = allActs.filter(
                                  (a) => a.date === dateKey
                                );
                                const myActs = dayActs.filter((a) =>
                                  (a.staff || []).includes(s.name)
                                );

                                return (
                                  <td
                                    key={d}
                                    onClick={() => {
                                      setSelDate(dateKey);
                                      if (isEditingChar) setCharEdit(null);
                                    }}
                                    onDragOver={(e) => {
                                      e.preventDefault();
                                      e.currentTarget.style.outline = `2px solid ${t.primary}`;
                                      e.currentTarget.style.outlineOffset =
                                        "-2px";
                                    }}
                                    onDragLeave={(e) => {
                                      e.currentTarget.style.outline = "";
                                    }}
                                    onDrop={(e) => {
                                      e.preventDefault();
                                      e.currentTarget.style.outline = "";
                                      doMove(dateKey, s.name);
                                    }}
                                    style={{
                                      padding: "2px",
                                      verticalAlign: "top",
                                      borderBottom: `1px solid ${C.BorderLight}`,
                                      borderLeft: `1px solid ${C.BorderLight}`,
                                      backgroundColor: cellBg,
                                      cursor: "pointer",
                                      position: "relative",
                                    }}
                                  >
                                    {/* Beschikbaarheidsindicator (lege cel) — zelfde
                                        kleurenschema als de rest van de app */}
                                    {avail &&
                                      myDiensten.length === 0 &&
                                      !myChar &&
                                      myActs.length === 0 && (
                                        <div
                                          style={{
                                            fontSize: "7px",
                                            fontWeight: 700,
                                            color:
                                              AVAIL_COLORS[
                                                avail.available
                                                  ? avail.start
                                                    ? "partial"
                                                    : "full"
                                                  : "off"
                                              ].text,
                                            padding: "1px 2px",
                                          }}
                                        >
                                          {avail.available
                                            ? avail.start
                                              ? avail.start
                                              : "✓"
                                            : "✕"}
                                        </div>
                                      )}

                                    {/* Karakter picker */}
                                    {isEditingChar ? (
                                      <div
                                        onClick={(e) => e.stopPropagation()}
                                        style={{
                                          position: "absolute",
                                          top: 0,
                                          left: 0,
                                          zIndex: 10,
                                          backgroundColor: "white",
                                          border: `1.5px solid ${t.primary}`,
                                          borderRadius: "6px",
                                          padding: "3px",
                                          display: "flex",
                                          flexDirection: "column",
                                          gap: "2px",
                                          minWidth: "72px",
                                          boxShadow:
                                            "0 4px 12px rgba(0,0,0,.15)",
                                        }}
                                      >
                                        <div
                                          style={{
                                            fontSize: "8px",
                                            fontWeight: 700,
                                            color: C.TextMuted,
                                            marginBottom: "1px",
                                          }}
                                        >
                                          Karakter
                                        </div>
                                        {myChar && (
                                          <button
                                            onClick={() =>
                                              assignChar(dateKey, s.name, null)
                                            }
                                            style={{
                                              fontSize: "8px",
                                              padding: "2px 4px",
                                              borderRadius: "3px",
                                              background: "#fee2e2",
                                              color: "#991b1b",
                                              fontWeight: 700,
                                              border: "none",
                                              cursor: "pointer",
                                              textAlign: "left",
                                            }}
                                          >
                                            ✕ Verwijder
                                          </button>
                                        )}
                                        {ROLES.map((role) => (
                                          <button
                                            key={role}
                                            onClick={() =>
                                              assignChar(dateKey, s.name, role)
                                            }
                                            style={{
                                              fontSize: "8px",
                                              padding: "2px 4px",
                                              borderRadius: "3px",
                                              background: charBg(role),
                                              color: charTx(role),
                                              fontWeight: 800,
                                              border:
                                                myChar?.role === role
                                                  ? "1.5px solid #000"
                                                  : "none",
                                              cursor: "pointer",
                                              textAlign: "left",
                                            }}
                                          >
                                            {role}
                                          </button>
                                        ))}
                                      </div>
                                    ) : (
                                      /* Normale cel: karakter + activiteiten badges */
                                      <div
                                        onClick={(e) => {
                                          e.stopPropagation();
                                          setCharEdit({
                                            dateKey,
                                            personName: s.name,
                                          });
                                        }}
                                        title="Karakter / activiteiten koppelen"
                                        style={{
                                          fontSize: "7px",
                                          fontWeight: 800,
                                          padding: "1px 3px",
                                          borderRadius: "3px",
                                          marginBottom: "1px",
                                          backgroundColor: myChar
                                            ? charBg(myChar.role)
                                            : "transparent",
                                          color: myChar
                                            ? charTx(myChar.role)
                                            : C.TextMuted,
                                          whiteSpace: "nowrap",
                                          overflow: "hidden",
                                          minHeight: "11px",
                                          cursor: "pointer",
                                          border: myChar
                                            ? "none"
                                            : `1px dashed ${C.BorderLight}`,
                                        }}
                                      >
                                        {myChar ? myChar.role : "＋"}
                                      </div>
                                    )}

                                    {/* Dienst blokjes */}
                                    {myDiensten.map((dienst) => {
                                      const tc =
                                        typeColors[dienst.type] ||
                                        typeColors.overig;
                                      return (
                                        <div
                                          key={dienst._idx}
                                          draggable
                                          onDragStart={(e) => {
                                            _drag = {
                                              dragType: "move",
                                              fromDateKey: dateKey,
                                              dienstIdx: dienst._idx,
                                              personName: s.name,
                                            };
                                            window._rmDragActive = true;
                                            e.dataTransfer.effectAllowed =
                                              "move";
                                            e.stopPropagation();
                                          }}
                                          onDragEnd={() => {
                                            window._rmDragActive = false;
                                          }}
                                          onClick={(e) => {
                                            e.stopPropagation();
                                            setSelDate(dateKey);
                                          }}
                                          style={{
                                            fontSize: "8px",
                                            fontWeight: 700,
                                            lineHeight: 1.3,
                                            padding: "1px 3px",
                                            borderRadius: "3px",
                                            marginBottom: "1px",
                                            backgroundColor: tc.bg,
                                            borderLeft: `2px solid ${tc.border}`,
                                            color: tc.text,
                                            whiteSpace: "nowrap",
                                            overflow: "hidden",
                                            cursor: "grab",
                                            userSelect: "none",
                                          }}
                                        >
                                          <div>
                                            {RM_TYPES[dienst.type]
                                              ?.fixedHours !== undefined
                                              ? RM_TYPES[dienst.type]?.label ||
                                                dienst.type
                                              : `${dienst.start || ""}${
                                                  dienst.end
                                                    ? `–${dienst.end}`
                                                    : ""
                                                }`}
                                          </div>
                                          {!RM_TYPES[dienst.type]?.fixedHours &&
                                            dienst.title && (
                                              <div style={{ opacity: 0.8 }}>
                                                {dienst.title.slice(0, 9)}
                                              </div>
                                            )}
                                        </div>
                                      );
                                    })}
                                  </td>
                                );
                              })}
                              <td
                                style={{
                                  padding: "4px 6px",
                                  textAlign: "center",
                                  verticalAlign: "middle",
                                  borderBottom: `1px solid ${C.BorderLight}`,
                                  borderLeft: `2px solid ${C.BorderLight}`,
                                  position: "sticky",
                                  right: 0,
                                  backgroundColor: rowBg,
                                  zIndex: 1,
                                }}
                              >
                                <div
                                  style={{
                                    fontSize: "10px",
                                    fontWeight: 800,
                                    color: hoursColor,
                                  }}
                                >
                                  {formatHours(h)}
                                </div>
                                {tgt2 && (
                                  <div
                                    style={{
                                      fontSize: "8px",
                                      color: C.TextMuted,
                                    }}
                                  >
                                    /{tgt2}u
                                  </div>
                                )}
                              </td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>
                </div>
              );
            })()}

          {/* Legenda */}
          <div className="px-4 pt-2 pb-1 flex items-center gap-4">
            {[
              { dot: STATUS.planned.dot, label: "Ingepland" },
              { dot: STATUS.partial.dot, label: "Deels" },
              { dot: STATUS.full.dot, label: "Vol" },
            ].map(({ dot, label }) => (
              <div
                key={label}
                className="flex items-center gap-1 text-[11px]"
                style={{ color: C.TextMuted }}
              >
                <div
                  className="w-2 h-2 rounded-full"
                  style={{ backgroundColor: dot }}
                />
                {label}
              </div>
            ))}
            {!selDate && (
              <span
                className="text-[11px] ml-auto"
                style={{ color: C.TextMuted }}
              >
                Klik een dag om te plannen
              </span>
            )}
          </div>

          {/* Uren overzicht */}
          {calView !== "rooster" && (
            <div
              className="mx-4 mt-3 bg-white rounded-2xl border overflow-hidden"
              style={{ borderColor: C.BorderLight }}
            >
              <div
                className="px-4 py-2 border-b flex items-center justify-between"
                style={{ borderColor: C.BorderLight, backgroundColor: C.Bg }}
              >
                <p
                  className="text-[11px] font-semibold uppercase tracking-wide"
                  style={{ color: C.TextMuted }}
                >
                  Ingeplande uren — {dutchMonths[viewMonth - 1]}
                </p>
              </div>
              <div className="divide-y" style={{ borderColor: C.BorderLight }}>
                {allStaffIncFM.map((s) => {
                  const hours = personMonthHours(s.name);
                  const target = contractTarget(s.name);
                  const pct = target
                    ? Math.min(100, Math.round((hours / target) * 100))
                    : null;
                  const over = target && hours > target * 1.05;
                  const under = target && hours < target * 0.8;
                  const barColor = !target
                    ? t.primary
                    : over
                    ? C.Honey
                    : under && hours > 0
                    ? C.Sunset
                    : hours === 0
                    ? C.BorderLight
                    : C.Grass;
                  return (
                    <div
                      key={s.name}
                      className="flex items-center gap-3 px-4 py-2.5"
                    >
                      <ProfileAvatar
                        name={s.name}
                        staffList={appData.staffList || []}
                        size={26}
                        color={t.primary}
                      />
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center justify-between mb-1">
                          <span className="text-sm font-medium">{s.name}</span>
                          <span
                            className="text-xs font-semibold"
                            style={{
                              color: hours > 0 ? barColor : C.TextMuted,
                            }}
                          >
                            {hours > 0
                              ? hours.toFixed(1).replace(".0", "") + "u"
                              : "–"}
                            {target ? (
                              <span className="font-normal text-gray-400">
                                /{target}u
                              </span>
                            ) : (
                              ""
                            )}
                          </span>
                        </div>
                        {target ? (
                          <div
                            className="w-full h-1.5 rounded-full overflow-hidden"
                            style={{ backgroundColor: C.BorderLight }}
                          >
                            <div
                              className="h-full rounded-full"
                              style={{
                                width: pct + "%",
                                backgroundColor: barColor,
                              }}
                            />
                          </div>
                        ) : (
                          <p
                            className="text-[9px]"
                            style={{ color: C.TextMuted }}
                          >
                            {hours > 0
                              ? `${formatHours(hours)} ingepland`
                              : "Nog niet ingepland"}
                          </p>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </div>
        {/* einde linker kolom */}

        {/* ── RECHTER KOLOM (desktop inline panel) ── */}
        {selDate && (
          <div
            className="hidden sm:flex sm:flex-col sm:w-[380px] sm:flex-shrink-0 sm:ml-4 sm:mr-4 sm:rounded-2xl sm:overflow-hidden sm:border-2 sm:self-start sm:sticky sm:top-4"
            style={{ borderColor: t.secondary, height: "calc(100vh - 120px)" }}
          >
            <DagPanel inModal={false} {...dagPanelProps} />
          </div>
        )}
        {/* ── Placeholder als geen dag geselecteerd op desktop ── */}
        {!selDate && (
          <div
            className="hidden sm:flex sm:w-[380px] sm:flex-shrink-0 sm:ml-4 sm:mr-4 sm:rounded-2xl sm:border-2 sm:border-dashed sm:items-center sm:justify-center sm:flex-col sm:gap-3 sm:py-16"
            style={{ borderColor: C.Border }}
          >
            <CalendarDays
              size={36}
              style={{ color: C.TextMuted, opacity: 0.3 }}
            />
            <p
              className="text-sm font-medium text-center"
              style={{ color: C.TextMuted }}
            >
              Selecteer een dag in de kalender
            </p>
          </div>
        )}
      </div>
      {/* einde 2-kolom */}

      {/* ── MOBILE: bottom sheet modal ── */}
      {selDate && (
        <div
          className="sm:hidden fixed inset-0 z-[75] flex items-end"
          style={{
            backgroundColor: "rgba(0,0,0,0.45)",
            backdropFilter: "blur(3px)",
          }}
          onClick={(e) => {
            if (e.target === e.currentTarget) {
              setSelDate(null);
              setPanel("overview");
              setExpandedId(null);
              setEditId(null);
            }
          }}
        >
          <div
            className="w-full bg-white rounded-t-3xl shadow-2xl flex flex-col"
            style={{ maxHeight: "88vh" }}
          >
            <DagPanel inModal={true} {...dagPanelProps} />
          </div>
        </div>
      )}
    </div>
  );
};

// --- ROOSTER VIEW (combineert Mijn Rooster + Teamrooster) ---

// ─────────────────────────────────────────────────────────────────────────────
// 📅 ROOSTER → AGENDA EXPORT (iCal)
// ─────────────────────────────────────────────────────────────────────────────
const RoosterExportModal = ({
  appData,
  loggedInUserName,
  theme,
  userRole,
  onClose,
}) => {
  const isFM = userRole === "fm" || userRole === "admin";

  const [scope, setScope] = useState("mine"); // "mine" | "team" | person name
  const [period, setPeriod] = useState("month"); // "month" | "3months" | "pick" | "all"
  const [done, setDone] = useState(false);

  const now = new Date();
  const [pickYear, setPickYear] = useState(now.getFullYear());
  const [pickMonth, setPickMonth] = useState(now.getMonth() + 1); // 1-12

  const staffList = (appData.staffList || [])
    .filter((s) => !s.inactive)
    .map((s) => s.name)
    .sort();

  // Beschikbare maanden uit het rooster
  const availableMonths = (() => {
    const keys = new Set();
    Object.keys(appData.workSchedule || {}).forEach((dk) =>
      keys.add(dk.slice(0, 7))
    );
    return Array.from(keys).sort();
  })();

  // Bepaal welke shifts worden meegenomen
  const getShifts = () => {
    let fromDate, toDate;
    if (period === "pick") {
      fromDate = new Date(pickYear, pickMonth - 1, 1);
      toDate = new Date(pickYear, pickMonth, 0);
    } else {
      fromDate = new Date(now.getFullYear(), now.getMonth(), 1);
      if (period === "month")
        toDate = new Date(now.getFullYear(), now.getMonth() + 1, 0);
      else toDate = new Date(2099, 0, 1);
    }

    const fromKey = toIsoDate(fromDate);
    const toKey = toIsoDate(toDate);

    const targetUser =
      scope === "mine" ? loggedInUserName : scope === "team" ? null : scope;

    const result = [];
    Object.entries(appData.workSchedule || {}).forEach(
      ([dateKey, dayShifts]) => {
        if (dateKey < fromKey || dateKey > toKey) return;
        dayShifts.forEach((shift) => {
          if (targetUser && shift.matchedUser !== targetUser) return;
          if (!targetUser && !shift.matchedUser) return;
          result.push({ dateKey, ...shift });
        });
      }
    );
    return result.sort((a, b) => a.dateKey.localeCompare(b.dateKey));
  };

  const generateIcs = () => {
    const shifts = getShifts();
    if (shifts.length === 0) return null;

    const pad = (n) => String(n).padStart(2, "0");
    const icsDate = (dateKey, time) => {
      const [y, m, d] = dateKey.split("-");
      const [h, min] = time.split(":");
      return `${y}${m}${d}T${pad(h)}${pad(min)}00`;
    };
    const stamp = (() => {
      const n = new Date();
      return `${n.getFullYear()}${pad(n.getMonth() + 1)}${pad(
        n.getDate()
      )}T${pad(n.getHours())}${pad(n.getMinutes())}${pad(n.getSeconds())}Z`;
    })();

    const escape = (s) =>
      (s || "").replace(/[\\,;]/g, (c) => "\\" + c).replace(/\n/g, "\\n");

    const events = shifts.map((s, i) => {
      const title =
        scope === "team"
          ? `${getFirstName(s.matchedUser)} — ${
              s.title || s.location || "Dienst"
            }`
          : s.title || s.location || "Dienst";

      const desc = [
        s.title && s.location ? s.location : "",
        s.breaks?.length
          ? `Pauze: ${s.breaks.map((b) => `${b.start}–${b.end}`).join(", ")}`
          : "",
        `Duur: ${formatHours(dienstHours(s))}`,
      ]
        .filter(Boolean)
        .join("\\n");

      return [
        "BEGIN:VEVENT",
        `UID:centerparcs-shift-${s.dateKey}-${i}@cp-app`,
        `DTSTAMP:${stamp}`,
        `DTSTART:${icsDate(s.dateKey, s.start)}`,
        `DTEND:${icsDate(s.dateKey, s.end)}`,
        `SUMMARY:${escape(title)}`,
        desc ? `DESCRIPTION:${escape(desc)}` : "",
        "LOCATION:Center Parcs Limburgse Peel, Peelheideweg 25, 5966 PJ America",
        "END:VEVENT",
      ]
        .filter(Boolean)
        .join("\r\n");
    });

    return [
      "BEGIN:VCALENDAR",
      "VERSION:2.0",
      "PRODID:-//Center Parcs App//Rooster//NL",
      "CALSCALE:GREGORIAN",
      "METHOD:PUBLISH",
      `X-WR-CALNAME:${
        scope === "team"
          ? "Teamrooster"
          : `Rooster ${getFirstName(
              scope === "mine" ? loggedInUserName : scope
            )}`
      }`,
      "X-WR-TIMEZONE:Europe/Amsterdam",
      ...events,
      "END:VCALENDAR",
    ].join("\r\n");
  };

  const handleDownload = () => {
    const ics = generateIcs();
    if (!ics) {
      return;
    }
    const blob = new Blob([ics], { type: "text/calendar;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    const name =
      scope === "mine"
        ? getFirstName(loggedInUserName)
        : scope === "team"
        ? "team"
        : getFirstName(scope);
    const per =
      period === "month"
        ? "maand"
        : period === "pick"
        ? `${String(pickMonth).padStart(2, "0")}-${pickYear}`
        : "alles";
    a.download = `rooster-${name}-${per}.ics`;
    a.click();
    URL.revokeObjectURL(url);
    setDone(true);
  };

  const shiftCount = getShifts().length;

  return (
    <div
      className="fixed inset-0 bg-black bg-opacity-60 flex items-end justify-center z-50 p-0"
      onClick={onClose}
    >
      <div
        className="w-full max-w-lg rounded-t-3xl overflow-hidden"
        onClick={(e) => e.stopPropagation()}
        style={{ backgroundColor: "white" }}
      >
        {/* Header */}
        <div
          className="px-5 pt-5 pb-4"
          style={{ backgroundColor: theme.primary }}
        >
          <div className="flex items-center justify-between mb-1">
            <div className="flex items-center gap-2">
              <Calendar size={18} style={{ color: theme.secondary }} />
              <span
                className="font-black text-base"
                style={{ color: theme.secondary }}
              >
                Exporteer naar agenda
              </span>
            </div>
            <button
              onClick={onClose}
              className="p-1.5 rounded-xl"
              style={{
                backgroundColor: `${theme.secondary}20`,
                color: theme.secondary,
              }}
            >
              <X size={16} />
            </button>
          </div>
          <p className="text-xs opacity-70" style={{ color: theme.secondary }}>
            Download als .ics — werkt op iPhone, Android en elke agenda-app
          </p>
        </div>

        <div className="px-5 py-5 space-y-5">
          {/* Wiens rooster */}
          {isFM && (
            <div>
              <p
                className="text-xs font-semibold mb-2"
                style={{ color: theme.primary }}
              >
                Wiens rooster?
              </p>
              <div className="flex flex-wrap gap-1.5">
                <button
                  onClick={() => setScope("mine")}
                  className="px-3 py-1.5 rounded-xl text-xs font-semibold transition-all"
                  style={{
                    backgroundColor:
                      scope === "mine" ? theme.primary : `${theme.primary}10`,
                    color: scope === "mine" ? "white" : theme.primary,
                  }}
                >
                  Mijn rooster
                </button>
                <button
                  onClick={() => setScope("team")}
                  className="px-3 py-1.5 rounded-xl text-xs font-semibold transition-all"
                  style={{
                    backgroundColor:
                      scope === "team" ? theme.primary : `${theme.primary}10`,
                    color: scope === "team" ? "white" : theme.primary,
                  }}
                >
                  Heel team
                </button>
                {staffList
                  .filter((n) => n !== loggedInUserName)
                  .map((name) => (
                    <button
                      key={name}
                      onClick={() => setScope(name)}
                      className="px-3 py-1.5 rounded-xl text-xs font-semibold transition-all"
                      style={{
                        backgroundColor:
                          scope === name ? theme.primary : `${theme.primary}10`,
                        color: scope === name ? "white" : theme.primary,
                      }}
                    >
                      {getFirstName(name)}
                    </button>
                  ))}
              </div>
            </div>
          )}

          {/* Periode */}
          <div>
            <p
              className="text-xs font-semibold mb-2"
              style={{ color: theme.primary }}
            >
              Periode
            </p>
            <div className="flex flex-wrap gap-1.5 mb-2">
              {[
                ["month", "Deze maand"],
                ["pick", "Kies maand"],
                ["all", "Alles"],
              ].map(([val, label]) => (
                <button
                  key={val}
                  onClick={() => setPeriod(val)}
                  className="px-3 py-1.5 rounded-xl text-xs font-semibold transition-all"
                  style={{
                    backgroundColor:
                      period === val ? theme.primary : `${theme.primary}10`,
                    color: period === val ? "white" : theme.primary,
                  }}
                >
                  {label}
                </button>
              ))}
            </div>
            {period === "pick" && (
              <div className="flex gap-2 mt-1">
                <StyledSelect
                  value={pickMonth}
                  onChange={(e) => setPickMonth(Number(e.target.value))}
                  className="flex-1 rounded-xl px-3 py-2 text-sm font-bold border outline-none"
                  style={{
                    borderColor: `${theme.primary}40`,
                    color: theme.primary,
                  }}
                >
                  {[
                    "januari",
                    "februari",
                    "maart",
                    "april",
                    "mei",
                    "juni",
                    "juli",
                    "augustus",
                    "september",
                    "oktober",
                    "november",
                    "december",
                  ].map((m, i) => (
                    <option key={i} value={i + 1}>
                      {m}
                    </option>
                  ))}
                </StyledSelect>
                <StyledSelect
                  value={pickYear}
                  onChange={(e) => setPickYear(Number(e.target.value))}
                  className="w-24 rounded-xl px-3 py-2 text-sm font-bold border outline-none"
                  style={{
                    borderColor: `${theme.primary}40`,
                    color: theme.primary,
                  }}
                >
                  {[...new Set(availableMonths.map((m) => m.slice(0, 4)))]
                    .sort()
                    .map((y) => (
                      <option key={y} value={Number(y)}>
                        {y}
                      </option>
                    ))}
                </StyledSelect>
              </div>
            )}
          </div>

          {/* Preview */}
          <div
            className="rounded-2xl px-4 py-3 flex items-center gap-3"
            style={{
              backgroundColor: `${theme.primary}08`,
              border: `1.5px solid ${theme.primary}20`,
            }}
          >
            <Calendar
              size={20}
              style={{ color: theme.primary, flexShrink: 0 }}
            />
            <div>
              <p className="font-bold text-sm" style={{ color: theme.primary }}>
                {shiftCount} {shiftCount === 1 ? "dienst" : "diensten"} gevonden
              </p>
              <p className="text-xs" style={{ color: C.TextMuted }}>
                {scope === "mine"
                  ? `Jouw rooster`
                  : scope === "team"
                  ? "Alle medewerkers"
                  : `Rooster van ${getFirstName(scope)}`}
                {" · "}
                {period === "month"
                  ? "deze maand"
                  : period === "pick"
                  ? `${
                      [
                        "",
                        "jan",
                        "feb",
                        "mrt",
                        "apr",
                        "mei",
                        "jun",
                        "jul",
                        "aug",
                        "sep",
                        "okt",
                        "nov",
                        "dec",
                      ][pickMonth]
                    } ${pickYear}`
                  : "volledig"}
              </p>
            </div>
          </div>

          {/* Instructie */}
          <div
            className="rounded-2xl px-4 py-3 space-y-1.5"
            style={{ backgroundColor: `${C.Sky}18` }}
          >
            <p
              className="text-xs font-semibold"
              style={{ color: C.TextPrimary }}
            >
              Hoe zet je dit in je telefoon?
            </p>
            {[
              "Druk op 'Download .ics bestand'",
              "Zoek het bestand in je downloads",
              "Tik erop — je agenda-app opent automatisch",
              "Bevestig het importeren",
            ].map((step, i) => (
              <div key={i} className="flex items-start gap-2">
                <span
                  className="w-4 h-4 rounded-full flex-shrink-0 flex items-center justify-center text-[11px] font-black mt-0.5"
                  style={{ backgroundColor: theme.primary, color: "white" }}
                >
                  {i + 1}
                </span>
                <span className="text-xs" style={{ color: C.TextSecondary }}>
                  {step}
                </span>
              </div>
            ))}
          </div>

          {/* Download knop */}
          {done ? (
            <div
              className="py-3 rounded-2xl text-center font-bold text-sm flex items-center justify-center gap-2"
              style={{ backgroundColor: "#dcfce7", color: "#16a34a" }}
            >
              <Check size={18} /> Bestand gedownload! Zoek het in je downloads.
            </div>
          ) : (
            <button
              onClick={handleDownload}
              disabled={shiftCount === 0}
              className="w-full py-3.5 rounded-2xl font-black text-sm flex items-center justify-center gap-2 transition-all"
              style={{
                backgroundColor: shiftCount > 0 ? theme.primary : C.BorderLight,
                color: shiftCount > 0 ? "white" : C.TextMuted,
              }}
            >
              <Download size={18} />
              Download .ics bestand
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

// ─────────────────────────────────────────────────────────────────────────────
// 🏖️ VAKANTIEPLANNER
// ─────────────────────────────────────────────────────────────────────────────
const VakantieplannerView = ({
  appData,
  updateData,
  theme,
  userRole,
  loggedInUserName,
  showAlert,
}) => {
  const isFM = userRole === "fm";
  const today = new Date();
  const [viewYear, setViewYear] = useState(today.getFullYear());
  const [viewMonth, setViewMonth] = useState(today.getMonth()); // 0-indexed
  const [hoverDay, setHoverDay] = useState(null);
  const [selecting, setSelecting] = useState(null); // { name, startDay }

  const rawStaff = (appData.staffList || []).filter((s) => !s.inactive);
  const hasMaik = rawStaff.some((s) => s.name === "Maik");
  const staffWithMaik = hasMaik
    ? rawStaff
    : [...rawStaff, { name: "Maik", role: "fm" }];
  const staffList = staffWithMaik.map((s) => s.name).sort();
  const vacations = appData.vakantieplannen || {};

  const daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();
  const monthKey = `${viewYear}-${String(viewMonth + 1).padStart(2, "0")}`;
  const totalStaff = staffList.length;

  const monthNames = [
    "Januari",
    "Februari",
    "Maart",
    "April",
    "Mei",
    "Juni",
    "Juli",
    "Augustus",
    "September",
    "Oktober",
    "November",
    "December",
  ];
  const dayNames = ["Ma", "Di", "Wo", "Do", "Vr", "Za", "Zo"];
  const firstDow = (new Date(viewYear, viewMonth, 1).getDay() + 6) % 7;

  const isOnVacation = (name, day) => {
    const dateStr = `${monthKey}-${String(day).padStart(2, "0")}`;
    return (vacations[name] || []).some(
      (v) => v.from <= dateStr && v.to >= dateStr
    );
  };

  const availableCount = (day) =>
    staffList.filter((n) => !isOnVacation(n, day)).length;

  const availColor = (count) => {
    const pct = count / Math.max(totalStaff, 1);
    if (pct >= 0.75)
      return { bg: "#dcfce7", text: "#15803d", border: "#86efac" };
    if (pct >= 0.5)
      return { bg: "#fef9c3", text: "#92400e", border: "#fde68a" };
    if (pct >= 0.25)
      return { bg: "#ffedd5", text: "#9a3412", border: "#fdba74" };
    return { bg: "#fee2e2", text: "#991b1b", border: "#fca5a5" };
  };

  const saveVacation = async (name, from, to) => {
    const current = (vacations[name] || []).filter(
      (v) => !(v.from <= to && v.to >= from)
    );
    const updated = [...current, { from, to }].sort((a, b) =>
      a.from.localeCompare(b.from)
    );
    await updateData({ vakantieplannen: { ...vacations, [name]: updated } });
  };

  const removeVacation = async (name, from) => {
    const updated = (vacations[name] || []).filter((v) => v.from !== from);
    await updateData({ vakantieplannen: { ...vacations, [name]: updated } });
  };

  const handleDayClick = (name, day) => {
    if (!isFM) return;
    const dateStr = `${monthKey}-${String(day).padStart(2, "0")}`;
    if (isOnVacation(name, day)) {
      const block = (vacations[name] || []).find(
        (v) => v.from <= dateStr && v.to >= dateStr
      );
      if (block) removeVacation(name, block.from);
      return;
    }
    if (!selecting || selecting.name !== name) {
      setSelecting({ name, startDay: day });
    } else {
      const d1 = Math.min(selecting.startDay, day);
      const d2 = Math.max(selecting.startDay, day);
      saveVacation(
        name,
        `${monthKey}-${String(d1).padStart(2, "0")}`,
        `${monthKey}-${String(d2).padStart(2, "0")}`
      );
      setSelecting(null);
    }
  };

  const isInSelection = (name, day) => {
    if (!selecting || selecting.name !== name) return false;
    const d1 = Math.min(selecting.startDay, hoverDay || selecting.startDay);
    const d2 = Math.max(selecting.startDay, hoverDay || selecting.startDay);
    return day >= d1 && day <= d2;
  };

  const colTemplate = `130px repeat(${daysInMonth}, 1fr)`;

  return (
    <div className="flex flex-col h-full overflow-y-auto pb-24">
      {/* ── Header ── */}
      <div className="flex-shrink-0 px-4 pt-4 pb-2 flex items-center justify-between gap-3 flex-wrap">
        <div className="flex items-center gap-1">
          <button
            onClick={() => {
              const d = new Date(viewYear, viewMonth - 1, 1);
              setViewYear(d.getFullYear());
              setViewMonth(d.getMonth());
            }}
            className="p-2 rounded-xl hover:bg-gray-100 transition-colors"
          >
            <ChevronLeft size={18} />
          </button>
          <h2 className="font-black text-xl min-w-[170px] text-center">
            {monthNames[viewMonth]} {viewYear}
          </h2>
          <button
            onClick={() => {
              const d = new Date(viewYear, viewMonth + 1, 1);
              setViewYear(d.getFullYear());
              setViewMonth(d.getMonth());
            }}
            className="p-2 rounded-xl hover:bg-gray-100 transition-colors"
          >
            <ChevronRight size={18} />
          </button>
        </div>
        {isFM && (
          <div className="text-xs text-gray-500 bg-blue-50 border border-blue-200 rounded-lg px-3 py-1.5 flex items-center gap-1.5">
            <Info size={12} className="text-blue-500" />
            Klik = start · 2e klik = einde · klik op 🏖️ = verwijderen
          </div>
        )}
      </div>

      {/* ── Grid: altijd volledig zichtbaar ── */}
      <div className="px-2">
        {/* Dag-koprij */}
        <div className="grid mb-1" style={{ gridTemplateColumns: colTemplate }}>
          <div />
          {Array.from({ length: daysInMonth }, (_, i) => {
            const day = i + 1;
            const dow = (firstDow + i) % 7;
            const isWeekend = dow >= 5;
            const dateStr = `${monthKey}-${String(day).padStart(2, "0")}`;
            const isToday = new Date().toISOString().slice(0, 10) === dateStr;
            return (
              <div key={day} className="flex flex-col items-center">
                <div
                  className="text-[8px] font-bold leading-none"
                  style={{ color: isWeekend ? "#f97316" : "#9ca3af" }}
                >
                  {dayNames[dow]}
                </div>
                <div
                  className="text-[11px] font-black w-full text-center py-0.5 rounded"
                  style={{
                    backgroundColor: isToday
                      ? theme.primary
                      : isWeekend
                      ? "#f3f4f6"
                      : "transparent",
                    color: isToday ? "#fff" : isWeekend ? "#6b7280" : "#374151",
                  }}
                >
                  {day}
                </div>
              </div>
            );
          })}
        </div>

        {/* ── BESCHIKBAARHEIDSRIJ ── */}
        <div
          className="grid mb-3 rounded-xl overflow-hidden border"
          style={{
            gridTemplateColumns: colTemplate,
            borderColor: theme.primary + "40",
          }}
        >
          <div
            className="flex items-center gap-1.5 px-2 py-2"
            style={{ backgroundColor: theme.primary + "15" }}
          >
            <Users size={12} style={{ color: theme.primary }} />
            <span
              className="text-[11px] font-black"
              style={{ color: theme.primary }}
            >
              Beschikbaar
            </span>
          </div>
          {Array.from({ length: daysInMonth }, (_, i) => {
            const day = i + 1;
            const ac = availableCount(day);
            const col = availColor(ac);
            const isHover = hoverDay === day;
            return (
              <div
                key={day}
                className="flex flex-col items-center justify-center py-1.5 transition-all"
                style={{
                  backgroundColor: isHover ? col.bg + "dd" : col.bg,
                  borderLeft: `1px solid ${col.border}`,
                }}
                title={`${ac} van ${totalStaff} beschikbaar`}
              >
                <span
                  className="text-[12px] font-black leading-none"
                  style={{ color: col.text }}
                >
                  {ac}
                </span>
                <span
                  className="text-[8px] font-medium"
                  style={{ color: col.text + "99" }}
                >
                  /{totalStaff}
                </span>
              </div>
            );
          })}
        </div>

        {/* ── Persoon-rijen ── */}
        <div className="space-y-px">
          {staffList.map((name) => {
            const totalDays = (vacations[name] || []).reduce((acc, v) => {
              return (
                acc +
                Math.round((new Date(v.to) - new Date(v.from)) / 86400000) +
                1
              );
            }, 0);
            const isSelecting = selecting?.name === name;

            return (
              <div
                key={name}
                className="grid rounded-lg overflow-hidden"
                style={{ gridTemplateColumns: colTemplate }}
              >
                {/* Naam-kolom */}
                <div
                  className="flex items-center gap-1.5 px-2 py-1"
                  style={{
                    backgroundColor: isSelecting ? "#dbeafe" : "#f9fafb",
                  }}
                >
                  <ProfileAvatar
                    name={name}
                    staffList={appData.staffList}
                    size={20}
                    color={theme.primary}
                  />
                  <span className="text-[11px] font-semibold truncate flex-1">
                    {getFirstName(name)}
                  </span>
                  {totalDays > 0 && (
                    <span className="text-[8px] px-1 py-0.5 rounded-full bg-violet-100 text-violet-700 font-bold flex-shrink-0">
                      {totalDays}d
                    </span>
                  )}
                </div>

                {/* Dag-cellen */}
                {Array.from({ length: daysInMonth }, (_, i) => {
                  const day = i + 1;
                  const dow = (firstDow + i) % 7;
                  const isWeekend = dow >= 5;
                  const onVac = isOnVacation(name, day);
                  const inSel = isInSelection(name, day);
                  const prevOnVac = day > 1 && isOnVacation(name, day - 1);
                  const nextOnVac =
                    day < daysInMonth && isOnVacation(name, day + 1);

                  let bg = isWeekend ? "#f9fafb" : "#fff";
                  if (onVac) bg = "#ede9fe";
                  else if (inSel) bg = "#dbeafe";

                  return (
                    <div
                      key={day}
                      className="relative h-8 transition-colors"
                      style={{
                        backgroundColor: bg,
                        cursor: isFM ? "pointer" : "default",
                        borderLeft:
                          onVac && !prevOnVac
                            ? "2px solid #8b5cf6"
                            : `1px solid ${isWeekend ? "#e5e7eb" : "#f3f4f6"}`,
                        borderRight:
                          onVac && !nextOnVac ? "2px solid #8b5cf6" : "none",
                        borderTop: onVac
                          ? "2px solid #8b5cf6"
                          : "1px solid #f3f4f6",
                        borderBottom: onVac
                          ? "2px solid #8b5cf6"
                          : "1px solid #f3f4f6",
                        borderRadius: onVac
                          ? `${!prevOnVac ? "5px" : "0"} ${
                              !nextOnVac ? "5px" : "0"
                            } ${!nextOnVac ? "5px" : "0"} ${
                              !prevOnVac ? "5px" : "0"
                            }`
                          : "2px",
                      }}
                      onClick={() => handleDayClick(name, day)}
                      onMouseEnter={() => setHoverDay(day)}
                      onMouseLeave={() => setHoverDay(null)}
                    >
                      {onVac && !prevOnVac && (
                        <span className="absolute inset-0 flex items-center justify-center text-sm select-none">
                          🏖️
                        </span>
                      )}
                    </div>
                  );
                })}
              </div>
            );
          })}
        </div>
      </div>

      {/* ── Overzicht: ALTIJD iedereen tonen ── */}
      <div className="px-4 mt-6">
        <h3 className="font-bold text-sm text-gray-700 mb-3 flex items-center gap-2">
          <Sun size={15} /> Vakanties {viewYear} — alle medewerkers
        </h3>
        <div className="space-y-2">
          {staffList.map((name) => {
            const perms = (vacations[name] || []).sort((a, b) =>
              a.from.localeCompare(b.from)
            );
            const totalDays = perms.reduce(
              (acc, v) =>
                acc +
                Math.round((new Date(v.to) - new Date(v.from)) / 86400000) +
                1,
              0
            );
            const fmt = (d) =>
              new Date(d).toLocaleDateString("nl-NL", {
                day: "numeric",
                month: "short",
              });

            return (
              <div
                key={name}
                className="bg-white rounded-xl border overflow-hidden"
              >
                {/* Persoon-header */}
                <div className="flex items-center gap-2 px-3 py-2 bg-gray-50 border-b">
                  <ProfileAvatar
                    name={name}
                    staffList={appData.staffList}
                    size={24}
                    color={theme.primary}
                  />
                  <span className="font-bold text-sm flex-1">{name}</span>
                  {totalDays > 0 ? (
                    <span className="text-[11px] text-violet-700 bg-violet-50 px-2 py-0.5 rounded-full font-bold">
                      {totalDays} dagen
                    </span>
                  ) : (
                    <span className="text-[11px] text-gray-400">
                      Geen vakanties
                    </span>
                  )}
                </div>

                {/* Periodes */}
                {perms.length > 0 ? (
                  <div className="divide-y">
                    {perms.map((v) => {
                      const days =
                        Math.round(
                          (new Date(v.to) - new Date(v.from)) / 86400000
                        ) + 1;
                      return (
                        <div
                          key={v.from}
                          className="flex items-center justify-between px-3 py-1.5"
                        >
                          <span className="text-xs font-medium text-gray-700">
                            {fmt(v.from)}
                            <span className="mx-1 text-gray-400">→</span>
                            {fmt(v.to)}
                            <span className="ml-2 text-[11px] text-violet-500 font-semibold">
                              ({days}d)
                            </span>
                          </span>
                          {isFM && (
                            <button
                              onClick={() => removeVacation(name, v.from)}
                              className="text-gray-300 hover:text-red-500 transition-colors"
                            >
                              <Trash2 size={13} />
                            </button>
                          )}
                        </div>
                      );
                    })}
                  </div>
                ) : (
                  <div className="px-3 py-2 text-xs text-gray-400 italic">
                    —
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

const RoosterView = ({
  appData,
  currentDay,
  loggedInUserName,
  theme,
  onPrev,
  onNext,
  onCalendar,
  setCurrentDay,
  updateData,
  showAlert,
  showConfirm,
  userRole,
  initialTab,
}) => {
  const [activeTab, setActiveTab] = useState(initialTab || "mine");
  const [showExport, setShowExport] = useState(false);

  const isFM = userRole === "fm";

  // ── Deadline badge: upcoming deadline this or next month ──
  const beschikbaarheidBadge = (() => {
    const maandInst = appData.maandInstellingen || {};
    const myAvail = appData.staffAvailability?.[loggedInUserName] || {};
    const today = new Date();
    // Check current + next 2 months
    for (let offset = 0; offset <= 1; offset++) {
      const d = new Date(today.getFullYear(), today.getMonth() + offset, 1);
      const mk = toMonthKey(d.getFullYear(), d.getMonth() + 1);
      const inst = maandInst[mk] || {};
      if (!inst.open || !inst.deadline) continue;
      const dl = new Date(inst.deadline + "T23:59:59");
      if (dl < today) continue; // expired
      const daysLeft = Math.ceil((dl - today) / 86400000);
      if (daysLeft > 14) continue; // only warn within 2 weeks
      // Only show badge if not all days are filled in for that month
      const daysInMo = new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate();
      let filled = 0;
      for (let day = 1; day <= daysInMo; day++) {
        const dateStr = `${mk}-${String(day).padStart(2, "0")}`;
        if (myAvail[dateStr]) filled++;
      }
      if (filled < daysInMo) return daysLeft; // not fully filled → show badge
    }
    return null;
  })();

  const tabs = [
    { id: "mine", label: "Mijn Rooster", icon: CalendarDays },
    { id: "team", label: "Teamrooster", icon: Users2 },
    { id: "beschikbaarheid", label: "Beschikbaarheid", icon: CalendarCheck2 },
    ...(isFM ? [{ id: "vakantie", label: "Vakanties", icon: Sun }] : []),
  ];

  return (
    <div className="h-full flex flex-col">
      {/* ── Tab balk — verbonden met nav hieronder ── */}
      <div className="flex-shrink-0 mx-3 mt-2 mb-1">
        <div className="flex gap-1.5 h-10">
          {tabs.map((tab) => {
            const Icon = tab.icon;
            const active = activeTab === tab.id;
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className="rooster-tab flex-1 flex items-center justify-center gap-1.5 text-[13px] font-bold transition-all rounded-xl"
                style={{
                  backgroundColor: active ? C.White : "transparent",
                  color: active ? theme.primary : C.TextMuted,
                  border: active
                    ? `1px solid ${C.BorderLight}`
                    : "1px solid transparent",
                  boxShadow: active ? "0 1px 4px rgba(0,0,0,0.06)" : "none",
                  opacity: 1,
                }}
              >
                <div className="relative">
                  <Icon size={15} />
                  {tab.id === "beschikbaarheid" &&
                    beschikbaarheidBadge !== null && (
                      <div
                        className="absolute -top-1 -right-1 w-2 h-2 rounded-full"
                        style={{ backgroundColor: C.Honey }}
                      />
                    )}
                </div>
                <span>{tab.label}</span>
              </button>
            );
          })}
        </div>
      </div>

      {/* Export Modal */}
      {showExport && (
        <RoosterExportModal
          appData={appData}
          loggedInUserName={loggedInUserName}
          theme={theme}
          userRole={userRole}
          onClose={() => setShowExport(false)}
        />
      )}

      {/* Content */}
      <div className="flex-1 overflow-hidden">
        {activeTab === "mine" ? (
          <MyScheduleView
            appData={appData}
            currentDay={currentDay}
            loggedInUserName={loggedInUserName}
            theme={theme}
            onPrev={onPrev}
            onNext={onNext}
            onCalendar={onCalendar}
            setCurrentDay={setCurrentDay}
            updateData={updateData}
            showAlert={showAlert}
            onExport={() => setShowExport(true)}
          />
        ) : activeTab === "team" ? (
          <SimpleTeamRooster
            appData={appData}
            theme={theme}
            updateData={updateData}
            showAlert={showAlert}
            userRole={userRole}
            onExport={() => setShowExport(true)}
          />
        ) : activeTab === "vakantie" ? (
          <VakantieplannerView
            appData={appData}
            updateData={updateData}
            theme={theme}
            userRole={userRole}
            loggedInUserName={loggedInUserName}
            showAlert={showAlert}
          />
        ) : (
          <BeschikbaarheidView
            appData={appData}
            updateData={updateData}
            theme={theme}
            userRole={userRole}
            loggedInUserName={loggedInUserName}
            showAlert={showAlert}
          />
        )}
      </div>
    </div>
  );
};

// --- MY SHIFT WIDGET (Dashboard) ---
const MyShiftWidget = ({ appData, currentDay, loggedInUserName, theme }) => {
  const dateKey = toIsoDate(currentDay);
  const allShifts = appData.workSchedule?.[dateKey] || [];
  const myShifts = allShifts.filter((s) => s.matchedUser === loggedInUserName);

  if (myShifts.length === 0) return null;

  const nextShift = myShifts[0];

  return (
    <div
      className="bg-white rounded-2xl shadow-sm border-2 overflow-hidden"
      style={{ borderColor: theme.primary }}
    >
      <div className="cp-pattern-dots">
        <div className="p-6">
          <div className="flex items-center gap-3">
            <div
              className="p-3 rounded-xl shadow-sm"
              style={{
                backgroundColor: `${theme.primary}20`,
                color: theme.primary,
              }}
            >
              <Clock size={28} />
            </div>
            <div className="flex-1">
              <h3
                className="text-base font-bold"
                style={{ color: theme.primary }}
              >
                Je shift vandaag
              </h3>
              <p
                className="text-sm font-medium"
                style={{ color: theme.primary }}
              >
                {nextShift.start} - {nextShift.end} •{" "}
                {nextShift.title || nextShift.location}
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

// --- SWAP REQUESTS WIDGET (Voor FM) ---
