// 📅 IN-APP KALENDER MODAL
const CalendarModal = ({ currentDay, onSelect, onClose, theme }) => {
  const t = theme || THEMES.general;
  const logoColor = CP_LOGO_COLORS[t?.id] || "#b4d6a1";
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const [viewMonth, setViewMonth] = React.useState(() => {
    const d = new Date(currentDay || new Date());
    return { year: d.getFullYear(), month: d.getMonth() };
  });

  const { year, month } = viewMonth;

  const firstDay = new Date(year, month, 1);
  const lastDay = new Date(year, month + 1, 0);

  // Maandag = 0
  const startOffset = (firstDay.getDay() + 6) % 7;
  const daysInMonth = lastDay.getDate();

  const monthName = firstDay.toLocaleDateString("nl-NL", {
    month: "long",
    year: "numeric",
  });

  const cells = [];
  for (let i = 0; i < startOffset; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(d);

  const prevMonth = () => {
    setViewMonth((v) => {
      if (v.month === 0) return { year: v.year - 1, month: 11 };
      return { year: v.year, month: v.month - 1 };
    });
  };
  const nextMonth = () => {
    setViewMonth((v) => {
      if (v.month === 11) return { year: v.year + 1, month: 0 };
      return { year: v.year, month: v.month + 1 };
    });
  };

  const selected = new Date(currentDay);
  selected.setHours(0, 0, 0, 0);

  const handleDay = (day) => {
    const d = new Date(year, month, day);
    onSelect(d);
    onClose();
  };

  const weeks = [];
  for (let i = 0; i < cells.length; i += 7) weeks.push(cells.slice(i, i + 7));

  return (
    <div
      className="fixed inset-0 z-50 flex items-end md:items-center justify-center bg-black/50 backdrop-blur-sm p-0 md:p-4"
      onClick={onClose}
    >
      <div
        className="w-full max-w-sm rounded-t-2xl md:rounded-2xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-4 md:zoom-in-95 duration-200 bg-white"
        onClick={(e) => e.stopPropagation()}
        style={{ border: `2px solid ${t.primary}` }}
      >
        {/* Header */}
        <div
          className="relative overflow-hidden"
          style={{ backgroundColor: t.primary }}
        >
          {PATTERN_BACKGROUNDS[t?.id] && (
            <div
              className="absolute inset-0 pointer-events-none"
              style={{
                backgroundImage: `url(${PATTERN_BACKGROUNDS[t?.id]})`,
                backgroundSize: "cover",
                backgroundPosition: "center",
                opacity: 0.1,
              }}
            />
          )}
          <div className="relative z-10 flex items-center justify-between px-4 py-3">
            <button
              onClick={prevMonth}
              className="p-2 rounded-xl active:scale-95 transition-transform"
              style={{ backgroundColor: "rgba(0,0,0,0.2)" }}
            >
              <ChevronLeft size={18} style={{ color: logoColor }} />
            </button>
            <div className="text-center">
              <div
                className="font-bold text-base capitalize"
                style={{ color: logoColor }}
              >
                {monthName}
              </div>
            </div>
            <button
              onClick={nextMonth}
              className="p-2 rounded-xl active:scale-95 transition-transform"
              style={{ backgroundColor: "rgba(0,0,0,0.2)" }}
            >
              <ChevronRight size={18} style={{ color: logoColor }} />
            </button>
          </div>
        </div>

        {/* Weekdagen header */}
        <div className="grid grid-cols-7 px-3 pt-3 pb-1">
          {["Ma", "Di", "Wo", "Do", "Vr", "Za", "Zo"].map((d) => (
            <div
              key={d}
              className="text-center text-xs font-semibold py-1"
              style={{ color: `${t.primary}80` }}
            >
              {d}
            </div>
          ))}
        </div>

        {/* Kalender grid */}
        <div className="px-3 pb-3">
          {weeks.map((week, wi) => (
            <div key={wi} className="grid grid-cols-7">
              {week.map((day, di) => {
                if (!day) return <div key={di} />;
                const d = new Date(year, month, day);
                d.setHours(0, 0, 0, 0);
                const isToday = d.getTime() === today.getTime();
                const isSelected = d.getTime() === selected.getTime();
                const isWeekend =
                  (firstDay.getDay() === 0
                    ? (di + 1) % 7
                    : (di + (7 - ((firstDay.getDay() + 6) % 7))) % 7) >= 5;
                return (
                  <button
                    key={di}
                    onClick={() => handleDay(day)}
                    className="aspect-square flex items-center justify-center rounded-xl m-0.5 text-sm font-medium transition-all active:scale-90"
                    style={{
                      backgroundColor: isSelected
                        ? t.primary
                        : isToday
                        ? `${t.primary}18`
                        : "transparent",
                      color: isSelected
                        ? "white"
                        : isToday
                        ? t.primary
                        : isWeekend
                        ? `${t.primary}60`
                        : t.primary,
                      fontWeight: isToday || isSelected ? "bold" : "normal",
                      boxShadow:
                        isToday && !isSelected
                          ? `0 0 0 2px ${t.primary}40`
                          : "none",
                    }}
                  >
                    {day}
                  </button>
                );
              })}
            </div>
          ))}
        </div>

        {/* Snelknoppen */}
        <div className="grid grid-cols-3 gap-2 px-3 pb-3">
          {[
            { label: "Gisteren", offset: -1 },
            { label: "Vandaag", offset: 0 },
            { label: "Morgen", offset: 1 },
          ].map(({ label, offset }) => {
            const d = new Date();
            d.setDate(d.getDate() + offset);
            d.setHours(0, 0, 0, 0);
            const isActive = d.getTime() === selected.getTime();
            return (
              <button
                key={label}
                onClick={() => {
                  onSelect(d);
                  onClose();
                }}
                className="py-2 rounded-xl text-sm font-bold transition-all active:scale-95"
                style={{
                  backgroundColor: isActive ? t.primary : `${t.primary}12`,
                  color: isActive ? "white" : t.primary,
                }}
              >
                {label}
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
};

