// ── Helper: vertaal een vraag ─────────────────────────────────
const djQ = (q, lang) => ({
  question: q[lang] || q.nl || q.question || "",
  options: q[`options_${lang}`] || q.options,
  correct: q.correct,
  _allLangs: {
    nl: q.nl || q.question || "",
    en: q.en || q.nl || q.question || "",
    de: q.de || q.nl || q.question || "",
    fr: q.fr || q.nl || q.question || "",
  },
});

