const djShuffle = (arr) => {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
};
const getQuestionsFromBank = (count, used = []) => {
  const s = new Set(used.map((q) => q.nl || q.question || ""));
  const av = DJ_QUESTION_BANK.filter((q) => !s.has(q.nl || q.question || ""));
  return djShuffle(av.length >= count ? av : DJ_QUESTION_BANK).slice(0, count);
};
const djSet = (ref, data) => setDoc(ref, data, { merge: true });
const djUpd = (ref, data) =>
  updateDoc(ref, data).catch(() => setDoc(ref, data, { merge: true }));

