  // Berekend: welke slide is nu gepind op basis van gekoppelde activiteiten?
  // Elke render herberekend; useEffect met interval voor realtime updates
  const [pinnedSlideId, setPinnedSlideId] = useState(null);
  const [pinnedActivityTime, setPinnedActivityTime] = useState(null); // { start, end }

  const parseActTimes = (act, now) => {
    const m = act.time?.match(/(\d{1,2}):(\d{2})/);
    if (!m) return null;
    const start = new Date(now);
    start.setHours(parseInt(m[1]), parseInt(m[2]), 0, 0);
    const rangeM = act.time.match(/(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/);
    const end = new Date(now);
    if (rangeM) {
      end.setHours(parseInt(rangeM[3]), parseInt(rangeM[4]), 0, 0);
    } else {
      end.setTime(start.getTime() + 60 * 60 * 1000); // +1 uur fallback
    }
    return { start, end };
  };

  useEffect(() => {
    const compute = () => {
      const now = new Date();
      const todayKey = now.toISOString().slice(0, 10);
      let winner = null;
      let winnerTimes = null;
      let winnerMinutesLeft = Infinity;

      for (const slide of activeSlides) {
        if (!slide.linkedActivity) continue;
        const pinMinutes = slide.pinMinutes ?? 60;

        // Zoek de eerstvolgende activiteit vandaag met deze titel
        const match = (appData?.schedule || []).find((act) => {
          if (act.date !== todayKey) return false;
          if (act.title !== slide.linkedActivity) return false;
          const times = parseActTimes(act, now);
          if (!times) return false;
          const minutesUntilStart = (times.start - now) / 60000;
          // Pin als: binnen pinMinutes vóór start, of activiteit is nog bezig
          return minutesUntilStart <= pinMinutes && now < times.end;
        });

        if (match) {
          const times = parseActTimes(match, now);
          const minutesLeft = Math.max(0, (times.start - now) / 60000);
          if (minutesLeft < winnerMinutesLeft) {
            winnerMinutesLeft = minutesLeft;
            winner = slide.id;
            winnerTimes = times;
          }
        }
      }
      setPinnedSlideId(winner);
      setPinnedActivityTime(winnerTimes);
    };

    compute();
    const interval = setInterval(compute, 30000); // elke 30 seconden herberekenen
    return () => clearInterval(interval);
  }, [activeSlides, appData?.schedule]);

  // Aftelklok: elke seconde tikken — gebruikt door zowel de countdown op
